window.JCST_ARTICLES = [{"doi":"10.1007/s11390-025-5538-1","title":"Reinforcement Learning for UAV-Assisted Intelligent Transportation Systems: Solutions, Challenges, and Future Directions","authors":[{"last":"Zairi","first":"Sajeh"},{"last":"Msadaa","first":"Ikbal Chammakhi"},{"last":"Dhraief","first":"Amine"}],"keywords":["autonomous decision-making","deep reinforcement learning","intelligent transportation system","unmanned aerial vehicle (UAV)"],"abstract":"This paper comprehensively explores how reinforcement learning (RL) and deep reinforcement learning (DRL) methods can address diverse challenges in unmanned aerial vehicle (UAV)-assisted intelligent transportation systems (ITS), ranging from coverage expansion to enhancing driver assistance and ensuring communication security. To facilitate further research endeavors, the paper offers insights into selecting suitable RL models for specific scenarios. In addition, it introduces a practical seven-step method for modeling UAV-assisted ITS as an RL problem, providing a structured approach for researchers to follow. The paper presents an overview of various RL and DRL algorithms, such as Q-learning, Deep Q-Network, and Deep Deterministic Policy Gradient, to maximize the benefits of ITS through autonomous decision-making and learning mechanisms. In addition, the paper explores the current challenges in this field. It outlines future research directions, paving the way for advances in integrating RL and DRL techniques with UAV-assisted ITS.","volume":41,"issue":4,"firstpage":1101,"lastpage":1119,"year":2026,"type":"Survey","research_area":["Reinforcement Learning","Robotics & Control"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5538-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5538-1?year=2026&issue=4","affiliations":["Qassim University","University of Carthage","University of Manouba"],"type_origin":"Survey"},{"doi":"10.1007/s11390-026-5545-x","title":"StableME: Stable Model Editing via Knowledge Augmentation for Large Language Models","authors":[{"last":"Wei","first":"Zi-Hao"},{"last":"Pang","first":"Liang"},{"last":"Ding","first":"Han-Xing"},{"last":"Deng","first":"Jing-Cheng"},{"last":"Shen","first":"Hua-Wei"},{"last":"Cheng","first":"Xue-Qi"}],"keywords":["knowledge augmentation","large language model (LLM)","model editing"],"abstract":"Efficient model editing of large language models is essential for updating outdated information and incorporating specialized knowledge. Existing methods, however, often rely on two implicit assumptions: that knowledge is localized in a small subset of parameters and that different facts are largely independent of one another and of the model’s broader capabilities. These assumptions can cause unstable edits, especially at large scales. To address this, we introduce StableME, a model-editing method based on knowledge augmentation rather than knowledge localization. StableME employs two automatic augmentation strategies during instruction finetuning: Semantic Paraphrase Enhancement (SPE), which diversifies factual expressions to strengthen the learning of edited knowledge, and Contextual Description Enrichment (CDE), which expands surrounding descriptions to mitigate forgetting of related knowledge. Experiments on our benchmark show that StableME surpasses prior editing methods in edited-knowledge stability and multi-hop knowledge stability while preserving unrelated knowledge and overall model capabilities. Furthermore, StableME is effective in a small-scale fine-tuning experiment on a closed-source ChatGPT model.","volume":41,"issue":4,"firstpage":1120,"lastpage":1131,"year":2026,"type":"Regular Paper","research_area":["Fine-Tuning & Model Adaptation"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5545-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5545-x?year=2026&issue=4","affiliations":["Chinese Academy of Sciences","University of Chinese Academy of Sciences"],"type_origin":"Regular Paper"},{"doi":"10.1007/s11390-026-5661-7","title":"Continual Visual Concept Learning with Scene Graph Expansion","authors":[{"last":"Cai","first":"Yu-Song"},{"last":"Guo","first":"Xiao-Han"},{"last":"Ling","first":"Shi-Mou"},{"last":"Pan","first":"Li-Li"},{"last":"Li","first":"Hong-Liang"}],"keywords":["continual visual concept learning","mixture-of-experts (MoE)","scene graph"],"abstract":"In this work, we tackle two key challenges in lifelong visual concept learning: catastrophic forgetting and semantic misalignment. Existing methods typically incorporate new visual concepts by updating the parameters of vision-language models (VLMs), but fail to capture high-level semantic knowledge (e.g., object layout) associated with those concepts. To address this issue, this paper introduces a novel framework, which simultaneously updates the parameters of VLMs and expands the scene graph when processing images of new concepts. The VLM is built upon a novel mixture-of-experts (MoE) architecture designed to alleviate catastrophic forgetting by minimizing unnecessary interference among experts. During inference, by leveraging the expanded scene graph, we streamline prompt design while ensuring that the generated images accurately reflect the scene layout derived from the graph. Extensive experimental results demonstrate that our method significantly improves both generative diversity and text-image alignment. Our code is available at \n                https://doi.org/10.57760/sciencedb.jcst.00039\n                \n              .","volume":41,"issue":4,"firstpage":1132,"lastpage":1143,"year":2026,"type":"Regular Paper","research_area":["Computer Vision","Multi-Task & Transfer Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5661-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5661-7?year=2026&issue=4","affiliations":["University of Electronic Science and Technology of China"],"type_origin":"Regular Paper"},{"doi":"10.1007/s11390-026-5822-8","title":"Collective Entity Linking with Large Language Models via Mention-Aware Question Answering","authors":[{"last":"Wei","first":"Nan"},{"last":"Weng","first":"Wei-Ning"},{"last":"Ren","first":"Xiao-Long"},{"last":"Fang","first":"Jin-Yun"}],"keywords":["entity linking","large language model (LLM)","joint entity disambiguation","zero-shot"],"abstract":"Large language models (LLMs) have demonstrated strong text understanding and reasoning capabilities, motivating their application to entity linking (EL). Existing prompt-based methods typically cast EL as a multiple-choice task but disambiguate each mention independently, relying solely on local context and ignoring semantic dependencies among mentions within the same document. This independence assumption limits document-level EL performance. To address this, we propose Collective Entity Linking via Mention-Aware Question Answering (CELMA), a novel prompt-based collective EL framework that formulates document-level disambiguation as a sequential decision process, where each mention’s resolution is conditioned on previously resolved mentions. This design enables LLMs to accumulate and leverage inter-mention signals, such as entity co-occurrence and topical coherence, without task-specific training or fine-tuning. Extensive experiments across eight public benchmarks show that our framework consistently improves document-level EL performance, achieving an average 4.0% micro-F1 gain and strong cross-domain generalization. Moreover, applying a confidence-order resolution strategy further boosts performance, particularly for difficult and ambiguous mentions. These results demonstrate the potential of prompting LLMs for collective reasoning in EL, offering a simple yet effective zero-shot alternative to traditionally trained models.","volume":41,"issue":4,"firstpage":1144,"lastpage":1153,"year":2026,"type":"Regular Paper","research_area":["Information Extraction"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5822-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5822-8?year=2026&issue=4","affiliations":["Chinese Academy of Sciences","University of Chinese Academy of Sciences"],"type_origin":"Regular Paper"},{"doi":"10.1007/s11390-026-5310-1","title":"FedCUS: A Client-Unperceived Selection Strategy for Data Heterogeneity in Federated Learning","authors":[{"last":"Guo","first":"Zi-Hao"},{"last":"Lv","first":"Hong-Tao"},{"last":"Zhang","first":"Yi-Xin"},{"last":"Zhang","first":"Yu"},{"last":"Zhao","first":"Yi-Bo-Wen"},{"last":"Xu","first":"Yong-Hui"},{"last":"Cui","first":"Li-Zhen"}],"keywords":["federated learning","client selection","data heterogeneity","truthfulness"],"abstract":"Federated learning (FL) has emerged as a pivotal framework for collaboratively training machine learning models across distributed clients while preserving privacy. However, the statistical heterogeneity inherent in client data distributions poses significant challenges to model convergence and system reliability. While existing client selection strategies partially address concerns about heterogeneity, their reliance on client-reported metrics, such as training loss and utility estimates, introduces vulnerabilities to strategic misreporting, which may compromise model integrity. To overcome these limitations, we present FedCUS, a novel client-unperceived selection strategy that ensures strategy-proof cooperation in heterogeneous FL ecosystems. Departing from conventional approaches, FedCUS implements an opaque selection mechanism by decoupling selection criteria from client visibility, thereby eliminating clients' awareness of the selection criteria and disincentivizing dishonest reporting behaviors. The proposed framework leverages a DPP (determinantal point process)-based diversity enhancement module for optimal client selection, utilizes matrix completion to estimate missing entries in the likelihood matrix for DPP, and incorporates an age-of-update (AoU) aware temporal weighting mechanism to mitigate the effect of stale local updates. Extensive empirical evaluations demonstrate that FedCUS accelerates convergence compared with existing baselines and maintains robust performance in the presence of untruthful clients.","volume":41,"issue":4,"firstpage":1154,"lastpage":1169,"year":2026,"type":"Regular Paper","research_area":["Federated Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5310-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5310-1?year=2026&issue=4","affiliations":["Shandong University"],"type_origin":"Article; Early Access"},{"doi":"10.1007/s11390-026-5759-y","title":"Text-Parsing Adaptive Gated Fusion for Audio-Visual Question Answering","authors":[{"last":"Shan","first":"Liang"},{"last":"Li","first":"Guang-Yao"}],"keywords":["audio-visual question answering","audio-visual scene understanding","audio-visual learning"],"abstract":"Audio-visual question answering (AVQA) tasks require models to answer questions concerning visual objects, sounds, and their interactions in videos by effectively integrating multimodal information. A key challenge in AVQA lies in the presence of irrelevant audio-visual contents that can obscure question-relevant signals, necessitating targeted perception and reasoning mechanisms for accurate predictions. In this study, we propose a text-parsing adaptive gated fusion network (TP-Net), a framework that dynamically adjusts modality contributions based on question semantics. Unlike existing methods that consider all question types uniformly, TP-Net emphasizes modality-specific features during prediction, such as increasing the weight of audio features for auditory-centric questions. The proposed model comprises a spatiotemporal perception module for selecting informative temporal segments and refining audio-visual spatiotemporal correlations and a modality-gated fusion module that reweights multimodal features based on question types. Extensive evaluations on standard AVQA benchmarks demonstrate that TP-Net achieves state-of-the-art performance, particularly excelling in scenarios requiring nuanced multimodal reasoning.","volume":41,"issue":4,"firstpage":1170,"lastpage":1180,"year":2026,"type":"Regular Paper","research_area":["Computer Vision","Speech & Audio"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5759-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5759-y?year=2026&issue=4","affiliations":["Shandong University of Finance & Economics","Renmin University of China","Tsinghua University"],"type_origin":"Article; Early Access"},{"doi":"10.1007/s11390-026-5671-5","title":"Local-Global Feature Complementation Network for Visual Place Recognition","authors":[{"last":"Wang","first":"Wei-Wei"},{"last":"Wang","first":"Mei-Jia"},{"last":"Wang","first":"Hao-Yi"},{"last":"Guo","first":"Wen-Qiang"},{"last":"Guo","first":"Jiapan"},{"last":"Zhang","first":"Ze-Jun"},{"last":"Sun","first":"Changming"},{"last":"Ma","first":"Ling-Kun"},{"last":"Zhang","first":"Wei-Chuan"}],"keywords":["visual place recognition (VPR)","dynamic feature fusion","vision transformer (ViT)","convolutional neural network (CNN)"],"abstract":"Visual place recognition (VPR) is crucial for robotic localization and navigation. Its key challenge lies in constructing feature representations that are robust to environmental changes. Existing methods typically adopt convolutional neural networks (CNNs) or vision transformers (ViTs) as feature extractors. Notably, these architectures excel in different aspects—CNNs are effective at capturing local details, while ViTs are better suited for modeling the global context. Thus, leveraging the strengths of both networks simultaneously is difficult. To address this issue, we propose the Local-Global Feature Complementation Network (LGCN) that integrates a parallel CNN-ViT hybrid architecture with the Dynamic Feature Fusion Module (DFM) for VPR. DFM performs dynamic feature fusion through the joint modeling of spatial and channel-wise dependencies. Furthermore, to enhance the expressiveness and adaptability of the ViT branch for VPR tasks, we introduce lightweight frequency-spatial fusion adapters into the frozen ViT backbone. These adapters enable task-specific adaptation using a controlled parameter overhead. Extensive experiments on multiple VPR benchmark datasets demonstrate that the proposed LGCN consistently outperforms existing approaches in terms of localization accuracy and robustness, validating its effectiveness and generalizability.","volume":41,"issue":4,"firstpage":1181,"lastpage":1191,"year":2026,"type":"Regular Paper","research_area":["Convolutional & Spiking Networks","Deep Learning & Neural Networks","Transformers & Attention"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5671-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5671-5?year=2026&issue=4","affiliations":["Shaanxi University of Science and Technology","University of Groningen","Zhejiang Normal University","Commonwealth Scientific and Industrial Research Organisation"],"type_origin":"Regular Paper"},{"doi":"10.1007/s11390-026-5753-4","title":"MFFNet: Multidomain Feature Fusion Network for Hyperspectral Pansharpening","authors":[{"last":"Wang","first":"Xiao-Zheng"},{"last":"Yang","first":"Yong"},{"last":"Huang","first":"Shu-Ying"},{"last":"Liu","first":"Zi-Yang"}],"keywords":["hyperspectral (HS) pansharpening","curvature","low-rank space","low-dimensional space"],"abstract":"Hyperspectral (HS) pansharpening is designed to fuse high-spatial resolution panchromatic (PAN) images with low-spatial resolution hyperspectral (LRHS) images to generate high-spatial resolution hyperspectral (HRHS) images. Because of insufficient consideration of the interference caused by modal differences in spectral and spatial features during feature fusion, most deep learning-based methods suffer from spectral and spatial distortions in the fusion results. To address these issues, a multidomain feature fusion network (MFFNet) is proposed to perform fine-grained extraction and fusion of multiscale spatial-spectral features from PAN and HS images. A dual U-Net model is constructed to extract and fuse multiscale features from PAN and HS images, with a spatial-curvature feature enhancement module (SpaFEM) and a spectral-curvature feature enhancement module (SpeFEM) designed to improve curvature features. Moreover, a low-rank feature cross-attention module (LFCM) based on matrix factorization is introduced to enhance and complement the PAN and HS image features through cross-modal fusion in a low-dimensional space. Extensive experiments across four datasets are used to demonstrate that the proposed MFFNet outperforms several state-of-the-art methods. The code is available at .","volume":41,"issue":4,"firstpage":1192,"lastpage":1204,"year":2026,"type":"Regular Paper","research_area":["Computer Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5753-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5753-4?year=2026&issue=4","affiliations":["Tiangong University"],"type_origin":"Article; Early Access"},{"doi":"10.1007/s11390-026-6176-y","title":"High-Level Synthesis for Approximate Computing: A Survey","authors":[{"last":"Dou","first":"Yu-Qin"},{"last":"Wang","first":"Yang"},{"last":"Wei","first":"Jian-Xu"},{"last":"Xu","first":"Ming-Lu"},{"last":"Waris","first":"Haroon"},{"last":"Woods","first":"Roger"},{"last":"Liu","first":"Wei-Qiang"}],"keywords":["approximate computing","design space exploration (DSE)","high-level synthesis for approximate computing (AHLS)"],"abstract":"The approximate computing paradigm allows designers to create efficient hardware and software designs by leveraging error-tolerance applications such as signal and multimedia processing, computer vision, and machine learning. A recent focus on incorporating approximate computing techniques in high-level synthesis (HLS) provides a new perspective on hardware design by facilitating trade-offs among performance, energy efficiency, and accuracy. However, in the field of HLS for approximate computing (AHLS), there is a lack of systematic review articles and in-depth analyses of the latest methodologies. This paper presents a comprehensive summary of the latest AHLS technologies, while focusing on error estimation, approximation techniques, and design space exploration (DSE). In addition, an analysis of the current research gaps in AHLS is presented. This work aims to provide researchers, engineers, and scholars with a comprehensive theoretical and practical AHLS framework, fostering academic exchange and technological innovation in this study field.","volume":41,"issue":4,"firstpage":1205,"lastpage":1218,"year":2026,"type":"Regular Paper","research_area":["Approximate Computing & Circuits"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6176-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6176-y?year=2026&issue=4","affiliations":["Nanjing University of Posts and Telecommunications","Institute of Space Technology","Queen's University Belfast","Nanjing University of Aeronautics and Astronautics"],"type_origin":"Review; Early Access"},{"doi":"10.1007/s11390-026-5632-z","title":"Auto-SpMM: Towards Efficient Sparse Matrix-Matrix Multiplication on Heterogeneous Servers via Automatic Resource Mapping and Pipeline Generation","authors":[{"last":"Dun","first":"Ming"},{"last":"Cao","first":"Hua-Wei"},{"last":"Song","first":"Shu-Han"},{"last":"Zhang","first":"Yuan"},{"last":"Ye","first":"Xiao-Chun"}],"keywords":["sparse matrix-matrix multiplication (SpMM)","performance optimization","machine learning"],"abstract":"Sparse matrix-matrix multiplication (SpMM) is the core computing routine in many advanced domains, including artificial intelligence and scientific computing. Thus, accelerating SpMM has become a focal area for high-performance computing (HPC) researchers. While many advanced studies attempt to optimize the Sp-MM computation kernels on GPUs, the overall SpMM performance on GPUs cannot achieve consistent speedups over CPU implementations, due to time-consuming data transfer between the host and the device. Moreover, although SpMM on GPUs can resort to a pipeline for computation-communication overlap, whether an arbitrary sparse matrix can benefit from such a pipeline remains undetermined. To address these challenges, we propose Auto-SpMM, which is an efficient auto-tuning scheme for SpMM on a CPU-GPU heterogeneous server. Auto-Sp-MM extracts concise features that capture the memory-access and computation pattern of sparse matrices, and then automatically selects the optimal computation resource and algorithm, along with the best pipeline pattern for each SpMM. Extensive evaluations with 2 644 sparse matrices demonstrate that Auto-SpMM can achieve an average speedup of 9.71x compared with Intel Math Kernel Library (MKL) on CPUs and 13.20x compared with cuSPARSE on GPUs.","volume":41,"issue":4,"firstpage":1219,"lastpage":1229,"year":2026,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Optimization & Heuristic Methods"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5632-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5632-z?year=2026&issue=4","affiliations":["Chinese Academy of Sciences","Zhongguancun Laboratory"],"type_origin":"Regular Paper"},{"doi":"10.1007/s11390-025-5560-3","title":"An Analysis of the Mismatch Between Garbage Collection Evolution and Datacenter Paradigm Shifting","authors":[{"last":"Xiao","first":"Jia-Wei"},{"last":"Hua","first":"Zi-Yue"},{"last":"Li","first":"Sheng-Kai"},{"last":"Yuan","first":"Yi-Zhe"},{"last":"Wu","first":"Ming-Yu"},{"last":"Xue","first":"Hao-Nan"},{"last":"Feng","first":"Xiao-Bing"},{"last":"Cui","first":"Hui-Min"},{"last":"Wang","first":"Chen-Xi"}],"keywords":["garbage collection","resource disaggregation","datacenter","design study"],"abstract":"Managed languages, such as Java, are widely used in cloud application development due to their good portability, scalability, and automatic memory management, i.e., garbage collection (GC). However, the managed applications exhibit a series of performance and latency issues when running on emerging memory-disaggregated servers, which is mainly caused by the mismatch between the design of GC and the hierarchical memory structure. The mismatch is even enlarged with the development of GC, the main reason for which is that the newly proposed GC keeps pursuing lower pause time and higher reclaiming throughput without being aware of the paradigm shift in the underlying memory hierarchy. In this work, we perform an extensive study on a wide spectrum of cloud applications to understand the sources of performance penalties-the poor data locality of GC, the interference between GC tasks and mutators, the failing heuristic GC policies due to the oversight of the underlying memory hierarchy, and the lack of cross-layer co-design. Based on the observations, we demonstrate that the existing GC can achieve similar performance to the disaggregated GC by only tuning its policy to be aware of the memory layouts while showing much better robustness. The developers can benefit from our research by tuning their existing production GC, thus avoiding the time to develop and debug a dedicated collector for the new hardware.","volume":41,"issue":4,"firstpage":1230,"lastpage":1248,"year":2026,"type":"Regular Paper","research_area":["Data Center Systems & Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5560-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5560-3?year=2026&issue=4","affiliations":["Chinese Academy of Sciences","University of Chinese Academy of Sciences","Peking University","Shanghai Jiao Tong University"],"type_origin":"Article; Early Access"},{"doi":"10.1007/s11390-026-5377-8","title":"A Fine-Grained Analysis for Parallel Tasks with Spin-Locks Under Global Fixed-Priority Scheduling","authors":[{"last":"Chen","first":"Ze-Wei"},{"last":"Luo","first":"Hang"},{"last":"Zhou","first":"Zi-Qian"},{"last":"Yang","first":"Mao-Lin"},{"last":"Liao","first":"Yong"},{"last":"Lei","first":"Hang"}],"keywords":["real-time system","global scheduling","blocking analysis","spin-lock","linear programming"],"abstract":"The synchronization of parallel tasks is critical for the schedulability of multiprocessor real-time systems. While non-preemptive spin-locks are widely adopted for their simplicity, analyzing the worst-case blocking time under more dynamic global scheduling remains challenging. The primary difficulty stems from transitive delays induced by non-preemptive busy-waiting, and existing techniques relying on the traditional coarsegrained resource model can be pessimistic. This paper presents an improved blocking analysis framework for parallel tasks under global fixed-priority (GFP) scheduling. Our approach incorporates a fine-grained resource model that explicitly accounts for both per-request lengths and request allocations. By leveraging a bi-directional bounding technique within a linear programming formulation, the proposed analysis framework ensures a tighter bound on transitive delay and achieves the property of inflation-freeness. Evaluations on randomly generated task sets demonstrate that the proposed analysis framework outperforms state-of-the-art approaches in terms of schedulability.","volume":41,"issue":4,"firstpage":1249,"lastpage":1261,"year":2026,"type":"Regular Paper","research_area":["Real-Time & Embedded Systems","Scheduling & Resource Allocation","Optimization & Heuristic Methods"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5377-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5377-8?year=2026&issue=4","affiliations":["University of Electronic Science & Technology of China"],"type_origin":"Article; Early Access"},{"doi":"10.1007/s11390-026-5768-x","title":"A Systematic Survey of Cross-Domain Data Sharing Architectures","authors":[{"last":"Zhang","first":"Ning"},{"last":"Sun","first":"Lan-Qi"},{"last":"Cheng","first":"Jin-Xi"},{"last":"Jing","first":"Xiang"},{"last":"Liu","first":"Tian-Cheng"},{"last":"Huang","first":"Gang"},{"last":"Luo","first":"Chao-Ran"}],"keywords":["cross-domain data sharing","data architecture","data sovereignty","Internet of Data (IoD)","International Data Spaces (IDS)"],"abstract":"Driven by the increasing complexity of data ecosystems and growing demands for data sovereignty, effective cross-domain architectures have become essential for global interoperability. This survey traces the evolution of these architectures from traditional databases to emerging paradigms, revealing a trajectory toward data-centric, decentralized, and user-oriented systems that prioritize trust and data sovereignty. This survey yields three primary findings. First, it constructs a comprehensive technical lineage of eight representative architectures, providing a structured comparative framework that is often absent in prior surveys. Second, it reveals a paradigm shift from “compute-centric” rigid integration to “data-centric” autonomous collaboration, as well as a transition from “performance-first” to “experience-first” user-centric systems. Third, this survey demonstrates that while security is evolving toward comprehensive data trustworthiness, considerable challenges remain, particularly regarding semantic alignment across heterogeneous domains and policy enforcement complexity in decentralized governance. By synthesizing these findings, this survey highlights research directions for balancing autonomy and standardization in future global data infrastructures.","volume":41,"issue":4,"firstpage":1262,"lastpage":1283,"year":2026,"type":"Survey","research_area":["Databases & Query Processing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5768-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5768-x?year=2026&issue=4","affiliations":["Xidian University","National Key Laboratory of Data Space Technology and System","Advanced Institute of Big Data","Peking University"],"type_origin":"Survey"},{"doi":"10.1007/s11390-026-5943-0","title":"Learning Code Anomalies for Bug Detection with Graph Neural Networks","authors":[{"last":"Zhang","first":"Chi"},{"last":"Wang","first":"Yu"},{"last":"Wang","first":"Ke"},{"last":"Wang","first":"Lin-Zhang"}],"keywords":["anomaly detection","graph neural network (GNN)","bug detection"],"abstract":"This paper proposes Adl, a neural network based approach that learns to detect bugs as anomalies. Compared with the classical anomaly detection approach, Adl eliminates the need for designing rule templates. Furthermore, Adl can generalize to bug types unseen during training. It also outperforms existing learning-based bug detectors in sample efficiency (i.e., requiring less training data) and self-explainability (i.e., explaining its predictions without external interpretability methods). An extensive evaluation of Adl shows that 1) Adl achieves significantly higher accuracy than Gated Graph Neural Network (GGNN) and Graph Interval Neural Network (GINN), two notable deep bug detection models, on two existing bug datasets (i.e., Bugs.jar and BugSwarm); 2) on Defects4J, Adl outperforms Infer, a prominent static analysis tool, and FICS, the latest anomaly detection method; and 3) on JBench, Adl surpasses RacerD—a state-of-the-art static race detector—without prior training on concurrent programs.","volume":41,"issue":4,"firstpage":1284,"lastpage":1301,"year":2026,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Graph Neural Networks","Software Testing & Analysis"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5943-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5943-0?year=2026&issue=4","affiliations":["Nanjing University","Tsinghua University"],"type_origin":"Regular Paper"},{"doi":"10.1007/s11390-026-5760-5","title":"NeSPCGC: Neighborhood-Scene Joint LiDAR Point Cloud Geometry Compression","authors":[{"last":"Han","first":"Cheng-Feng"},{"last":"Zhang","first":"Jun-Zhe"},{"last":"Yao","first":"Jie"},{"last":"Yu","first":"Guo-Sheng"},{"last":"Ding","first":"Dan-Dan"}],"keywords":["geometry compression","light detection and ranging (LiDAR) point cloud","lossless coding","probability prediction"],"abstract":"To meet the high efficiency compression demand of light detection and ranging (LiDAR) point cloud data, this paper proposes NeSPCGC, a neighborhood-scene joint point cloud geometry compression method based on a multiscale architecture. In contrast to previous voxel- and octree-based models which are limited to local receptive fields, NeSPCGC leverages the inherent characteristics of LiDAR point clouds by jointly capturing local neighborhood correlations and scene-level structural consistency, achieving more efficient and effective compression. Specifically, NeSPCGC introduces an inter-scale occupancy-guided prior generation (POG) unit, which transforms occupancy values from the lower scale into informative features that serve as priors for the current scale. Furthermore, to enhance intra-scale prediction, NeSPCGC employs a joint prediction (JOP) unit comprising two complementary branches: Neighborhood Feature Extractor (NFE), which captures local spatial correlations in 3D (three dimensional) space, and Scene Feature Extractor (SFE), which perceives global structural information from the projected 2D (two dimensional) range image. The features from both branches are then fused to form a comprehensive representation of the point cloud for occupancy probability prediction. Extensive experiments demonstrate that NeSPCGC achieves BD-BR (Bj & oslash;ntegaard Delta bitrate) gains of 35.64% and 34.62% over MPEG (moving pictures experts group) G-PCC (geometry point cloud compression) on the SemanticKITTI and Ford datasets, respectively, significantly outperforming state-of-the-art learning-based methods such as EHEM (an efficient hierarchical entropy model) and Unicorn, while delivering much faster coding speed.","volume":41,"issue":4,"firstpage":1302,"lastpage":1314,"year":2026,"type":"Regular Paper","research_area":["Computer Graphics & Visualization","Point Cloud & 3D Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5760-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5760-5?year=2026&issue=4","affiliations":["Hangzhou Normal University","T Head Semiconductor Co., Ltd."],"type_origin":"Article; Early Access"},{"doi":"10.1007/s11390-026-5683-1","title":"BDTM: A High-Performance Intelligent Transportation Information Transfer Model Based on Dynamic Adaptive Optimization Strategy","authors":[{"last":"Zheng","first":"Wen-Long"},{"last":"He","first":"Xiang"},{"last":"Li","first":"Peng"},{"last":"Xu","first":"He"},{"last":"Wu","first":"Jian"},{"last":"Qin","first":"Yi-Feng"}],"keywords":["Kafka","collaborative intelligent transportation system (C-ITS)","dynamic adaptive optimization","information transmission"],"abstract":"In recent years, collaborative intelligent transportation systems (C-ITS) have been developing rapidly, and the efficient real-time processing of massive amounts of C-ITS information has become a new challenge. An information transmission model based on message queuing telemetry transport (MQTT) bridging to Kafka is a feasible solution; however, it faces significant performance bottlenecks due to fluctuations in upstream traffic. To address this issue, we propose BDTM, a high-performance information transmission model for intelligent transportation systems based on a dynamic adaptive optimization strategy. BDTM utilizes an MQTT-Kafka bridging architecture, leveraging the Kafka connector to enhance system fault tolerance and horizontal scalability. Building upon the MQTT-Kafka bridging architecture, BDTM integrates two core technologies. First, we propose a weighted Latin hypercube sampling (wLHS) algorithm improved based on the concept of linear regression. By quantifying the relative importance (weights) of key Kafka parameters on throughput performance, the wLHS algorithm dynamically optimizes the sampling coverage of the high-dimensional parameter space, generating an optimal configuration knowledge base while reducing modeling complexity. Second, we propose a dynamic adaptive optimization strategy based on the Autoregressive Integrated Moving Average (ARIMA) model for traffic forecasting. This strategy monitors and forecasts upstream Kafka traffic in real time and dynamically adjusts Kafka resource allocation based on the forecast results, achieving a precise match between computing resource supply and traffic demand. Experiments show that BDTM achieves a communication throughput increase of more than 20% compared with the original model, while reducing communication latency by more than 30%. Therefore, BDTM offers significant advantages in overall performance.","volume":41,"issue":4,"firstpage":1315,"lastpage":1330,"year":2026,"type":"Regular Paper","research_area":["Optimization & Heuristic Methods"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5683-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5683-1?year=2026&issue=4","affiliations":["Nanjing University of Posts and Telecommunications","Jiangsu High Technology Research Key Laboratory for Wireless Sensor Networks"],"type_origin":"Regular Paper"},{"doi":"10.1007/s11390-026-0003-3","title":"A Processor Approach to Fast Fully Homomorphic Encryption","authors":[{"last":"Xu","first":"Zhi-Wei"}],"keywords":[],"abstract":"","volume":41,"issue":3,"firstpage":843,"lastpage":844,"year":2026,"type":"Perspective","research_area":["Cryptographic Hardware","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-0003-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-0003-3?year=2026&issue=3","affiliations":["Great Bay University"],"type_origin":"Editorial Material","cover_doi":"10.1007/s11390-026-5125-0","topic_source":"cover_inherited"},{"doi":"10.1007/s11390-026-5125-0","title":"Homomorphic Processing Unit","authors":[{"last":"Yang","first":"Ying-Hao"},{"last":"Xu","first":"Xi-Cheng"},{"last":"Lu","first":"Hang"},{"last":"Li","first":"Xiao-Wei"}],"keywords":["fully homomorphic encryption (FHE)","Homomorphic Processing Unit (HPU)","privacy computing"],"abstract":"Fully homomorphic encryption (FHE) enables computation over encrypted data without decryption, ensuring data confidentiality throughout the processing pipeline. However, the complexity and heterogeneity of FHE schemes like CKKS, BFV, and TFHE pose challenges for unified hardware design. In this paper, we propose the Homomorphic Processing Unit (HPU), a general-purpose platform supporting multiple FHE schemes. Unlike fixed-function accelerators, HPU is implemented as a RISC-V extension and introduces a dedicated homomorphic instruction set architecture (H-ISA), comprising micro-instructions for minimal compute kernels and macro-instructions for integration with general-purpose models. Core operations like the number-theoretic transform (NTT) and automorphism are abstracted into a unified instruction layer, mapped onto specialized homomorphic compute units. HPU integrates a collaborative computation and storage design, utilizing a polynomial-level instruction set and a polynomial-granular memory management unit (MMU) to optimize memory and reduce data movement. By combining a complete ISA with a general-purpose computing core, HPU can achieve efficient computing, control, and scheduling. We evaluate the HPU prototype using four multi-FHE benchmarks on field-programmable gate array (FPGA) and 7 nm ASIC. The key results are as follows. 1) HPU achieves up to 1596x and 1174x speedup over CPU for CKKS-like and TFHE operations, respectively. 2) Compared with SOTA FPGA solutions for CKKS and TFHE, HPU achieves 1.36x and 1.2x improvement, respectively. 3) HPU's ASIC implementation achieves 1.36x speedup over state-of-the-art TFHE accelerators for long short-term memory (LSTM).","volume":41,"issue":3,"firstpage":845,"lastpage":861,"year":2026,"type":"Regular Paper","research_area":["Cryptographic Hardware","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5125-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5125-0?year=2026&issue=3","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-6220-y","title":"Dual-Level Adaptive Correction for Subgraph-Based GNN Training with Efficient Strategy Search","authors":[{"last":"Liu","first":"Ding-Wei"},{"last":"Wang","first":"Zhao-Hua"},{"last":"Zhang","first":"Zhi-Bin"},{"last":"Yan","first":"Jin"},{"last":"Li","first":"Zhen-Yu"}],"keywords":["graph neural network (GNN)","subgraph sampling","correction"],"abstract":"Graph neural networks have achieved remarkable performance across a wide range of complex graph-based tasks. While subgraph sampling (SS) methods substantially improve per-epoch efficiency for large graphs, they introduce higher gradient variance, which hinders convergence and reduces accuracy. Moreover, applying corrections to reduce SS variance impact faces the issue of diminishing returns, thereby limiting training efficiency. To address these challenges, we propose ECHO+, a novel dual-level correction framework designed to accelerate training while maintaining accuracy comparable to that of node sampling. ECHO+ employs a lightweight, variance-guided strategy search during preprocessing to reduce SS variance. During training, it operates on two levels: a coarse level that adaptively schedules correction to reduce residual SS variance, and a fine level that leverages a batch-loss driven early stopping mechanism to improve overall training efficiency. Experimental results reveal that ECHO+ achieves rapid convergence with high accuracy, delivering a speedup of up to 12.4x over the node sampling baseline while maintaining comparable performance. Furthermore, ECHO+ outperforms existing SS baselines, achieving up to 4.3x faster convergence.","volume":41,"issue":3,"firstpage":862,"lastpage":875,"year":2026,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Graph Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6220-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6220-y?year=2026&issue=3","affiliations":["Chinese Academy of Sciences","University of Chinese Academy of Sciences","China Internet Network Information Center"],"type_origin":"Regular Paper"},{"doi":"10.1007/s11390-025-5191-8","title":"Quote from Similars: Aspect Sentiment Triplet Extraction with Hierarchical Inter-Sentence Information Retrieval","authors":[{"last":"Yu","first":"Guo-Xin"},{"last":"Ao","first":"Xiang"},{"last":"Li","first":"Ji-Wei"},{"last":"Yu","first":"Yue"},{"last":"Luo","first":"Ping"}],"keywords":["aspect sentiment triplet extraction","inter-sentence information retrieval","corpus-enhanced graph"],"abstract":"Discovering possible candidate elements and capturing their connections to form the output triplets constitute the core challenge of aspect sentiment triplet extraction (ASTE). However, the information encapsulated by prevailing methods within a solitary sentence may often prove insufficient, particularly in complex scenarios characterized by uncommon aspect, opinion terms or intricate syntax patterns. To mitigate these limitations, we advocate incorporating inter-sentence information retrieval to enrich intra-sentence representations within ASTE. One existing study has proposed a method dubbed Retrieval-Based Aspect Sentiment Triplet Extraction via Label Interpolation (RLI), which retrieves triplets from the corpus to augment the representations of a candidate aspect-opinion pair and further improve sentiment prediction. Nevertheless, obtaining data with standard triplets might be challenging in practice. Therefore, we propose an approach, namely Multi-Task ASTE with the Corpus-Enhanced Graph (MACG), to conduct sentence-level retrieval and extract helpful information from unlabeled similar sentences. Specifically, we design a corpus-level enhanced graph to capture inter-sentence information, alongside a local graph preserving intra-sentence information. A graph neural network is subsequently employed to adaptively learn enhanced representations of the target sentence for ASTE. RLI and MACG collaboratively form a comprehensive methodological framework, which is effective in both scenarios with and without standard triplet labels. Extensive experiments on two benchmarks demonstrate the superiority and flexibility of retrieving inter-sentence information, which underscores their potential to advance ASTE by leveraging neighboring information.","volume":41,"issue":3,"firstpage":876,"lastpage":895,"year":2026,"type":"Regular Paper","research_area":["Sentiment Analysis & Opinion Mining"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5191-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5191-8?year=2026&issue=3","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","Peng Cheng Laboratory","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5356-5","title":"NR-CLIP: CLIP-Guided Multimodal News Recommendation via Multi-View Learning","authors":[{"last":"Guo","first":"Ying"},{"last":"Hu","first":"Shu-Ting"},{"last":"Yu","first":"Min-Jing"},{"last":"Yi","first":"Ran"},{"last":"Wang","first":"Qi"},{"last":"Liu","first":"Jie"},{"last":"Liu","first":"Yong-Jin"}],"keywords":["multimodal news recommendation","multi-view learning","multimodal learning","Contrastive Language-Image Pretraining (CLIP)"],"abstract":"In the era of social media, the evolution of news has diversified its format, incorporating texts, images, and videos. However, the majority of news recommendation methods focus solely on text data, overlooking the substantial role of news images. This paper introduces a news recommendation method based on CLIP (Contrastive Language-Image Pretraining), NR-CLIP, which is a CLIP-guided algorithm with enhanced multimodal news recommendation via multi-view learning. Specifically, our method employs a CLIP encoder to embed textual and visual information into the same feature space of neural networks, where a unified news textual representation is learned by treating titles, categories, subcategories, and bodies as different views of news. In addition, feature enhancements are applied to fully fuse textual and visual features. Finally, click history and user representations are embedded to predict the click probability of candidate news. Extensive comparisons and in-depth analyses with state-of-the-art news recommendation methods have been presented on V-MIND (Visual Microsoft News Dataset), which provides the visual information on the basis of the classic MIND (Microsoft News Dataset), demonstrating that our proposed method effectively improves the performance of news recommendation.","volume":41,"issue":3,"firstpage":896,"lastpage":909,"year":2026,"type":"Regular Paper","research_area":["Recommendation Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5356-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5356-5?year=2026&issue=3","affiliations":["North China University of Technology","Tsinghua University","Tianjin University","Shanghai Jiao Tong University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5518-5","title":"Complexity-Constraint Code Evaluation: A Benchmark for Time Complexity Compliance in LLM-Generated Code","authors":[{"last":"Chen","first":"Li-Guo"},{"last":"Wang","first":"Xin"},{"last":"Chen","first":"Jue-Yu"},{"last":"Liang","first":"Ren-Zhao"},{"last":"Zeng","first":"Zheng-Ran"},{"last":"Li","first":"Yang-Ning"},{"last":"Li","first":"Ying-Hui"},{"last":"Wang","first":"Yi-Dong"},{"last":"Xu","first":"Yi-Jiang"},{"last":"Gao","first":"Qing"},{"last":"Zhang","first":"Shi-Kun"}],"keywords":["large language model for code (Code LLM)","code evaluation","benchmark dataset","time complexity constraint"],"abstract":"While large language models for code (Code LLMs) excel at generating functionally correct code, existing benchmarks neglect a crucial aspect: adherence to explicit time complexity constraints. We introduce the Complexity-Constraint Code Evaluation (C3E), a novel benchmark evaluating both functional correctness and complexity compliance across feasible and infeasible scenarios. C3E enables precise differentiation between asymptotic complexity classes and tests model robustness against theoretically impossible constraints. Our proposed Complexity Alignment Score (CAS) integrates correctness and complexity adherence into a unified metric, assessed through theoretical analysis rather than costly executions. Experiments reveal a striking gap in state-of-the-art models: GPT-4o achieves 81% correctness but only 31% CAS, demonstrating poor complexity compliance. Notably, most models fail to recognize infeasible constraints except advanced ones such as GPT-4o. These findings underscore the necessity for complexity-aware evaluation, positioning C3E as an essential tool for advancing real-world coding reliability in Code LLMs. The C3E benchmark is available at .","volume":41,"issue":3,"firstpage":910,"lastpage":923,"year":2026,"type":"Regular Paper","research_area":["LLM Evaluation & Benchmarking"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5518-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5518-5?year=2026&issue=3","affiliations":["Peking University","Beihang University","Tsinghua University"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-5705-z","title":"Safety Evaluation for Large Language Models with Metamorphic Testing: An Empirical Study","authors":[{"last":"Xing","first":"Ying"},{"last":"Huang","first":"Jia-Qi"},{"last":"Zhao","first":"Hai-Jiao"},{"last":"Zhang","first":"Long"},{"last":"Li","first":"Wen-Jin"}],"keywords":["large language model","safety evaluation","metamorphic testing"],"abstract":"Although large language models (LLMs) have been widely deployed across numerous applications, they can generate harmful or illicit content, posing substantial safety risks. Evaluating such risks requires effective evaluation methodologies using high-quality benchmarking datasets. This study introduces LLMSafety-Choice in this regard, a multilingual benchmark for content safety evaluation containing 11 911 multiple-choice questions in both Chinese and English, covering four safety domains and eight categories per language (nine in total). We further introduce a systematic metamorphic-testing approach, defining seven metamorphic relations for LLMSafetyChoice, for LLM safety evaluations. Through an extensive empirical study involving 1 408 evaluation scenarios (11 LLMs & times;(8 categories & times;2 languages)& times;(1 constructed benchmark + 7 transformations)), we reveal key insights into model behavior under safety-critical conditions and demonstrate that metamorphic testing effectively uncovers subtle safety vulnerabilities. The benchmark and evaluation results are publicly available at .","volume":41,"issue":3,"firstpage":924,"lastpage":935,"year":2026,"type":"Regular Paper","research_area":["LLM Evaluation & Benchmarking"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5705-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5705-z?year=2026&issue=3","affiliations":["Beijing University of Posts & Telecommunications"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-5762-3","title":"MSCFN: Multiscale Spatial-Frequency Collaborative Fusion Network for Multicontrast Magnetic Resonance Imaging Super-Resolution","authors":[{"last":"Huang","first":"Shu-Ying"},{"last":"Huang","first":"Xue-Ying"},{"last":"Yang","first":"Yong"},{"last":"Wang","first":"Xiao-Zheng"},{"last":"Ren","first":"Heng"},{"last":"Niu","first":"Yu-Fan"}],"keywords":["magnetic resonance imaging","super-resolution","multicontrast","collaborative learning"],"abstract":"Magnetic resonance imaging (MRI) can generate images with varying contrasts and acquisition times depending on imaging parameters. Utilizing a high-resolution contrast with a short acquisition time as a reference for the super-resolution (SR) of low-resolution contrasts with long acquisition times is effective for the rapid acquisition of high-quality images. However, existing methods mainly process features in the spatial domain, and overlook potential features in the frequency domain. This paper proposes Multiscale Spatial-Frequency Collaborative Fusion Network (MSCFN), which jointly leverages information in the spatial and frequency domains for SR. A global-local fusion block optimizes global structural features and local texture details at different scales, and an adaptive low-high frequency fusion module utilizes the complementary nature of multiple contrasts to decompose reference images into high- and low-frequency components and adaptively fuse them to enhance feature integration. Experimental results indicate that MSCFN outperforms existing multicontrast MRI SR methods. The code is publicly available at \n                https://github.com/crystal177/MSCFN\n                \n              .","volume":41,"issue":3,"firstpage":936,"lastpage":946,"year":2026,"type":"Regular Paper","research_area":["Bioinformatics & Life Sciences","Computer Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5762-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5762-3?year=2026&issue=3","affiliations":["Tiangong University","Xiamen University of Technology"],"type_origin":"Regular Paper"},{"doi":"10.1007/s11390-026-5756-1","title":"AWGT-Benchmark: An Air-Writing Benchmark Supporting Cross-Scenario Text Recognition","authors":[{"last":"Jin","first":"Yi-Heng"},{"last":"Wu","first":"Jia-Zheng"},{"last":"Li","first":"Jian-Guang"},{"last":"Liu","first":"Wu"},{"last":"An","first":"Shan"}],"keywords":["air-writing","benchmark dataset","multilingual","multigranularity","video-based text recognition"],"abstract":"We introduce the Air-Writing General Text Benchmark, termed AWGT-Benchmark (AWGT), a video-based, multilingual, and multigranularity dataset designed to advance air-writing text recognition (AWTR) across diverse scenarios. Although AWGT bridges the gap between conventional text recognition and AWTR scenarios, it also poses new challenges for computer vision and natural language processing. AWGT comprises 226 648 video frames across four subsets in Chinese and English, with finger-writing trajectories captured using RGB cameras in real-world scenarios to ensure realism and diversity. Based on AWGT, we propose a two-stage recognition framework that first extracts finger motion trajectories and subsequently converts them into trajectory images for character recognition. This design effectively suppresses background noise and emphasizes structural character details. Experimental results on AWGT show that widely used text recognition models suffer substantial performance degradation when applied to air-writing tasks, highlighting their limited ability to handle dynamic finger movements and cluttered visual contexts. AWGT provides a unified evaluation protocol and an experimental baseline, reveals key limitations of existing methods, and offers insights for developing more robust and adaptable cross-scenario recognition systems. Furthermore, it contributes to advancing research in intelligent human-computer interaction. The dataset is made publicly available to facilitate future research: .","volume":41,"issue":3,"firstpage":947,"lastpage":960,"year":2026,"type":"Regular Paper","research_area":["Computer Vision","Human-Computer Interaction"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5756-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5756-1?year=2026&issue=3","affiliations":["Shanghai Normal University","Tianjin University","Chinese Academy of Sciences","University of Science & Technology of China, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-5767-y","title":"RagMedge: Dense Retrieval Augmented Medical Dialogue Generation Towards Personalized Medical Knowledge Grounded Diagnosis","authors":[{"last":"Lyu","first":"Bo"},{"last":"Tang","first":"Chen"},{"last":"Yu","first":"Guo-Xin"},{"last":"Liu","first":"Na-Yu"},{"last":"Yu","first":"Yue"}],"keywords":["retrieval augmented generation","medical dialogue generation","natural language generation","dataset construction"],"abstract":"To develop a medical generative system, current research has primarily focused on integrating medical knowledge into language models (LMs) through training them on medical corpora or incorporating external medical resources, such as knowledge graphs and terminologies. However, approaches rely on implicit knowledge integration from textual narratives or standardized knowledge sources (e.g., Unified Medical Language System), making the acquired knowledge opaque and difficult to control during inference. This lack of transparency limits the traceability of knowledge accumulated from historical training data. To address these limitations, we propose constructing a personalized medical knowledge base that extracts discrete knowledge points from real doctor-patient dialogues and encodes them as semantically condensed vectors. Building on this, we introduce a novel dense retrieval-augmented medical dialogue generation framework, called RagMedge, which retrieves relevant knowledge embeddings conditioned on the input context and incorporates them into response generation. Experimental results demonstrate that RagMedge achieves state-of-the-art performance, highlighting the effectiveness of leveraging personalized medical knowledge for improved dialogue generation.","volume":41,"issue":3,"firstpage":961,"lastpage":976,"year":2026,"type":"Regular Paper","research_area":["Bioinformatics & Life Sciences","Text Generation & Dialogue"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5767-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5767-y?year=2026&issue=3","affiliations":["Chinese Academy of Sciences","Pengcheng Laboratory","University of Chinese Academy of Sciences","The University of Manchester"],"type_origin":"Regular Paper"},{"doi":"10.1007/s11390-025-5524-7","title":"CroFinBen: A Multilingual Benchmark of Large Language Models Across High- and Low-Resource Languages in Finance","authors":[{"last":"Hu","first":"Gang"},{"last":"Lyu","first":"Si-Qi"},{"last":"Wang","first":"Qing-Qing"},{"last":"Huang","first":"Ze-Kang"},{"last":"Qin","first":"Ke"},{"last":"Peng","first":"Min"},{"last":"Yue","first":"Kun"}],"keywords":["low-resource language","financial large language model (FinLLM)","multilingual benchmark"],"abstract":"Recent advancements in financial large language models (FinLLMs) have shown strong performance in high-resource languages like English and Chinese, but are limited in low-resource settings, particularly in Southeast Asia (SEA), where labeled data resources are extremely scarce and challenging to annotate. Existing benchmarks primarily focus on high-resource finance, neglecting low-resource finance. To address these issues, we introduce CroFinBen, to the best of our knowledge, the first multilingual benchmark specifically designed to bridge the language-resource gap between high- and low-resource finance. It includes four key financial NLP tasks-financial sentiment analysis (FinSA), financial stock prediction (FinSP), financial text summarization (FinTS), and financial text classification (FinTC)-across both high-resource languages (English and Chinese) and low-resource Southeast Asian (SEA) languages (Indonesian, Malay, Thai, Filipino, and Vietnamese), comprising over 50 000 samples from 16 datasets, providing a comprehensive and balanced evaluation of LLMs. Unlike others that rely on full translations or overlook local context, CroFinBen incorporates localized annotations to reflect financial terms and cultural nuances in SEA languages. Evaluating 25 LLMs shows significant performance differences, with no clear proficiency in either high- or low-resource languages, especially for existing language-biased fine-tuned FinLLMs. The 1800B large-parameter closed-source GPT-4o excels, while DeepSeek-V3 and ChatGPT-3.5 also perform well. By bridging language-resource barriers, CroFinBen enhances the fairness and robustness of FinLLMs, providing strong support for improving performance in global financial scenarios. Our data resources are available at .","volume":41,"issue":3,"firstpage":977,"lastpage":992,"year":2026,"type":"Regular Paper","research_area":["LLM Evaluation & Benchmarking"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5524-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5524-7?year=2026&issue=3","affiliations":["Yunnan University","Wuhan University"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-5659-1","title":"HI-SM4: Exploiting Domestic Hygon DCU for High-Performance SM4 Cryptographic Computing","authors":[{"last":"Chen","first":"Fu-Yuan"},{"last":"Dong","first":"Jian-Kuo"},{"last":"Wang","first":"Xing-Yu"},{"last":"Dong","first":"Zhen-Jiang"},{"last":"Wang","first":"Hua-Qun"}],"keywords":["SM4","deep-learning computing unit (DCU)","cryptographic engineering"],"abstract":"With the rapid rise of domestic accelerators and the growing demand for efficient cryptographic algorithm implementations, optimizing the performance of domestic commercial cryptography on homegrown hardware platforms has become a critical research challenge. This paper focuses on utilizing the Chinese Hygon Deeplearning Computing Unit (DCU) as an acceleration platform and proposes a high-performance SM4 encryption implementation. First, we design a collaborative CPU/DCU computing framework, where the CPU handles task scheduling while the DCU performs parallel execution of computationally intensive tasks. Additionally, we leverage the data copy engine of the DCU and employ HIP (heterogeneous-computing interface for portability) stream-based data transmission to enhance computational efficiency. Second, we propose an optimized hierarchical memory access strategy by merging multiple sets of computational data for unified transfer and employing a hierarchical storage scheme based on data characteristics to improve memory access efficiency. Furthermore, we employ GCN (Graphics Core Next) ISA (Instruction Set Architecture) inline assembly to achieve constant-time computation, which enhances both security and computational performance. Finally, we support both single-key and multi-key encryption modes, optimizing memory access and parallel computation for each. The experimental results show that our optimized SM4 implementation HI-SM4 achieves a throughput of 161.81 Gbps in the multikey encryption mode and up to 730.88 Gbps in the single-key encryption mode. Compared with the best existing SM4 implementations on CPU, FPGA, and GPU platforms, our approach achieves performance improvements of 28.22x, 4.50x, and 1.36x, respectively. Our research presents a feasible framework for efficiently implementing indigenous cryptographic algorithms on domestically developed hardware accelerators, thereby contributing to the advancement of high-performance cryptographic computation.","volume":41,"issue":3,"firstpage":993,"lastpage":1008,"year":2026,"type":"Regular Paper","research_area":["Cryptographic Hardware","GPU & Accelerator Architecture","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5659-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5659-1?year=2026&issue=3","affiliations":["Nanjing University of Posts & Telecommunications","Chinese Academy of Sciences","University of Science & Technology of China, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5111-y","title":"Cholesky Parallel Decomposition Optimization Algorithm Based on ScaLAPACK","authors":[{"last":"Xu","first":"He"},{"last":"Zhou","first":"Tao"},{"last":"Li","first":"Peng"},{"last":"Qin","first":"Fang-Fang"},{"last":"Ji","first":"Yi-Mu"}],"keywords":["scalable linear algebra package (ScaLAPACK)","Cholesky","parallel computing","math kernel library"],"abstract":"The scalable linear algebra package (ScaLAPACK) is a critical library for parallel computing on distributed-memory systems, enabling the development of numerous scientific applications that depend on robust linear algebra operations. However, for specific computations such as the Cholesky decomposition, the native ScaLAPACK routines are not communication-optimal and fail to fully leverage the capabilities of modern parallel architectures. This paper proposes the Parallel Cholesky Factorization (PCF) optimization algorithm designed to address these limitations within the ScaLAPACK framework. The PCF algorithm enhances performance and load balancing by strategically differentiating data partitions across processes. It involves a temporary redistribution of computational workloads to a root process, which performs a concentrated calculation before redistributing the results. This approach ensures a more balanced utilization of CPU resources. Experimental evaluation is conducted on both Intel and Kunpeng processor platforms. The first set of experiments demonstrates that the PCF algorithm achieves an average performance improvement of 30% over the native ScaLAPACK algorithm on the Intel platform under optimized process and thread configurations. The second comparative experiment shows that the PCF algorithm on the Kunpeng platform achieves an average computational efficiency increase of 200% and 50% under different thread configurations, respectively, significantly outperforming the Intel math kernel library (MKL) on the Intel platform. These results confirm that the proposed optimization effectively enhances performance and portability across diverse modern computing environments.","volume":41,"issue":3,"firstpage":1009,"lastpage":1023,"year":2026,"type":"Regular Paper","research_area":["High-Performance & Parallel Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5111-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5111-y?year=2026&issue=3","affiliations":["Nanjing University of Posts & Telecommunications"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-6073-4","title":"Containerlet: Software-Granular Container Layer for High-Performance Deployment of Machine Learning Applications","authors":[{"last":"Li","first":"Feng-Zhi"},{"last":"Xu","first":"Qing-Ru"},{"last":"Zhou","first":"Tuo"},{"last":"Wang","first":"Chen-Xi"},{"last":"Wang","first":"Yi-Fan"},{"last":"Peng","first":"Xiao-Hui"}],"keywords":["container deployment","container image","container scheduling","machine learning"],"abstract":"Large-scale machine learning (ML) clusters deploy hundreds of models packaged as large container images, making scheduling and image pulling dominant contributors to deployment latency. Current systems adopt a hybrid-granularity strategy: they schedule using image-level metadata, reuse on-node layer caches, and lazily fetch content at the file or chunk level. This fragmentation leads to suboptimal cross-image reuse. We show that an intermediate unit, software granularity, can be uniformly applied at scheduling, caching, and pulling to improve deployment performance. We present Containerlet, a software-scoped layer that reorganizes standard images into one private layer plus multiple reusable per-software units that reside in compatible registries and are pulled by unmodified runtimes. Containerlet promotes cross-image reuse while bounding the number of units that the scheduler must consider. We design a file backtracking method to convert standard images into Containerlet images, which includes one private layer and multiple Containerlets. We also extend Kubernetes and container runtime to support software-granular scheduling, caching, and lazy pulling. End-to-end deployment experiments on diverse ML images and production cluster traces show consistent gains, reducing deployment overhead by 18% compared with state-of-the-art systems.","volume":41,"issue":3,"firstpage":1024,"lastpage":1035,"year":2026,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Scheduling & Resource Allocation"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6073-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6073-4?year=2026&issue=3","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-5995-1","title":"Double Auction Mechanism for Heterogeneous Computility Network Task Scheduling","authors":[{"last":"Zhang","first":"Ji-Xian"},{"last":"Yang","first":"Xun"},{"last":"Zhang","first":"Xing-Zhou"},{"last":"Wu","first":"Hao"},{"last":"Li","first":"Wei-Dong"}],"keywords":["computility network","computility pricing","double auction","task scheduling","mechanism design"],"abstract":"Computility networks (CNs) enable large-scale computation scheduling and have emerged as a new computing paradigm. CNs have a broader service scope and more complex infrastructure than cloud and edge computing. Consequently, resource allocation and task scheduling in CNs face numerous challenges, such as unifying diverse computility resources in existing heterogeneous clouds, adequately incorporating network resource providers within the CN framework, and pricing computility resources. In this study, first, we extract computility and network resources to construct a task scheduling model for CNs. To maximize the number of tasks successfully scheduled, we represent this problem as a mixed-integer programming model that involves multiple roles, tasks, and resource constraints. Unlike most approaches, we explicitly incorporate network resource providers into the model. Second, we propose a double auction mechanism named Computility Double Auction (Computility_DA) to address the task scheduling problem in CNs. Specifically, we derive feasible solutions for task scheduling and network flow using optimization methods and then determine the final winners and payment pricing solution based on matching theory. Furthermore, we demonstrate that the proposed mechanism has economic properties such as individual rationality, truthfulness, and budget balance. Experimental results demonstrate that compared with existing algorithms, Computility_DA significantly increases the number of scheduled tasks and the utility and revenue for participants.","volume":41,"issue":3,"firstpage":1036,"lastpage":1053,"year":2026,"type":"Regular Paper","research_area":["Cloud, Edge & Utility Computing","Game Theory & Mechanism Design","Scheduling & Resource Allocation"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5995-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5995-1?year=2026&issue=3","affiliations":["Yunnan University","Chinese Academy of Sciences","Institute of Computing Technology, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5093-9","title":"A Progressive Quasi-Bounding Method and Its Applications to Boundary Value Problems","authors":[{"last":"Chen","first":"Hong-Yu"},{"last":"Chen","first":"Xiao-Diao"},{"last":"Ma","first":"Wei-Yin"}],"keywords":["boundary value problem","convergence rate","curve design","iterative method","quasi-bounding method"],"abstract":"Boundary value problems (BVPs) have wide applications in computer graphics and mechanical engineering. This paper presents a quasi-bounding method for progressively solving several boundary value problems, where initial solutions are easy to be obtained for rapidly solving the accurate solution. Given an equation F(u, t) = 0,t is an element of [a, b], and several boundary value constraints as well, two systems consisting of n + 1 equations are derived for rapidly searching two polynomials f n, 1(t) and f n, 2(t) of degree n, which satisfy F(f n, 1,t) <= 0 <= F(f n, 2, t),t is an element of [a, b] in the cases when certain conditions are satisfied. From the middle value theorem, the solution u star(t) is bounded by f n, 1(t) and f n, 2(t), t is an element of [a, b]. These two bounding polynomials f n, i(t), i = 1, 2, are taken as initial values for progressive refinements of approximation error in two ways, i.e., B-Spline form of the same degree with more knots, and B & eacute;zier form of a higher degree. Numerical experiments show that the new method can be applied to more generalized BVPs, and achieves better computational stability, much better approximation with less error and better computational efficiency than prevailing methods, even by using a small degree n.","volume":41,"issue":3,"firstpage":1054,"lastpage":1070,"year":2026,"type":"Regular Paper","research_area":["Computer Graphics & Visualization"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5093-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5093-9?year=2026&issue=3","affiliations":["Hangzhou Dianzi University","City University of Hong Kong"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-5448-x","title":"PPredictor: Workload-Aware Performance Prediction for Distributed Databases Using Graph Encoding","authors":[{"last":"Yang","first":"Jian-Wen"},{"last":"Zhang","first":"Qiu-Hong"},{"last":"Yan","first":"Jin"},{"last":"Zhang","first":"Shuo"},{"last":"Zhu","first":"Mei-Ling"},{"last":"Ding","first":"Zhi-Ming"}],"keywords":["performance prediction","analytical distributed database","multi-head graph attention network","AI4DB"],"abstract":"Predicting query performance is essential for database tasks such as resource allocation and scheduling. However, existing methods, designed for single-node systems, often fail in distributed analytical databases. This is because they overlook key features such as data partitioning, cross-node data transfer, and parallel query execution. To address these challenges, we propose a novel approach, PPredictor (Performance-Predictor), for predicting query performance in analytical distributed databases that is grounded in graph representation models. First, we introduce a graph model that encodes both data partitions and query execution plans within distributed databases. In this model, vertices represent partitioned tables, whereas edges capture their relationships, such as partitioned tables located on the same data node and data transfers between partitioned tables within an execution plan. Second, we present a prediction model that effectively uses a graph attention mechanism network to encode graph features and uses deep learning techniques for performance prediction. Third, considering dynamic workloads and various database environments, we introduce an incremental learning method based on feature replay. Extensive experiments conducted on real-world datasets demonstrate that our approach significantly outperforms state-of-the-art methods.","volume":41,"issue":3,"firstpage":1071,"lastpage":1086,"year":2026,"type":"Regular Paper","research_area":["Databases & Query Processing","High-Performance & Parallel Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5448-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5448-x?year=2026&issue=3","affiliations":["Chinese Academy of Sciences","Institute of Software, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-5122-3","title":"SEMQuant: A Computational Platform for Accurate and Comprehensive Quantitative Mewtaproteomics Analysis","authors":[{"last":"Zhang","first":"Bailu"},{"last":"Feng","first":"Shichao"},{"last":"Xiong","first":"Yi"},{"last":"Pan","first":"Chongle"},{"last":"Guo","first":"Xuan"}],"keywords":["label-free quantification","mass spectrometry","match-between-runs","metaproteomics"],"abstract":"Metaproteomics, utilizing high-throughput liquid chromatography-mass spectrometry (LC-MS), offers a profound understanding of microbial communities. Quantitative metaproteomics further enriches this understanding by measuring relative protein abundance and revealing dynamic changes under different conditions. However, the challenge of missing peptide quantification persists in metaproteomics analysis, particularly in data-dependent acquisition (DDA) mode, where high-intensity precursors for MS2 scans are selected. To tackle this issue, the match-between-runs (MBR) technique is used to transfer peptides between LC-MS runs. Inspired by the benefits of MBR and the need for streamlined metaproteomics data analysis, we develop SEMQuant, an end-to-end software integrating Sipros-Ensemble's robust peptide identifications with IonQuant's MBR function. The experiments show that SEMQuant consistently obtains the highest or second highest number of quantified proteins, with notable precision and accuracy. This demonstrates SEMQuant's effectiveness in conducting comprehensive and accurate quantitative metaproteomics analyses across diverse datasets and highlights its potential to propel advancements in microbial community studies. SEMQuant is freely available under the GNU GPL license at .","volume":41,"issue":3,"firstpage":1087,"lastpage":1100,"year":2026,"type":"Regular Paper","research_area":["Bioinformatics & Life Sciences"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5122-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5122-3?year=2026&issue=3","affiliations":["University of North Texas System","University of North Texas Denton","University of Oklahoma System","University of Oklahoma - Norman"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-0002-4","title":"The Preface","authors":[{"last":"Guo","first":"De-Ke"},{"last":"Peng","first":"Xiao-Hui"}],"keywords":[],"abstract":"","volume":41,"issue":2,"firstpage":473,"lastpage":474,"year":2026,"type":"Regular Paper","research_area":[],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-0002-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-0002-4?year=2026&issue=2","affiliations":["Sun Yat Sen University","Chinese Academy of Sciences"],"type_origin":"Editorial Material"},{"doi":"10.1007/s11390-025-5684-5","title":"MoFedNet: Semantic Link is All Models Need","authors":[{"last":"Chen","first":"Yi-Qiang"},{"last":"Jiang","first":"Xin-Long"},{"last":"Chen","first":"Qian"},{"last":"Yang","first":"Xiao-Dong"},{"last":"Li","first":"Jia-Hao"},{"last":"Zhang","first":"Teng"},{"last":"Qin","first":"Xin"},{"last":"Huang","first":"Wu-Liang"}],"keywords":["model collaboration","semantic link","distributed intelligence","task-driven orchestration"],"abstract":"The future of artificial intelligence (AI) systems lies in large-scale, heterogeneous agent collaboration to solve increasingly diverse and complex tasks. This collaborative paradigm promises greater flexibility and scalability but brings a fundamental challenge: how to balance collaboration efficiency with task quality. Existing Model Context Protocol (MCP) and Agent-to-Agent (A2A) architectures struggle to achieve this trade-off, facing either scalability bottlenecks or unstable coordination. To address these issues, we propose MoFedNet (Model Federalization Network), a novel semantic link-guided model collaboration system that integrates disparate models into a federated collective. MoFedNet features a dual-layer architecture with centralized monitoring and decentralized collaboration. Its core semantic link (SL) mechanism enables scalable, efficient, and dynamic collaboration among heterogeneous models while supporting intelligent task orchestration and network evolution. We enhance MoFedNet with three key modules. The Link-to-Link Semantic Protocol (L2L) organizes interactions over the hypergraph. The Contextual Memory Enhanced Retrieval Module (CoMER) introduces structured memory modules to store and retrieve representations across abstraction levels. The Evolutionary Local-global Optimization Module (EvoLOM) drives continuous improvement by accumulating memory and optimizing the hypergraph. We propose a novel quality-efficiency (QE) index to evaluate system performance. In a large-scale generic task simulation with over 15 000 nodes, MoFedNet achieves a QE score of 0.74, significantly outperforming the MCP and A2A approaches. Furthermore, when applied to a real-world medical task, MoFedNet attains a QE of 0.63, demonstrating clear superiority over existing multi-agent methods alongside stable temporal and spatial complexity.","volume":41,"issue":2,"firstpage":475,"lastpage":493,"year":2026,"type":"Regular Paper","research_area":["LLM Agents & Embodied Intelligence"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5684-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5684-5?year=2026&issue=2","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS","Ant Group"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5623-5","title":"Duba: Cost-Efficient Serverless Cloud-Edge Collaborative Machine Learning Serving with Dual-Batching","authors":[{"last":"Liao","first":"Jian-Xiong"},{"last":"Peng","first":"Jing"},{"last":"Zhou","first":"Zhi"},{"last":"Xu","first":"Fei"}],"keywords":["serverless","cloud-edge collaboration","machine learning"],"abstract":"The integration of edge and serverless cloud computing, which combines the low-latency advantages of edge processing with the cost efficiency and scalability of serverless cloud architectures, provides an ideal foundation for serving machine learning (ML) applications. While batching has demonstrated significant improvements in resource utilization through parallel execution, current approaches that independently optimize batching for edge or serverless cloud environments overlook their synergistic potential, leading to suboptimal end-to-end performance. To bridge this gap, we present Duba, a serverless cloud-edge collaborative system designed for cost-efficient ML serving. At its core, Duba introduces a novel dual-batching mechanism that harmonizes batching strategies across edge and serverless cloud environments. To implement this design, Duba combines lightweight configuration optimization with an adaptive scheduling policy, delivering substantial improvements in both cost efficiency and performance. Experimental results demonstrate that Duba consistently outperforms state-of-the-art systems, reducing serving costs by up to 74.1% and improving service-level objective (SLO) compliance by over 6.9%.","volume":41,"issue":2,"firstpage":494,"lastpage":505,"year":2026,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5623-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5623-5?year=2026&issue=2","affiliations":["Sun Yat Sen University","East China Normal University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5695-2","title":"DynaHyEdge: Fine-Grained Privacy-Aware Online Scheduling for Hybrid Edge Services","authors":[{"last":"Cheng","first":"Zi-Chen"},{"last":"Liao","first":"Han-Long"},{"last":"Luo","first":"Lai-Long"},{"last":"Ren","first":"Bang-Bang"}],"keywords":["edge computing","computing utility","privacy isolation","online scheduling","hybrid edge"],"abstract":"Edge clouds must increasingly co-serve privacy-critical streams (e.g., per-user telemetry and industrial control loops) and best-effort utility services (e.g., large language model inference and augmented-reality rendering) on the same constrained nodes to meet strict latency targets and sustain resource utilization. Operating them on disjoint server pools satisfies privacy requirements but leaves capacity restricted because private demand is substantial. Naive colocation improves utilization but cannot offer hard service-level agreements (SLAs) or data-residency guarantees. Hence, we propose DynaHyEdge, a hybrid scheduler that 1) continuously partitions capacity between private and public domains, 2) enforces per-core time isolation with microsecond domain flips, and 3) uses event-driven admission to utilize idle computational resources without preemption. This joint design maximizes on-time completion while provably meeting private-task SLAs, keeping sensitive data local, and reclaiming otherwise idle computational resources. Experiments on real-world and synthetic traces show that DynaHyEdge increases the deadline success rates, decreases the latency, and increases CPU utilization over greedy, fixed-partition, and earliest-deadline-first baselines without compromising privacy.","volume":41,"issue":2,"firstpage":506,"lastpage":519,"year":2026,"type":"Regular Paper","research_area":["Cloud, Edge & Utility Computing","Scheduling & Resource Allocation"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5695-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5695-2?year=2026&issue=2","affiliations":["National University of Defense Technology - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5554-1","title":"TCLI: A Triple-Cache Layer-Wise Inference System for Reducing Redundant Data Loading and Computation in Graph Neural Networks","authors":[{"last":"Luo","first":"Yi"},{"last":"Wang","first":"Yao-Bin"},{"last":"Song","first":"Ying-Chen"},{"last":"Xu","first":"Xiao-Hua"},{"last":"Tang","first":"Ping-Ping"}],"keywords":["graph neural network","triple cache","large graph","inference"],"abstract":"With the accelerated development of computility infrastructure, achieving efficient inference of graph neural networks (GNNs) on resource-constrained nodes has become a key challenge that limits the fine-grained scheduling and service-oriented utilization of computing resources. However, existing node-wise inference methods are simple but inefficient, especially when dealing with multi-hop neighbors, which can lead to redundant computation issues. This significantly increases computational overhead and becomes a bottleneck in the inference process. Additionally, the limited data transfer efficiency between host memory and GPU memory results in slow inference speed and underutilized resources. In this paper, we propose a tailored Triple-Cache Layer-wise Inference (TCLI) system for GNN tasks, designed to minimize redundant loading during the sampling process and redundant computation during the evaluation process, thus accelerating GNN inference. TCLI divides the idle GPU memory into three regions: adjacency matrix cache, node feature cache, and node embedding cache, which are used to accelerate sampling, feature loading, and computation, respectively. We also merge multiple mini-batches into a super-batch to maximize GPU hardware utilization. Furthermore, we customize a pipeline for our system to hide the data loading time during inference. Extensive experimental results show that TCLI achieves an average speedup of 10.40x over DGL and 10.24x over the state-of-the-art layer-wise inference system RAIN in end-to-end inference, with accuracy loss kept below 0.5%.","volume":41,"issue":2,"firstpage":520,"lastpage":532,"year":2026,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Graph Neural Networks","Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5554-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5554-1?year=2026&issue=2","affiliations":["Southwest University of Science & Technology - China","Chinese Academy of Sciences","University of Science & Technology of China, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5573-y","title":"Comprehensive Multistep Prefetching Strategy for Short Video Streaming","authors":[{"last":"Jiang","first":"Wan-Chun"},{"last":"Shan","first":"Yong-Xin"},{"last":"Hu","first":"Jin-Tian"},{"last":"Su","first":"Qi-Chen"},{"last":"Huang","first":"Jia-Wei"},{"last":"Wang","first":"Jian-Xin"}],"keywords":["short video","computility","quality of experience","bandwidth wastage","prefetching strategy"],"abstract":"The short video market is currently growing rapidly. As a typical bandwidth-intensive application, short video streaming can easily cause bandwidth bottlenecks in servers. Hence, we propose a prefetching strategy to improve the quality of experience (QoE) and reduce the wastage of bandwidth, utilizing computility for performance optimization. We reveal that the state-of-the-art Dashlet prefetching strategy fails to maximize the weighted sum of QoE and bandwidth usage (i.e., utility). To overcome this limitation, the proposed comprehensive multistep prefetching strategy (CMPS) for short video streaming computes the prefetching urgency of chunks and combines it with expected utility to comprehensively evaluate multistep decision sequences, achieving higher QoE and bandwidth utilization than Dashlet. The extensive evaluations show that the proposed CMPS improves the average utility across diverse scenarios by 16.1% compared with Dashlet.","volume":41,"issue":2,"firstpage":533,"lastpage":547,"year":2026,"type":"Regular Paper","research_area":["Cloud, Edge & Utility Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5573-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5573-y?year=2026&issue=2","affiliations":["Central South University"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-6289-3","title":"Self Model for Embodied Artificial Intelligence","authors":[{"last":"Jiang","first":"Shu-Qiang"},{"last":"Zhang","first":"Si-Xian"},{"last":"Tao","first":"Shi-Da"},{"last":"Zhu","first":"Xi-Hong"},{"last":"Qi","first":"Tian-Liang"},{"last":"Song","first":"Xin-Hang"}],"keywords":["embodied artificial intelligence","self model","self model hierarchy"],"abstract":"This paper presents a systematic formulation of the self model for embodied artificial intelligence (AI), aiming to provide the missing internal representation that enables an agent to understand its own body, capabilities, memories, and decision processes. Unlike existing approaches that address isolated aspects such as perception, prediction, or skill adaptation, we propose a unified computational framework that integrates body schema, forward and inverse models, perceptual memory mechanisms, and agency. This framework captures how an embodied agent represents its physical structure, predicts the consequences of its actions, selects policies, and accumulates experiences to form a coherent sense of self. We further introduce a six-level hierarchy (L0–L5) that characterizes the developmental stages of self model from non-self representation to full self-awareness, providing the first operational taxonomy for evaluating self-awareness in embodied AI systems. Then, a practical implementation is proposed and validated on embodied navigation and manipulation tasks. Experimental results demonstrate the effectiveness of the self model and its components, including self-perception, self-memory, self-prediction, and self-decision. Overall, this work proposes the concept and instantiation of the self model in embodied AI and discusses future directions of the self model. Related video demonstrations can be accessed from https://taoshida11.github.io/Selfmodel/ .","volume":41,"issue":2,"firstpage":548,"lastpage":563,"year":2026,"type":"Regular Paper","research_area":["Robotics & Control","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6289-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6289-3?year=2026&issue=2","affiliations":["University of Chinese Academy of Sciences","Chinese Academy of Sciences"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-025-5351-x","title":"Survey on Hypergraph Algorithms: Foundations, Advances, and Applications in Cloud Computing","authors":[{"last":"Wang","first":"Wen-Xuan"},{"last":"Wu","first":"Jie"}],"keywords":["hypergraph","hypergraph learning","cloud computing","artificial intelligence (AI)","machine learning (ML)"],"abstract":"As a generalization of traditional graph structures, hypergraphs provide a powerful mathematical framework for modeling complex, high-order, and many-to-many relationships among entities. With the rapid advancement of artificial intelligence (AI) and machine learning (ML), research on hypergraph algorithms has gained increasing momentum, spanning both theoretical foundations and practical applications. Motivated by this trend, this survey offers a systematic and comprehensive overview of hypergraph algorithms, along with cloud computing scenarios in which hypergraph modeling can be effectively applied. The paper begins by introducing the fundamentals of hypergraphs and analyzing the structural distinctions between hypergraphs and traditional graphs, highlighting their practical implications for cloud computing tasks. We then review theoretical advances, with particular attention to partitioning, coloring, and isomorphism, followed by a comprehensive overview of hypergraph learning methods, including spectral methods and neural network based techniques. In addition, we analyze the types of scenarios in cloud computing where hypergraph methods can be effectively applied, with emphasis on data center networking, traffic prediction, resource scheduling, data management, anomaly detection, and cloud security. With the advancement of AI-driven learning methods, hypergraph-based models are increasingly capable of capturing high-order dependencies, enabling more timely and accurate decision making in complex cloud environments. Last but not least, we outline the major challenges and opportunities for future research. This paper provides critical insights into the role of hypergraphs in addressing complex computational and organizational challenges across multidisciplinary fields.","volume":41,"issue":2,"firstpage":564,"lastpage":592,"year":2026,"type":"Survey","research_area":["Cloud, Edge & Utility Computing","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5351-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5351-x?year=2026&issue=2","affiliations":["China Telecom Corporation Limited","Pennsylvania Commonwealth System of Higher Education (PCSHE)","Temple University"],"type_origin":"Review"},{"doi":"10.1007/s11390-025-5433-9","title":"PINNAS: Physics-Informed Neural Network Architecture Search for Solving Integral Equations","authors":[{"last":"Ren","first":"Zhi-Yuan"},{"last":"Zhou","first":"Shi-Jie"},{"last":"Liu","first":"Dong"},{"last":"Liu","first":"Qi-He"}],"keywords":["differentiable neural architecture search (DNAS)","deep neural network (DNN)","integral equation (IE)","neural architecture search (NAS)","physics-informed neural network (PINN)"],"abstract":"Physics-informed neural networks (PINNs) have emerged as a powerful framework for solving partial differential equations (PDEs) by incorporating physical laws into the training of neural networks. However, their effectiveness in solving integral equations (IEs) remains constrained by suboptimal manual architecture design and computational inefficiencies in existing neural architecture search (NAS) methods. This paper introduces PINNAS (Physics-Informed Neural Network Architecture Search), a novel framework that integrates gradient-based NAS with PINNs to automate architecture optimization for solving IEs. Key innovations include: 1) a differentiable neural architecture search (DNAS) mechanism that relaxes discrete search spaces into continuous domains, enabling joint optimization of network weights and architecture parameters, 2) dynamic masking techniques to resolve tensor shape mismatches in variable-width layers, and 3) domain-specific search spaces tailored for integral operators. Extensive experiments on six IE types (one-dimensional or two-dimensional, linear or nonlinear, Volterra or Fredholm) demonstrate that PINNAS-optimized architectures achieve 15%-30% lower mean squared error (MSE) than manually designed networks while using 40% fewer parameters. Crucially, we reveal that non-uniform layer widths outperform uniform configurations, challenging conventional NAS practices. This work bridges the gap between automated machine learning and scientific computing, offering a scalable strategy for IE solutions.","volume":41,"issue":2,"firstpage":593,"lastpage":608,"year":2026,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5433-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5433-9?year=2026&issue=2","affiliations":["University of Electronic Science & Technology of China"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5304-4","title":"Federated Deep Subspace Clustering","authors":[{"last":"Zhang","first":"Yu-Pei"},{"last":"Feng","first":"Rou-Jia"},{"last":"Wang","first":"Yi-Fei"},{"last":"Liu","first":"Shu-Hui"},{"last":"Shang","first":"Xue-Qun"}],"keywords":["federated learning","deep subspace clustering","private protection","deep learning","image clustering"],"abstract":"This paper presents Federated Deep Subspace Clustering (FDSC), a privacy-preserving deep subspace clustering model built upon a federated learning framework. In FDSC, each client employs a dedicated deep subspace clustering network to process its locally isolated data. This network consists of an encoder, a self-expressive layer, and a decoder. To enable collaboration across clients, the encoder network is shared with a central server, allowing communication and model aggregation. Furthermore, FDSC enhances local clustering performance by preserving the neighborhood relationships among data samples within each client. By integrating federated learning with locality preservation, the encoder learns more expressive features, which in turn improve the self-expressiveness and clustering accuracy. Extensive experiments on public datasets show that FDSC outperforms existing methods, benefiting from both federated learning and locality preservation.","volume":41,"issue":2,"firstpage":609,"lastpage":620,"year":2026,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Federated Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5304-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5304-4?year=2026&issue=2","affiliations":["Northwestern Polytechnical University","Tsinghua University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5199-0","title":"Applications of Hypergraph Learning for Brain Disorder Diagnosis with Neuroimaging: A Survey","authors":[{"last":"He","first":"Meng-Shen"},{"last":"Tian","first":"Xu"},{"last":"Li","first":"Jun-Jian"},{"last":"Yue","first":"Hai-Lin"},{"last":"Li","first":"Xin-Yu"},{"last":"Kuang","first":"Hu-Lin"},{"last":"Lin","first":"Hanhe"},{"last":"Qiu","first":"Zhen"},{"last":"Liu","first":"Jin"}],"keywords":["brain disorder","hypergraph learning","neuroimaging","computer aided diagnosis","functional connectivity"],"abstract":"The human brain, as the most complex organ, comprises billions of neurons forming intricate and dynamic networks. This complexity results in brain disorders exhibiting multifaceted manifestations, both in their pathological mechanisms and clinical symptoms, thereby posing significant challenges for accurate diagnosis and effective treatment. In the light of this, the development of advanced diagnostic techniques and analytical methodologies has become increasingly crucial. While graph learning has promising performance in modeling neuroimaging data, its reliance on pairwise (binary) relationships limits its capacity to capture higher-order interactions among brain regions. Hypergraph learning frameworks address this shortcoming by modeling complex, multi-way relationships, offering a richer and more expressive mathematical foundation for understanding brain network structure and function. This survey provides a comprehensive overview of recent advancements in hypergraph learning for neuroimaging-based brain disorder diagnosis, discussing current methodological challenges and outlining promising directions for future research in this rapidly evolving field.","volume":41,"issue":2,"firstpage":621,"lastpage":637,"year":2026,"type":"Survey","research_area":["Bioinformatics & Life Sciences","Graph Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5199-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5199-0?year=2026&issue=2","affiliations":["Central South University","Xinjiang University","University of Dundee"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-025-5020-0","title":"Obstet-LLM: Large Language Model for Early Prediction of SGA-LGA Newborns","authors":[{"last":"Xu","first":"Geng-Xin"},{"last":"Jiang","first":"Hui"},{"last":"Nguyen","first":"Sau Van"},{"last":"Wu","first":"Dan"},{"last":"Liu","first":"Zeng-Ding"},{"last":"Sha","first":"Feng"},{"last":"Li","first":"Ye"}],"keywords":["large language model (LLM)","fetal growth prediction","gestational age","birth weight","model interpretability"],"abstract":"Predicting small for gestational age (SGA) and large for gestational age (LGA) newborns is crucial for preventing adverse pregnancy outcomes and improving neonatal health. Existing purely data-driven methods have achieved promising performance in SGA-LGA newborn prediction, but most of them lack model interpretability, raising doubts in clinical auxiliary diagnosis and failing to provide targeted interventions. To address this challenge, this paper proposes an obstetric knowledge-driven large language model, termed Obstet-LLM. Specifically, Obstet-LLM is pre-trained on the content from professional knowledge bases in the field of obstetrics. This pre-training enables the model to understand and integrate domain-specific knowledge and clinical insights. Subsequently, the model undergoes prompt engineering and instruction fine-tuning to learn precise predictions of neonatal growth outcomes. To enhance model interpretability, a causal learning paradigm is designed, allowing Obstet-LLM to generate clear and understandable explanations. Experimental results show that Obstet-LLM achieves an accuracy rate of over 90% in predicting SGA-LGA newborns, outperforming existing data-driven models. Moreover, by integrating domain-specific knowledge, Obstet-LLM provides actionable insights for clinicians, thereby enhancing the quality of prenatal care and reducing the risk of adverse pregnancy outcomes.","volume":41,"issue":2,"firstpage":638,"lastpage":652,"year":2026,"type":"Regular Paper","research_area":["Bioinformatics & Life Sciences"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5020-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5020-0?year=2026&issue=2","affiliations":["Chinese Academy of Sciences","Shenzhen Institute of Advanced Technology, CAS","Guangdong Academy of Medical Sciences & Guangdong General Hospital","Southern Medical University - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5487-8","title":"MedDiffusionNet: A Geometric Deep Learning Network for Intracranial Aneurysm Segmentation Across Imaging Modalities","authors":[{"last":"Zhang","first":"Ze-Yao"},{"last":"Wang","first":"Xing-Ce"},{"last":"Deng","first":"Xian"},{"last":"Ru","first":"Xu-Dong"},{"last":"Liu","first":"Zhen-Hong"},{"last":"Wu","first":"Zhong-Ke"},{"last":"Liu","first":"Jing-Yi"},{"last":"Ju","first":"Xiao-Dong"},{"last":"Zhu","first":"Yi-Cheng"},{"last":"Shui","first":"Wu-Yang"}],"keywords":["geometric deep learning","intracranial aneurysm","mesh segmentation"],"abstract":"As intracranial aneurysms (IAs) are potentially fatal vascular abnormalities that can lead to severe strokes, their accurate segmentation from acquired imaging data is essential for diagnosis and treatment planning. Current automatic IA segmentation methods predominantly focus on directly processing medical images, whereas research exploring approaches beyond image-based modalities is limited. To address this gap, we propose Medical Diffusion Network (MedDiffusionNet), a novel segmentation network incorporating geometric deep learning, designed to directly work on three-dimensional mesh models of aneurysms. The core of MedDiffusionNet comprises multiple diffusion blocks grounded in the heat diffusion equation, which enable efficient information propagation on graphs. By incorporating learnable diffusion time and gradient features, MedDiffusionNet performs frequency-domain convolution with an adaptive receptive field. Notably, this architecture aligns with the geometric properties of vascular aneurysm models, allowing MedDiffusionNet to learn a powerful nonlinear mapping from the feature space onto the label space on the associated mesh. We validate MedDiffusionNet on an extremely imbalanced dataset reconstructed from data acquired through multiple imaging modalities. Experimental results show that MedDiffusionNet outperforms eight state-of-the-art networks in IA segmentation, accurately delineating IA boundaries across diverse vascular shapes and sizes. Moreover, our network achieves higher values of the associated intersection over union and Dice similarity coefficient while maintaining geometric consistency with the ground truths.","volume":41,"issue":2,"firstpage":653,"lastpage":668,"year":2026,"type":"Regular Paper","research_area":["Computer Graphics & Visualization","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5487-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5487-8?year=2026&issue=2","affiliations":["Beijing Normal University","Chinese Academy of Medical Sciences - Peking Union Medical College","Peking Union Medical College Hospital","Peking University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5404-1","title":"Spatial-Temporal Mixture-of-Graph-Experts for Multi-Type Crime Prediction","authors":[{"last":"Wu","first":"Zi-Yang"},{"last":"Liu","first":"Fan"},{"last":"Han","first":"Jin-Dong"},{"last":"Liang","first":"Yu-Xuan"},{"last":"Liu","first":"Hao"}],"keywords":["multi-type crime prediction","spatio-temporal prediction","mixture-of-experts"],"abstract":"As various types of crimes continue to threaten public safety and economic development, predicting the occurrence of multiple types of crimes becomes increasingly vital for effective prevention measures. Although extensive efforts have been made, most of them overlook the heterogeneity of different crime categories and fail to address the issue of imbalanced spatial distribution. In this work, we propose Spatial-Temporal Mixture-of-Graph-Experts (ST-MoGE), a framework for collective multiple-type crime prediction. To enhance the model's ability to identify diverse spatial-temporal dependencies and mitigate potential conflicts caused by spatial-temporal heterogeneity of different crime categories, we introduce a module, Mixture-of-Graph-Experts (MGE), to capture the distinctive and shared crime patterns of each crime category. Then, we propose Cross-Expert Contrastive Learning (CECL) to refine MGE and force each expert to specialize in modeling specific patterns, thereby reducing blending and redundancy. Furthermore, to address the issue of imbalanced spatial distribution, we propose a module, Hierarchical Adaptive Loss Re-Weighting (HALR), to eliminate biases and underfitting in data-scarce regions. To evaluate the effectiveness of our methods, we conduct comprehensive experiments on two real-world crime datasets and compare our results with 12 advanced baselines. The experimental results demonstrate the superiority of our methods.","volume":41,"issue":2,"firstpage":669,"lastpage":683,"year":2026,"type":"Regular Paper","research_area":["Trajectory & Spatial Data","Data Mining & Analytics"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5404-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5404-1?year=2026&issue=2","affiliations":["The Hong Kong University of Science and Technology","The Hong Kong University of Science and Technology (Guangzhou)"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-025-5113-9","title":"TopoChat: Enhancing Topological Materials Retrieval with Large Language Model and Multi-Source Knowledge","authors":[{"last":"Xu","first":"Huang-Chao"},{"last":"Zhang","first":"Bao-Hua"},{"last":"Jin","first":"Zhong"},{"last":"Zhu","first":"Tian-Nian"},{"last":"Wu","first":"Quan-Sheng"},{"last":"Weng","first":"Hong-Ming"}],"keywords":["information retrieval","large language model (LLM)","knowledge graph","prompt learning"],"abstract":"Large language models (LLMs) perform well in general text tasks but face challenges in specialized fields like materials science. We present TopoChat, a knowledge-enhanced question-answering framework for materials science, which combines a domain-specific knowledge graph (TopoKG, Topological Materials Knowledge Graph) and a literature clustering module. TopoChat retrieves both relevant subgraphs and literature information for each query, integrating structured and unstructured knowledge to support LLM reasoning. Experiments on two benchmarks, MaScQA and TopoQA, show that TopoChat improves answer accuracy across multiple LLMs. These results demonstrate that integrating knowledge graphs and literature context enhances reliability in scientific question answering. TopoChat provides an effective approach for adapting LLMs to complex domains, narrowing the gap between general language abilities and domain expertise.","volume":41,"issue":2,"firstpage":684,"lastpage":697,"year":2026,"type":"Regular Paper","research_area":["Knowledge Graphs & Heterogeneous Information Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5113-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5113-9?year=2026&issue=2","affiliations":["Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Computer Network Information Center, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5042-7","title":"Model Knowledge Transfer for Ab Initio Molecular Dynamics Simulations","authors":[{"last":"Lyu","first":"Shuai"},{"last":"Yao","first":"Yu-Fan"},{"last":"Sun","first":"Yan-Hui"},{"last":"Wu","first":"Wen-Tiao"},{"last":"Hu","first":"Wei"}],"keywords":["molecular dynamics","model knowledge transfer","plane-wave density functional theory (PWDFT)","computational efficiency","machine learning"],"abstract":"Machine learning based potential energy surface (PES) models have revolutionized ab initio molecular dynamics (AIMD) simulations, providing a much faster alternative to traditional electronic structure methods. Nevertheless, despite their speed advantages, these models incur significant computational overhead and resource inefficiencies when directly used for predicting molecular properties with pre-trained models, which ultimately reduces their overall efficiency. To address this, we propose a novel model knowledge transfer strategy for enhancing ab initio molecular dynamics (KTAIMD) simulations without compromising accuracy. This strategy, applied as a post-training refinement step, significantly reduces computational overhead while retaining the precision of the original model. Extensive experiments conducted on the plane-wave density functional theory (PWDFT) platform validate the KTAIMD strategy, demonstrating a notable reduction in memory usage by an order of magnitude. Consequently, this approach offers substantial practical value for large-scale simulations and establishes a new benchmark for efficiency and scalability in molecular dynamics.","volume":41,"issue":2,"firstpage":698,"lastpage":709,"year":2026,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Bioinformatics & Life Sciences"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5042-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5042-7?year=2026&issue=2","affiliations":["Chinese Academy of Sciences","University of Science & Technology of China, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5171-z","title":"Efficient Vision Transformer Inference via UDP for Edge-Cloud Collaboration: An Adaptive Loss Detection Approach","authors":[{"last":"Kim","first":"Hyochan"},{"last":"Ko","first":"Jong Hwan"}],"keywords":["collaborative intelligence","vision transformer","User Datagram Protocol (UDP) transfer","edge-cloud","real-time system"],"abstract":"Vision transformers (ViTs) deliver exceptional performance in computer vision tasks but pose significant computational challenges for edge devices. We present an efficient vision transformer inference framework (EViTIF), an edge-cloud collaborative framework that utilizes User Datagram Protocol (UDP) to achieve low-latency communication by strategically partitioning ViT models between edge and cloud environments. To mitigate UDP's inherent unreliability, we introduce the Packet Error Rate Adaptive Loss Detection Network (PALDN), which dynamically recovers lost data without requiring extensive model retraining. Our experiments, conducted on an NVIDIA Jetson Xavier NX edge device and an A100 GPU-equipped cloud server, demonstrate that EViTIF reduces inference latency by up to 57x compared with traditional TCP (Transmission Control Protocol)-based methods. Even with up to 60% packet loss, PALDN maintains accuracy degradation below 2%, outperforming existing super-resolution based recovery approaches. Moreover, EViTIF demonstrates its versatility by generalizing across different ViT variants and scaling effectively to larger datasets like ImageNet. This framework enables real-time, high-performance vision applications in edge computing by balancing computational efficiency with robustness against network imperfections.","volume":41,"issue":2,"firstpage":710,"lastpage":723,"year":2026,"type":"Regular Paper","research_area":["Real-Time & Embedded Systems","Transformers & Attention"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5171-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5171-z?year=2026&issue=2","affiliations":["Sungkyunkwan University (SKKU)"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4478-0","title":"Understanding Users' Affective States During Issue Resolution in Open Source Software Projects","authors":[{"last":"Zhuang","first":"Yu-Qian"},{"last":"Wang","first":"Liang"},{"last":"Sun","first":"Ke-Xin"},{"last":"Kuang","first":"Hong-Yu"},{"last":"Tao","first":"Xian-Ping"}],"keywords":["affective state","issue resolution","user retention","large language model (LLM)"],"abstract":"In this work, we explore users' affective states during issue resolution in open source software (OSS) projects, and study the correlations between these states and their future retention. While many studies focus on users' sentiment polarities, few have delved into the complex cognitive processes underlying issue resolution. This work proposes a nine-state model that describes users' affective states by combining sentiment polarities with emotion. With this model, we perform affective state estimation from users' issue comments with the state-of-the-art large language models (LLMs). Experimental results on existing benchmarks suggest that LLMs are effective in estimating the affective states from issue comments, and the finetuned RoBERTa-based estimator achieves the best performance with a 69.01% accuracy. With the estimator, we analyze the dynamics of users' affective states during issue resolution in 114 real-world OSS projects and find significant differences between popular projects under active maintenance and inactive projects. Moreover, we perform regression analysis and find significant correlations between users' affective states during issue resolution and their future retention and activeness in participating in issue discussions and making contributions. Compared with existing factors, we improve the average goodness-of-fit of regression models by 42.56% and 12.08%, for user retention and future activeness, after extending the factors to include users' affective states, respectively. The results suggest that experiencing confusion and frustration is negatively associated with a user's future retention, while being engaged corresponds to a higher likelihood of future participation. Our study shows the importance of maintaining an engaged and positive atmosphere in OSS teams.","volume":41,"issue":2,"firstpage":724,"lastpage":741,"year":2026,"type":"Regular Paper","research_area":["Education & Social Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4478-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4478-0?year=2026&issue=2","affiliations":["Nanjing University"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-5611-4","title":"Survey of Coarse-Grained Reconfigurable Architectures Mapping Algorithms","authors":[{"last":"Du","first":"Yi-Min"},{"last":"Chang","first":"Ke-Yang"},{"last":"Shi","first":"Jing-Lin"},{"last":"Zhou","first":"Yi-Qing"},{"last":"Zheng","first":"Tian-Hao"},{"last":"Wang","first":"Zhe"},{"last":"Hong","first":"Rui"}],"keywords":["coarse-grained reconfigurable architecture (CGRA)","baseband processor","mapping algorithm","machine learning"],"abstract":"This paper presents a comprehensive survey of mapping algorithms for coarse-grained reconfigurable architectures (CGRAs), which have emerged as promising and popular accelerators in wireless communication chips in the era of Industry 4.0. To address the limitations of traditional application-specific integrated circuits (ASICs), which incur high single tape-out costs and suffer from inflexibility, as well as the design redundancies and high power consumption of digital signal processors (DSPs) in wireless processing scenarios, CGRAs achieve high flexibility and low energy consumption through reconfigurable processing elements (PEs) with interconnections. Mapping applications onto CGRAs is a crucial step in achieving efficient acceleration functionality, and numerous mapping algorithms have been proposed to address this challenge. This paper clarifies that the essence of CGRA mapping lies in the mapping between tasks and PEs, and analyzes core features of task description graphs and hardware architecture description graphs. It decomposes the three-stage process and bottlenecks of mapping to help researchers grasp key concepts. It also analyzes mainstream mapping algorithms, deduces their suitable task and hardware features, forms a table for scenario-based selection, organizes machine learning's mapping application paradigms to offer innovation paths, and analyzes general algorithms for communication scenarios to support researchers' selection.","volume":41,"issue":2,"firstpage":742,"lastpage":760,"year":2026,"type":"Survey","research_area":["Processor & Microarchitecture","GPU & Accelerator Architecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5611-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5611-4?year=2026&issue=2","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS","ShanghaiTech University"],"type_origin":"Review"},{"doi":"10.1007/s11390-025-4525-x","title":"Grouping Algorithms for Optimal Configuration of Virtual Links in Avionics Full-Duplex Switched Ethernet","authors":[{"last":"Feng","first":"Shao-Ting"},{"last":"Peng","first":"Quan-Quan"},{"last":"Li","first":"Qin-Ya"},{"last":"Wu","first":"Fan"},{"last":"Chen","first":"Gui-Hai"}],"keywords":["Avionics Full-Duplex Switched Ethernet (AFDX) network","resource configuration","bandwidth consumption","virtual link"],"abstract":"Virtual links (VLs) are isolated data tunnels used in Avionics Full-Duplex Switched Ethernet (AFDX) to route Ethernet frames. Each VL is allocated dedicated bandwidth, ensuring reliable communication under adverse conditions. Proper VL configuration can reduce bandwidth consumption by assigning appropriate message flows and setting parameters like maximum transfer unit (MTU) and bandwidth allocation gap (BAG). Previous studies often assume messages with the same source and the destination share the same VL, leading to bandwidth waste. This paper presents a dynamic programming (DP)-based grouping algorithm (DPGA) for low-bandwidth systems and a traversal top-down algorithm (TTDA) for systems with a large number of messages, to enhance bandwidth utilization. Validated on a real dataset, DPGA reduces bandwidth by 19.9% for small-scale messages, and TTDA by 24.7% for large-scale messages compared with a single VL approach. Our methods handle larger message scales and significantly reduce network bandwidth usage compared with previous work.","volume":41,"issue":2,"firstpage":761,"lastpage":773,"year":2026,"type":"Regular Paper","research_area":["Network Protocols & Measurement"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4525-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4525-x?year=2026&issue=2","affiliations":["Shanghai Jiao Tong University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5052-5","title":"HARLD: A RISC-V Based Tightly Coupled Heterogeneous Computing Architecture for Low-Density Parity Check Decoding","authors":[{"last":"Wang","first":"Bing"},{"last":"Ma","first":"Zi-Rui"},{"last":"Wu","first":"Hai-Bin"},{"last":"Zhang","first":"Fu-Lin"},{"last":"Yue Wang","first":"Yue Wang"},{"last":"Fan","first":"Zhi-Hua"},{"last":"Li","first":"Wen-Ming"},{"last":"Ye","first":"Xiao-Chun"},{"last":"Fan","first":"Dong-Rui"}],"keywords":["tightly coupled heterogeneous computing architecture","low-density parity check (LDPC) decoding","RISC-V extension"],"abstract":"Low-density parity check (LDPC) decoding is an efficient error correction method in communication systems, especially in 5G networks, which require high performance and low latency; while common generalpurpose architectures cannot meet the requirements. There has been some research on accelerating LDPC decoding, but the current methods still suffer from limitations in performance, flexibility, and communication cost. In this paper, we propose HARLD (Heterogeneous Architecture of RISC-V for LDPC Decoding), a tightly coupled heterogeneous computing architecture based on extended RISC-V for LDPC decoding, consisting of a CPU and a processing array. Compared with a loosely coupled System-on-Chip (SoC)-bus baseline, the tightly coupled design improves throughput by up to 32.4% and reduces average latency by up to 24.7% across evaluated configurations, while also enhancing resource and energy efficiency: processing element utilization up to 93.5%, instruction RAM utilization increased by up to 4.8x, and energy efficiency improved by up to 24.8%. At the system level, area and power are reduced by 17.6% and 10.2%, respectively, versus the loosely coupled design.","volume":41,"issue":2,"firstpage":774,"lastpage":790,"year":2026,"type":"Regular Paper","research_area":["High-Performance & Parallel Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5052-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5052-5?year=2026&issue=2","affiliations":["China Mobile","Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5022-y","title":"iSCoder: Mitigating Genomic Sequencing Data Compression Bottlenecks via In-SRAM Computing","authors":[{"last":"Liu","first":"Wan-Qi"},{"last":"Li","first":"Ye-Wen"},{"last":"Tan","first":"Guang-Min"}],"keywords":["genomic sequencing data","compression","in-SRAM computing","hardware accelerator"],"abstract":"With the rapid expansion of genomic sequencing data over the years, the costs associated with storage, transmission, and bandwidth are becoming the primary bottlenecks in genomic research and applications. Data compression is widely used to alleviate this burden, provided it achieves a sufficiently high compression ratio and fast compression speed. MPEG-G is a genome-specific compression standard that offers a higher compression ratio than general-purpose compression tools (4.3x), however, at the cost of performance reduction (5x). Following common strategies in compression acceleration, we design to the best of our knowledge, the first hardware accelerator for the MPEG-G genomic data compression pipeline utilizing in-SRAM (Static Random-Access Memory) computing, referred to as iSCoder. We identify and analyze MatchC (Match Coding) and LutC (Lut Coding) as two bottleneck algorithms within this pipeline, propose two optimized in-SRAM algorithms, and design a unified hardware architecture for these algorithms, considering the characteristics of genomic data. Compared with 72-core Intel processors operating at 3.0 GHz, experimental results demonstrate that iSCoder achieves an average speedup of 131x for MatchC and 191x for LutC.","volume":41,"issue":2,"firstpage":791,"lastpage":808,"year":2026,"type":"Regular Paper","research_area":["GPU & Accelerator Architecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5022-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5022-y?year=2026&issue=2","affiliations":["Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4764-x","title":"Durable Impact Period Queries on Time-Varying Preference","authors":[{"last":"Zhang","first":"Chu-Han"},{"last":"Li","first":"Jian-Zhong"},{"last":"Jiang","first":"Shou-Xu"}],"keywords":["time-varying preference","durable impact period query","reverse top-k query","top-k query"],"abstract":"The reverse top-k query was proposed for market analysis over ten years ago. The query identifies users' preferences whose top-k choices include a given object o. Users' preferences are considered static in the traditional reverse top-k query. However, preferences change over time due to factors like mood, seasons, and economic conditions. In this paper, to address the dynamic nature of preference in market analysis, a new query, called the Durable Impact Period Query, is proposed. Taking a query object o and a time period I as inputs, the durable impact period query aims to determine whether I is a durable impact period of o. This involves checking whether, for most of the time in I, more than a certain proportion of users include o in their top-k choices. The impact period serves as a critical determinant in the decision-making process for product launches. To process durable impact period queries efficiently, three algorithms are proposed. First, an exhaustive search algorithm is designed. Then, by transforming the durable impact period query into the halfspace range thresholding query, a pruning-based algorithm is proposed. Notably, the pruning-based algorithm demonstrates a significant reduction in time cost, often by two orders of magnitude compared with the exhaustive search algorithm. Moreover, a sampling-based approximate algorithm is presented to further enhance efficiency. Finally, extensive experiments show that the proposed algorithms are correct and efficient.","volume":41,"issue":2,"firstpage":809,"lastpage":824,"year":2026,"type":"Regular Paper","research_area":["Databases & Query Processing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4764-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4764-x?year=2026&issue=2","affiliations":["Harbin Institute of Technology","Chinese Academy of Sciences","Shenzhen Institute of Advanced Technology, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-5439-y","title":"WOWAF: Enhanced Dynamic Binary Analysis Framework Targeting Windows-on-Windows 64-Bit Environments","authors":[{"last":"Pan","first":"Jia-Ye"},{"last":"Sha","first":"Le-Tian"},{"last":"Chen","first":"Xiao"},{"last":"Li","first":"De-Qiang"},{"last":"Xiao","first":"Fu"}],"keywords":["dynamic analysis","binary program","windows kernel","malicious code","Windows-on-Windows 64-bit (WOW64)"],"abstract":"Dynamic binary program analysis plays a crucial role in software vulnerability discovery and malicious code analysis. While 64-bit computing environments have become prevalent, numerous applications still utilize their 32-bit counterparts due to factors such as compatibility considerations, including both regular software and malware. Traditional dynamic analysis frameworks are not optimized for the analysis of 32-bit and mixed-mode programs. As a result, they often encounter issues such as anomalies and performance problems when applied to specific application analysis. To address these issues, this paper proposes WOWAF, an enhanced dynamic binary analysis framework tailored for Windows-on-Windows 64-bit (WOW64) environments that enables efficient fine-grained analysis of target applications. The framework is implemented on the built-in emulator in 64-bit Windows operating systems, facilitating effective and stable analysis of both pure 32-bit programs and mixed applications. By leveraging kernel features, the framework facilitates dynamic instrumentation of target programs, while incorporating a novel shadow memory allocation management scheme to minimize impact on program execution, and demonstrates its good deployment feasibility. The effectiveness of WOWAF is validated through comprehensive evaluations of diverse applications in real-world environments, such as exploit programs and evasive malware samples. Additionally, systematic benchmark experiments further demonstrate its strong analytical performance.","volume":41,"issue":2,"firstpage":825,"lastpage":842,"year":2026,"type":"Regular Paper","research_area":["Software Testing & Analysis"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5439-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5439-y?year=2026&issue=2","affiliations":["Nanjing University of Posts & Telecommunications"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-6092-1","title":"What Is Computation? And Why Turing?","authors":[{"last":"Zhang","first":"Nick"}],"keywords":["analog vs digital","Church-Turing Thesis","continuous vs discrete","general recursive function","nature of computation","Strong Church-Turing Thesis","universal Turing machine"],"abstract":"This paper delves into the formation of the Church-Turing Thesis, aiming to elucidate philosophical and historical issues of the nature of computation. As a cornerstone of computer science, the Church-Turing Thesis asserts that the Turing machine is the most universal computing device. This paper explores Turing's pivotal role in the process. The Church-Turing Thesis is a conviction supported by the fact that various computational mechanisms, including the general recursive function, lambda-calculus, and the Post systems among others, have been proven mathematically equivalent. A stronger formulation of the thesis implies that intelligence is reducible to Turing machines, further prompting discussions on the nature of artificial intelligence. This thesis has led the theory of computation to bridge across mathematics and physics, and moreover, the most enduring dichotomy in philosophy, mind and matter.","volume":41,"issue":1,"firstpage":4,"lastpage":25,"year":2026,"type":"Perspective","research_area":["Formal Methods & Verification"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6092-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6092-1?year=2026&issue=1","affiliations":["Wuzhen Institute"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5946-2","title":"Uncovering Several Useful Structures of Complex Networks in Computer Science Applications","authors":[{"last":"Wu","first":"Jie"}],"keywords":["complex network","distributed and localized solution","dynamic and mobile network","graph theory","labeling and coding","learning","structural property"],"abstract":"Graph theory originated in the 18th century when Euler worked on the K & ouml;nigsberg bridge problem. Since then, graph theory has been applied to many fields, ranging from biological networks to transportation networks. In this paper, we study complex networks and their applications in computer science, with a focus on computer system and network applications, including mobile and wireless networks. In a social society, many group activities can be represented as a complex network in which entities (vertices) are connected in pairs by lines (edges). Uncovering useful global structures of complex networks is important for understanding system behaviors and providing global guidance for application designs. We briefly review existing graph models, discuss several mechanisms used in traditional graph theory, distributed computing, and system communities, and point out their limitations. Throughout the paper, we focus on how to uncover useful structures in dynamic networks and summarize three promising approaches to uncover useful structures: trimming, layering, and remapping. We then study several distributed and local labeling and coding methods as a way of learning and their relationships to machine learning (ML), including graph neural networks (GNNs). Finally, we present challenges in algorithmic techniques, with a focus on distributed and localized ones, in labeling and coding in a dynamic network.","volume":41,"issue":1,"firstpage":26,"lastpage":45,"year":2026,"type":"Survey","research_area":["Graph Theory & Algorithms"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5946-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5946-2?year=2026&issue=1","affiliations":["China Telecom Corporation Limited","Pennsylvania Commonwealth System of Higher Education (PCSHE)","Temple University"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-6040-0","title":"Automated Conjecturing and Theorem Finding: A Survey","authors":[{"last":"Zhang","first":"Jian"},{"last":"Tan","first":"Si-Cheng"}],"keywords":["automated conjecturing","theorem finding","automated theorem proving","neural-symbolic method","theory exploration"],"abstract":"Automated conjecturing and theorem finding represents a fundamental challenge in artificial intelligence, involving the systematic generation of mathematical conjectures and theorems from given axioms and definitions. This survey provides an overview of automated conjecturing and theorem finding methods. We categorize existing approaches into symbolic methods and data-driven methods. Symbolic methods, which include top-down lemma discovery and bottom-up theory exploration, leverage deductive reasoning and symbolic enumeration. Data-driven methods comprise statistical analogy learning and recent neural methods based on large language models, which learn patterns from large formal corpora, and also include efforts in scientific discovery from experimental data and theorem generation for synthetic data. We also discuss strategies and evaluation methods of interestingness. Finally, we identify current challenges and suggest some future research directions. This comprehensive analysis aims to guide researchers in understanding the current state of automated conjecturing and identifying opportunities for advancing this critical area of mechanized mathematics and automated reasoning.","volume":41,"issue":1,"firstpage":46,"lastpage":66,"year":2026,"type":"Survey","research_area":["Formal Methods & Verification"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6040-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6040-0?year=2026&issue=1","affiliations":["Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Institute of Software, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Review"},{"doi":"10.1007/s11390-026-6292-8","title":"Physical Intelligence on the Edge: A Vision for the Decade Ahead","authors":[{"last":"Shi","first":"Weisong"},{"last":"Dong","first":"Zheng"},{"last":"Zhou","first":"Peipei"}],"keywords":["embodied spatial/temporal reasoning","customization","symbiosis","sustainability"],"abstract":"This article examines key challenges in computing systems research under the emerging paradigm of Physical Intelligence on the Edge (PIE), in which raw sensor streams are transformed into real-time, safety-critical intelligence that can act in the physical world. It traces the evolution of computing architectures from centralized systems to distributed systems and edge computing, and argues that PIE constitutes a qualitative shift: the edge becomes the primary platform for tightly integrating sensing, reasoning, and actuation under stringent real-time constraints. The article identifies five emerging research thrusts-embodied spatial reasoning, embodied temporal reasoning, edge-native customization, symbiosis, and sustainability. Using a hypothetical PIE scenario, it exposes a fundamental gap between the capabilities of current systems and the requirements of future PIE-enabled autonomy: while today's edge platforms can execute individual components of perception and inference, they remain unable to autonomously close the sense-think-act loop with certifiable guarantees on timing and safety. This vision is further substantiated by recent industrial progress, including several compelling demonstrations showcased at CES 2026 by leading companies such as NVIDIA and AMD. The article concludes by calling for a paradigm shift in systems thinking-from efficiently transporting and processing data (bits) to predictably and safely influencing the physical world (atoms)-thereby positioning edge-native system design as a foundational enabler of next-generation autonomous and robotic systems.","volume":41,"issue":1,"firstpage":67,"lastpage":82,"year":2026,"type":"Perspective","research_area":["Cloud, Edge & Utility Computing","Robotics & Control"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6292-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6292-8?year=2026&issue=1","affiliations":["University of Delaware","Wayne State University","Brown University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5923-9","title":"PPIMCE: In-Memory Computing Fabric for Privacy Preserving Computing","authors":[{"last":"Geng","first":"Haoran"},{"last":"Mo","first":"Jianqiao"},{"last":"Reis","first":"Dayane"},{"last":"Takeshita","first":"Jonathan"},{"last":"Jung","first":"Taeho"},{"last":"Reagen","first":"Brandon"},{"last":"Niemier","first":"Michael"},{"last":"Hu","first":"Xiaobo Sharon"}],"keywords":["cloud computing security","computing-in-memory","cryptographic protocol","data privacy","garbled circuit","homomorphic encryption","parallel processing","privacy-preserving machine learning"],"abstract":"Privacy has rapidly become a major concern/design consideration. Homomorphic encryption (HE) and garbled circuits (GC) are privacy-preserving techniques that support computations on encrypted data. HE and GC can complement each other, as HE is more efficient for linear operations, while GC is more effective for non-linear operations. Together, they enable complex computing tasks, such as machine learning, to be performed exactly on ciphertexts. However, HE and GC introduce two major bottlenecks: an elevated computational overhead and high data transfer costs. This paper presents Privacy Preserving In-Memory Computing Engine (PPIMCE), an in-memory computing (IMC) fabric designed to mitigate both computational overhead and data transfer issues. Through the use of multiple IMC cores for high parallelism, and by leveraging in-SRAM IMC for data management, PPIMCE offers a compact, energy-efficient solution for accelerating HE and GC. PPIMCE achieves a 107x speedup against a CPU implementation of GC. Additionally, PPIMCE achieves a 1 500x and 800x speedup compared with CPU and GPU implementations of CKKS-based HE multiplications. For privacy-preserving machine learning inference, PPIMCE attains a 1 000x speedup compared with CPU and a 12x speedup against CraterLake, the state-of-art privacy preserving computation accelerator.","volume":41,"issue":1,"firstpage":83,"lastpage":102,"year":2026,"type":"Regular Paper","research_area":["Cloud, Edge & Utility Computing","Cryptographic Hardware","Deep Learning & Neural Networks","GPU & Accelerator Architecture","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5923-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5923-9?year=2026&issue=1","affiliations":["University of Notre Dame","New York University","New York University Tandon School of Engineering","State University System of Florida"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-6043-x","title":"Data-Driven Automated Processor Design","authors":[{"last":"Guan","first":"Xiang-Tao"},{"last":"Cheng","first":"Shu-Yao"},{"last":"Zou","first":"Mo"},{"last":"Zhang","first":"Rui"},{"last":"Chen","first":"Yun-Ji"}],"keywords":["automated processor design","data-driven design","binary speculative diagram"],"abstract":"Fully automated processor design has recently gained significant popularity due to its fast convergence speed and reduced human costs. However, automated design remains challenging in processor correctness and performance guarantee. In this article, we introduce a series of processor auto-design methods based on a data-driven method, Binary Speculative Diagram (BSD), emphasizing how they guarantee design correctness and improve the auto-designed processor performance. Auto-designed by BSD, QiMeng-CPU-v1, an industrial-scale RISC-V CPU, achieves up to 99.999 999 999 99% accuracy. Auto-designed by State-BSD, QiMeng-CPU-v2 is comparable to ARM Cortex A53 (2010s CPU), a human-designed superscalar processor. Finally, we discuss potential future directions for extending and improving the proposed design methods toward more generalized automated processor architectures.","volume":41,"issue":1,"firstpage":103,"lastpage":113,"year":2026,"type":"Perspective","research_area":["Processor & Microarchitecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6043-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6043-x?year=2026&issue=1","affiliations":["Chinese Academy of Sciences","University of Science & Technology of China, CAS","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-6034-y","title":"DPU for Cybersecurity: Enabling Inline Defense and Self-Protection","authors":[{"last":"Li","first":"Xiao-Wei"},{"last":"Liao","first":"Yun-Kun"},{"last":"i Yan","first":"Gui-Hai"}],"keywords":["cybersecurity","confidential computing","data processing unit","remote direct memory access"],"abstract":"As conventional CPU-based security architectures struggle to scale with ever-growing network bandwidths and increasingly sophisticated cyberattacks, the data processing unit (DPU), a specialized processor for datacenter infrastructure, has emerged as a transformative foundation for secure and high-performance computing. Unlike prior fragmented studies, this work proposes a comprehensive security framework for DPUs by systematically investigating the DPUs'le in cybersecurity, serving both as an active security enforcer and as a critical component that must itself be protected. First, the framework offloads security policies onto the DPU to enable line-rate packet inspection and hardware-accelerated security processing. Second, the framework re-architects the DPU itself to defend against physical and architectural attacks, acknowledging that the DPU also introduces a new attack surface. We validate these two design directions through two representative case studies, demonstrating the effectiveness and practicality of the proposed DPU security framework. Experimental results show that the proposed framework reduces remote direct memory access (RDMA) cache side-channel detection latency by up to 98.7% compared with the state-of-the-art, while enabling a trusted execution environment on field-programmable gate array (FPGA)-based DPUs with sub-100 ns overhead and less than 4% FPGA resource consumption.","volume":41,"issue":1,"firstpage":114,"lastpage":127,"year":2026,"type":"Perspective","research_area":["Processor & Microarchitecture","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6034-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6034-y?year=2026&issue=1","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-6331-5","title":"High-Performance Computing in the Age of Machine Learning Interatomic Potentials: A Review of Optimization Strategies for Training and Inference","authors":[{"last":"Hu","first":"Si-Yu"},{"last":"Yao","first":"Er-Lin"},{"last":"Tan","first":"Guang-Ming"},{"last":"Jia","first":"Wei-Le"}],"keywords":["high-performance computing","machine learning interatomic potentials","molecular dynamics"],"abstract":"As one typical AI-for-Science application, machine learning interatomic potentials (MLIPs) have revolutionized the representation of potential energy surfaces. MLIPs can be categorized into specialized MLIPs, which prioritize high accuracy for specific systems, and pretrained MLIPs, which emphasize generalizability across chemical spaces. Specialized MLIPs and pretrained MLIPs differ in the dataset to be trained, model capability (parameters), the training workflow, and the workload in molecular dynamics. We review different high-performance computing (HPC) optimization techniques for training and inference that specialized MLIPs and pretrained MLIPs tend to prefer. For example, from the perspective of the training dataset, we investigate the load balance strategies, which are critical for pretrained MLIPs to enhance scalability. From the perspective of model parameters, we indicate that specialized MLIPs can benefit from curvature-aware optimization algorithms given their moderate model size. We remark that advances in HPC are not merely engineering improvements but play a key role in faster iteration of MLIPs, broader applicability, and sustained progress in MLIP development.","volume":41,"issue":1,"firstpage":128,"lastpage":146,"year":2026,"type":"Survey","research_area":["Deep Learning & Neural Networks","High-Performance & Parallel Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6331-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6331-5?year=2026&issue=1","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Review"},{"doi":"10.1007/s11390-025-5953-3","title":"A Review of Quantum Computing Systems and Software","authors":[{"last":"Yin","first":"Jian-Wei"},{"last":"Chen","first":"Zi-Rong"},{"last":"Peng","first":"Shun"},{"last":"Luo","first":"Hao-Chen"},{"last":"Tao","first":"Chen-Ning"},{"last":"Tan","first":"Si-Wei"},{"last":"Lu","first":"Li-Qiang"}],"keywords":["quantum computing","quantum software","computer architecture","operating system"],"abstract":"Quantum computing is an emerging paradigm that leverages quantum mechanics to solve problems difficult for classical computing. Realizing reliable quantum advantage requires not only hardware, but also a full software stack ranging from algorithms to operating systems. This paper provides a structured review of quantum computing systems and software, examining the current state and future directions of the field. We first introduce the architectures of quantum computing using superconducting and neutral atom systems as examples. At the software level, we begin by analyzing potential quantum applications, including physical simulation, optimization, and artificial intelligence. We then review current quantum programming interfaces, including software development kits (SDKs), verification, and program repair methods. Following these interfaces, this review introduces quantum compilation passes for quantum programs, such as mapping, decomposition, and noise mitigation, that transform logical algorithms into efficient, hardware-executable instructions. At the system level, we explore quantum operating system services such as scheduling, calibration, and error correction, which directly control quantum devices. Then, we present quantitative comparisons of gate count, circuit depth, and execution latency across various software-level methods. Finally, we discuss major challenges of quantum hardware and software, including high error rates, low operation speeds, and limited scalability. By integrating research across these levels, this review provides a comprehensive overview of quantum systems and software architectures, and highlights the significance of co-design between hardware and software.","volume":41,"issue":1,"firstpage":147,"lastpage":169,"year":2026,"type":"Survey","research_area":["Quantum Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5953-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5953-3?year=2026&issue=1","affiliations":["Zhejiang University"],"type_origin":"Review"},{"doi":"10.1007/s11390-026-6076-1","title":"HEC: Heterogeneity-Enriched Communication for AI Symphony","authors":[{"last":"Lu","first":"Xiaoyi"}],"keywords":["heterogeneity","artificial intelligence","data communication","scalability","efficiency"],"abstract":"Modern parallel and distributed computing systems are becoming increasingly complex as applications in high-performance computing (HPC) and artificial intelligence (AI) demand ever-greater levels of computation and communication efficiency. To address these demands, recent architectures integrate heterogeneous computing devices, such as CPUs, GPUs, and DPUs (or SmartNICs), within a single compute node, forming what we refer to as multi-rail heterogeneity. This trend offers substantial potential for scalability and performance but also amplifies the challenges of data movement, synchronization, and coordination across heterogeneous components. We propose Heterogeneity-Enriched Communication (HEC) as a new paradigm that embraces multi-rail heterogeneity by accurately analyzing communication primitives, adaptively composing multi-rail strategies, and scalably optimizing end-to-end pipelines. Through three representative case studies, including HCCL (collective communication), TrimEC (multi-rail erasure coding), and DPU-KV (edge data services), we demonstrate that HEC improves efficiency, scalability, and resilience in parallel and distributed systems for AI workloads. We envision HEC as a foundation for the next generation of AI infrastructure, harmonizing heterogeneous computing instruments into a symphony of scalable and efficient systems tailored for the emerging AI era.","volume":41,"issue":1,"firstpage":170,"lastpage":192,"year":2026,"type":"Perspective","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6076-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6076-1?year=2026&issue=1","affiliations":["University of California System","University of California Merced"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-6250-5","title":"Computing Utility Needs Monadic Abstractions","authors":[{"last":"Du","first":"Yu"},{"last":"Pan","first":"Yu-Xuan"},{"last":"Yu","first":"Zi-Shu"},{"last":"Xu","first":"Zhi-Wei"}],"keywords":["cloud computing","computility","monad","programming abstraction","stored-computer architecture"],"abstract":"Barbara Liskov proposed a vision of abstraction-powered Internet Computer in 2009, updating John McCarthy's 1961 vision of utility computing. But what kinds of abstractions are needed? What fundamental problem do such abstractions aim to solve? This position paper points out a Liskov-Lamport chasm problem and argues that one type of abstractions is needed to realize a planet-scale, abstraction-powered computing utility, termed monadic abstraction. We outline three desirable properties and research goals of such abstractions: 1) a single programming concept encapsulating data, program, and machine, 2) abstraction mechanisms facilitating enforced dynamic soundness, and 3) amortized zero-cost abstractions.","volume":41,"issue":1,"firstpage":193,"lastpage":203,"year":2026,"type":"Perspective","research_area":["Cloud, Edge & Utility Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6250-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6250-5?year=2026&issue=1","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS","Great Bay University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5938-2","title":"TrustFusion AI: A Deep Fusion Architecture for Trusted AI Applications","authors":[{"last":"Guo","first":"Xiao-Bing"},{"last":"Guo","first":"Qing-Xiao"},{"last":"Zhang","first":"Wei-Feng"},{"last":"Wang","first":"Yun-Hao"},{"last":"Ma","first":"Yi-Long"}],"keywords":["privacy computing","blockchain","large language model (LLM)"],"abstract":"In this paper, we propose a novel integrated framework for trustworthy artificial intelligence (AI) systems, which deeply fuses privacy computing (PC), blockchain (BC), and large language models (LLMs) into a cohesive unit (TrustFusion AI). LLMs have emerged as significant drivers of digital economic growth and industrial transformation. However, their widespread adoption has raised significant data privacy and security concerns that conventional centralized security approaches have struggled to address. Despite the potential of PC and BC to offer solutions, there is still a lack of an integrated framework that systematically combines these technologies with LLMs to address practical issues of privacy, trust, and compliance. Our proposed TrustFusion AI deep fusion framework views these technologies as a cohesive unit designed to establish an end-to-end trustworthy AI service chain. In this framework, we analyze the synergistic roles of each component: privacy computing secures data confidentiality and invisibility during computation; blockchain serves as a decentralized trust anchor, ensuring the integrity and traceability of data and computational processes; and LLMs serve as the intelligent core, leveraging their robust analytical capabilities while safeguarding privacy. Future research should prioritize investigating the bidirectional enabling mechanism of LLMs and PC/BC. In this paper, we demonstrate the practical application of this framework through two industrial case studies: intelligent manufacturing quality control and enterprise data compliance audits. Furthermore, we address the primary challenges and future research directions concerning technical standardization and the balance between performance and safety within the framework. Our study offers a viable approach for establishing a reliable and sustainable AI data collaboration technology system and presents a novel perspective for future research in this domain.","volume":41,"issue":1,"firstpage":204,"lastpage":216,"year":2026,"type":"Regular Paper","research_area":["Blockchain & Distributed Ledger","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5938-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5938-2?year=2026&issue=1","affiliations":["Legend Holdings","Lenovo"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5978-7","title":"An Overview of Cangjie Programming Language","authors":[{"last":"Feng","first":"Xin-Yu"},{"last":"Fu","first":"Rong-Xiao"},{"last":"Shi","first":"Lei"},{"last":"Tu","first":"Le"},{"last":"Yang","first":"Yong-Yong"}],"keywords":["programming language design and implementation","multi-paradigm programming","high-level intermediate representation","compiler optimization","language runtime"],"abstract":"Cangjie is a modern programming language designed for application-level software development. It is statically typed and statically compiled, utilizing a tracing garbage collector (GC) for automated memory management. The language's design strives to balance simplicity, safety, extensibility, and performance. Cangjie supports multi-paradigm programming with a concise syntax. With a strong emphasis on extensibility, it features type extension, macro programming, and a simple, efficient C Foreign Function Interfaces (C-FFI). The compiler frontend leverages modern techniques to support robust type inference and introduces a language-specific high-level intermediate representation, Cangjie high-level intermediate representation (CHIR), to facilitate efficient analysis and semantics-aware optimization. Additionally, the language runtime and LLVM-based backend implement lightweight user-mode threads and a concurrent compacting GC. The standard LLVM backend has been extended with GC-specific intrinsics and custom compilation passes for Cangjie-specific optimizations. Preliminary experimental results demonstrate that Cangjie achieves performance competitive with other application-level languages.","volume":41,"issue":1,"firstpage":217,"lastpage":244,"year":2026,"type":"Regular Paper","research_area":["Programming Languages & Compilers"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5978-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5978-7?year=2026&issue=1","affiliations":["Nanjing University"],"type_origin":"Review"},{"doi":"10.1007/s11390-026-6182-0","title":"From User Operations to Agentic Automation: Toward Intent-Oriented Software in the LLM Era","authors":[{"last":"Xie","first":"Tao"},{"last":"Ran","first":"De-Zhi"},{"last":"Cao","first":"Yuan"},{"last":"Wu","first":"Meng-Zhou"},{"last":"Guo","first":"Yu-Zhe"},{"last":"Yang","first":"Wei"}],"keywords":["large language model (LLM)","LLM agent","software engineering","human-computer interaction"],"abstract":"Foundation models (FMs) make possible a new software paradigm in which users express what they want to accomplish rather than how to operate an application. We call this paradigm intent-oriented software. Although recent FM capabilities suggest the feasibility of intent-oriented software, the concept itself has not been formally articulated or systematized. This article provides the first definition of intent-oriented software and examines how such systems can be engineered in practice. We propose two complementary architectural models for realizing intent-oriented software. 1) A plug-in model. Intent-oriented software operates as a middleware layer that wraps around an existing operation-oriented application. It interprets user intents and translates them into the application's existing UI operations without modifying the underlying operation-oriented software. 2) A native model. FMs interpret user intents and generate the necessary backend actions (e.g., API calls, function executions) directly without going through traditional UI. Both models aim to fundamentally transform the interaction paradigm by decoupling user intents from operational procedures, enabling users to accomplish goals without requiring procedural knowledge of application interfaces, while preserving the full functional expressiveness of underlying systems. We systemize key technical challenges, including intent understanding, execution planning, and error recovery, and identify research opportunities in software engineering to advance the development of robust, trustworthy, and user-centered intent-oriented software.","volume":41,"issue":1,"firstpage":245,"lastpage":257,"year":2026,"type":"Perspective","research_area":["LLM Agents & Embodied Intelligence"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6182-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6182-0?year=2026&issue=1","affiliations":["Peking University","Fudan University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5951-5","title":"General Framework of AI Agents","authors":[{"last":"Li","first":"Hang"}],"keywords":["AI agent","robot","information processing framework","multimodal large language model (MLLM)"],"abstract":"AI agents represent one of the most prominent frontiers in artificial intelligence. They include software agents that operate on PCs and mobile devices, as well as hardware agents (robots) that function in the physical world. Currently, research and development on AI agents are making significant progress in foundation models, training methods, system design, and practical applications. However, research on agent frameworks remains limited. This article, as a perspective paper, summarizes existing work and proposes a general framework for AI agent information processing. The key features of this framework are that agents are task-oriented, take text and multimodal data as inputs and outputs, use large language models for reasoning, are constructed through reinforcement learning, and leverage tools and memory. Representative agents and agent frameworks developed to date, as well as several agents recently developed at ByteDance Seed, all conform to this general framework. This article introduces these agents as examples. In addition, the article discusses the relationship between the proposed general agent framework and the information processing mechanisms of the human brain, analyzes the main characteristics of agent technologies, and proposes important directions for future research on AI agents.","volume":41,"issue":1,"firstpage":258,"lastpage":270,"year":2026,"type":"Perspective","research_area":["LLM Agents & Embodied Intelligence"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5951-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5951-5?year=2026&issue=1","affiliations":["Beijing ByteDance Technology Co., Ltd."],"type_origin":"Article"},{"doi":"10.1007/s11390-026-6258-x","title":"Physical AI: Evolution, Progress, Challenges, and Prospects","authors":[{"last":"Wu","first":"En-Hua"},{"last":"Liu","first":"You-Quan"},{"last":"Xu","first":"Tian-Chen"},{"last":"Ren","first":"Li-Xin"},{"last":"Qin","first":"Yi-Ming"},{"last":"Wei","first":"Ming-Yu"},{"last":"He","first":"Xiao-Wei"},{"last":"Yuan","first":"Dong-Yan"},{"last":"Hou","first":"Wen-Chao"},{"last":"Ma","first":"Zhi-Wei"},{"last":"Sheng","first":"Bin"}],"keywords":["Physical AI","Physical-Informed AI","Generative AI","Embodied AI","physical simulation"],"abstract":"Recent advancements in deep learning, high-fidelity simulation, and robotic hardware have propelled significant progress in Physical Artificial Intelligence (AI). This field marks a revolutionary step in the evolution of AI by combining the precision of physical laws with the adaptability of machine learning. In this paper, we review the development of Physical AI and its taxonomy by examining the relevant literature, categorizing it into three sub-domains: Physical-Informed AI, Generative Physical AI, and Embodied AI. These sub-domains primarily tackle scientific and engineering challenges, create physics-plausible scenarios, and enable robots or autonomous vehicles to interact with the physical world. This approach also addresses the questions of how to perceive, generate, and interact with the physical world by integrating physics with AI algorithms. Additionally, we discuss related benchmarks and datasets. Finally, we outline the current challenges and propose potential opportunities for future research.","volume":41,"issue":1,"firstpage":271,"lastpage":288,"year":2026,"type":"Survey","research_area":["Robotics & Control"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6258-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6258-x?year=2026&issue=1","affiliations":["Chinese Academy of Sciences","Institute of Software, CAS","University of Macau","Chang'an University"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-5948-8","title":"Data Preparation for Large Language Models","authors":[{"last":"Liang","first":"Hao"},{"last":"Wong","first":"Zhen Hao"},{"last":"Liu","first":"Rui-Tong"},{"last":"Wang","first":"Yu-Han"},{"last":"Qiang","first":"Mei-Yi"},{"last":"Zhao","first":"Zheng-Yang"},{"last":"Shen","first":"Cheng-Yu"},{"last":"He","first":"Cong-Hui"},{"last":"Zhang","first":"Wen-Tao"},{"last":"Cui","first":"Bin"}],"keywords":["data-centric artificial intelligence (AI)","data management","large language model (LLM)"],"abstract":"Large language models (LLMs) have demonstrated remarkable generalization capabilities across diverse domains, largely attributed to the availability of massive amounts of high-quality training data. Recently, the development paradigm of LLMs has been shifting from a model-centric to a data-centric perspective. In this paper, we provide a comprehensive survey of data preparation algorithms and workflows for LLMs, categorized into three stages: pre-training, continual pre-training, and post-training. We further summarize widely used datasets along with their associated data preparation method, offering a practical reference for researchers who may lack extensive experience in the field of data preparation. Finally, we outline potential directions for future work, highlighting open challenges and opportunities in advancing data preparation for LLMs.","volume":41,"issue":1,"firstpage":289,"lastpage":317,"year":2026,"type":"Survey","research_area":["Deep Learning & Neural Networks","LLM Data & Prompting"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5948-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5948-8?year=2026&issue=1","affiliations":["Peking University","Shanghai Artificial Intelligence Laboratory"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-6426-z","title":"Uncertainty Calibration in Deep Learning: Methods, Emerging Challenges, and LLM Frontiers","authors":[{"last":"Zhang","first":"Min-Ling"},{"last":"Wang","first":"Deng-Bao"}],"keywords":["uncertainty quantification","uncertainty calibration","deep learning","large language models (LLMs)"],"abstract":"Despite the remarkable breakthroughs in deep neural networks (DNNs), the deployment of deep models in high-stakes, safety-critical applications remains a significant challenge. For trustworthy machine learning systems, the ability to provide reliable and well-calibrated uncertainty estimates is fundamental. However, DNNs are notoriously overconfident, often yielding miscalibrated probabilities that hinder their integration into real-world decision-making tasks. This survey provides a comprehensive review of the recent advancements in the field of uncertainty calibration in deep learning. It begins by introducing a range of advanced methods recently proposed for calibrating uncertainty in DNNs. To this end, we organize them into four primary paradigms: train-time regularization, post-hoc adjustments, Bayesian and ensemble neural networks, and hybrid approaches. Then, we transition to emerging research challenges that have gained significant attention in recent years, specifically focusing on calibration challenges in out-of-distribution (OOD) scenarios, uncertainty quantification of generative models, calibration in multimodal learning, and human-AI collaboration setting. Finally, we structure our exploration of uncertainty calibration in large language models (LLMs) around three fundamental research questions: how LLMs express uncertainty, how to evaluate their confidence, and how to effectively calibrate LLMs. By reviewing these diverse perspectives, this paper aims to serve as a holistic roadmap for researchers and practitioners aiming to bridge the gap between predictive performance and model trustworthiness.","volume":41,"issue":1,"firstpage":318,"lastpage":340,"year":2026,"type":"Survey","research_area":["Deep Learning & Neural Networks","Uncertainty & Probabilistic Modeling"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6426-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6426-z?year=2026&issue=1","affiliations":["Southeast University - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-5979-1","title":"A Survey of Quantization in LLM: Unlocking Potential Hardware Efficiency","authors":[{"last":"Chen","first":"Yi-Dong"},{"last":"Zheng","first":"Kai-Jun"},{"last":"Guo","first":"Zhen-Hua"},{"last":"Zhang","first":"Qi-Hao"},{"last":"Zhang","first":"Yong-Hua"},{"last":"Zhai","first":"Ji-Dong"}],"keywords":["quantization","large language model (LLM)","mixed-precision","kernel generation"],"abstract":"Large language models (LLMs) have achieved remarkable progress in natural language processing, but their immense scale leads to significant computational and storage overheads, limiting their deployment and widespread application in resource-constrained environments. Model quantization, as an effective model compression technique, significantly reduces LLMs' memory footprint and computational requirements by lowering the numerical precision of model parameters and/or activations, while striving to maintain minimal performance loss. This survey aims to comprehensively review the latest advancements in LLM quantization, covering various techniques from the pretraining phase to the inference phase. We will delve into state of the art quantization during pretraining, post-training quantization, and quantization-aware training in quantization fine-tuning, and various quantization methods during inference. Through in-depth analysis of these methods, this survey seeks to provide researchers and engineers with a comprehensive understanding of LLM quantization techniques to identify future research directions and offers an insight of how to generate high performance low-precision kernels in different chips.","volume":41,"issue":1,"firstpage":341,"lastpage":358,"year":2026,"type":"Survey","research_area":["LLM Systems & Infrastructure"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5979-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5979-1?year=2026&issue=1","affiliations":["Tsinghua University","Inspur"],"type_origin":"Review"},{"doi":"10.1007/s11390-026-5922-5","title":"Cross-Modal Retrieval from Coarse-Grained to Fine-Grained Perspectives: A Survey","authors":[{"last":"Peng","first":"Yu-Xin"},{"last":"Zheng","first":"Ming-Hang"},{"last":"Liu","first":"Yang"}],"keywords":["cross-modal retrieval","image-text retrieval","video-text retrieval","image grounding","video temporal grounding"],"abstract":"Cross-modal retrieval (CMR) has become a fundamental technique in multimedia understanding and recommendation systems, enabling information retrieval across heterogeneous modalities such as images, videos, and text. While several prior surveys have reviewed the progress of CMR, they are limited by outdated taxonomies and insufficient coverage of recent developments. In particular, most surveys focus on coarse-grained retrieval, which retrieves entire instances given a query, while neglecting fine-grained tasks that require retrieving at a finer semantic level to distinguish different subcategories or retrieving only a specific part of the instance, such as a region within an image or a segment within a video. Moreover, due to the rapid development of large-scale vision-language pre-training (VLP) models and multimodal large language models (MLLMs), many existing surveys fail to capture the impact of these transformative advancements on CMR. To address these gaps, in this survey, we provide a unified taxonomy, categorizing CMR into coarse-grained cross-modal retrieval (CCMR) and fine-grained cross-modal retrieval (FCMR). CCMR aims to retrieve the whole instance based on the given query, such as image-text and video-text retrieval. FCMR aims to distinguish and retrieve specific subordinate-level fine-grained categories within a super-class, or retrieve a part of the instance, such as image grounding and video temporal grounding. Taking both these types into consideration brings a broad view to CMR, bridges the gap between disparate tasks, and offers a comprehensive overview of the field. We review major methodological paradigms, including recent VLP-based and MLLM-based approaches, and summarize widely used datasets and evaluation protocols. Beyond systematic performance comparisons, we also discuss applications and insights for future research.","volume":41,"issue":1,"firstpage":359,"lastpage":393,"year":2026,"type":"Survey","research_area":["Computer Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-5922-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-5922-5?year=2026&issue=1","affiliations":["Peking University"],"type_origin":"Review"},{"doi":"10.1007/s11390-025-6000-0","title":"From MOOC to MAIC: Reimagine Online Teaching and Learning Through LLM-Driven Agents","authors":[{"last":"Yu","first":"Ji-Fan"},{"last":"Zhang-Li","first":"Daniel"},{"last":"Zhang","first":"Zhe-Yuan"},{"last":"Wang","first":"Yu-Cheng"},{"last":"Li","first":"Hao-Xuan"},{"last":"Lim","first":"Joy Jia Yin"},{"last":"Hao","first":"Zhan-Xin"},{"last":"Tu","first":"Shang-Qing"},{"last":"Zhang","first":"Lu"},{"last":"Dai","first":"Xu-Sheng"},{"last":"Jiang","first":"Jian-Xiao"},{"last":"Yang","first":"Shen"},{"last":"Qin","first":"Fei"},{"last":"Li","first":"Ze-Kun"},{"last":"Liu","first":"Bing-Lin"},{"last":"Cong","first":"Xin"},{"last":"Xu","first":"Bin"},{"last":"Hou","first":"Lei"},{"last":"Li","first":"Man-Li"},{"last":"Li","first":"Juan-Zi"},{"last":"Liu","first":"Hui-Qin"},{"last":"Zhang","first":"Yu"},{"last":"Liu","first":"Zhi-Yuan"},{"last":"Sun","first":"Mao-Song"}],"keywords":["intelligent tutoring system","large language model (LLM)","multi-agent system","online education"],"abstract":"Since the first instances of online education, where courses were uploaded to accessible and shared online platforms, this form of scaling the dissemination of human knowledge to reach a broader audience has sparked extensive discussion and widespread adoption. Since personalized learning still holds significant potential for improvement, new artificial intelligence (AI) technologies have been continuously integrated into this learning format, resulting in a variety of educational AI applications such as educational recommendation and intelligent tutoring. The emergence of intelligence in large language models (LLMs) has allowed these educational enhancements to be built upon a unified foundational model, enabling deeper integration. In this context, we propose MAIC (Massive AI-Empowered Course), a new form of online education that leverages LLM-driven multi-agent systems to construct an AI-augmented classroom, balancing scalability with adaptivity. Beyond exploring the conceptual framework and technical innovations, we conduct preliminary experiments at Tsinghua University, Beijing, one of the leading universities in China. Drawing from more than 100 000 learning records of more than 500 students, we obtain a series of valuable observations and initial analyses. This project will continue to evolve, ultimately aiming to establish a comprehensive open platform that supports and unifies research, technology, and applications to explore the possibilities of online education in the era of large-model AI. We envision this platform as a collaborative hub that brings together educators, researchers, and innovators to collectively explore the future of AI-driven online education.","volume":41,"issue":1,"firstpage":394,"lastpage":414,"year":2026,"type":"Regular Paper","research_area":["LLM Agents & Embodied Intelligence"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-6000-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-6000-0?year=2026&issue=1","affiliations":["Tsinghua University"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-6122-z","title":"Automatic Radar-Camera Calibration and Fusion for Traffic Perception","authors":[{"last":"Shi","first":"Pan"},{"last":"Li","first":"Yao"},{"last":"Ren","first":"Hao-Jie"},{"last":"Xia","first":"Rui"},{"last":"Shi","first":"Wei-Kai"},{"last":"Zhang","first":"Yan-Yong"}],"keywords":["intelligent transportation system","spatial-temporal calibration","sensor fusion"],"abstract":"In intelligent transportation systems (ITS), millimeter-wave (MMW) radar-camera fusion has emerged as a cost-effective and viable solution due to low sensor prices. However, deploying such a fusion system in practical far-range scenes faces significant challenges in both sensor calibration and fusion processes. To address these challenges, this paper presents a systematic study from theoretical analysis to practical system deployment. First, we review the status quo of radar-camera fusion systems, comparing existing calibration and fusion paradigms carefully. Through comparative analysis, we find that though feature-level fusion is popular in related research, the target-level fusion is more practical for roadside applications because it is computationally efficient and more robust to depth ambiguity. Second, we introduce an automatic radar-camera calibration and fusion system for real-world traffic perception. This system implements a trajectory-based calibration scheme for spatio-temporal synchronization, specifically tackling the difficulty of identifying distinguishable calibration targets in far-range environments. After calibration, this system applies a robust two-stage target-level fusion method to achieve effective radar-camera fusion in traffic scenes. Finally, we introduce the promising advancements of the proposed system and discuss several open challenges for large-scale and high-safety commercialization. We believe physics-aware self-supervised learning, cooperative perception across roadside devices, and end-to-end perception foundation models are important for future traffic perception systems.","volume":41,"issue":1,"firstpage":415,"lastpage":427,"year":2026,"type":"Perspective","research_area":["Computer Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6122-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6122-z?year=2026&issue=1","affiliations":["Chinese Academy of Sciences","University of Science & Technology of China, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5908-8","title":"Surgical Data Science in Time-Critical Contexts: A Roadmap Toward Brain-Inspired Computing","authors":[{"last":"Pan","first":"Yi"},{"last":"Zou","first":"Shi-Hao"},{"last":"Yang","first":"Jia-Wen"},{"last":"Si","first":"Wei-Xin"},{"last":"Zheng","first":"Wei-Min"}],"keywords":["surgical data science (SDS)","surgical scene understanding","spiking neural network (SNN)"],"abstract":"Surgical data science (SDS) aims to model complex surgical workflows, predict clinical outcomes, and enhance surgical efficiency, patient safety, and personalized treatment. This survey reviews SDS with emphasis on surgical scene understanding, including workflow and phase recognition, skill assessment, intra-operative augmented reality, and surgical embodied intelligence, while also outlining representative datasets and recent progress in deep learning and foundation models in this field. As these tasks are mostly intra-operative, they are inherently time-critical. Delayed or inaccurate responses can directly compromise safety and effectiveness. Yet the scaling laws that have fueled recent breakthroughs in AI now reveal critical bottlenecks: ever-larger models impose prohibitive computational and energy demands, making real-time intra-operative deployment increasingly impractical. To address this challenge, we highlight brain-inspired computing, particularly neuromorphic systems and spiking neural networks (SNNs), as a fundamentally different paradigm designed for ultra-low-latency and energy-efficient processing. Recent prototypes such as IBM NorthPole, Tianjic, ActiveN, and SpiNNaker demonstrate the feasibility of scalable neuromorphic hardware, while SNNs are achieving competitive or even superior performance compared with current deep learning models on tasks ranging from image classification to video understanding. By aligning the efficiency and adaptability of biological neural systems with the stringent time-critical demands of surgery, brain-inspired computing offers a sustainable alternative to GPU-based systems and paves the way toward next-generation AI-assisted surgical systems capable of real-time intelligence.","volume":41,"issue":1,"firstpage":428,"lastpage":446,"year":2026,"type":"Survey","research_area":["Convolutional & Spiking Networks","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5908-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5908-8?year=2026&issue=1","affiliations":["Shenzhen University of Advanced Technology","Chinese Academy of Sciences","Shenzhen Institute of Advanced Technology, CAS","Beihang University"],"type_origin":"Article"},{"doi":"10.1007/s11390-026-6030-2","title":"Artificial Intelligence in Medical Informatics: From Algorithms to Clinical Practice—A Survey","authors":[{"last":"Luo","first":"Yu-Fan"},{"last":"Bu","first":"De-Chao"},{"last":"Wu","first":"Yang"},{"last":"Zhao","first":"Yi"}],"keywords":["medical artificial intelligence","algorithmic innovation","clinical practice","precision medicine"],"abstract":"Artificial intelligence (AI) is reshaping medical informatics from a discipline of data management into a science of integration, inference, and translation. As biomedical data proliferate across physiological, clinical, and molecular domains, AI functions as the integrative engine that transforms complexity into actionable understanding. In this survey, we synthesize recent advances spanning data representation, algorithmic innovation, and clinical deployment, emphasizing the transition from isolated tasks to cohesive systems that link discovery and care. We highlight how advances in medical AI algorithms across clinical data, medical imaging, and multi-omics are beginning to converge with applications in clinical diagnosis, drug discovery, precision medicine, and surgery. Looking ahead, medical AI is moving toward a self-reflective and collaborative paradigm, where progress in multi-modality, trustworthiness, human-machine synergy, and ethical reasoning may allow intelligence to be woven into the pipeline of clinical practice and fulfill its translational promise.","volume":41,"issue":1,"firstpage":447,"lastpage":472,"year":2026,"type":"Survey","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6030-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6030-2?year=2026&issue=1","affiliations":["Chinese Academy of Sciences","University of Chinese Academy of Sciences, CAS","Institute of Computing Technology, CAS"],"type_origin":"Review"},{"doi":"10.1007/s11390-026-6648-0","title":"MRPNet: Workload Utilization Prediction for Configuration Tuning in Distributed Stream Systems","authors":[{"last":"Wang","first":"Zheng-Kai"},{"last":"Zhao","first":"Li-Yong"},{"last":"Peng","first":"Hai-Li"},{"last":"Liu","first":"Hui"},{"last":"Du","first":"Jun-Zhao"}],"keywords":["distributed stream processing system","workload utilization prediction","discrete wavelet decomposition","patching mechanism"],"abstract":"In the context of accelerating digital transformation and intelligent decision-making, distributed stream processing systems have become key infrastructures for supporting real-time analyses of large amounts of unbounded streaming data. To address the complex and difficult-to-predict workload variations in stream processing that may easily lead to insufficient configurations, we propose the Multiresolution Patching Network (MRPNet), a lightweight application workload utilization prediction method. This method integrates multilevel discrete wavelet decomposition and includes a lightweight forecasting branch based on a patching mechanism to enhance the ability to capture local bursty patterns. Moreover, considering the asymmetric cost of prediction errors in configuration decision scenarios, we design a frequency-weighted asymmetric loss function (FWA-Loss), which effectively reduces the underprediction rate and magnitude by imposing heavier penalties on underpredicted samples. The experimental results demonstrate that MRPNet achieves excellent forecasting performance while maintaining a lightweight architecture. Compared with the baseline methods, MRPNet achieves maximum reductions of 13.2% and 14.3% in average symmetric mean absolute percentage error (SMAPE) under 15-min and 5-min sampling intervals, respectively. Moreover, FWA-Loss reduces the underprediction rate and underprediction magnitude by 37.4% and 41.3%, respectively.","volume":null,"issue":null,"firstpage":null,"lastpage":null,"year":2026,"type":"Regular Paper","research_area":["High-Performance & Parallel Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-026-6648-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-026-6648-0?year=2026","affiliations":["Xidian University"],"type_origin":"Article; Early Access"},{"doi":"10.1007/s11390-025-4929-7","title":"Exploring LLM-Based Data Synthesis Strategies for Aligning Medical Consultation Preferences","authors":[{"last":"Dou","first":"Cheng-Feng"},{"last":"Zhang","first":"Ying"},{"last":"Jin","first":"Zhi"},{"last":"Jiao","first":"Wen-Pin"},{"last":"Zhao","first":"Hai-Yan"},{"last":"Zhao","first":"Yong-Qiang"},{"last":"Tao","first":"Zheng-Wei"}],"keywords":["large language model (LLM)","medical dialogue","reinforcement learning from artificial intelligence feedback (RLAIF)","standardized patient testing"],"abstract":"This research explores the application of reinforcement learning from artificial intelligence feedback (RLAIF) techniques to enhance healthcare consultation models, with the aim of addressing the challenges associated with preference-aligned data synthesis while reducing the dependence on medical experts. Specifically, we investigate the use of RLAIF in the generation of medical dialogues, focusing on two primary challenges: accurately reflecting doctors' preferences and the unreliability of existing automated assessment systems. To address these issues, we propose a two-stage approach for synthesizing preference-aligned datasets. In the first stage, we leverage the dialogue continuation capabilities of a large language model to sample diverse, contextually aligned dialogue branches, employing one-shot learning for intervention. The second stage involves modeling doctors' preferences through both outcome and process feedback. For outcome feedback, a rule-based reward system is utilized, whereas a planning-based reward strategy is employed for process feedback. To validate our approach, we develop the Chinese Standardized Patient Test (CSPT) dataset that emphasizes user guiding, instruction following, and synthesis ability, and construct an objective assessment system based on standardized patient testing. Experimental results demonstrate that our data synthesis approach performs well across five datasets, achieving a 17.6% improvement in diagnostic accuracy with outcome feedback and a 23.3% improvement with process feedback.","volume":40,"issue":6,"firstpage":1485,"lastpage":1498,"year":2025,"type":"Regular Paper","research_area":["Bioinformatics & Life Sciences","Deep Learning & Neural Networks","Reinforcement Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4929-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4929-7?year=2025&issue=6","affiliations":["Peking University","Beijing Jiaotong University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4333-3","title":"Imputation with Inter-Series Information from Prototypes for Healthcare Time Series","authors":[{"last":"Yu","first":"Zhi-Hao"},{"last":"Ma","first":"Lian-Tao"},{"last":"Wang","first":"Ya-Sha"},{"last":"Chu","first":"Xu"}],"keywords":["time series imputation","healthcare time series analysis","prototype learning"],"abstract":"Time series with missing values are ubiquitous in healthcare scenarios, presenting significant challenges for analysis. Despite existing methods addressing imputation, they predominantly focus on leveraging intra-series information, neglecting the potential benefits that inter-series information could provide, such as reducing uncertainty and memorization effect. To bridge this gap, we propose PRIME, Prototype Recurrent Imputation ModEl, which integrates both intra-series and inter-series information for imputing missing values in irregularly sampled time series. PRIME comprises a prototype memory module for learning inter-series information, a bidirectional gated recurrent unit utilizing prototype information for imputation, and an attentive prototypical refinement module for adjusting imputations. We conduct extensive experiments on four datasets, and the results underscore PRIME's superiority over the state-of-the-art models by up to 26% relative improvement in mean square error. Our code is available at https://jcst.ict.ac.cn/news/382.","volume":40,"issue":6,"firstpage":1499,"lastpage":1511,"year":2025,"type":"Regular Paper","research_area":["Bioinformatics & Life Sciences"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4333-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4333-3?year=2025&issue=6","affiliations":["Peking University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4761-0","title":"SwFormer: Enabling Faster Foundation Models on New Sunway Supercomputer via Holistic Kernel Tiling and Scheduling","authors":[{"last":"Wu","first":"Ruo-Han"},{"last":"Zhu","first":"Xian-Yu"},{"last":"Chen","first":"Jun-Shi"},{"last":"An","first":"Hong"}],"keywords":["deep learning","foundation model","Sunway architecture","fine-grained tiling","operator scheduling"],"abstract":"Deep learning's continuous evolution has driven the creation of increasingly large foundation models, such as GPT-3, which requires optimized performance on large-scale computing platforms. The new Sunway Supercomputer, equipped with numerous SW26010pro processors, supports AI workloads in both all-shared and single-CG (core group) modes. However, existing optimizations primarily target AI operators like Generalized Matrix Multiplication (GEMM) in the single-CG mode, leaving challenges in scaling performance across all six CGs in the all-shared mode. This paper introduces SwFormer, a framework designed to accelerate foundation models via intra-op tiling and inter-op scheduling. The intra-op tiling method breaks down operators into fine-grained tiled kernels and employs an offline profiling-based approach to determine the optimal tiling strategy. The inter-op scheduling method employs heuristic graph traversal algorithms to automatically reorder the computation of these tiled kernels, thereby maximizing hardware utilization. Compared with operator libraries for the all-shared mode such as SWDNNv2 and SWattention, SwFormer's intra-op tiling method accelerates end-to-end GPT-3 6.7B and 13B models training by up to 1.27x. Evaluated with GPT-style models, the inter-op scheduling method further outperforms the intra-op tiling method by up to 1.32x.","volume":40,"issue":6,"firstpage":1512,"lastpage":1529,"year":2025,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","LLM Systems & Infrastructure","Scheduling & Resource Allocation"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4761-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4761-0?year=2025&issue=6","affiliations":["Chinese Academy of Sciences","University of Science & Technology of China, CAS","Laoshan Laboratory"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-4251-9","title":"SENTRY: Lifetime Secure Technique for Industry Embedded Non-Volatile Random-Access Memory","authors":[{"last":"Guo","first":"Zi-Long"},{"last":"Chang","first":"Liang"},{"last":"Liu","first":"Jian-Wei"},{"last":"Tan","first":"Hai-Ning"},{"last":"Zhou","first":"Jing"},{"last":"Wu","first":"Qiang"}],"keywords":["embedded nonvolatile memory","endurance","wear-leveling","resistive random access memory","magnetic random access memory"],"abstract":"Emerging non-volatile memories (NVMs), including resistive random-access memory (RRAM) and magnetic random-access memory (MRAM), have been promising solutions for intelligent embedded systems. With the non-volatility and low leakage power consumption, the industry-based embedded NVMs can be used to develop energy-efficient artificial intelligent processors. However, industry-based NVMs typically have low endurance with only 10^4 to 10^6 maximum write times, shortening the lifetime of embedded systems. In addition, non-uniform write distribution to physical addresses onto NVMs may further reduce system lifetime. Furthermore, several intentional attacks, such as malicious writing, may impair embedded NVMs. In this paper, we present a novel wear-leveling technique based on row-column data movement, SENTRY, to extend system lifetime. We explore industry-based embedded NVM chips and analyze practical data distributions of several tasks. We design a coordinate system based moving method with negligible storage overhead for more efficient data movement. The experiment shows that SENTRY achieves a 96.07% life utilization rate with 1.47% data movement overhead. In addition, SENTRY increases the endurance margin of memory by 6048 x compared with an unprotected baseline (without SENTRY) under malicious address attacks.","volume":40,"issue":6,"firstpage":1530,"lastpage":1545,"year":2025,"type":"Regular Paper","research_area":["Memory & Storage Systems","Real-Time & Embedded Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4251-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4251-9?year=2025&issue=6","affiliations":["University of Electronic Science and Technology of China","Chinese Academy of Sciences","Nanjing Houmo Technology Co., Ltd."],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-025-4285-7","title":"HI-SM3: High-Performance Implementation of SM3 Hash Function on Heterogeneous GPUs","authors":[{"last":"Dong","first":"Jian-Kuo"},{"last":"Wu","first":"Wen"},{"last":"Lu","first":"Sheng"},{"last":"Sha","first":"Le-Tian"},{"last":"Zheng","first":"Fang-Yu"},{"last":"Xiao","first":"Fu"},{"last":"Wang","first":"Hua-Qun"}],"keywords":["SM3","heterogeneous GPU","CUDA","cryptographic engineering"],"abstract":"Hash functions are essential in cryptographic primitives such as digital signatures, key exchanges, and blockchain technology. SM3, built upon the Merkle-Damgard structure, is a crucial element in Chinese commercial cryptographic schemes. Optimizing hash function performance is crucial given the growth of Internet of Things (IoT) devices and the rapid evolution of blockchain technology. In this paper, we introduce a high-performance implementation framework for accelerating the SM3 cryptography hash function, short for HI-SM3, using heterogeneous GPU (graphics processing unit) parallel computing devices. HI-SM3 enhances the implementation of hash functions across four dimensions: parallelism, register utilization, memory access, and instruction efficiency, resulting in significant performance gains across various GPU platforms. Leveraging the NVIDIA RTX 4090 GPU, HI-SM3 achieves a remarkable peak performance of 454.74 GB/s, surpassing OpenSSL on a high-end server CPU (E5-2699V3) with 16 cores by over 150 times. On the Hygon DCU accelerator, a Chinese domestic graphics card, it achieves 113.77 GB/s. Furthermore, compared with the fastest known GPU-based SM3 implementation, HI-SM3 on the same GPU platform exhibits a 3.12x performance improvement. Even on embedded GPUs consuming less than 40W, HI-SM3 attains a throughput of 5.90 GB/s, which is twice as high as that of a server-level CPU. In summary, HI-SM3 provides a significant performance advantage, positioning it as a compelling solution for accelerating hash operations.","volume":40,"issue":6,"firstpage":1546,"lastpage":1562,"year":2025,"type":"Regular Paper","research_area":["Cryptographic Hardware","GPU & Accelerator Architecture","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4285-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4285-7?year=2025&issue=6","affiliations":["Nanjing University of Posts & Telecommunications","Chinese Academy of Sciences","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4366-7","title":"DSBP: Data-Free and Swift Backdoor Purification for Trustworthy Federated Learning via Multi-Teacher Adversarial Distillation","authors":[{"last":"Li","first":"Gao-Lei"},{"last":"Wu","first":"Jun"},{"last":"Li","first":"Jian-Hua"},{"last":"Zhao","first":"Yuan-Yuan"},{"last":"Lian","first":"Hui-Juan"},{"last":"Zheng","first":"Long-Fei"}],"keywords":["federated learning (FL)","multi-teacher distillation","backdoor attack","data-free","backdoor purification"],"abstract":"Federated learning (FL) faces severe backdoor threats. Due to the inaccessibility of clean samples, the parameter server cannot clean them up in real time even if poisoning features are discovered. Meanwhile, existing backdoor defense methods always require sacrificing model accuracy or increasing communication delay in exchange for better FL trustworthiness. To address these challenges, we propose a novel data-free and swift backdoor purification (DSBP) scheme based on multi-teacher adversarial distillation to effectively erase various backdoor variants in FL. DSBP treats the purification task as an adversarial game process between knowledge inheritance and backdoor inhibition by enforcing the student model to learn ensemble results of multiple teacher models on reconstructed clean samples, while being insensitive to synthetic poisoned samples. In DSBP, we utilize the self-similarity of poisoned features to optimize the trigger generator and accelerate the convergence of DSBP during the adversarial distillation process. We validate the effectiveness of DBSP by comparing it with four state-of-the-art defense methods against three backdoor variants on three datasets. The average attack success rate can be reduced from 96.6% to 2.3% with only 300 rounds.","volume":40,"issue":6,"firstpage":1563,"lastpage":1576,"year":2025,"type":"Regular Paper","research_area":["Federated Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4366-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4366-7?year=2025&issue=6","affiliations":["Shanghai Jiao Tong University","Hangzhou Normal University","Zhengzhou University","Ant Group"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4583-0","title":"U2CMigration: User-Unaware Container Migration with Predictive Analysis of Memory Dirty Pages","authors":[{"last":"Peng","first":"Yong"},{"last":"Xu","first":"Fei"},{"last":"Wei","first":"Zong-Qing"},{"last":"Lin","first":"Shuo-Hao"},{"last":"Zhou","first":"Zhi"},{"last":"Zhang","first":"Miao"}],"keywords":["container live migration","memory dirty page","prediction method","spatio-temporal characteristic","system-level feature"],"abstract":"Container live migration serves as the cornerstone of maintaining containerized workloads in cloud and edge datacenters, particularly for stateful applications. However, the de facto memory pre-copy-based migration faces severe performance issues for containers with dynamically changing memory dirty pages. Existing research often overlooks such dynamic nature of memory pages of various workloads and their unpredictable relationship with system-level features, causing unwise stop-and-copy iterations of container migrations. This can prolong container migrations by tens of seconds, severely degrading application performance. To address these challenges, we introduce U2CMigration, a user-unaware container live migration strategy for containerized workloads. It employs a lightweight and autonomous two-phase prediction by analyzing container memory pages across various workloads. We utilize the data shift prediction for stable memory pages (phase-1). For unstable memory pages (phase-2), we develop an attention-based prediction that jointly considers the spatio-temporal characteristics of memory pages and system-level features. Guided by dirty page predictions, we further develop a container live migration strategy that judiciously decides the optimal stop-and-copy iteration with the minimum amount of memory dirty pages. We have implemented an open-source prototype of U2CMigration (https://doi.org/10.57760/sciencedb.32136) based on the CRIU (checkpoint/restore in userspace) project. Extensive prototype experiments demonstrate that U2CMigration reduces the container migration duration by 26.1%-47.9% and the downtime by 21.3%-32.6% compared with the state-of-the-art solutions.","volume":40,"issue":6,"firstpage":1577,"lastpage":1592,"year":2025,"type":"Regular Paper","research_area":["Cloud, Edge & Utility Computing","Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4583-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4583-0?year=2025&issue=6","affiliations":["National University of Defense Technology - China","East China Normal University","Sun Yat Sen University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4616-8","title":"Performance Modeling and Testing of DAG-Based Distributed Ledger Systems","authors":[{"last":"Shi","first":"Jing"},{"last":"Bai","first":"Xiao-Ying"},{"last":"Zhang","first":"Wen-Zheng"},{"last":"Li","first":"Pei-Lun"},{"last":"Wu","first":"Kai-Dong"},{"last":"Yang","first":"Guo-Li"},{"last":"Zhang","first":"Ming-Tao"}],"keywords":["distributed ledger system","blockchain","directed acyclic graph (DAG)","performance testing","performance modeling"],"abstract":"Performance is a major concern of the large-scale application of distributed ledger systems (DLSs). Compared with chain-based DLSs, directed acyclic graph (DAG)-based DLSs are promising to enhance transaction parallel processing capabilities greatly and have gained increasing interest. However, due to the complex technology stack, current metrics, such as transactions per second (TPS) and latency, are insufficient for a deep understanding of DAG-based DLS performance. To address this problem, based on a comprehensive analysis of the transaction lifecycle process, we propose a state model and a set of performance indicators by identifying the key operations in the workflow. Then we develop an automated testing tool and conduct experiments on two representative open-source systems, IOTA and Conflux, considering their open-source nature, extensive documentation, and representativeness. The experiments profile the DAG-based DLS performance with respect to the system architecture, DAG topology, runtime behavior, and DAG processing mechanisms. The state model, indicators, and key experiment findings are valuable for future DLS design, deployment, and performance optimization.","volume":40,"issue":6,"firstpage":1593,"lastpage":1607,"year":2025,"type":"Regular Paper","research_area":["Blockchain & Distributed Ledger","High-Performance & Parallel Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4616-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4616-8?year=2025&issue=6","affiliations":["Peking University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4788-2","title":"vTensor-Based GPU Memory Management for Edge Deep Learning Training","authors":[{"last":"Gao","first":"He-Ran"},{"last":"Luo","first":"Diao-Han"},{"last":"Wu","first":"Yue-Wen"},{"last":"Wu","first":"Heng"},{"last":"Zhang","first":"Wen-Bo"}],"keywords":["deep learning training","vTensor","memory management","memory swapping","memory layout"],"abstract":"Supporting real-time and privacy-preserving learning at the edge is emerging as a critical trend, bringing forth substantial challenges for deep learning (DL) training in the context of limited GPU (graphic processing unit) memory. Recent work has sought to address the limitations by swapping tensors between GPU memory and CPU memory. Unfortunately, their tensor-based memory management encounters additional overhead since the swapped tensors do not align with the actual memory demands, resulting in decreased throughput. This paper introduces a vTensor-based memory management approach designed to mitigate memory swapping overhead. Virtualized tensors, dubbed vTensors, are used to finely align memory swapping amounts with real-time memory demands. Firstly, we introduce an abstraction layer that virtualizes coarse-grained tensors to multiple finer-grained vTensors. Secondly, we propose the Layered Graph Model (LGM) for analyzing vTensor mappings, which produces a memory swapping plan leveraged in the subsequent DL training iterations. Evaluations conducted on typical edge deep learning models illustrate that our approach surpasses prior work with a 15.60% increase in DL training throughput.","volume":40,"issue":6,"firstpage":1608,"lastpage":1625,"year":2025,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4788-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4788-2?year=2025&issue=6","affiliations":["Chinese Academy of Sciences","Institute of Software, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4928-8","title":"MVCASyn: Predicting Synergistic Drug Combinations Based on Multi-View Learning and Cross-Attention Mechanism","authors":[{"last":"Xie","first":"Chen-Liang"},{"last":"Zhao","first":"Hao-Chen"},{"last":"Wang","first":"Jian-Xin"}],"keywords":["anticancer drug combination","molecular representation learning","synergistic prediction"],"abstract":"The increase in cancer drug resistance poses an enormous challenge in implementing effective therapeutic interventions. Combination therapy has emerged as an effective method to combat this resistance, but traditional methods for identifying viable drug combinations are often cumbersome and resource intensive. Recently, computational models have been developed to simplify the prediction of viable drug combinations, thereby improving the efficiency of this field of research. However, many existing models treat drug combinations independently, ignoring the crucial interaction dynamics between them. Moreover, these models fail to exploit the complementary insights provided by cell line multiomics data. In this work, we propose MVCASyn, an innovative deep learning model that predicts synergistic drug combinations. Compared with existing models, MVCASyn combines a dual-view representation learning module to precisely extract the multilevel features of atomic interactions, and adopts a cross-attention mechanism to fuse cell line multiomics data. Our experimental results show that MVCASyn consistently outperforms the current advanced models across all the evaluation metrics. Visualization experiments of drug atomic importance scores further emphasize the ability of MVCASyn to identify key drug substructures. A case study experiment also confirms that MVCASyn is effective in practical applications. The code of MVCASyn is publicly accessible at https://doi.org/10.57760/sciencedb.31476.","volume":40,"issue":6,"firstpage":1626,"lastpage":1638,"year":2025,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4928-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4928-8?year=2025&issue=6","affiliations":["Central South University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4969-z","title":"scMCG: Analyzing a Single-Cell Assay for Transposase-Accessible Chromatin Using Sequencing Data Based on Contrastive Learning and Generative Adversarial Network","authors":[{"last":"Lan","first":"Wei"},{"last":"He","first":"Guo-Hang"},{"last":"Zhou","first":"Wei-Hao"},{"last":"Chen","first":"Qing-Feng"},{"last":"Zheng","first":"Rui-Qing"},{"last":"Pan","first":"Yi"},{"last":"Chen","first":"Yi-Ping Phoebe"}],"keywords":["single-cell assay for transposase-accessible chromatin using sequencing (scATAC-seq)","contrastive learning","convolutional neural network","generative adversarial network"],"abstract":"The development of single-cell assay for transposase-accessible chromatin using sequencing (scATAC-seq) has significantly advanced the study of cell heterogeneity in the epigenetic landscape. Numerous studies have leveraged scATAC-seq data to explore deeper gene regulatory relationships. However, scATAC-seq usually faces dropout events which may result in data sparsity and noise. In this work, we propose a method (scMCG) for analyzing scATAC-seq data that employs contrastive learning and a generative adversarial network (GAN). First, the scMCG method uses two distinct encoders for contrastive learning to solve the issues of feature redundancy and data sparsity in scATAC-seq data. Subsequently, a generator is used to reconstruct the latent embedding. Finally, a decoder is used to generate binary accessibility. We conduct experiments on multiple scATAC-seq datasets. The results demonstrate that the scMCG method achieves excellent performance in multiple tasks such as cell clustering and transcription factor activity influence.","volume":40,"issue":6,"firstpage":1639,"lastpage":1649,"year":2025,"type":"Regular Paper","research_area":["Bioinformatics & Life Sciences","Contrastive & Self-Supervised Learning","Convolutional & Spiking Networks","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4969-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4969-z?year=2025&issue=6","affiliations":["Guangxi University","Central South University","Chinese Academy of Sciences","Shenzhen Institute of Advanced Technology, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4999-6","title":"Predicting Cancer Driver Genes via Contrastive Graph Diffusion and Dynamic Weighting","authors":[{"last":"Peng","first":"Wei"},{"last":"Xu","first":"Xin-Ping"},{"last":"Dai","first":"Wei"},{"last":"Zhou","first":"Zheng-Nan"},{"last":"Fu","first":"Xiao-Dong"},{"last":"Liu","first":"Li"},{"last":"Liu","first":"Li-Jun"}],"keywords":["cancer driver gene","protein-protein interaction","graph diffusion","graph contrastive learning"],"abstract":"Accurate identification of mutation-driven cancer driver genes is vital for cancer biology and targeted therapy. To address noise in protein-protein interaction (PPI) networks, we propose DGCL_DWA, a novel method utilizing graph diffusion and contrastive learning. DGCL_DWA first employs personalized PageRank to generate a diffusion graph, revealing hidden biological connections. Chebyshev graph convolution extracts features from both the PPI and diffusion networks, and neighborhood contrastive learning harmonizes gene representations, reducing noise. The network-specific features are refined via Chebyshev graph convolutions, which are constrained via node classification and link prediction. A dynamic weight adjustment strategy balances task-specific losses during training. Finally, logistic regression is used to predict driver genes. The experimental results demonstrate the superior performance in pan-cancer and specific cancer driver gene identification compared with state-of-the-art methods. Ablation studies confirm the positive impact of the diffusion graph, contrastive learning, and dynamic weight adjustment on predictive accuracy. The source codes are available at https://doi.org/10.57760/sciencedb.31933.","volume":40,"issue":6,"firstpage":1650,"lastpage":1661,"year":2025,"type":"Regular Paper","research_area":["Contrastive & Self-Supervised Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4999-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4999-6?year=2025&issue=6","affiliations":["Kunming University of Science & Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4745-0","title":"ISC4DGF: Enhancing Directed Grey-Box Fuzzing with Initial Seed Corpus Generation Driven by Large Language Models","authors":[{"last":"Xu","first":"Yi-Jiang"},{"last":"Jia","first":"Hong-Rui"},{"last":"Chen","first":"Li-Guo"},{"last":"Wang","first":"Xin"},{"last":"Zeng","first":"Zheng-Ran"},{"last":"Wang","first":"Yi-Dong"},{"last":"Gao","first":"Qing"},{"last":"Ye","first":"Wei"},{"last":"Zhang","first":"Shi-Kun"},{"last":"Wu","first":"Zhong-Hai"}],"keywords":["fuzz testing","directed grey-box fuzzing","large language model (LLM)","initial seed corpus"],"abstract":"Fuzz testing is crucial for identifying software vulnerabilities, with coverage-guided grey-box fuzzers like AFL and Angora excelling in broad detection. However, as the need for targeted detection grows, directed grey-box fuzzing (DGF) has become essential, focusing on specific vulnerabilities. The initial seed corpus, which consists of carefully selected input samples that the fuzzer uses as a starting point, is fundamental in determining the paths that the fuzzer explores. A well-designed seed corpus can guide the fuzzer more effectively towards critical areas of the code, improving the efficiency and success of the fuzzing process. Even with its importance, much work concentrates on refining guidance mechanisms while paying less attention to optimizing the initial seed corpus. In this paper, we introduce ISC4DGF, a novel approach to generating optimized initial seed corpus for DGF using large language models (LLMs). By leveraging LLMs' deep understanding of software and refined user inputs, ISC4DGF creates a precise seed corpus that efficiently triggers specific vulnerabilities through a multi-round validation process. Implemented on AFL and tested against state-of-the-art fuzzers such as Titan, BEACON, AFLGo, FairFuzz, and Entropic using the Magma benchmark, ISC4DGF achieves a 25.03x speedup with fewer target reaches. Moreover, ISC4DGF improves target vulnerabilities detection accuracy while narrowing the detection scope and reducing code coverage.","volume":40,"issue":6,"firstpage":1662,"lastpage":1677,"year":2025,"type":"Regular Paper","research_area":["LLM Systems & Infrastructure","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4745-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4745-0?year=2025&issue=6","affiliations":["Peking University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4684-9","title":"A Separation Logic for Sequences in Block-Based Cloud Storage Systems and Its Decidability","authors":[{"last":"Cao","first":"Tian-Yue"},{"last":"Zhang","first":"Bo-Wen"},{"last":"Jin","first":"Zhao"},{"last":"Cao","first":"Yong-Zhi"},{"last":"Wang","first":"Han-Pin"}],"keywords":["cloud storage system","decidability","formal verification","logic","separation logic"],"abstract":"Cloud storage systems are crucial for ensuring business stability and data reliability. Among them, block-based cloud storage systems (BCSSs) have been widely adopted in the industry due to their high efficiency and strong performance. However, system failures occur from time to time, causing significant financial losses to companies. Therefore, verifying the reliability of BCSSs has become important and urgent. Nevertheless, since blocks in these systems are of finite but variable sizes, it is difficult to describe and verify properties using first-order logic or separation logic. To address this issue, we propose Sequence-Heap Separation Logic (SeqSL), which introduces sequence values and sequence variables into separation logic. Our logic can simplify property expressions while enhancing the ability to describe these systems. To provide a theoretical foundation for verification, we study the decidability of this logic, with the main conclusions as follows. 1) The satisfiability problem of the fragment with a single quantifier alternation is decidable, and belongs to 2-EXPTIME (2-Exponential Time). As a by-product, we propose a decision procedure for this decidable fragment. 2) The satisfiability problem of the fragment with two quantifier alternations is undecidable.","volume":40,"issue":6,"firstpage":1678,"lastpage":1692,"year":2025,"type":"Regular Paper","research_area":["Formal Methods & Verification","Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4684-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4684-9?year=2025&issue=6","affiliations":["Peking University","Zhengzhou University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-0004-7","title":"Searching for an Intuitive Metric for Scalable Internet of Things","authors":[{"last":"Xu","first":"Zhi-Wei"}],"keywords":[],"abstract":"","volume":40,"issue":5,"firstpage":1181,"lastpage":1181,"year":2025,"type":"Perspective","research_area":["IoT & Wireless Networks","Network Protocols & Measurement"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-0004-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-0004-7?year=2025&issue=5","affiliations":["Great Bay University"],"type_origin":"Editorial Material","cover_doi":"10.1007/s11390-025-5178-5","topic_source":"cover_inherited"},{"doi":"10.1007/s11390-025-5178-5","title":"On the Scalability of Internet of Things Systems","authors":[{"last":"Wang","first":"Ji-Liang"},{"last":"Tong","first":"Shuai"},{"last":"Li","first":"Xiang-Yang"},{"last":"Yang","first":"Zheng"},{"last":"Xiao","first":"Fu"},{"last":"Liu","first":"Yun-Hao"}],"keywords":["Internet of Things (IoT)","network scalability","wireless sensor network","routing protocol"],"abstract":"The rapid growth of the Internet of Things (IoT) demands efficient system architectures and protocols to ensure consistent performance at scale. This paper explores the scalability of IoT systems across three key layers: sensing, network, and control. IoT scalability is the ability of a system to maintain consistent and reliable performance despite a continuous increase in connected devices. To evaluate scalability, we introduce the scalability indicator (SI), a metric designed to assess an IoT system's scalability capability. Through extensive research and real-world deployments, we identify key challenges in data sensing, routing, and system control. Our study presents a model to understand these challenges and proposes strategies to optimize resource utilization, ensuring efficient data collection. The findings also emphasize the key influencing factors for the stable performance of large-scale IoT systems, providing valuable insights for how to design scalable systems that can meet the growing demand for interconnected devices.","volume":40,"issue":5,"firstpage":1182,"lastpage":1194,"year":2025,"type":"Regular Paper","research_area":["IoT & Wireless Networks","Network Protocols & Measurement"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5178-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5178-5?year=2025&issue=5","affiliations":["Tsinghua University","Chinese Academy of Sciences","University of Science & Technology of China, CAS","Nanjing University of Posts & Telecommunications"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-0005-6","title":"The Preface","authors":[{"last":"Wan","first":"Xiao-Jun"},{"last":"Wong","first":"Derek F."},{"last":"Zhang","first":"Yue"}],"keywords":[],"abstract":"","volume":40,"issue":5,"firstpage":1195,"lastpage":1196,"year":2025,"type":"Regular Paper","research_area":[],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-0005-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-0005-6?year=2025&issue=5","affiliations":["Peking University","University of Macau","Westlake University"],"type_origin":"Editorial Material"},{"doi":"10.1007/s11390-025-5508-7","title":"AllGuard: A Multimodal Large Language Model for Edge-Deployed Content Security Assessment","authors":[{"last":"Qu","first":"Wei"},{"last":"Lu","first":"Wei"},{"last":"Chen","first":"Cong"},{"last":"Li","first":"Tao"},{"last":"Chen","first":"Hao-Dong"},{"last":"Du","first":"Rui-Qi"},{"last":"Ling","first":"Xin-Yu"}],"keywords":["multimodal","context moderation","large language model (LLM)","artificial intelligent generated content (AIGC)","end-side device"],"abstract":"The rapid advancement of artificial intelligent generated content (AIGC) technologies and the growth of the digital economy have led to an explosion in heterogeneous content creation, posing increasingly complex challenges for content moderation (CM). While large language models (LLMs) have made significant progress in CM, most existing frameworks are limited to single-modality inputs (e.g., text), and are therefore inadequate for detecting nuanced or latent risks in multimodal data. Moreover, the computational demands of LLMs hinder their deployment on edge devices with limited resources. To address these challenges, we propose AllGuard-a lightweight, scalable multimodal CM framework optimized for edge deployment. AllGuard integrates a modular pipeline capable of handling text, image, audio, and video inputs through multimodal tokenization and prompt-based safety reasoning. We construct and annotate a high-quality multimodal dataset based on a comprehensive safety taxonomy, and fine-tune LLM using LoRA (Low-Rank Adaptation)-based adaptation for efficient model specialization. Empirical results show that AllGuard achieves state-of-the-art performance across multiple modalities, with an overall accuracy of 91.58% and strong generalization on edge hardware, maintaining over 90.66% accuracy on both the Jetson Orin and Orange Pi 5 Plus platforms. Our work provides a practical, robust, and deployable solution for real-world CM, promoting the safe and responsible use of AIGC applications.","volume":40,"issue":5,"firstpage":1197,"lastpage":1208,"year":2025,"type":"Regular Paper","research_area":["Security, Privacy & Cryptography","LLM Evaluation & Benchmarking"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5508-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5508-7?year=2025&issue=5","affiliations":["Hunan University of Science & Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5512-y","title":"KnowBench: Evaluating the Knowledge Alignment on Large Visual Language Models","authors":[{"last":"Ma","first":"Zheng"},{"last":"Yang","first":"Hao-Tian"},{"last":"Zhang","first":"Jian-Bing"},{"last":"Chen","first":"Jia-Jun"}],"keywords":["large visual language model (LVLM)","knowledge alignment","image and text fusing","evaluation benchmark"],"abstract":"Large visual language models (LVLMs) have revolutionized the multimodal domain, demonstrating exceptional performance in tasks requiring fusing visual and textual information. However, the current evaluation benchmarks fail to adequately assess the knowledge alignment between images and text, focusing primarily on answer accuracy rather than the reasoning processes behind them. To address this gap and enhance the understanding of LVLMs' capabilities, we introduce KnowBench, a novel benchmark designed to assess the alignment of knowledge between images and text for LVLMs. KnowBench comprises 1 081 image-question pairs, each with four options and four pieces of corresponding knowledge across 11 major categories. We evaluate mainstream LVLMs on KnowBench, including proprietary models like Gemini, Claude, and GPT, and open-source models like LLaVA, Qwen-VL, and InternVL. Our experiments reveal a notable discrepancy in the models' abilities to select correct answers and corresponding knowledge whether the models are open-source or proprietary. This indicates that there is still a significant gap in the current LVLMs' knowledge alignment between images and text. Furthermore, our further analysis shows that model performance on KnowBench improves with increased parameters and version iterations. This indicates that scaling laws have a significant impact on multimodal knowledge alignment, and the iteration of the model by researchers also has a positive effect. We anticipate that KnowBench will foster the development of LVLMs and motivate researchers to develop more reliable models. We have made our dataset publicly available at https://doi.org/10.57760/sciencedb.29672.","volume":40,"issue":5,"firstpage":1209,"lastpage":1219,"year":2025,"type":"Regular Paper","research_area":["Computer Vision","LLM Evaluation & Benchmarking"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5512-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5512-y?year=2025&issue=5","affiliations":["Nanjing University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5514-9","title":"CodeRankEval: Benchmarking and Analyzing LLM Performance for Code Ranking","authors":[{"last":"Chen","first":"Li-Guo"},{"last":"Xiao","first":"Zheng"},{"last":"Xu","first":"Yi-Jiang"},{"last":"An","first":"Rui-Chuan"},{"last":"Wang","first":"Xin"},{"last":"Li","first":"Yang-Ning"},{"last":"Li","first":"Ying-Hui"},{"last":"Wang","first":"Yi-Dong"},{"last":"Zeng","first":"Zheng-Ran"},{"last":"Gao","first":"Qing"},{"last":"Zhang","first":"Shi-Kun"}],"keywords":["large language model (LLM)","code ranking","benchmark dataset","empirical study"],"abstract":"Large language models (LLMs) are increasingly applied across diverse software engineering tasks. Consequently, their ability to effectively rank code quality is crucial for applications like selecting optimal solutions and aiding code review. However, evaluating this essential code ranking capability is hampered by a lack of benchmarks covering diverse paradigms and robustness testing. To address this, we introduce CodeRankEval, a benchmark suite for multi-paradigm evaluation, and CodeRankEval-Perturbed for robustness testing against common code flaws. Our empirical study reveals key insights: pairwise ranking yields the highest accuracy but is costly; listwise is the cheapest and shows comparable performance with pairwise; pointwise generally exhibits lower performance with intermediate cost. Besides, ranking ability correlates positively with generation ability, models show reasonable robustness to perturbations but may exhibit positional bias. Overall, this work provides valuable resources and insights for understanding and improving LLM-based code ranking evaluation.","volume":40,"issue":5,"firstpage":1220,"lastpage":1233,"year":2025,"type":"Regular Paper","research_area":["Code Intelligence & Maintenance","LLM Evaluation & Benchmarking"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5514-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5514-9?year=2025&issue=5","affiliations":["Peking University","Tsinghua University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-0006-5","title":"The Preface","authors":[{"last":"Hu","first":"Shi-Min"},{"last":"Didyk","first":"Piotr"},{"last":"Hou","first":"Junhui"}],"keywords":[],"abstract":"","volume":40,"issue":5,"firstpage":1234,"lastpage":1235,"year":2025,"type":"Regular Paper","research_area":[],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-0006-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-0006-5?year=2025&issue=5","affiliations":["Tsinghua University","Universita della Svizzera Italiana","City University of Hong Kong"],"type_origin":"Editorial Material"},{"doi":"10.1007/s11390-025-5462-4","title":"A Survey of Recent Advances in Generative 3D Reconstruction","authors":[{"last":"Huang","first":"Shi-Sheng"},{"last":"Zhang","first":"Shao-Kui"},{"last":"Yang","first":"Sheng"},{"last":"Guo","first":"Jian-Wei"},{"last":"Huang","first":"Hua"}],"keywords":["generative 3D reconstruction","generative AI model","diffusion model"],"abstract":"Inspired by the rapid progress of generative AI techniques, there have been huge advances made for the 3D (three-dimensional) reconstruction community, which promoted the traditional 3D reconstruction framework from deep implicit 3D reconstruction to generative 3D reconstruction, achieving more robust and expansive 3D reconstruction results with the help of generative AI models. Meanwhile, there is still a lack of corresponding review articles to provide a comprehensive analysis of recent advances from the perspective of 3D reconstruction. In response, this paper gives a comprehensive review for the generative 3D reconstruction approaches, especially on the recent advances made from the computer graphics and vision communities. Firstly, this paper mainly divides the recent generative 3D reconstruction approaches into four categories, including generative structure-from-motion/multiview-sterero (SfM/MVS), generative adversarial networks (GAN) based 3D reconstruction, diffusion-based 3D reconstruction, and cross-modal 3D reconstruction, which cover most generative-model aided 3D reconstruction work with a comprehensive review and analysis. Thereafter, some representative applications inspired by the generative 3D reconstruction including dynamic human avatars, 3D interactive editing, and autonomous driving are also reviewed. Besides, some major datasets widely used for the generative 3D reconstruction approaches are included. Finally, this paper makes a discussion of the potential future work in further improving the quality of generative 3D reconstruction, towards better and more intelligent 3D reconstruction and generation.","volume":40,"issue":5,"firstpage":1236,"lastpage":1254,"year":2025,"type":"Survey","research_area":["Generative Models","Point Cloud & 3D Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5462-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5462-4?year=2025&issue=5","affiliations":["Beijing Normal University","Alibaba Group"],"type_origin":"Review"},{"doi":"10.1007/s11390-025-5239-9","title":"Efficient and Structure-Aware Three-Dimensional Reconstruction via Differentiable Primitive Abstraction","authors":[{"last":"Zhang","first":"Gao-Yang"},{"last":"Chen","first":"Ying-Xi"},{"last":"Li","first":"Han-Chao"},{"last":"Liu","first":"Xin-Guo"}],"keywords":["neural surface reconstruction","differentiable rendering","primitive abstraction","mesh refinement"],"abstract":"Reconstructing detailed three-dimensional (2D) models from multi-view images often involves a trade-off between efficiency and fidelity. Existing methods based on volumetric representations or dense meshes can be computationally expensive, while primitive-based methods struggle to capture fine geometric details. We propose a novel method that addresses this challenge by combining differentiable primitive abstraction with adaptive mesh refinement. Our method first abstracts the scene into a set of cuboid primitives represented by analytical signed distance functions (SDFs), enabling part separability. This stage leverages differentiable volume rendering to efficiently optimize the primitives' poses and sizes. Subsequently, an automatic coarse-to-fine refinement procedure, guided by rendering loss, restores fine geometric details. Our method yields high-quality, part-separable meshes with low geometric complexity, suitable for applications requiring part manipulation and efficient rendering. We demonstrate the effectiveness of our method on the Technical University of Denmark Multi-View Stereo (DTU-MVS), BlendedMVS, and Tanks and Temples datasets, achieving a better balance between mesh complexity and reconstruction fidelity compared with existing techniques.","volume":40,"issue":5,"firstpage":1255,"lastpage":1269,"year":2025,"type":"Regular Paper","research_area":["Computer Graphics & Visualization"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5239-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5239-9?year=2025&issue=5","affiliations":["Zhejiang University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5281-7","title":"Concept-Guided Open-Vocabulary Temporal Action Detection","authors":[{"last":"Wang","first":"Song-Miao"},{"last":"Han","first":"Rui-Ze"},{"last":"Feng","first":"Wei"}],"keywords":["open-vocabulary","temporal action detection (TAD)","visual-language model"],"abstract":"Vision-language models (VLMs) have shown strong open-vocabulary learning abilities in various video understanding tasks. However, when applied to open-vocabulary temporal action detection (OV-TAD), existing OV-TAD methods often face challenges in generalizing to unseen action categories due to their reliance on visual features, resulting in limited generalization. In this paper, we propose a novel framework, Concept-Guided Semantic Projection (CSP), to enhance the generalization ability of OV-TAD methods. By projecting video features into a unified action concept space, CSP enables the use of abstracted action concepts for action detection, rather than solely relying on visual details. To further improve feature consistency across action categories, we introduce a mutual contrastive loss (MCL), ensuring semantic coherence and better feature discrimination. Extensive experiments on the ActivityNet and THUMOS14 benchmarks demonstrate that our method outperforms state-of-the-art OV-TAD methods. Code and data are available at Concept-Guided-OV-TAD.","volume":40,"issue":5,"firstpage":1270,"lastpage":1284,"year":2025,"type":"Regular Paper","research_area":["Computer Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5281-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5281-7?year=2025&issue=5","affiliations":["Tianjin University","Shenzhen University of Advanced Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5287-1","title":"Multi-Scale Adaptive Large Kernel Graph Convolutional Network for Skeleton-Based Action Recognition","authors":[{"last":"Zhang","first":"Yu-Qing"},{"last":"Pang","first":"Chen"},{"last":"Geng","first":"Pei"},{"last":"Lu","first":"Xue-Quan"},{"last":"Lyu","first":"Lei"}],"keywords":["skeleton-based action recognition","graph convolutional network (GCN)","multi-scale large kernel attention"],"abstract":"Graph convolutional networks (GCNs) have become a dominant approach for skeleton-based action recognition tasks. Although GCNs have made significant progress in modeling skeletons as spatial-temporal graphs, they often require stacking multiple graph convolution layers to effectively capture long-distance relationships among nodes. This stacking not only increases computational burdens but also raises the risk of over-smoothing, which can lead to the neglect of crucial local action features. To address this issue, we propose a novel multi-scale adaptive large kernel graph convolutional network (MSLK-GCN) to effectively aggregate local and global spatio-temporal correlations while maintaining the computational efficiency. The core components of the network include two multi-scale large kernel graph convolution (LKGC) modules, a multi-channel adaptive graph convolution (MAGC) module, and a multi-scale temporal self-attention convolution (MSTC) module. The LKGC module adaptively focuses on active motion regions by utilizing a large convolution kernel and a gating mechanism, effectively capturing long-distance dependencies within the skeleton sequence. Meanwhile, the MAGC module dynamically learns relationships between different joints by adjusting connection weights between nodes. To further enhance the ability to capture temporal dynamics, the MSTC module effectively aggregates the temporal information by integrating Efficient Channel Attention (ECA) with multi-scale convolution. In addition, we use a multi-stream fusion strategy to make full use of different modal skeleton data, including bone, joint, joint motion, and bone motion. Exhaustive experiments on three scale-varying datasets, i.e., NTU-60, NTU-120, and NW-UCLA, demonstrate that our MSLK-GCN can achieve state-of-the-art performance with fewer parameters.","volume":40,"issue":5,"firstpage":1285,"lastpage":1300,"year":2025,"type":"Regular Paper","research_area":["Computer Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5287-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5287-1?year=2025&issue=5","affiliations":["Shandong Normal University","Nanjing University of Science & Technology","University of Western Australia"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5252-z","title":"FGHDet: Delving into Fine-Grained Features with Head Selection for UAV Object Detection","authors":[{"last":"Bi","first":"Yan-Chao"},{"last":"Ning","first":"Yang"},{"last":"Nie","first":"Xiu-Shan"},{"last":"Lu","first":"Xian-Kai"},{"last":"Zhang","first":"Rui-Heng"},{"last":"Zhang","first":"Huan-Long"}],"keywords":["anchor-head-based scale-level matching","drone-view image","fine-grained information extraction","learning fine-grained semantics"],"abstract":"Detecting small objects in unmanned aerial vehicle (UAV) imagery is a challenging and crucial task in computer vision. Most current methods struggle to address the challenges of small objects: fine-grained feature mining, multiple-layer feature fusion, and mismatches in scale between anchors and feature maps. To alleviate the aforementioned issues, we present FGHDet, which focuses on delving into fine-grained features in low-level features with a head selection mechanism. First, our approach introduces a detail-preserving semantic information enhancement module (DSIEM) to retain fine-grained information while excavating coarse-grained semantic details relevant to fine-grained information. Then, we devise a coarse-to-fine feature guidance module (CFGM) that leverages coarse-grained semantic information and fine-grained information to co-guide feature enhancement, further improving the model's classification ability. Finally, we introduce a multiscale detection strategy based on anchor-head matching, ensuring scale-level matching between anchors and feature maps to prevent overfitting due to overly fine anchor divisions. Extensive experiments on the VisDrone, CARPK, and Drone-vs.-Bird datasets demonstrate that FGHDet achieves notable improvements in mAP (IoU range [0.5: 0.95]) of 4.9, 4.1, and 2.2, respectively. The code is available at https://github.com/b-yanchao/UAVDetection.git.","volume":40,"issue":5,"firstpage":1301,"lastpage":1315,"year":2025,"type":"Regular Paper","research_area":["Computer Vision","Robotics & Control"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5252-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5252-z?year=2025&issue=5","affiliations":["Shandong Jianzhu University","Shandong University","Beijing Institute of Technology","Zhengzhou University of Light Industry"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5290-6","title":"Palette-Based Color Transfer for Images and Videos","authors":[{"last":"Zhao","first":"Yue"},{"last":"Chen","first":"Zhong-Gui"},{"last":"Cao","first":"Juan"}],"keywords":["color transfer","image","palette","video"],"abstract":"In this paper, we propose a method that can extract enhanced color palettes for images, which are characterized by a heightened level of representativeness for images. The resulted palettes are not only easy to compute but also effectively convey the distribution of pixels across the color space. Based on these extracted palettes, we present a tailored color palette matching algorithm designed for our image color transfer method by solving an optimization problem to transfer colors from a reference image to the original image. Our algorithm offers the flexibility to operate in fully automatic mode or provide various levels of user interactivity, allowing for coarse-to-fine editing. Moreover, we demonstrate the adaptability of our palette-based color transfer method to diverse applications, including grayscale image colorization and temporally consistent, time-varying video color transfer. Extensive experiments and comparisons have been conducted to measure the quality of our results, employing both visual assessments and evaluation metrics. These findings demonstrate that our palette-based color transfer method efficiently and faithfully transfers color styles from reference images to both color and grayscale images and videos.","volume":40,"issue":5,"firstpage":1316,"lastpage":1330,"year":2025,"type":"Regular Paper","research_area":["Computer Graphics & Visualization"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5290-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5290-6?year=2025&issue=5","affiliations":["Xiamen University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5275-5","title":"A Summarization-Based Pattern-Aware Matrix Reordering Approach","authors":[{"last":"Zhou","first":"Zi-Han"},{"last":"Pan","first":"Jia-Cheng"},{"last":"Wang","first":"Xu-Meng"},{"last":"Han","first":"Dong-Ming"},{"last":"Guo","first":"Fang-Zhou"},{"last":"Zhu","first":"Min-Feng"},{"last":"Chen","first":"Wei"}],"keywords":["graph summarization","graph visualization","matrix-based visualization","matrix reordering"],"abstract":"Matrix-based graph visualization is effective in revealing relationships among entities in graphs. The visibility of structural patterns depends on the ordering of rows/columns in matrices. Most existing approaches mainly settle on an ideal ordering according to quality metrics, which emphasize certain types of patterns but ignore others. This paper proposes a summarization-based pattern-aware reordering approach to highlight multiple patterns simultaneously. First, the pattern-aware graph summarization utilizes the Minimum Description Length (MDL) technique to identify various types of patterns from the input graph. Second, we propose a coarse-to-fine reordering mechanism to generate matrixbased visualizations that maintain the structure of all identified patterns. Experimental results of two comparative studies and a user study on several datasets demonstrate that our approach simultaneously highlights more types of patterns than other approaches and performs well across multiple quality metrics.","volume":40,"issue":5,"firstpage":1331,"lastpage":1346,"year":2025,"type":"Regular Paper","research_area":["Computer Graphics & Visualization"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5275-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5275-5?year=2025&issue=5","affiliations":["Zhejiang University","Nankai University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4827-z","title":"A Survey of Hardware-Assisted Intra-Address Space Protections","authors":[{"last":"Jin","first":"Yue"},{"last":"Huang","first":"Tian-Yi"},{"last":"Zeng","first":"Si-Yuan"},{"last":"Xu","first":"Yi-Bin"},{"last":"Wang","first":"Han"},{"last":"Lu","first":"Tian-Yue"},{"last":"Chen","first":"Ming-Yu"}],"keywords":["software security","hardware-assisted security","intra-address space protection (IASP)"],"abstract":"With a similar threat model, conventional software mechanisms aimed at various levels of security can be categorized as intra-address space protection (IASP) including memory safety, control-flow integrity, syscall filtering, and isolation. When enhancing security, software-only IASP methods result in an expanded trusted computing base (TCB) and can lead to performance slowdowns, making it challenging to strike a balance between security and performance. Recent studies indicate that hardware-assisted methods enhance efficiency by encapsulating hardware primitives and utilizing specialized microarchitecture designs. They also enhance security by reducing the trusted computing base's attack surface. However, there has been limited discussion regarding the key challenges in current hardware-assisted IASP studies. This paper conducts a comprehensive survey of hardware-assisted IASP and discusses critical design issues, such as metadata management strategies, protection comprehensiveness, protection granularity, and processor complexity. Through a qualitative analysis of existing methods, this paper summarizes the research trends in hardware-assisted IASP technologies and emphasizes the importance of isolation models, access control strategies, and cross-compartment switching in future hardware-assisted IASP designs.","volume":40,"issue":5,"firstpage":1347,"lastpage":1367,"year":2025,"type":"Survey","research_area":["Processor & Microarchitecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4827-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4827-z?year=2025&issue=5","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS","Zhongguancun Laboratory"],"type_origin":"Review"},{"doi":"10.1007/s11390-025-4555-4","title":"Decoupled Vector Processing Unit: Past, Present, and Future","authors":[{"last":"Wang","first":"Ruo-Xi"},{"last":"Zhang","first":"Dun-Bo"},{"last":"Lang","first":"Qing-Jie"},{"last":"Xie","first":"Dong-Huan"},{"last":"Wang","first":"Zhi-Wei"},{"last":"Gao","first":"Zhen-Yu"},{"last":"Shen","first":"Li"}],"keywords":["decoupled organization","single instruction multiple data (SIMD)","vector architecture","processing in memory"],"abstract":"Vector architectures are widely employed in modern processors due to their high performance and energy efficiency in exploiting data-level parallelism through single instruction multiple data (SIMD) paradigms. The built-in scalar cores and the vector processing units (VPUs) can be organized as integrated or decoupled. The decoupled vector architecture primarily offers the advantage of independent operation, allowing the VPU and the scalar core to execute concurrently at different frequencies, enhancing overall throughput and performance. This enables specialized VPU optimization for long vectors, complex vector operations, and separate power management, which excels in computation-intensive applications. This paper comprehensively reviews processors with decoupled VPUs, discussing their advantages and various implementations. Design challenges and corresponding potential solutions are also be included.","volume":40,"issue":5,"firstpage":1368,"lastpage":1385,"year":2025,"type":"Survey","research_area":["GPU & Accelerator Architecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4555-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4555-4?year=2025&issue=5","affiliations":["National University of Defense Technology - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4348-9","title":"NPC: Negative Prototypical Contrasting for Label Disambiguation of Partial Label Learning","authors":[{"last":"Jin","first":"Yu-Jie"},{"last":"Wang","first":"Ya-Sha"},{"last":"Chu","first":"Xu"}],"keywords":["machine learning","partial label learning","weak supervision","negative prototype","expectation maximization"],"abstract":"Partial label learning (PLL) learns under label ambiguity where each training instance is annotated with a set of candidate labels, among which only one is the ground-truth label. Recent advances showed that PLL can be promoted by combining label disambiguation with representation learning coherently, which achieved state-of-the-art performance. However, most of the existing deep PLL methods over-emphasize pulling the inaccurate pseudo-label-induced positive samples and fail to achieve a balance between the intra-class compactness and the inter-class separability, thus leading to a sub-optimal representation space. In this paper, we solve this issue by taking into account the pure negative supervision information which can be extracted perfectly from the non-candidate label set. Methodologically, we propose a novel framework Negative Prototypical Contrasting (NPC). The optimization objective of NPC contrasts each instance with its candidate prototypes against its negative prototypes, aiming at a sufficiently distinguishable representation space. Based on the learned representations, the label disambiguation process is performed in a moving-average style. Theoretically, we show that the objective of NPC is equivalent to solving a constrained maximum likelihood optimization. We also justify applying the moving average from the stochastic expectation-maximization perspective. Empirically, extensive experiments demonstrate that the proposed NPC method achieves state-of-the-art classification performance on various datasets, and even competes with its supervised counterparts.","volume":40,"issue":5,"firstpage":1386,"lastpage":1400,"year":2025,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4348-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4348-9?year=2025&issue=5","affiliations":["Peking University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4330-6","title":"Electrocardiogram Signal Classification Based on Bidirectional LSTM and Multi-Task Temporal Attention","authors":[{"last":"Zhu","first":"Mu-Ran"},{"last":"Liu","first":"Jin-Duo"},{"last":"Ji","first":"Jun-Zhong"}],"keywords":["electrocardiogram signals classification","long short-term memory (LSTM)","encoder-decoder module","mutitask learning"],"abstract":"The analysis of electrocardiogram (ECG) signals is of great significance in predicting arrhythmias and preventing cardiovascular diseases. However, ECG data has high noise and highly temporally correlated temporal characteristics, which challenges machine learning algorithms in classification tasks. This paper proposes an ECG signal classification method based on the bidirectional long short-term memory (BiLSTM) network and multi-task temporal attention, named BiLMTA, which combines a time series encoding module and a multi-task decoding module. Specifically, the first step of the method involves feeding the filtered ECG signals into the encoder module, in which BiLSTM is utilized to model temporal dependencies between preceding and succeeding time steps. Subsequently, the multi-task decoding module handles two key tasks: one is responsible for the main task, the classification task of ECG signals; the other serves as an auxiliary task to predict normal and abnormal heartbeats. To better capture the key information in ECG signals and improve sensitivity to abnormal patterns, a temporal attention mechanism is introduced. In addition, in order to promote the interactive learning between two tasks, a new joint loss function is proposed. This loss function comprehensively considers the cross entropy loss of the main task and auxiliary task to ensure that the two tasks can jointly optimize the model and improve the accuracy of classification results. The experimental results show that the BiLMTA method performs well on two publicly available datasets, surpassing traditional methods and state-of-the-art deep learning methods.","volume":40,"issue":5,"firstpage":1401,"lastpage":1413,"year":2025,"type":"Regular Paper","research_area":["Bioinformatics & Life Sciences"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4330-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4330-6?year=2025&issue=5","affiliations":["Beijing University of Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4468-2","title":"From Anywhere to the Destination: Visual Reinforcement Learning for GNSS-Denied Drone Navigation","authors":[{"last":"Wang","first":"Yu-Xin"},{"last":"Zhang","first":"Zhen-Yu"},{"last":"Liu","first":"Shun-Yu"},{"last":"Sun","first":"Li"},{"last":"Song","first":"Ming-Li"}],"keywords":["deep reinforcement learning","drone navigation","vision for robotics","autonomous driving"],"abstract":"Unmanned aerial vehicles (UAVs), also referred to as drones, typically depend on the Global Navigation Satellite System (GNSS) for positional awareness and navigation. However, the GNSS can be unreliable in specific environments due to signal obstruction or degradation. In recent years, vision-based navigation has emerged as a promising alternative to GNSS. Despite its potential, this visual method necessitates a significant investment in expert-guided demonstrations, resulting in a cumbersome and passive collection process, especially for large-scale outdoor navigation tasks. In this paper, we propose AceFormer, a vision-based active exploration transformer framework that enables agent navigation from any starting point to a destination without expert guidance. Specifically, this framework introduces an intra instance feature encoder in tandem with a semantic guidance decoder, which empowers the drone agent to extract global instance-level semantic information. Deep reinforcement learning is further employed to train the drone agent, enabling it to explore the environment dynamically, and learn navigation tasks in a trial-and-error way. To empirically evaluate AceFormer, a challenging drone navigation simulated flight environment (DroEnv) is designed by leveraging Google Earth as a navigation platform, which contributes to a standardized benchmark for the drone navigation field. Extensive experiments conducted on DroEnv with randomly sampled starting points demonstrate the effectiveness of the proposed AceFormer in both ideal and noisy environments. Our code is publicly available.","volume":40,"issue":5,"firstpage":1414,"lastpage":1426,"year":2025,"type":"Regular Paper","research_area":["Reinforcement Learning","Robotics & Control"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4468-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4468-2?year=2025&issue=5","affiliations":["Zhejiang University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5186-5","title":"Federated Class-Incremental Learning with New-Class Augmented Self-Distillation","authors":[{"last":"Wu","first":"Zhi-Yuan"},{"last":"Sun","first":"Sheng"},{"last":"He","first":"Tian-Liu"},{"last":"Wang","first":"Yu-Wei"},{"last":"Liu","first":"Min"},{"last":"Gao","first":"Bo"},{"last":"Jiang","first":"Xue-Feng"}],"keywords":["federated learning","class-incremental learning","knowledge distillation"],"abstract":"Federated learning (FL) enables collaborative model training among participants while guaranteeing the privacy of raw data. Mainstream FL methodologies overlook the dynamic nature of real-world data, particularly its tendency to grow in volume and diversify in classes over time. This oversight results in FL methods suffering from catastrophic forgetting, where the trained models inadvertently discard previously learned information upon assimilating new data. In response to this challenge, we propose a novel federated class-incremental learning (FCIL) method, named Federated Class-incremental Learning with New-Class Augmented Self-Distillation (FedCLASS). The core of FedCLASS is to enrich the class scores of historical models with new class scores predicted by current models and utilize the combined knowledge for self-distillation, enabling a more sufficient and precise knowledge transfer from historical models to current models. Theoretical analyses demonstrate that FedCLASS stands on reliable foundations, considering the scores of old classes predicted by historical models as conditional probabilities in the absence of new classes, and the scores of new classes predicted by current models as the conditional probabilities of class scores derived from historical models. Empirical experiments demonstrate the superiority of FedCLASS over four baseline algorithms in reducing average forgetting rate and boosting global accuracy.","volume":40,"issue":5,"firstpage":1427,"lastpage":1437,"year":2025,"type":"Regular Paper","research_area":["Federated Learning","Knowledge Distillation"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5186-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5186-5?year=2025&issue=5","affiliations":["Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-4020-9","title":"UFN: User-Friendly Navigation Framework Based on Systematic Utilization of User-Friendliness Features from Historical Traffic Data","authors":[{"last":"Huang","first":"Shi-En"},{"last":"Sun","first":"Baixi"},{"last":"Fan","first":"Ling-Jun"},{"last":"Chen","first":"Xinyu"},{"last":"Tian","first":"Jiannan"},{"last":"Shen","first":"Qian-Wen"},{"last":"Wan","first":"Huai-Yu"},{"last":"Tao","first":"Dingwen"},{"last":"Bao","first":"Er-Gu-De"}],"keywords":["intelligent transportation","traffic forecasting","route planning","duration-safety-comfort (DSC) correlation matrix","multiple-objective optimization"],"abstract":"Due to the ever-increasing number of traffic vehicles, navigation services play an important role in daily life. Current studies typically plan the fastest route by two steps: traffic forecasting and route planning. The planned routes may not be safe or comfortable for drivers. Even if some studies consider user-friendliness factors and extract safety and comfort information from historical traffic (HT) data, they simply combine user-friendliness factors with driving time at the beginning of traffic forecasting. It would be more accurate to keep and use all the information until the planned route is obtained. To address this challenge, we propose a user-friendly navigation framework called UFN. UFN extracts user-friendliness features from HT data and systematically predicts all the features without combining them beforehand. Based on the prediction results, UFN plans the most user-friendly route by simplifying and solving a multiple-objective optimization problem. Experimental results demonstrate that UFN is accurate, and the more accurate the predicted user-friendliness features, the more user-friendly the planned route.","volume":40,"issue":5,"firstpage":1438,"lastpage":1453,"year":2025,"type":"Regular Paper","research_area":["Optimization & Heuristic Methods"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4020-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4020-9?year=2025&issue=5","affiliations":["Beijing Jiaotong University","Indiana University System","Indiana University Bloomington","Washington State University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4126-8","title":"Fault-Tolerant Routing Under Conditional Fault Pattern in Data Center Network of RRect","authors":[{"last":"An","first":"Ni"},{"last":"Lyu","first":"Meng-Jie"},{"last":"Fan","first":"Wei-Bei"},{"last":"Han","first":"Lei"},{"last":"Xiao","first":"Fu"}],"keywords":["data center network (DCN)","RRect","fault tolerant routing","conditional fault pattern"],"abstract":"With the expansion and increasing complexity of data center networks (DCNs), network fault-tolerance has become increasingly important. RRect is a server-centered DCN with a good interconnection structure. In this paper, we propose a fault-tolerant routing algorithm RRFP under a conditional fault pattern of RRect, which can find a fault-free path between any two fault-free vertices. Firstly, we study a fault pattern of RRect in the case of restricted faulty vertex sets, {1, 2}-restricted connectivity. It is about {2, 3} times RRect's traditional connectivity, indicating that {1, 2}-restricted connectivity better evaluates the fault-tolerant capability. Secondly, we design an effective fault-tolerant routing algorithm RRFP under the conditional fault pattern of RRect, and RRFP can accommodate more faulty vertices. Finally, we conduct experiments on RRFP to evaluate its performance. The experimental results show that in terms of the running time, as parameters n and k change, RRFP outperforms Dijkstra's algorithm by 64%-84% and Breadth-First-Search (BFS) by 56%-71%. The running time of all the three algorithms is very short as parameter m changes. In terms of the constructing path length, as parameters change, RRFP outperforms BFS by 12%-19%. Moreover, the path constructed by RRFP approaches the shortest path of Dijkstra's algorithm. Moreover, RRFP still maintains a low transmission failure rate (TFR) and high reliability even with an increase in the number of fault elements.","volume":40,"issue":5,"firstpage":1454,"lastpage":1467,"year":2025,"type":"Regular Paper","research_area":["Data Center Systems & Networks","Network Protocols & Measurement"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4126-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4126-8?year=2025&issue=5","affiliations":["Nanjing University of Posts & Telecommunications"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4300-z","title":"Incremental Detection of Strongly Connected Components for Scholarly Data","authors":[{"last":"Liu","first":"Jun-Feng"},{"last":"Ma","first":"Shuai"},{"last":"Chen","first":"Han-Qing"}],"keywords":["incremental algorithm","strongly connected component (SCC) detection","graph partition","local topological order","scholarly data analysis"],"abstract":"Strongly connected component (SCC) detection is fundamental for analyzing citation graphs, yet existing general-purpose algorithms inefficiently handle the dynamic nature and specific properties of these networks. This study addresses this gap by developing specialized incremental SCC detection methods. We first leverage distinct edge types inherent in citation graphs to devise partition and local topological ordering strategies, minimizing redundant graph traversals. Based on this, we introduce two efficient bounded incremental algorithms: one for continuous single updates via dynamic maintenance of partitions and order, and the other for batch updates that further reduces edge traversals by building upon the single-update technique. Experimental evaluations on real-world citation graphs verify significant efficiency improvements, with our single incremental method achieving speedups of at least 11.5 times, and the batch incremental method achieving speedups of at least 5.0 times compared with baseline methods.","volume":40,"issue":5,"firstpage":1468,"lastpage":1484,"year":2025,"type":"Regular Paper","research_area":["Databases & Query Processing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4300-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4300-z?year=2025&issue=5","affiliations":["Beihang University","Peng Cheng Laboratory"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-0002-9","title":"RF Waves as a Computing Medium","authors":[{"last":"Zhang","first":"Xinyu"}],"keywords":[],"abstract":"","volume":40,"issue":4,"firstpage":939,"lastpage":940,"year":2025,"type":"Perspective","research_area":["IoT & Wireless Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-0002-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-0002-9?year=2025&issue=4","affiliations":["University of California System","University of California San Diego"],"type_origin":"Editorial Material","cover_doi":"10.1007/s11390-025-5484-y","topic_source":"cover_inherited"},{"doi":"10.1007/s11390-025-5484-y","title":"RF Computing: A New Realm of IoT Research","authors":[{"last":"He","first":"Yuan"},{"last":"Sun","first":"Yi-Miao"},{"last":"Guo","first":"Xiu-Zhen"}],"keywords":["radio frequency (RF)","analog computing","Internet of Things (IoT)","sensing"],"abstract":"Current Internet of Things (IoT) systems encounter substantial challenges in realizing ubiquitous sensing and connectivity, characterized by constrained sensing coverage, prohibitive deployment costs, and energy inefficiencies inherent in conventional digital-centric architectures. This paper presents RF Computing, an innovative paradigm that exploits radio frequency (RF) signals to simultaneously serve as information carriers and computational operands. By enabling direct information processing through RF signal manipulation in the RF domain, RF Computing effectively bypasses the limitations of traditional digital systems, delivering exceptional energy efficiency and superior performance characteristics. We provide a systematic definition of RF Computing, classify its operational modalities, and showcase representative applications that highlight its transformative potential. The existing research landscape is organized into three principal categories: information injection, transformation, and augmentation. Furthermore, we delineate critical open challenges, including the development of unified theoretical models, RF resource management strategies, analog-digital co-design methodologies, and programming frameworks for RF Computing systems. Finally, we propose promising directions to propel this emerging field forward.","volume":40,"issue":4,"firstpage":941,"lastpage":956,"year":2025,"type":"Regular Paper","research_area":["IoT & Wireless Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5484-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5484-y?year=2025&issue=4","affiliations":["Tsinghua University","Beijing National Research Center for Information Science and Technology","Zhejiang University"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-025-0003-8","title":"The Preface","authors":[{"last":"Xia","first":"Xin"},{"last":"Hu","first":"Xing"}],"keywords":[],"abstract":"","volume":40,"issue":4,"firstpage":957,"lastpage":957,"year":2025,"type":"Regular Paper","research_area":[],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-0003-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-0003-8?year=2025&issue=4","affiliations":["Zhejiang University"],"type_origin":"Editorial Material"},{"doi":"10.1007/s11390-025-5132-6","title":"SEPAL: A Consistency-Driven Programming Framework and Runtime Support for Human-Cyber-Physical Systems with Reliable Sensing and Dynamic Adaptation","authors":[{"last":"Zhang","first":"Shu-Hui"},{"last":"Yang","first":"Rong"},{"last":"Zhang","first":"Ling-Yu"},{"last":"Li","first":"Han"},{"last":"Wang","first":"Ming-Xiao"},{"last":"Gao","first":"Ming-Chen"},{"last":"Hu","first":"Hao-Ming"},{"last":"Wang","first":"Hui-Yan"},{"last":"Qin","first":"Yi"},{"last":"Xu","first":"Chang"}],"keywords":["human-cyber-physical system (HCPS)","sensing and adaptation assurance","programming framework","runtime support"],"abstract":"In recent years, human-cyber-physical systems (HCPSs) have become increasingly complex due to the widespread adoption of environmental sensing and behavioral adaption. Apart from the tight coupling between application logic and sensing-adaptation modules, such applications are mainly constrained by erroneous sensing and abnormal adaptation issues, often resulting in misjudgment of scenarios or adaptation behaviors that deviate from intended goals. Reliability in constructing and maintaining such application systems faces significant challenges, especially as human-cyber-physical scenarios exhibit dynamic uncertainties and evolving requirements, further exacerbating the development difficulty. To address these challenges, we design and implement SEPAL, a consistency-driven programming framework and runtime support for HCPSs with reliable environmental sensing and dynamic adaptation. SEPAL simplifies the design of environmental sensing and behavioral adaption in HCPSs through a unified programming framework, and transparently manages the reliability of sensing and the unbiasedness of adaptation through its two built-in consistency-based services. SEPAL also provides a flexible browser-based management interface and a customizable interface design language for ease of usage. Case studies and evaluations demonstrate SEPAL's facilitation of reliable support for various HCPSs, as well as the effectiveness and efficiency of environmental sensing and behavioral adaption capabilities.","volume":40,"issue":4,"firstpage":958,"lastpage":968,"year":2025,"type":"Regular Paper","research_area":["Robotics & Control"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5132-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5132-6?year=2025&issue=4","affiliations":["Nanjing University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5133-5","title":"ValExtractor: Reliable Automated Local Variable Extraction in Code Refactoring","authors":[{"last":"Jiang","first":"Yan-Jie"},{"last":"Fan","first":"Fu"},{"last":"Wei","first":"Wei"},{"last":"Chi","first":"Xia-Ye"},{"last":"Xia","first":"Yun-Ni"},{"last":"Zhang","first":"Yu-Xia"},{"last":"Ji","first":"Wei-Xing"},{"last":"Liu","first":"Hui"}],"keywords":["software defect","software refactoring","extract local variable"],"abstract":"Extracting local variable is a well-known and widely used refactoring technique designed to enhance code readability by replacing complex expressions with simpler variable references. Although most integrated development environments (IDEs) provide tool support for such refactoring, these tools often result in semantic errors due to a lack of in-depth analysis. To overcome these limitations, we present ValExtractor, a novel and reliable approach for reliable automated variable extraction. The key challenge involves accurately and efficiently identifying the side effects of extracted expressions and their potential interactions with the surrounding context, without resorting to time-consuming dynamic execution. ValExtractor employs lightweight static source code analysis to validate the side effects of selected expressions and determine which instances of the expressions can be extracted together without altering program semantics or introducing new potential exceptions. Our evaluation demonstrates that mainstream refactoring engines, such as those in Eclipse and IntelliJ IDEA, frequently generate incorrect variable extractions, whereas ValExtractor successfully avoids these errors. The algorithm and its implementation have been integrated into Eclipse, serving over three million global Eclipse users.","volume":40,"issue":4,"firstpage":969,"lastpage":979,"year":2025,"type":"Regular Paper","research_area":["Code Intelligence & Maintenance"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5133-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5133-5?year=2025&issue=4","affiliations":["Peking University","Beijing Institute of Technology","Chongqing University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5139-z","title":"CoEdPilot: Interactively Recommending Project-Wise Code Edits","authors":[{"last":"Huang","first":"Yu-Huan"},{"last":"Liu","first":"Chen-Yan"},{"last":"Lin","first":"Yun"},{"last":"Cai","first":"Yu-Fan"},{"last":"Jiang","first":"Bo"},{"last":"Yang","first":"Ping"},{"last":"Huang","first":"Zhiyong"},{"last":"Dong","first":"Jin Song"}],"keywords":["interactive tool","end-to-end code editing","human-computer interaction"],"abstract":"Incremental code editing, as a fundamental task in software development, requires developers to iteratively identify edit locations and modify code. However, existing language model-driven approaches primarily focus on generating edit solutions for a single location, failing to provide comprehensive end-to-end solutions. To address this limitation and support real-world editing scenarios, we propose CoEdPilot, a project-wide interactive code editing recommendation tool. CoEdPilot utilizes edit descriptions and edit history, and recommends the next edit location with solutions across the entire project. It further refines its recommendations based on user editing feedback, enabling an end-to-end, iterative, and interactive editing process. We implement CoEdPilot as a visual studio code extension that monitors user actions, identifies subsequent editing locations, and generates edits throughout the project. Its functionality is powered by a set of backend language models, which are trained on 180k high-quality commits from 471 open-source repositories. Extensive experiments demonstrate CoEdPilot's capabilities in accurately identifying editing locations (i.e., edit location predicted with an accuracy of 85.03%-88.99%) and generating high-quality edit solutions (i.e., generated edit content with a top-1 exact match rate (EMR) of 33.48%-48.94%). Our case study and user study of 18 participants further validate CoEdPilot's practicability.","volume":40,"issue":4,"firstpage":980,"lastpage":992,"year":2025,"type":"Regular Paper","research_area":["Code Intelligence & Maintenance","Human-Computer Interaction"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5139-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5139-z?year=2025&issue=4","affiliations":["Shanghai Jiao Tong University","National University of Singapore"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5140-6","title":"Parf: An Adaptive Abstraction-Strategy Tuner for Static Analysis","authors":[{"last":"Wang","first":"Zhong-Yi"},{"last":"Chen","first":"Ming-Shuai"},{"last":"Lin","first":"Teng-Jie"},{"last":"Yang","first":"Lin-Yu"},{"last":"Zhuo","first":"Jun-Hao"},{"last":"Wang","first":"Qiu-Ye"},{"last":"Qin","first":"Sheng-Chao"},{"last":"Yi","first":"Xiao"},{"last":"Yin","first":"Jian-Wei"}],"keywords":["automatic parameter tuning","Frama-C/Eva","program verification","static analysis","abstraction strategy"],"abstract":"We launch Parf - a toolkit for adaptively tuning abstraction strategies of static program analyzers in a fully automated manner. Parf models various types of external parameters (encoding abstraction strategies) as random variables subject to probability distributions over latticed parameter spaces. It incrementally refines the probability distributions based on accumulated intermediate results generated by repeatedly sampling and analyzing, thereby ultimately yielding a set of highly accurate abstraction strategies. Parf is implemented on top of Frama-C/Eva - an off-the-shelf open-source static analyzer for C programs. Parf provides a web-based user interface facilitating the intuitive configuration of static analyzers and visualization of dynamic distribution refinement of the abstraction strategies. It further supports the identification of dominant parameters in Frama-C/Eva analysis. Benchmark experiments and a case study demonstrate the competitive performance of Parf for analyzing complex, large-scale real-world programs.","volume":40,"issue":4,"firstpage":993,"lastpage":1005,"year":2025,"type":"Regular Paper","research_area":["Formal Methods & Verification","Software Testing & Analysis"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5140-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5140-6?year=2025&issue=4","affiliations":["Zhejiang University","Huawei Technologies","Xidian University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5142-4","title":"HmTest: Automated Testing of HarmonyOS Apps via Model-Driven Navigation and Reinforcement Learning","authors":[{"last":"Chen","first":"Yi-Ge"},{"last":"Fan","first":"Yu-Jia"},{"last":"Wang","first":"Si-Nan"},{"last":"Tao","first":"Yi-Da"},{"last":"Liu","first":"Ye-Pang"}],"keywords":["HarmonyOS app","graphical user interface (GUI) testing","page transition graph","model-based testing","reinforcement learning"],"abstract":"HarmonyOS is a new all-scenario operating system for smart devices. As its software ecosystem expands rapidly, how to conduct automated testing of HarmonyOS apps for quality assurance has become a crucial task. This paper presents HmTest, an automated testing framework for HarmonyOS apps, which consists of two complementary modules: targeted exploration and reinforcement learning (RL)-based exploration. Targeted exploration performs white-box testing, leveraging static analysis to construct a page transition graph (PTG). By systematically traversing PTGs to guide testing, HmTest can quickly achieve high page coverages. On the other hand, RL-based exploration performs black-box testing, utilizing reinforcement learning to achieve a comprehensive exploration of app states. Additionally, an automaton-based mechanism is employed to efficiently recover and restart the testing process when reinforcement learning encounters stagnation. We have evaluated HmTest on nine HarmonyOS NEXT apps and compared it with two official HarmonyOS app testing tools. The experimental results demonstrate that targeted exploration can generate highly-precise PTGs and help achieve high page coverages within a few minutes. RL-based exploration can significantly outperform other methods in terms of finer-grained statement coverage on the majority of the tested apps and benefits from the recovery mechanism. To facilitate future research, we have made HmTest open-source at https://github.com/sqlab-sustech/hmtest and provided a video demo at https://jcst.ict.ac.cn/news/361.","volume":40,"issue":4,"firstpage":1006,"lastpage":1021,"year":2025,"type":"Regular Paper","research_area":["Reinforcement Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5142-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5142-4?year=2025&issue=4","affiliations":["Southern University of Science & Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4239-0","title":"A Survey of Static and Temporal Explainable Methods and Their Applications in Knowledge Tracing","authors":[{"last":"Li","first":"Fan"},{"last":"Zhang","first":"Tian-Cheng"},{"last":"Yin","first":"Yi-Fang"},{"last":"Fan","first":"Di"},{"last":"Yu","first":"Ming-He"},{"last":"Yu","first":"Ge"}],"keywords":["deep learning","explainable artificial intelligence","temporal model","knowledge tracing"],"abstract":"Deep learning has found widespread application across diverse domains owing to its exceptional performance. Nevertheless, the lack of transparency in deep learning models' decision-making processes undermines their usability, especially in critical contexts. While researchers have made noteworthy advancements in explaining these models, they have frequently overlooked the differences between static and temporal models during explanation generation. In temporal models, features change over time, posing new challenges in the generation of explanations. Though extensive research has been dedicated to surmounting these hurdles, a survey summarizing these contributions is currently absent. To bridge this gap, this paper endeavors to summarize existing methods and their contributions in terms of both static and temporal models, highlighting their disparities. Additionally, we propose an innovative classification approach based on the comprehensibility of explanations, demonstrating that different explanation methods vary in their understandability for users. Finally, to assess the limitations of the explanation capabilities of existing methods, we specifically choose knowledge tracing to analyze the evolution of explanation methods in this context of temporal modeling and interpretations.","volume":40,"issue":4,"firstpage":1022,"lastpage":1045,"year":2025,"type":"Survey","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4239-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4239-0?year=2025&issue=4","affiliations":["Northeastern University - China","Agency for Science Technology & Research (A*STAR)","A*STAR - Institute for Infocomm Research (I2R)"],"type_origin":"Review"},{"doi":"10.1007/s11390-025-4802-8","title":"Multimodal Agent AI: A Survey of Recent Advances and Future Directions","authors":[{"last":"Sun","first":"Yu-Zhu"},{"last":"Sun","first":"He-Li"},{"last":"Ma","first":"Jian-Cong"},{"last":"Zhang","first":"Peng"},{"last":"Huang","first":"Xiao-Yong"}],"keywords":["multimodal agent AI","task planning","decision making","robotic","healthcare"],"abstract":"In recent years, multimodal agent AI (MAA) has emerged as a pivotal area of research, holding promise for transforming human-machine interaction. Agent AI systems, capable of perceiving and responding to inputs from multiple modalities (e.g., language, vision, audio), have demonstrated remarkable progress in understanding complex environments and executing intricate tasks. This survey comprehensively reviews the state-of-the-art developments in MAA and examines its fundamental concepts, key techniques, and applications across diverse domains. We first introduce the basics of agent AI and its multimodal interaction capabilities. We then delve into the core technologies that enable agents to perform task planning, decision-making, and multi-sensory fusion. Furthermore, we focus on exploring various applications of MAA in robotics, healthcare, gaming, and beyond. Additionally, we mainly focus on analyzing the challenges and limitations of current systems and propose promising research directions for future improvements, including human-AI collaboration, online learning method improvement. By reviewing existing work and highlighting open questions, this survey aims to provide a comprehensive roadmap for researchers and practitioners in the field of MAA.","volume":40,"issue":4,"firstpage":1046,"lastpage":1063,"year":2025,"type":"Survey","research_area":["LLM Agents & Embodied Intelligence"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4802-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4802-8?year=2025&issue=4","affiliations":["Xi'an Jiaotong University","Northwestern Polytechnical University"],"type_origin":"Review"},{"doi":"10.1007/s11390-025-3739-2","title":"Discriminative Binary Multi-View Clustering","authors":[{"last":"You","first":"Yun-Ning"},{"last":"Tang","first":"Chang"},{"last":"Zheng","first":"Xiao"},{"last":"Liu","first":"Xin-Wang"},{"last":"Liu","first":"Yuan-Yuan"},{"last":"Li","first":"Xian-Ju"},{"last":"Jiang","first":"Liang-Xiao"}],"keywords":["multi-view clustering","graph regularization","binary coding learning","feature selection"],"abstract":"Binary multi-view clustering has attracted intense attention from researchers due to its efficiency in handling large-scale datasets. However, previous clustering approaches suffer from at least two limitations. First, they ignore correlations among the features of original data. As a result, the geometric consistency of data is not preserved in the to-be-learnt binary representation space. Second, redundant and noisy features mixed in original data inevitably limit the ultimate clustering performance. In light of this, we propose a novel discriminative binary multi-view clustering (DBMVC) method to address the issues. Specifically, the proposed DBMVC first maps original data onto the Hamming space to obtain corresponding binary codes, which can effectively reduce the computational complexity and storage costs in the following steps. To enable our method to select useful features from original data and get a discriminative representation, the L2, 1-norm is used to constrain the feature projection matrix. In addition, a graph regularization term is further introduced to preserve the local manifold structure of the learned binary representation. Finally, an alternative iterative optimization algorithm is designed to solve the optimization problems of the objective function. Comprehensive experiments on six large-scale multi-view datasets validate that the proposed DBMVC markedly outperforms other state-of-the-art methods in terms of effectiveness and efficiency.","volume":40,"issue":4,"firstpage":1064,"lastpage":1078,"year":2025,"type":"Regular Paper","research_area":["Data Mining & Analytics"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-3739-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-3739-2?year=2025&issue=4","affiliations":["China University of Geosciences","National University of Defense Technology - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5088-6","title":"PCRec: A Multi-Interest News Recommendation Framework with Prompt-Guided Cross-View Contrastive Learning","authors":[{"last":"Tong","first":"Yi-Qi"},{"last":"Liu","first":"Qian-Qi"},{"last":"Guo","first":"Wei"},{"last":"Niu","first":"Hong-Rui"},{"last":"Zhuang","first":"Fu-Zhen"},{"last":"Wang","first":"De-Qing"},{"last":"Gao","first":"Jun"}],"keywords":["contrastive learning","multi-interest modeling","news recommendation","prompt learning"],"abstract":"Effective news recommendation is crucial for alleviating users' information overload. While recent prompt-based news recommendation methods have shown promising performance by reformulating the recommendation task as a masked prediction problem, we note that this paradigm still faces several major limitations including inadequate multi-interest representation, limited global interaction modeling, and historical interaction truncation. To address these problems, this paper proposes PCRec, a prompt-guided cross-view contrastive learning framework for multi-interest news recommendation. PCRec first introduces feature-level prompts to overcome the input constraints inherent in text-level prompts. Moreover, a two-stage user modeling module is designed to capture users' multi-interests. Finally, to model global usernews relationships, PCRec implements a cross-view contrastive learning strategy. This approach groups similar users, enabling learning from multiple perspectives and breaking down isolated relationships among users, news categories, and news subcategories. Extensive experiments on two real-world news recommendation datasets validate the superiority of our proposed PCRec compared with various state-of-the-art baselines.","volume":40,"issue":4,"firstpage":1079,"lastpage":1093,"year":2025,"type":"Regular Paper","research_area":["Contrastive & Self-Supervised Learning","Recommendation Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5088-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5088-6?year=2025&issue=4","affiliations":["Beihang University","University of Cambridge","Harbin Engineering University","Zhongguancun Laboratory"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-3978-2","title":"Enhanced Feature Representations for Low-Resolution Fine-Grained Image Recognition Via Categorical Knowledge Guidance","authors":[{"last":"Yan","first":"Tian-Tian"},{"last":"Sun","first":"Bao-Li"},{"last":"Mu","first":"Jie"},{"last":"Wang","first":"Wei"},{"last":"Zhou","first":"Dong-Sheng"}],"keywords":["low-resolution fine-grained image recognition","class-wise distillation","memory bank","part query"],"abstract":"Low-resolution (LR) fine-grained image recognition requires the ability to recognize the subcategories of LR samples with limited fine-grained details. The existing methods do not make full use of the guiding and constraining capabilities of category-related knowledge to recover and extract the fine-grained features of LR data; thus these methods have a limited ability to learn the global and local fine-grained features of LR data. In this paper, we propose an enhanced feature representation network (EFR-Net) based on categorical knowledge guidance to capture delicate and reliable fine-grained feature descriptions of LR data and improve the recognition accuracy. First, to overcome the challenges posed by the limited fine-grained details in LR data, we design a classwise distillation loss. This loss function transfers the high-quality features of class-specific high-resolution (HR) samples into the feature learning of the same-category LR samples by using a memory bank. In this way, the global representation of LR images is closer to the meaningful and high-quality image features. Second, considering that fine-grained discriminative features are often hidden in object parts, we present a group of part queries to learn the positional information where the discriminative cues exist across all categories, and we then use the queries to decode diverse and discriminative part features. The global representation, in combination with the local discriminative features, creates more comprehensive and meaningful feature descriptions of the LR fine-grained objects, thus improving the recognition performance. Extensive comparison experiments on four LR datasets demonstrate the effectiveness of EFR-Net.","volume":40,"issue":4,"firstpage":1094,"lastpage":1108,"year":2025,"type":"Regular Paper","research_area":["Computer Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-3978-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-3978-2?year=2025&issue=4","affiliations":["Dalian University","Dalian University of Technology","Dongbei University of Finance & Economics","Sun Yat Sen University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4973-3","title":"Novel Probabilistic and Machine Learning Approaches for the Protein Scaffold Gap Filling Problem","authors":[{"last":"Badal","first":"Kushal"},{"last":"Qingge","first":"Letu"},{"last":"Liu","first":"Xiaowen"},{"last":"Zhu","first":"Binhai"}],"keywords":["heuristic algorithm","machine learning","probabilistic model","protein scaffold filling","protein sequencing"],"abstract":"In de novo protein sequencing, we often could only obtain an incomplete protein sequence, namely a scaffold, from top-down and bottom-up tandem mass spectrometry. While most sections of proteins can be inferred from their homologous sequences, some specific section of proteins is always missing and it is hard to predict the missing amino acids in the gaps of the scaffolds. Thus, we only focus on predicting the gaps based on a probabilistic algorithm and a machine learning model instead predicting the complete protein sequence using generative AI models in this paper. We study two versions of the protein scaffold filling problem with known gap size and known gap mass, respectively. For the known size gaps version, we develop several machine learning models based on random forest, k-nearest neighbors, decision tree, and fully connected neural network. For the known gap mass problem, we design a probabilistic algorithm to predict the missing amino acids in the gaps. The experimental results on both real and simulation data show that our proposed algorithms show promising results of 100% and close to 100% accuracy, respectively.","volume":40,"issue":4,"firstpage":1109,"lastpage":1123,"year":2025,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Uncertainty & Probabilistic Modeling","Bioinformatics & Life Sciences"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4973-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4973-3?year=2025&issue=4","affiliations":["University of North Carolina","North Carolina A&T State University","Tulane University","Montana State University System"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4930-1","title":"MiRNA-Disease Association Prediction Based on Stacked Autoencoders and Variant Triplet Networks","authors":[{"last":"Quynh","first":"Nguyen-Phuc-Xuan"},{"last":"Tran","first":"Hoai-Nhan"},{"last":"Yan","first":"Cheng"},{"last":"Wang","first":"Jian-Xin"}],"keywords":["miRNA-disease association prediction","fast kernel learning","stacked autoencoder","triplet network"],"abstract":"MicroRNAs (miRNAs) play a key role in the prevention, diagnosis, and treatment of complex diseases. However, identifying miRNA-disease associations (MDAs) through traditional methods is costly and time-consuming. Recent studies have reported numerous validated MDAs, forming the basis for the prediction of new MDAs using computational methods. In this study, we propose SAETNMDA, a computational method that applies fast kernel learning (FKL) and variant triplet networks to predict MDAs. First, miRNA and disease similarities are integrated into two kernels via FKL to enrich biological data. Next, feature representations are obtained by applying stacked autoencoders (SAEs) and triplet networks, enabling the identification of associated pairs by mapping them to nearby locations in the embedding space, while unassociated ones are mapped distantly. Finally, we utilize XGBoost (Extreme Gradient Boosting) to obtain predictive scores for MDAs from these features. SAETNMDA's performance is evaluated with 5-fold cross-validation (5-fold-CV) and compared with other methods. It achieves the highest AUC and AUPR (0.941 9, 0.474 9 for HMDD v2.0; 0.949 6, 0.535 5 for HMDD v3.2, respectively). The performance is also validated on an independent dataset and de novo miRNAs, with SAETNMDA achieving the highest AUC and AUPR in all validations. Case studies also demonstrate the robust predictive capability of our method, with the top 50 predicted miRNAs validated for each of the three diseases. These results highlight SAETNMDA as an efficient model for MDA prediction. SAETNMDA's source code is available at https://github.com/npxquynhdhsp/SAETNMDA.","volume":40,"issue":4,"firstpage":1124,"lastpage":1137,"year":2025,"type":"Regular Paper","research_area":["Bioinformatics & Life Sciences"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4930-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4930-1?year=2025&issue=4","affiliations":["Central South University","Hue University","Hunan University of Chinese Medicine"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-4458-9","title":"AR: An Efficient Alliance Root Service with Decentralized Trust","authors":[{"last":"Zhang","first":"Bin"},{"last":"Zhang","first":"Yu"},{"last":"Feng","first":"Yu-Ming"},{"last":"Zhang","first":"Wei-Zhe"},{"last":"Ji","first":"Dong-Cen"},{"last":"Nie","first":"Fan"}],"keywords":["domain name system (DNS)","network measurement","internet root security","blockchain DNS"],"abstract":"The domain name system (DNS) provides essential services for translations between human-readable domain names and IP addresses, which runs under global DNS roots. DNS roots face security vulnerabilities and trust risks due to the centralized management architecture. Several related schemes have been proposed to mitigate the security vulnerabilities and trust risks. However, most methods on trust risks focus on verifying their mechanisms. The comparison of the actual operational effectiveness of these methods and the existing DNS is rarely disclosed. In this paper, we present a trustworthy decentralized DNS root management architecture called AR based on blockchain. Instead of all top level domains (TLDs) authorized by an institution, the root owner in AR has the authority over its TLDs. Our proposed AR can work with the global roots without influencing the operation of the existing DNS. A cross-national and cross-regional research testbed is constructed on the Internet to verify the feasibility and practicality of our proposed AR.","volume":40,"issue":4,"firstpage":1138,"lastpage":1154,"year":2025,"type":"Regular Paper","research_area":["Blockchain & Distributed Ledger","Network Protocols & Measurement"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4458-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4458-9?year=2025&issue=4","affiliations":["Harbin Institute of Technology","Sun Yat Sen University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-4075-7","title":"NapFS: A High-Performance Persistent Memory File System for Non-Uniform Memory Access Architectures","authors":[{"last":"Jia","first":"Wen-Qing"},{"last":"Jiang","first":"De-Jun"},{"last":"Xiong","first":"Jin"}],"keywords":["non-uniform memory access (NUMA)","persistent memory","file system","IO delegation"],"abstract":"Persistent memory (PM) allows file systems to directly persist data on the memory bus. To increase the capacity of PM file systems, building a file system across sockets with each attached PM is attractive. However, accessing data across sockets incurs impacts of the non-uniform memory access (NUMA) architecture, which will lead to significant performance degradation. In this paper, we first use experiments to understand the NUMA impacts on building PM file systems. And then, we propose four design principles for building a high-performance PM file system NapFS for the NUMA architecture. We architect NapFS with per-socket local PM file systems and per-socket dedicated IO thread pools. This not only allows applications to delegate data accesses to IO threads for avoiding remote PM accesses, but also fully reuses existing single-socket PM file systems to reduce implementation complexity. Additionally, NapFS utilizes fast DRAM to accelerate performance by adding a global cache and adopts a selective cache mechanism to eliminate the redundant double-copy overhead for synchronization operations. Lastly, we show that NapFS can adopt extended optimizations to improve scalability and the performance of critical requests. We evaluate NapFS against other multi-socket PM file systems. The evaluation results show that NapFS achieves 2.2x and 1.0x throughput improvement for Filebench and RocksDB, respectively.","volume":40,"issue":4,"firstpage":1155,"lastpage":1171,"year":2025,"type":"Regular Paper","research_area":["Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4075-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4075-7?year=2025&issue=4","affiliations":["Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4120-1","title":"On Optimal Local Discrimination Algorithm of Two-Qubit Unitary Operations","authors":[{"last":"Yao","first":"Peng-Hui"},{"last":"Ye","first":"Ze-Kun"}],"keywords":["quantum computing","local operations and classical communication (LOCC)","unitary operation discrimination"],"abstract":"It has been known that two different bipartite unitary operations are perfectly distinguishable by local operations and classical communication (LOCC) when a finite number of queries is allowed. However, it has been a longstanding open problem to determine the optimal number of queries needed to distinguish bipartite unitary operations perfectly by LOCC since 2007. In this paper, we show that if two two-qubit unitary operations are perfectly distinguishable using T queries, they are also perfectly distinguishable in the LOCC scenario using [6 pi T] queries. As a result, LOCC operations are as powerful as global operations when using constant times the number of queries for the perfect discrimination of two-qubit unitary operations.","volume":40,"issue":4,"firstpage":1172,"lastpage":1180,"year":2025,"type":"Regular Paper","research_area":["Quantum Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4120-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4120-1?year=2025&issue=4","affiliations":["Nanjing University","Hefei National Laboratory"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-5126-4","title":"Hypertasking: From Information Web to Computing Utility","authors":[{"last":"Xu","first":"Zhi-Wei"},{"last":"Yu","first":"Zi-Shu"},{"last":"Li","first":"Feng-Zhi"},{"last":"Zhang","first":"Yao"}],"keywords":["cloud computing","computing utility","hypermedia","hypertask","stored-computer architecture"],"abstract":"John McCarthy proposed the vision of utility computing in 1961. Barbara Liskov proposed a related vision of abstraction-powered Internet Computer in 2009. This position paper outlines a distributed computing model towards realizing the McCarthy-Liskov vision. This hypertasking model aims at extending the hypermedia model of the World Wide Web into a model of World Wide Computing Utility, turning an information web into a computing web. The hypertasking model contains three abstractions, including global resource space, stored-computer architecture, and monadic hypermedia. A prototype architecture and experimental evidence are presented to support this perspective.","volume":40,"issue":3,"firstpage":607,"lastpage":620,"year":2025,"type":"Regular Paper","research_area":["Cloud, Edge & Utility Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-5126-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-5126-4?year=2025&issue=3","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4733-4","title":"An Understandable Cross-Chain Authentication Mechanism for JointCloud Computing","authors":[{"last":"Jiang","first":"Feng"},{"last":"Wang","first":"Huai-Min"},{"last":"Shi","first":"Pei-Chang"},{"last":"Fu","first":"Xiang"},{"last":"Feng","first":"Liao-Liao"},{"last":"Li","first":"Rui"},{"last":"Lin","first":"Mo-Heng"}],"keywords":["blockchain","JointCloud computing","smart contract","cross-chain data authentication","accountability"],"abstract":"JointCloud computing is a new computing paradigm that supports cloud services to achieve mutually beneficial outcomes. A key component of this model is the JointCloud computing distributed ledger, which ensures trust among cloud entities with diverse interests by providing digital space evidence. Blockchain forms the foundation of this framework, and its adoption is growing in various fields to optimize workflows. However, challenges related to blockchain interoperability and cross-chain data authentication remain unresolved, hindering the broader establishment of trust among cloud entities. This paper focuses on the specific scenario of cross-chain data authentication and provides a secure and easy-to-deploy solution. Drawing on the concepts of relay chain and notary mechanism in cross-chain methods, our solution leverages smart contracts and on-chain proofs to ensure security, thereby reducing the reliance on relay nodes. In cases of data falsification, our method offers mechanisms for accountability and data revocation, further enhancing security. Additionally, participating blockchains do not need to alter their data structures or network compositions for authentication, which makes the solution easy to deploy. Experimental results demonstrate that our design can be easily deployed on both homogeneous and heterogeneous blockchains. While maintaining performance comparable to existing solutions, it significantly enhances system security. In the event of data falsification, the solution can quickly hold individuals accountable and eliminate the impact of falsified data, reducing the time to mitigate the impact by half compared with other solutions.","volume":40,"issue":3,"firstpage":621,"lastpage":636,"year":2025,"type":"Regular Paper","research_area":["Blockchain & Distributed Ledger","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4733-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4733-4?year=2025&issue=3","affiliations":["National University of Defense Technology - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4821-5","title":"DSparse: A Distributed Training Method for Edge Clusters Based on Sparse Update","authors":[{"last":"Peng","first":"Xiao-Hui"},{"last":"Sun","first":"Yi-Xuan"},{"last":"Zhang","first":"Zheng-Hui"},{"last":"Wang","first":"Yi-Fan"}],"keywords":["distributed training","edge computing","edge machine learning","sparse update","edge cluster"],"abstract":"Edge machine learning creates a new computational paradigm by enabling the deployment of intelligent applications at the network edge. It enhances application efficiency and responsiveness by performing inference and training tasks closer to data sources. However, it encounters several challenges in practice. The variance in hardware specifications and performance across different devices presents a major issue for the training and inference tasks. Additionally, edge devices typically possess limited network bandwidth and computing resources compared with data centers. Moreover, existing distributed training architectures often fail to consider the constraints of resources and communication efficiency in edge environments. In this paper, we propose DSparse, a method for distributed training based on sparse update in edge clusters with various memory capacities. It aims at maximizing the utilization of memory resources across all devices within a cluster. To reduce memory consumption during the training process, we adopt sparse update to prioritize the updating of selected layers on the devices in the cluster, which not only lowers memory usage but also reduces the data volume of parameters and the time required for parameter aggregation. Furthermore, DSparse utilizes a parameter aggregation mechanism based on multi-process groups, subdividing the aggregation tasks into AllReduce and Broadcast types, thereby further reducing the communication frequency for parameter aggregation. Experimental results using the MobileNetV2 model on the CIFAR-10 dataset demonstrate that DSparse reduces memory consumption by an average of 59.6% across seven devices, with a 75.4% reduction in parameter aggregation time, while maintaining model precision.","volume":40,"issue":3,"firstpage":637,"lastpage":653,"year":2025,"type":"Regular Paper","research_area":["Cloud, Edge & Utility Computing","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4821-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4821-5?year=2025&issue=3","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4636-4","title":"Carbon-Aware Energy Cost Optimization of Data Analytics Across Geo-Distributed Data Centers","authors":[{"last":"Chen","first":"Yi-Ting"},{"last":"Luo","first":"Lai-Long"},{"last":"Guo","first":"De-Ke"},{"last":"He","first":"Qian"}],"keywords":["data analytics","geo-distributed data center","carbon emission","energy cost"],"abstract":"The amount and scale of worldwide data centers grow rapidly in the era of big data, leading to massive energy consumption and formidable carbon emission. To achieve the efficient and sustainable development of information technology (IT) industry, researchers propose to schedule data or data analytics jobs to data centers with low electricity prices and carbon emission rates. However, due to the highly heterogeneous and dynamic nature of geo-distributed data centers in terms of resource capacity, electricity price, and the rate of carbon emissions, it is quite difficult to optimize the electricity cost and carbon emission of data centers over a long period. In this paper, we propose an energy-aware data backup and job scheduling method with minimal cost (EDJC) to minimize the electricity cost of geo-distributed data analytics jobs, and simultaneously ensure the long-term carbon emission budget of each data center. Specifically, we firstly design a cost-effective data backup algorithm to generate a data backup strategy that minimizes cost based on historical job requirements. After that, based on the data backup strategy, we utilize an online carbon-aware job scheduling algorithm to calculate the job scheduling strategy in each time slot. In this algorithm, we use the Lyapunov optimization to decompose the long-term job scheduling optimization problem into a series of real-time job scheduling optimization subproblems, and thereby minimize the electricity cost and satisfy the budget of carbon emission. The experimental results show that the EDJC method can significantly reduce the total electricity cost of the data center and meet the carbon emission constraints of the data center at the same time.","volume":40,"issue":3,"firstpage":654,"lastpage":670,"year":2025,"type":"Regular Paper","research_area":["Data Center Systems & Networks","Data Mining & Analytics"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4636-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4636-4?year=2025&issue=3","affiliations":["Guilin University of Electronic Technology","National University of Defense Technology - China","Sun Yat Sen University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4634-6","title":"ResCheckpointer: Building Program Error Resilience-Aware Checkpointing Mechanism for HPC Systems","authors":[{"last":"Wei","first":"Xiao-Hui"},{"last":"Tong","first":"Shi-Yu"},{"last":"Sun","first":"Zhong-Ao"},{"last":"Li","first":"Xiang"},{"last":"Yue","first":"Heng-Shan"}],"keywords":["error resilience","Checkpoint/Restart (C/R)","graph neural network (GNN)","fault injection","high-performance computing"],"abstract":"The reliability of high-performance computing (HPC) is essential for program execution stability. However, as the hardware fault rate constantly increases, fault-tolerance techniques such as Checkpoint/Restart (C/R) introduce significant system overhead. This paper proposes Program Error Resilience-Aware Checkpointing Mechanism (ResCheckpointer) to mitigate the overhead of the C/R mechanism. The primary motivation of ResCheckpointer is that we observe that crash proneness (i.e., the probability of the program crashing after fault occurrence) varies significantly among inter-and intra-HPC programs, which prompts us to flexibly adjust checkpoint intervals for further C/R overhead optimization. Specifically, we first construct the graph neural network (GNN) based learning paradigms to excavate the complex error propagation and effect mechanisms hidden within the HPC program's execution flow, and propose Crash-Predictor for efficiently predicting programs' crash proneness. Based on this, we build ResCheckpointer, which equips an intelligent checkpoint interval setting strategy for HPC programs, i.e., denser for the crash proneness stage while sparser for the error resilience stage. Experimental results show that ResCheckpointer can achieve up to 55.37% C/R cost reduction compared with the baseline C/R mechanism.","volume":40,"issue":3,"firstpage":671,"lastpage":685,"year":2025,"type":"Regular Paper","research_area":["Graph Neural Networks","High-Performance & Parallel Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4634-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4634-6?year=2025&issue=3","affiliations":["Jilin University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4632-8","title":"DiffTSN: Scheduling Mixed Flows in Time-Sensitive Networks with Diffusion-Based Method","authors":[{"last":"Chang","first":"Wei-Ming"},{"last":"Li","first":"Jing-Yi"},{"last":"Chen","first":"Lin"},{"last":"Chen","first":"Xu"}],"keywords":["diffusion model","sporadic flow","time-sensitive network (TSN)","time-triggered flow"],"abstract":"Deterministic transmission plays a vital role in industrial networks. The time-sensitive network (TSN) protocol family offers a promising paradigm for transmitting time-critical data. To achieve low latency and high Quality of Service (QoS) in TSN, appropriate data flow scheduling is needed under the given network topology and data flow requirements to fully utilize the potential of TSN. Both time-triggered flows and sporadic flows can carry high-priority data and need to be considered jointly to eliminate the effects of each other. To this end, in this work, we investigate the challenging mixed-flow scheduling problem and propose a novel diffusion-based algorithm, DiffTSN, to solve the joint routing and scheduling problem of mixed flows. We transform the sporadic flows into probabilistic flows and design certain mechanisms to fit the nature of these probabilistic flows. For routing, we transform the problem into a diffusion policy and constraint denoising process with a value guide to achieve a better routing policy. For scheduling, we adopt a first-valid-time-slot algorithm to determine the start transmission time of the flows. We train and evaluate DiffTSN in our TSN simulator. Experiments show that DiffTSN outperforms state-of-the-art algorithms in various metrics.","volume":40,"issue":3,"firstpage":686,"lastpage":700,"year":2025,"type":"Regular Paper","research_area":["Network Protocols & Measurement","Scheduling & Resource Allocation"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4632-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4632-8?year=2025&issue=3","affiliations":["Sun Yat Sen University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-4817-6","title":"Virtualization, Cloudification, and Service Orientation of Network: A Systematic Review","authors":[{"last":"Quan","first":"Shuo"},{"last":"Gao","first":"Shen"},{"last":"Zhang","first":"Jian-Song"},{"last":"Wu","first":"Jie"}],"keywords":["network function virtualization","network virtualization","network cloudification","network service orientation"],"abstract":"Innovations in new applications and technological advancements are driving the evolution of network architectures towards flexibility and automation. Network Function Virtualization (NFV) deploys Network Functions (NFs) as software applications onto cloud infrastructures, redefining the development, deployment, and operation models of communication networks, thereby meeting the evolution demands of networks. However, after more than a decade of development, the progress of network service operators in NFV has not met expectations, partly because some key technologies remain unresolved. To accelerate the large-scale commercial use of NFV, this paper focuses on reviewing relevant literature from the past five years. Based on practical applications and insights into future trends, we explore the three directions of network virtualization, network cloudification, and network service orientation. We investigate the most representative technologies and the latest research progress in these fields, analyze the current problems and challenges, and provide corresponding suggestions on how to deal with them. Finally, we forecast future directions of technological development.","volume":40,"issue":3,"firstpage":701,"lastpage":730,"year":2025,"type":"Regular Paper","research_area":["Cloud, Edge & Utility Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4817-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4817-6?year=2025&issue=3","affiliations":["China Telecom Corporation Limited","Pennsylvania Commonwealth System of Higher Education (PCSHE)","Temple University"],"type_origin":"Review"},{"doi":"10.1007/s11390-024-3843-8","title":"A Random Mixing Scheme for Protecting Transaction Privacy on Ethereum","authors":[{"last":"Cao","first":"Dong-Yu"},{"last":"Yin","first":"Hao"},{"last":"Li","first":"Bi-Xin"}],"keywords":["blockchain","privacy protection","mixing","Ethereum"],"abstract":"The blockchain technology allows participants to establish pseudonymous addresses, decoupling their real-world identities from their activities on the blockchain network. However, pseudonymity is not completely anonymous and several attacks pose a growing threat to transaction privacy between users. We propose a privacy protection scheme utilizing random mixing on Ethereum, which includes three strategies: RandomMix, TRandomMix, and VRandomMix. The three strategies can protect the sender accounts, the receiver accounts, and the transaction values for one transaction, two transactions, and some equal-value transactions, respectively. We conduct experiments to evaluate both security and performance. The security evaluation results indicate that RandomMix and TRandomMix can resist account clustering attacks, transaction fingerprinting analysis attacks, and Sybil attacks, while VRandomMix can safeguard against account clustering attacks, and is weak against the latter two attacks. In terms of performance, VRandomMix acquires fewer on-chain transactions than RandomMix and TRandomMix. Furthermore, all of them need no off-chain communication and low gas consumption.","volume":40,"issue":3,"firstpage":731,"lastpage":747,"year":2025,"type":"Regular Paper","research_area":["Blockchain & Distributed Ledger","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3843-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3843-8?year=2025&issue=3","affiliations":["Southeast University - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-3850-4","title":"LWCM: A Lookahead-Window Constrained Model for Disk Failure Prediction in Large Data Centers","authors":[{"last":"Zhang","first":"Xin-Yan"},{"last":"Feng","first":"Dan"},{"last":"Tan","first":"Zhi-Peng"},{"last":"Xie","first":"Yan-Wen"},{"last":"Zhao","first":"Shao-Feng"},{"last":"Wei","first":"Ya-Yuan"}],"keywords":["lookahead-window constraint","dynamic relabeling and resampling","disk failure prediction","system reliability"],"abstract":"Disk failures, the most common and major failures in storage systems, increase the risk of service interruption and data loss, and bring additional maintenance costs, which reduces system reliability. Disk failure prediction methods aim to forecast failures, initiating prompt data migration and disk replacement. Existing methods continuously optimize the models with different sampling methods and modeling algorithms. However, due to issues such as inaccurate sample labeling, insufficient data sampling, and improper sample segmentation, the predictive capabilities of existing models within the lookahead-window time are unstable and decline as the lookahead-window time increases. To address this, we propose LWCM (Lookahead-Window Constrained Model) to improve the predictability and stability of failure prediction models within the lookahead-window time. LWCM leverages dynamic sample relabeling methods based on lookahead-window time constraints and failure symptom durations to modify inaccurate sample labels. LWCM utilizes effective sample data by using the two-phase data sampling method including initial expectation sampling and subsequent segmented resampling. LWCM employs dynamic weighted optimization in backpropagation to enhance the predictability and stability of the disk failure prediction model. Experimental results show that LWCM has better failure prediction performance. The true positive and false positive rates surpass those of the offline-RF model by 38.7% and 92.4%, respectively. Furthermore, LWCM demonstrates its applicability across disk models while maintaining stability within the lookahead constraint window.","volume":40,"issue":3,"firstpage":748,"lastpage":765,"year":2025,"type":"Regular Paper","research_area":["Fault Diagnosis & Reliability"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-3850-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-3850-4?year=2025&issue=3","affiliations":["Huazhong University of Science & Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4342-2","title":"Advanced Cross-Graph Cycle Attention Model for Dissecting Complex Structures in Mass Spectrometry Imaging","authors":[{"last":"Cui","first":"Jiang-Nan"},{"last":"Gao","first":"Yang"},{"last":"Wang","first":"Qiu"},{"last":"Li","first":"Xuan"},{"last":"Xu","first":"Ke-Ren"},{"last":"Huang","first":"Zhen-Yu"},{"last":"Zhang","first":"Jing-Song"},{"last":"Zuo","first":"Chun-Man"}],"keywords":["mass spectrometry imaging","multimodal data integration","cross-graph cycle attention","graph attention autoencoder"],"abstract":"Joint analysis of multimodalities in spatial mass spectrometry imaging (SMSI) data, including histology, spatial location, and molecule data, allows us to gain novel insights into tissue structures. However, the significant differences in characteristics such as scale and heterogeneity among the multimodal data, coupled with the high noise levels and uneven quality of MSI data, severely hinder their comprehensive analysis. Here, we introduce a cross-graph cycle attention model, MSCG, to learn efficient joint embeddings for multimodalities of SMSI data by integrating graph attention autoencoders and attention-transfer. Specifically, MSCG enables leveraging one modality (e.g., histology) to fine-tune the graph neural network trained for another modality (e.g., MSI). Our study on real datasets from different platforms highlights the superior capacities of MSCG in dissecting cellular heterogeneity, as well as in denoising and aggregating MSI data. Notably, MSCG demonstrates versatile applicability across MSI data from various platforms, showcasing its potential for broad utility in this field.","volume":40,"issue":3,"firstpage":766,"lastpage":779,"year":2025,"type":"Regular Paper","research_area":["Bioinformatics & Life Sciences"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4342-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4342-2?year=2025&issue=3","affiliations":["Donghua University","Jilin University","Southern University of Science & Technology","Fudan University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4324-4","title":"Unsupervised Adversarial Domain Adaptation with Hierarchical Semantic Consistency for Cross-Modal Nuclei Detection","authors":[{"last":"Guo","first":"Shu-Yu"},{"last":"Huang","first":"Lan"},{"last":"Mu","first":"Yu-Hao"},{"last":"Bai","first":"Tian"}],"keywords":["domain adaptation","nuclei detection","unsupervised learning","microscopy image","pathological stain transformation"],"abstract":"Deep learning based methods have demonstrated outstanding capabilities in quantifying nuclei and cells in microscopy images. However, differences among various stain modalities would affect the performance of nuclei detection. How to fully utilize limited annotations for nuclei detection in other pathological staining images without annotations has become a significant challenge. This paper proposes an end-to-end unsupervised multi-level semantic consistent generative adversarial network (MSC-GAN) for nuclei detection across different pathological staining modalities. Specifically, we address nuclei detection on the unlabeled target domain data by first transforming the stain modality of the source domain into the target domain, and then utilizing the source domain annotations to train the nuclei detector network. A hierarchical semantic consistency loss including feature-level consistency and mask-level consistency is introduced to offer supplementary supervision to enhance the accuracy of generative adversarial learning. We further design an augmentation module to prevent the discriminator from overfitting. The experimental results on four microscopy image datasets demonstrate that MSC-GAN outperforms state-of-the-art methods in the nuclei detection tasks, achieving superior F1 scores.","volume":40,"issue":3,"firstpage":780,"lastpage":791,"year":2025,"type":"Regular Paper","research_area":["Contrastive & Self-Supervised Learning","Multi-Task & Transfer Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4324-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4324-4?year=2025&issue=3","affiliations":["Jilin University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4816-2","title":"Central Feature Network Enables Accurate Detection of Both Small and Large Particles in Cryo-Electron Tomography","authors":[{"last":"Wang","first":"Yao-Yu"},{"last":"Wan","first":"Xiao-Hua"},{"last":"Chen","first":"Cheng"},{"last":"Zhang","first":"Fa"},{"last":"Cui","first":"Xue-Feng"}],"keywords":["particle detection","cryo-electron tomography","pattern recognition","deep learning"],"abstract":"Advances in cryo-electron tomography (cryo-ET) have enabled the visualization of molecules within their native cellular environments in three-dimensions (3D). These visualizations are essential for studying the functions of biological entities in their natural conditions. Recently, deep learning techniques have shown significant success in tackling the challenge of particle detection in cryo-ET data. However, accurately identifying and classifying multi-class molecules remain challenging due to factors like low signal-to-noise ratios and the wide range of particle sizes. In this study, we introduce a novel framework CFNPicker for 3D object detection applied to cryo-ET analysis. A major advantage of our method is the design of central feature network (CFN) to integrate central features across multiple scales, allowing for the accurate detection of both small (<= 200) and large (>= 600) molecules. Additionally, we propose an adaptive weighted sampling training strategy to distinguish the complex noise distribution in the background, reducing false positive particles. We also construct the localization label to explicitly utilize the size and position variations of multi-class protein structures. Compared with existing methods, CFN improves the F1 score for classification by 3.6%, 7.3%, 6.6%, and 5.1% for the four smallest molecules tested respectively, while preserving similar or higher F1 scores for other molecules analyzed.","volume":40,"issue":3,"firstpage":792,"lastpage":804,"year":2025,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4816-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4816-2?year=2025&issue=3","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS","Beijing Institute of Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3536-3","title":"Pushing to the Limit: An Attention-Based Dual-Prune Approach for Highly-Compacted CNN Filter Pruning","authors":[{"last":"Fang","first":"Yu-Chu"},{"last":"Li","first":"Wen-Zhong"},{"last":"Zeng","first":"Yao"},{"last":"Lu","first":"Qing-Ning"},{"last":"Lu","first":"Sang-Lu"}],"keywords":["ultra-high compression","dual attention based structured pruning","inter-layer dependency","layer collapse","neural network compression"],"abstract":"Filter pruning is an important technique to compress convolutional neural networks (CNNs) to acquire lightweight high-performance model for practical deployment. However, the existing filter pruning methods suffer from sharp performance drops when the pruning ratio is large, probably due to the unrecoverable information loss caused by aggressive pruning. In this paper, we propose a dual attention based pruning approach called DualPrune to push the limit of network pruning at an ultra-high compression ratio. Firstly, it adopts a graph attention network (GAT) to automatically extract filter-level and layer-level features from CNNs based on the roles of their filters in the whole computation graph. Then the extracted comprehensive features are fed to a side-attention network, which generates sparse attention weights for individual filters to guide model pruning. To avoid layer collapse, the side-attention network adopts a side-path design to preserve the information flow going through the CNN model properly, which allows the CNN model to be pruned at a high compression ratio at initialization and trained from scratch afterward. Extensive experiments based on several well-known CNN models and real-world datasets show that the proposed DualPrune method outperforms the state-of-the-art methods with significant performance improvement, particularly for model compression at a high pruning ratio.","volume":40,"issue":3,"firstpage":805,"lastpage":820,"year":2025,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3536-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3536-3?year=2025&issue=3","affiliations":["Nanjing University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-3956-8","title":"A Chinese Spelling Check Method Based on Reverse Contrastive Learning","authors":[{"last":"Lin","first":"Nan-Kai"},{"last":"Wu","first":"Hong-Yan"},{"last":"Fu","first":"Si-Hui"},{"last":"Jiang","first":"Sheng-Yi"},{"last":"Yang","first":"Ai-Min"}],"keywords":["Chinese spelling check","reverse contrastive learning","pre-trained model","confusable characters distinction"],"abstract":"Chinese spelling check is a task to detect and correct spelling mistakes in Chinese texts. Existing research aims to enhance the text representation and exploit multi-source information to improve the detection and correction capabilities of models, with little attention to improving the ability to distinguish confusable words. Contrastive learning, aiming to minimize the distance in the representation space between similar sample pairs, has recently become a dominant technique in natural language processing. Inspired by contrastive learning, we present a novel method for Chinese spelling checking, RCL-CSC, which consists of three modules: language representation, spelling check, and reverse contrastive learning. Specifically, we propose a reverse contrastive learning method, which explicitly forces the model to minimize the agreement between similar examples, namely, the phonetically and visually confusable characters. Experimental results show that our method is model-agnostic, and thus can be combined with existing Chinese spelling check models to achieve state-of-the-art performance.","volume":40,"issue":3,"firstpage":821,"lastpage":834,"year":2025,"type":"Regular Paper","research_area":["Contrastive & Self-Supervised Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-3956-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-3956-8?year=2025&issue=3","affiliations":["Guangdong University of Technology","Guangdong University of Foreign Studies","Guangzhou College of Commerce"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-3489-y","title":"Joint-Communication Optimal Matrix Multiplication with Asymmetric Memories","authors":[{"last":"Zhu","first":"Lin"},{"last":"Hua","first":"Qiang-Sheng"},{"last":"Jin","first":"Hai"}],"keywords":["distributed algorithm","matrix multiplication","read-write asymmetric memory","vertical communication","horizontal communication"],"abstract":"Emerging hardware like non-volatile memory (NVM) and high-speed network interface cards are promising to improve the performance of matrix multiplication. However, a critical challenge in achieving high performance is the tradeoff between horizontal communication (data movement between processors) and vertical communication (data movement across memory hierarchies). In this paper, we provide an analysis in the distributed memory parallel model with additional consideration for communication between main memory and cache. We measure joint communication as the sum of the horizontal bandwidth and vertical bandwidth cost, and study the joint-communication cost of square matrix multiplication in the read-write symmetric setting (such as DRAM) and asymmetric setting (such as NVM). Specifically, we identify that in the symmetric setting, a joint-communication optimal algorithm can be directly obtained by combining the horizontally optimal and vertically optimal algorithms. We also identify that in the asymmetric setting, horizontal and vertical communications cannot be optimal at the same time, which means that there is a tradeoff between the two communications. In this case, we first present a joint-communication lower bound, and then we propose Joint-Communication Optimal Matrix Multiplication Algorithm (JOMMA), a parallel matrix multiplication algorithm whose joint-communication complexity meets the lower bound. The key idea behind JOMMA is to derive optimal matrix dimensions that each processor locally performs, which leads to determining the processor grid and an optimal schedule.","volume":40,"issue":3,"firstpage":835,"lastpage":854,"year":2025,"type":"Regular Paper","research_area":["High-Performance & Parallel Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3489-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3489-y?year=2025&issue=3","affiliations":["Huazhong University of Science & Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3673-8","title":"Optimization of Generalized Eigensolver for Dense Symmetric Matrices on AMD GPU","authors":[{"last":"Zhang","first":"Chong"},{"last":"Su","first":"Zi-Tong"},{"last":"Li","first":"Min"},{"last":"Li","first":"Hui-Yuan"},{"last":"Ma","first":"Wen-Jing"},{"last":"Li","first":"Lei-Sheng"}],"keywords":["AMD GPU","dense symmetric matrix","generalized eigenproblem","performance optimization"],"abstract":"Accelerating the eigensolver on GPUs is getting more and more attention due to its ubiquitous usage in scientific and engineering fields. However, it is very challenging to achieve high performance on eigensolvers because of the intricate computational patterns which cause inefficient memory access and workload imbalance on GPUs. In this work, we propose a series of optimizations for generalized dense symmetric eigenvalue problems from both the system and operator perspectives on AMD GPUs. Firstly, we adjust the workload assignments between CPUs and GPUs and find the computational performance balance between different levels of computation. Besides, we propose a multi-level pre-aggregation strategy for symmetric matrix-vector multiplication (SYMV) and general matrix-vector multiplication (GEMV) operators to tackle the performance issue caused by lacking hardware support for atomic operation. Furthermore, we optimize Cholesky decomposition and SYR2K by adopting a better overlapping method and utilizing symmetry to reduce computation. Experiments on AMD MI60 GPUs show that our optimized eigensolver outperforms the previous state-of-the-art with roughly 1.8x-3.8x speedups.","volume":40,"issue":3,"firstpage":855,"lastpage":869,"year":2025,"type":"Regular Paper","research_area":["GPU & Accelerator Architecture","Optimization & Heuristic Methods"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3673-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3673-8?year=2025&issue=3","affiliations":["Chinese Academy of Sciences","University of Chinese Academy of Sciences, CAS","Nanjing Institute of Geology & Paleontology, CAS","Institute of Software, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3040-9","title":"Caching Document Identifiers to Speedup Query Processing in Search Servers","authors":[{"last":"Tolosa","first":"Gabriel H."},{"last":"Lavallen","first":"Pablo"},{"last":"Rissola","first":"Esteban A."}],"keywords":["caching","efficiency","query processing","search"],"abstract":"Modern search systems have become a fundamental tool for accessing the massive amount of information stored in different repositories. These systems use sophisticated techniques to efficiently process a high volume of queries (thus optimizing energy consumption). One of these techniques is caching, which is implemented at different levels of a search architecture. In this work, we propose a novel caching strategy that speeds up dynamic pruning techniques (such as Maxscore) by exploiting the information of the lowest (Min) and highest (Max) document identifiers that appear as the result of a previously submitted query. We name this technique as Min/Max caching. The idea is to use Min/Max information for pruning the terms' posting lists in the query before executing the ranking algorithm in a document-at-a-time (DAAT) approach. The proposed technique uses low memory resources, returns safe results, and complements other levels of caching (if present). We also combine the approach with different access policies. Extensive experimentation on real-world data shows that the proposed method increases query processing speedup up to 1.23x and can also reduce high-percentile tail latency (up to 2.0x speedup), an essential requirement for operational scenarios. We evaluate different access and eviction cache policies based on different decision criteria. Our findings confirm that considering the cost of the cached items (cost-aware policies) allows more computation savings.","volume":40,"issue":3,"firstpage":870,"lastpage":886,"year":2025,"type":"Regular Paper","research_area":["Databases & Query Processing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3040-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3040-9?year=2025&issue=3","affiliations":["Universidad Nacional de Lujan"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-4497-x","title":"AB-DHD: An Attention Mechanism and Bi-Directional Gated Recurrent Unit Based Model for Dynamic Link Library Hijacking Vulnerability Discovery","authors":[{"last":"Chen","first":"Xiao"},{"last":"Sha","first":"Le-Tian"},{"last":"Xiao","first":"Fu"},{"last":"Pan","first":"Jia-Ye"},{"last":"Dong","first":"Jian-Kuo"}],"keywords":["attention mechanism","dynamic link library hijacking","gated recurrent unit (GRU)","operating system","vulnerability discovery"],"abstract":"With the rapid development of operating systems, attacks on system vulnerabilities are increasing. Dynamic link library (DLL) hijacking is prevalent in installers on freeware platforms and is highly susceptible to exploitation by malware attackers. However, existing studies are based solely on the load paths of DLLs, ignoring the attributes of installers and invocation modes, resulting in low accuracy and weak generality of vulnerability detection. In this paper, we propose a novel model, AB-DHD, which is based on an attention mechanism and a bi-directional gated recurrent unit (BiGRU) neural network for DLL hijacking vulnerability discovery. While BiGRU is an enhancement of GRU and has been widely applied in sequence data processing, a double-layer BiGRU network is introduced to analyze the internal features of installers with DLL hijacking vulnerabilities. Additionally, an attention mechanism is incorporated to dynamically adjust feature weights, significantly enhancing the ability of our model to detect vulnerabilities in new installers. A comprehensive List of Easily Hijacked DLLs is developed to serve a reference for future studies. We construct an EXEFul dataset and a DLLVul dataset, using data from two publicly available authoritative vulnerability databases, Common Vulnerabilities & Exposures (CVE) and China National Vulnerability Database (CNVD), and mainstream installer distribution platforms. Experimental results show that our model outperforms popular automated tools like Rattler and DLLHSC, achieving an accuracy of 97.79% and a recall of 94.72%. Moreover, 17 previously unknown vulnerabilities have been identified, and corresponding vulnerability certifications have been assigned.","volume":40,"issue":3,"firstpage":887,"lastpage":903,"year":2025,"type":"Regular Paper","research_area":["Transformers & Attention","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-4497-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-4497-x?year=2025&issue=3","affiliations":["Nanjing University of Posts & Telecommunications"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3517-6","title":"OSKR/OKAI: Systematic Optimization of Key Encapsulation Mechanisms from Module Lattice","authors":[{"last":"Shen","first":"Shi-Yu"},{"last":"Zhang","first":"Hong"},{"last":"He","first":"Feng"},{"last":"Liang","first":"Zhi-Chuang"},{"last":"Zheng","first":"Jie-Yu"},{"last":"Wei","first":"Han-Yu"},{"last":"Wang","first":"Yang"},{"last":"Zhang","first":"Zhen-Feng"},{"last":"Zhao","first":"Yun-Lei"}],"keywords":["post-quantum cryptography (PQC)","lattice-based cryptography","key encapsulation mechanism","Number Theoretic Transform","software optimization"],"abstract":"In this work, we make systematic optimizations of key encapsulation mechanisms based on Module Learning-with-Errors, covering algorithmic design, fundamental operation of the Number Theoretic Transform (NTT), approaches to expanding the encapsulated key size, and AVX2/ARM implementations. We observe that decryption can be simplified, leading to a both faster and less error-prone decryption process. Based on a systematic study of variants of NTT, we present a new variant named hybrid-NTT that combines the advantages of existing NTT methods, and derive its optimality in computational complexity. We analyze and compare the different approaches to expand the size of the key to be encapsulated and conclude with the most economic approach. Each above optimization technique is of independent value, and we apply all of them to KYBER and Aigis, resulting in new scheme variants named OSKR and OKAI, respectively. For all new schemes proposed in this work, we provide optimized AVX2 and ARM Cortex-M4 implementations and present the performance benchmarks. Our AVX2 implementation provides up to 19.7% and 26.4% speedups compared with KYBER and Aigis, respectively. Meanwhile, with our new parameter set and optimization techniques, we show up to a 17% improvement compared with KYBER on the ARM Cortex-M4 platform.","volume":40,"issue":3,"firstpage":904,"lastpage":920,"year":2025,"type":"Regular Paper","research_area":["Quantum Computing","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3517-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3517-6?year=2025&issue=3","affiliations":["Fudan University","Shandong University","Chinese Academy of Sciences","Institute of Software, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3670-y","title":"Efficient Function-Hiding Inner Product Functional Encryption and Its Application to Fine-Grained Data Sharing","authors":[{"last":"Wan","first":"Ming"},{"last":"Wang","first":"Geng"},{"last":"Sun","first":"Shi-Feng"}],"keywords":["function-hiding","functional encryption","fine-grained data sharing","generic group model","inner product"],"abstract":"In a function-hiding inner product functional encryption (FH-IPFE) scheme, both secret keys and ciphertexts are associated with vectors. Given a secret key for an n-dimensional vector x, and a ciphertext for an n-dimensional vector y, a decryptor learns the inner product value < x, y > and nothing else about both x and y. FH-IPFE has been shown to be very useful in privacy-preserving computation. In this paper, we first propose a new (secret-key) FH-IPFE scheme and prove it the secure in the generic group model. Compared with the state-of-the-art scheme of Kim et al., the proposed scheme has comparable performance in decryption and reduces 1) the size of master key from n2 to 3n - 1, 2) the setup complexity from O(n3) to O(n), and 3) the encryption and key generation complexities from O(n2) to O(n log n). To the best of our knowledge, this is the most efficient construction based on pairings to date. Moreover, we apply our FH-IPFE scheme to build a fine-grained data sharing system, where data owners store their encrypted data on an untrusted server. Our design supports not only basic database operations but also statistical analyses on encrypted data. To achieve this goal, we also introduce a new security notion, partial-key exposure-resilient simulation-based security (PK-ER-SIM), for FH-IPFE, which enables lightweight clients to securely delegate heavy computations to a powerful server and may be independent of interest.","volume":40,"issue":3,"firstpage":921,"lastpage":938,"year":2025,"type":"Regular Paper","research_area":["Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3670-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3670-y?year=2025&issue=3","affiliations":["Shanghai Jiao Tong University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-4465-x","title":"Domain Adaptation for Graph Representation Learning: Challenges, Progress, and Prospects","authors":[{"last":"Shi","first":"Bo-Shen"},{"last":"Wang","first":"Yong-Qing"},{"last":"Guo","first":"Fang-Da"},{"last":"Xu","first":"Bing-Bing"},{"last":"Shen","first":"Hua-Wei"},{"last":"Cheng","first":"Xue-Qi"}],"keywords":["graph domain adaptation","graph representation learning","transfer learning"],"abstract":"Graph representation learning often faces knowledge scarcity in real-world applications, including limited labels and sparse relationships. Although a range of methods have been proposed to address these problems, such as graph few-shot learning, they mainly rely on inadequate knowledge within the task graph, which would limit their effectiveness. Moreover, they fail to consider other potentially useful task-related graphs. To overcome these limitations, domain adaptation for graph representation learning has emerged as an effective paradigm for transferring knowledge across graphs. It is also recognized as graph domain adaptation (GDA). In particular, to enhance model performance on target graphs with specific tasks, GDA introduces a bunch of task-related graphs as source graphs and adapts the knowledge learnt from source graphs to the target graphs. Since GDA combines the advantages of graph representation learning and domain adaptation, it has become a promising direction of transfer learning on graphs and has attracted an increasing amount of research interest in recent years. In this paper, we comprehensively overview the studies of GDA and present a detailed survey of recent advances. Specifically, we outline the current research status, analyze key challenges, propose a taxonomy, introduce representative work and practical applications, and discuss future prospects. To the best of our knowledge, this paper is the first survey for graph domain adaptation.","volume":40,"issue":2,"firstpage":283,"lastpage":300,"year":2025,"type":"Survey","research_area":["Deep Learning & Neural Networks","Graph Neural Networks","Multi-Task & Transfer Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4465-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4465-x?year=2025&issue=2","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2984-5","title":"Density Peak Clustering Algorithm Based on Data Field Theory and Grid Similarity","authors":[{"last":"Yu","first":"Qing-Ying"},{"last":"Shi","first":"Ge-Ge"},{"last":"Xu","first":"Dong-Sheng"},{"last":"Wang","first":"Wen-Kai"},{"last":"Chen","first":"Chuan-Ming"},{"last":"Luo","first":"Yong-Long"}],"keywords":["clustering","data field","grid similarity","grid space","neighborhood extension center"],"abstract":"The density peak clustering algorithm can rapidly identify cluster centers by drawing decision graphs without any prior knowledge; however, when multiple density peaks are present in one cluster of the dataset, the cluster centers cannot be accurately obtained, leading to incorrect clustering. Moreover, the single-step allocation strategy is poorly fault-tolerant and can lead to successive allocation errors. To address these problems, this study proposes a density peak clustering method based on data field theory and grid similarity, which divides the original data into grid spaces to obtain subspace codes and grid data. Subsequently, the potential grid density is introduced to measure the density of each grid based on the data field, and the density peaks are identified to obtain the cluster centers from the high-density grids. Finally, self-organized clustering is realized based on neighborhood extension centers and grid similarity. It thus reduces the possibility of successive assignment errors and the negative impact of multiple density peaks on the clustering results. In addition, the algorithm automatically determines the cluster centers and can correctly assign the non-density-peak grid to the corresponding clusters. Experimental results with synthetic and real-world datasets demonstrate that the proposed algorithm outperforms similar algorithms in terms of accuracy and efficiency when dealing with complex datasets with large density differences and cross-tangling.","volume":40,"issue":2,"firstpage":301,"lastpage":321,"year":2025,"type":"Regular Paper","research_area":["Data Mining & Analytics"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2984-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2984-5?year=2025&issue=2","affiliations":["Anhui Normal University","Anhui Provincial Key Laboratory of Network and Information Security"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-023-3013-4","title":"A Model-Agnostic Hierarchical Framework Towards Trajectory Prediction","authors":[{"last":"Qian","first":"Tang-Wen"},{"last":"Wang","first":"Yuan"},{"last":"Xu","first":"Yong-Jun"},{"last":"Zhang","first":"Zhao"},{"last":"Wu","first":"Lin"},{"last":"Qiu","first":"Qiang"},{"last":"Wang","first":"Fei"}],"keywords":["spatial-temporal data mining","trajectory prediction","hierarchical framework","model-agnostic"],"abstract":"Predicting the future trajectories of multiple agents is essential for various applications in real life, such as surveillance systems, autonomous driving, and social robots. The trajectory prediction task is influenced by many factors, including the individual historical trajectory, interactions between agents, and the fuzzy nature of the observed agents' motion. While existing methods have made great progress on the topic of trajectory prediction, they treat all the information uniformly, which limits the effectiveness of information utilization. To this end, in this paper, we propose and utilize a model-agnostic framework to regard all the information in a two-level hierarchical view. Particularly, the first-level view is the inter-trajectory view. In this level, we observe that the difficulty in predicting different trajectory samples varies. We define trajectory difficulty and train the proposed framework in an easy-to-hard schema. The second-level view is the intra-trajectory level. We find the influencing factors for a particular trajectory can be divided into two parts. The first part is global features, which keep stable within a trajectory, i.e., the expected destination. The second part is local features, which change over time, i.e., the current position. We believe that the two types of information should be handled in different ways. The hierarchical view is beneficial to take full advantage of the information in a fine-grained way. Experimental results validate the effectiveness of the proposed model-agnostic framework.","volume":40,"issue":2,"firstpage":322,"lastpage":339,"year":2025,"type":"Regular Paper","research_area":["Data Mining & Analytics","Trajectory & Spatial Data"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3013-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3013-4?year=2025&issue=2","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2995-2","title":"BAM_CRS: Blockchain-Based Anonymous Model for Cross-Domain Recommendation Systems","authors":[{"last":"Wang","first":"Li-E"},{"last":"Li","first":"Dong-Cheng"},{"last":"Liu","first":"Peng"},{"last":"Li","first":"Xian-Xian"}],"keywords":["anonymous","cross-domain recommendation (CDR)","data authenticity","privacy protection","utility"],"abstract":"The cross-domain recommendation (CDR) technique has been widely applied in recommendation systems and can effectively relieve the data sparsity and cold start problems. However, it brings up data privacy and authenticity challenges due to different data sources. Most existing solutions only consider data privacy, and are not robust against participant poisoning attacks that affect the quality of recommendations. How to leverage the privacy and authenticity of data remains a key challenge. To this end, we propose a blockchain-based anonymous model for CDR systems (BAM_CRS). Under this model, we use a three-chain structure to store users, products, and the relationships between the two parties to guarantee privacy. This structure enables transactions to be separated from users and items to guarantee privacy and to establish consensus without relying on a central authority. For data authenticity, we warrant data imtamability and traceability through on-chain data collection and design a contribution-based quantification and incentive mechanism to ensure system sustainability. Additionally, a signature-based verifiable mechanism is designed to motivate node participation and further guarantee data authenticity. Experiments on real-life datasets demonstrate that our model can protect privacy with an advantage of about 2% improvement over baselines in terms of precision and F1 metrics.","volume":40,"issue":2,"firstpage":340,"lastpage":358,"year":2025,"type":"Regular Paper","research_area":["Recommendation Systems","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2995-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2995-2?year=2025&issue=2","affiliations":["Guangxi Normal University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3661-z","title":"Facial Expression Generation from Text with FaceCLIP","authors":[{"last":"Fu","first":"Wen-Wen"},{"last":"Gong","first":"Wen-Juan"},{"last":"Yu","first":"Chen-Yang"},{"last":"Wang","first":"Wei"},{"last":"Gonzalez","first":"Jordi"}],"keywords":["facial expression generation","contrastive language-image pre-training (CLIP)","multi-stage","generative adversarial network (GAN)"],"abstract":"Facial expression generation from pure textual descriptions is widely applied in human-computer interaction, computer-aided design, assisted education, etc. However, this task is challenging due to the intricate facial structure and the complex mapping between texts and images. Existing methods face limitations in generating high-resolution images or capturing diverse facial expressions. In this study, we propose a novel generation approach, named FaceCLIP, to tackle these problems. The proposed method utilizes a CLIP-based multi-stage generative adversarial model to produce vivid facial expressions with high resolutions. With strong semantic priors from multi-modal textual and visual cues, the proposed method effectively disentangles facial attributes, enabling attribute editing and semantic reasoning. To facilitate text-to-expression generation, we build a new dataset called the FET dataset, which contains facial expression images and corresponding textual descriptions. Experiments on the dataset demonstrate improved image quality and semantic consistency compared with state-of-the-art methods.","volume":40,"issue":2,"firstpage":359,"lastpage":377,"year":2025,"type":"Regular Paper","research_area":["Generative Models"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3661-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3661-z?year=2025&issue=2","affiliations":["China University of Petroleum","Chinese Academy of Sciences","Institute of Automation, CAS","Nanjing Institute of Geology & Paleontology, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2978-y","title":"Vision-Based Sign Language Translation via a Skeleton-Aware Neural Network","authors":[{"last":"Ga","first":"Shi-Wei"},{"last":"Yin","first":"Ya-Feng"},{"last":"Jiang","first":"Zhi-Wei"},{"last":"Xie","first":"Lei"},{"last":"Lu","first":"Sang-Lu"}],"keywords":["human action recognition","sign language translation","skeleton","neural network"],"abstract":"Sign languages are mainly expressed by human actions, such as arm, hand, and finger motions. Thus a skeleton which reflects human pose information can provide an important cue for distinguishing signs (i.e., human actions), and can be used for sign language translation (SLT), which aims to translate sign language to spoken language. However, the recent neural networks typically focus on extracting local-area or full-frame features, while ignoring informative skeleton features. Therefore, this paper proposes a novel skeleton-aware neural network, SANet, for vision-based SLT. Specifically, to introduce skeleton modality, we design a self-contained branch for skeleton extraction. To efficiently guide the feature extraction from videos with skeletons, we concatenate the skeleton channel and RGB channels of each frame for feature extraction. To distinguish the importance of clips (i.e., segmented short videos), we construct a skeleton-based graph convolutional network, GCN, for feature scaling, i.e., giving an importance weight for each clip. Finally, to generate spoken language from features, we provide an end-to-end method and a two-stage method for SLT. Besides, based on SANet, we provide an SLT solution on the smartphone for benefiting communication between hearing-impaired people and normal people. Extensive experiments on three public datasets and case studies in real scenarios demonstrate the effectiveness of our method, which outperforms existing methods.","volume":40,"issue":2,"firstpage":378,"lastpage":396,"year":2025,"type":"Regular Paper","research_area":["Computer Vision","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2978-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2978-y?year=2025&issue=2","affiliations":["Nanjing University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3337-8","title":"FSD-GAN: Generative Adversarial Training for Face Swap Detection via the Latent Noise Fingerprint","authors":[{"last":"Ge","first":"Jia-Wei"},{"last":"Cao","first":"Jiu-Xin"},{"last":"Zhao","first":"Zhi-Xiang"},{"last":"Liu","first":"Bo"}],"keywords":["DeepFake detection","latent noise fingerprint","generative adversarial network","deep learning"],"abstract":"Current studies against DeepFake attacks are mostly passive methods that detect specific defects of DeepFake algorithms, lacking generalization ability. Meanwhile, existing active defense methods only focus on defending against face attribute manipulations, and there remain enormous challenges to establishing an active and sustainable defense mechanism for face swap detection. Therefore, we propose a novel training framework called FSD-GAN (Face Swap Detection based on Generative Adversarial Network), immune to the evolution of face swap attacks. Specifically, FSD-GAN contains three modules: the data processing module, the attack module that generates fake faces only used in training, and the defense module that consists of a fingerprint generator and a fingerprint discriminator. We embed the latent noise fingerprints generated by the fingerprint generator into face images, unperceivable to attackers visually and statistically. Once an attacker uses these protected faces to perform face swap attacks, these fingerprints will be transferred from training data (protected faces) to generative models (real-world face swap models), and they also exist in generated results (swapped faces). Our discriminator can easily detect latent noise fingerprints embedded in face images, converting the problem of face swap detection to verifying if fingerprints exist in swapped face images or not. Moreover, we alternately train the attack and defense modules under an adversarial framework, making the defense module more robust. We illustrate the effectiveness and robustness of FSD-GAN through extensive experiments, demonstrating that it can confront various face images, mainstream face swap models, and JPEG compression under different qualities.","volume":40,"issue":2,"firstpage":397,"lastpage":412,"year":2025,"type":"Regular Paper","research_area":["Computer Vision","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3337-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3337-8?year=2025&issue=2","affiliations":["Southeast University - China","Purple Mountain Laboratories"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-3006-3","title":"CTNet: A Convolutional Transformer Network for Color Image Steganalysis","authors":[{"last":"Wei","first":"Kang-Kang"},{"last":"Luo","first":"Wei-Qi"},{"last":"Tan","first":"Shun-Quan"},{"last":"Huang","first":"Ji-Wu"}],"keywords":["steganalysis","steganography","convolutional neural network","Transformer","color image"],"abstract":"Compared with convolutional neural network (CNN), Transformer can obtain global receptive field features more effectively and has recently achieved great success in natural language processing and computer vision. Due to the particularity of steganography, however, almost all existing steganalytic networks just employ CNN with local receptive fields to detect embedding artifacts. In this paper, we propose a novel convolutional Transformer network for color image steganalysis. Specifically, we firstly obtain various image residuals for each color channel of an input image in the pre-processing module. To capture more comprehensive steganalytic features, the truncated residuals after channel concatenation will pass through a feature extraction module composed of a CNN group and a Transformer group. The CNN group aims to extract local receptive fields features, while the Transformer group with multi-head self-attention as the key tries to extract global steganalytic features. Finally, we employ a global covariance pooling (GCP) and two fully-connected (FC) layers with dropout for classification. Extensive comparative experiments demonstrate that the proposed method can significantly improve the detection performances in color image steganalysis and achieve state-of-the-art results. Although the proposed method is originally designed for color images, it can also obtain competitive results for grayscale images compared with the current best detector. In addition, we provide numerous ablation studies to verify the rationality of the proposed network architecture.","volume":40,"issue":2,"firstpage":413,"lastpage":427,"year":2025,"type":"Regular Paper","research_area":["Convolutional & Spiking Networks","Deep Learning & Neural Networks","Transformers & Attention"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3006-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3006-3?year=2025&issue=2","affiliations":["Sun Yat Sen University","Shenzhen University","Shenzhen Institute of Artificial Intelligence & Robotics for Society"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3039-2","title":"Novel Algorithms for Efficient Mining of Connected Induced Subgraphs of a Given Cardinality","authors":[{"last":"Wang","first":"Shan-Shan"},{"last":"Xiao","first":"Cheng-Long"}],"keywords":["graph theory","subgraph enumeration","connected induced subgraph","top-down search"],"abstract":"Mining subgraphs with interesting structural properties from networks (or graphs) is a computationally challenging task. In this paper, we propose two algorithms for enumerating all connected induced subgraphs of a given cardinality from networks (or connected undirected graphs in networks). The first algorithm is a variant of a previous well-known algorithm. The algorithm enumerates all connected induced subgraphs of cardinality k in a bottom-up manner. The data structures that lead to unit time element checking and linear space are presented. Different from previous algorithms that work in either a bottom-up manner or a reverse search manner, an algorithm that enumerates all connected induced subgraphs of cardinality k in a top-down manner is proposed. The correctness and complexity of the top-down algorithm are theoretically analyzed and proven. In the experiments, we evaluate the efficiency of the algorithms using a set of real-world networks from various fields. Experimental results show that the variant bottom-up algorithm outperforms the state-of-the-art algorithms for enumerating connected induced subgraphs of small cardinality, and the top-down algorithm can achieve an order of magnitude speedup over the state-of-the-art algorithms for enumerating connected induced subgraphs of large cardinality.","volume":40,"issue":2,"firstpage":428,"lastpage":443,"year":2025,"type":"Regular Paper","research_area":["Graph Theory & Algorithms"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3039-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3039-2?year=2025&issue=2","affiliations":["Shantou University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3773-5","title":"VastPipe: A High-Throughput Inference System via Adaptive Space-Division Multiplexing for Diverse Accelerators","authors":[{"last":"Ma","first":"Li-Xian"},{"last":"Wang","first":"Le-Ping"},{"last":"Shao","first":"En"},{"last":"Cao","first":"Rong-Yu"},{"last":"Tan","first":"Guang-Ming"}],"keywords":["cluster scheduling","resource management","reinforcement learning","DNN accelerator"],"abstract":"The escalating demand on batched deep learning inference requires concurrent deployment of multiple deep neural network (DNN) models on a shared accelerator, thereby enabling spatial multiplexing to enhance resource utilization. Spatial multiplexing for co-locating multiple model services on the same accelerator increases the complexity of scheduling within a cluster. The meticulous collaborative optimization of model co-location combinations and resource allocation in a cluster creates an extensive configuration space for scheduling. In this paper, we present VastPipe, a high-throughput inference system that schedules batch-oriented and heterogeneous requests on spatial multiplexing-enabled computing clusters. VastPipe determines optimal scheduling configurations by jointly optimizing model co-location and resource allocation using reinforcement learning to solve this combinatorial optimization problem. The experimental results demonstrate that on a large-scale cluster comprising 250 machine nodes with 1 000 neural processing units (NPUs), VastPipe achieves average performance improvements of 2.2x, 1.3x, and 1.2x compared with the baseline systems, respectively. Furthermore, VastPipe is optimized and evaluated on mainstream GPUs. The results demonstrate that VastPipe achieves average throughput improvements of 2.7x on the NVIDIA A100 GPU and 1.9x on the AMD MI100 GPU.","volume":40,"issue":2,"firstpage":444,"lastpage":463,"year":2025,"type":"Regular Paper","research_area":["GPU & Accelerator Architecture","Reinforcement Learning","Scheduling & Resource Allocation"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3773-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3773-5?year=2025&issue=2","affiliations":["Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-3762-3","title":"Harmonizing Security and Performance in Microkernel File Servers","authors":[{"last":"Li","first":"Wen-Tai"},{"last":"Wang","first":"Zi-Xuan"},{"last":"Gu","first":"Jin-Yu"},{"last":"Xia","first":"Yu-Bin"},{"last":"Zang","first":"Bin-Yu"}],"keywords":["microkernel","file system","confidentiality","integrity"],"abstract":"Microkernel OSes separate OS functionalities, including file systems and device drivers, into different user-level services, which mitigates the problem of lacking isolation in monolithic OSes. Nevertheless, from the perspective of applications, compromised services may still threaten applications' security. Specifically, attackers can utilize vulnerabilities in file systems and disk drivers to leak or manipulate applications' file content. The key problem is that de-privileging OS services from the kernel level to the user level does not mean the reduction of applications' trusted computing base (TCB), and applications still need to trust all the required system services. This paper shows a case for providing the file service to applications with minimum TCB on microkernel OSes. Observing that file services actually do not need to access concrete file content, we propose a mechanism named Mirage, which deprives their privilege of accessing file content while preserving their management capability. Mirage efficiently protects the confidentiality and integrity of application files from untrusted services. The evaluation demonstrates that Mirage outperforms an encryption-based mechanism by up to 128% for IO-intensive workloads.","volume":40,"issue":2,"firstpage":464,"lastpage":481,"year":2025,"type":"Regular Paper","research_area":["Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-3762-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-3762-3?year=2025&issue=2","affiliations":["Shanghai Jiao Tong University"],"type_origin":"Article"},{"doi":"10.1007/s11390-025-3886-5","title":"FuHsi: Shifting Base-Calling Closer to Sequencer via In-Cache Acceleration","authors":[{"last":"Li","first":"Ye-Wen"},{"last":"Tan","first":"Guang-Ming"},{"last":"Li","first":"Xue-Qi"}],"keywords":["genome base-calling","in-cache accelerator","domain-specific architecture","genome analysis","Nanopore sequencing"],"abstract":"Base-calling is an essential step in the analysis of third-generation genome data. Many previous hardware efforts aimed at enhancing processing in the workflow. However, an order of magnitude throughput gap still exists. In this paper, we propose FuHsi to improve the end-to-end throughput of the base-calling process. FuHsi is an in-cache accelerator that only introduces three components to the traditional CPUs in the sequencer. We propose FuHsi Cache, which offloads the bottleneck operations to cache arithmetic. Specifically, we accelerate beam search, string conversion, and MAC (multiply-accumulate) using algorithm/hardware co-design. We also introduce FuHsi APIs and FuHsi Controller to provide coarse-grained control for FuHsi Cache. Experimental results show that FuHsi can achieve 45.7x, 113.1x, and 100x throughput per watt speedup compared with an NVIDIA Jetson baseline, an NVIDIA A100 GPU baseline, and the Helix accelerator, respectively. FuHsi can provide base-calling requests for up to 15 ONT sequencers simultaneously.","volume":40,"issue":2,"firstpage":482,"lastpage":499,"year":2025,"type":"Regular Paper","research_area":["GPU & Accelerator Architecture","Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-025-3886-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-025-3886-5?year=2025&issue=2","affiliations":["Chinese Academy of Sciences","University of Chinese Academy of Sciences"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-023-3002-7","title":"SegNet-OPC: A Mask Optimization Framework in VLSI Design Flow Based on Semantic Segmentation Network","authors":[{"last":"Xu","first":"Hui"},{"last":"Qi","first":"Pan"},{"last":"Tang","first":"Fu-Xin"},{"last":"Liang","first":"Hua-Guo"},{"last":"Huang","first":"Zheng-Feng"}],"keywords":["learning-based framework","mask optimization","mask printability","optical proximity correction"],"abstract":"With the continuous decrease in the critical dimensions of integrated circuits, mask optimization has become the main challenge in VLSI design. In recent years, thriving machine learning has been gradually introduced in the field of optical proximity correction (OPC). Currently, advanced learning-based frameworks have been limited by low mask printability or large computational overhead. To address these limitations, this paper proposes a learning-based framework named SegNet-OPC, which can generate optimized masks from the target layout at shorter training and turnaround time with higher mask printability. The proposed framework consists of a backbone network and loss terms suitable for mask optimization tasks, followed by a fine-tuning network. The framework yields remarkable improvements over conventional methods, delivering significantly faster turnaround time and superior mask printability and manufacturability. With just 1.25 hours of training, the framework achieves comparable mask complexity while surpassing the state-of-the-art methods, achieving a minimum 3% enhancement in mask printability and an impressive 16.7% improvement in mask manufacturability.","volume":40,"issue":2,"firstpage":500,"lastpage":512,"year":2025,"type":"Regular Paper","research_area":["Optimization & Heuristic Methods"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3002-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3002-7?year=2025&issue=2","affiliations":["Anhui University of Science & Technology","Hefei University of Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3298-y","title":"Edge-Centric Pricing Mechanisms with Selfish Heterogeneous Users","authors":[{"last":"Tan","first":"Hai-Sheng"},{"last":"Li","first":"Guo-Peng"},{"last":"Shen","first":"Zi-Yu"},{"last":"Wang","first":"Zi-He"},{"last":"Han","first":"Zhen-Hua"},{"last":"Xiao","first":"Ming-Jun"},{"last":"Li","first":"Xiang-Yang"},{"last":"Chen","first":"Guo-Liang"}],"keywords":["edge computing","mechanism design","network economics","pricing mechanism"],"abstract":"Through deploying computing resources close to users, edge computing is regarded as a promising complement to cloud computing to provide low-latency computational services. Meanwhile, edge platforms also play the role of competitors of the cloud platforms in a non-cooperative game, which sets prices for computational resources to attract users with different real-time requirements. In this paper, we propose the edge pricing game under competition (EPGC) and investigate the truthful pricing mechanisms of the edge platform with the objective of maximizing its revenue under three different settings. When all user information is available, the optimal mechanism (OM) can be achieved based on a knapsack problem oracle. With partial information, where users' resource demand is given but their preference information to the edge platform is private, we propose a random sampling mechanism (RSM) that achieves a constant approximation with probability approaching one. We also propose an efficient heuristic greedy mechanism, and we call it GM. Both mechanisms are truthful, GM is directly applicable, while RSM requires minor modifications (RSM+) for deployment in the prior-free setting where all user information is private. Finally, extensive simulations are conducted on the Google cluster dataset. The results validate our theoretical analysis that RSM+ works well in the market where edge resources are scarce, while GM performs better when the edge platform has a larger capacity constraint.","volume":40,"issue":2,"firstpage":513,"lastpage":530,"year":2025,"type":"Regular Paper","research_area":["Cloud, Edge & Utility Computing","Game Theory & Mechanism Design"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3298-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3298-y?year=2025&issue=2","affiliations":["Chinese Academy of Sciences","University of Science & Technology of China, CAS","Renmin University of China","Microsoft Research Asia"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-3041-0","title":"Unilateral Control for Social Welfare of Iterated Game in Mobile Crowdsensing","authors":[{"last":"Gu","first":"Ji-Qing"},{"last":"Song","first":"Chao"},{"last":"Wu","first":"Jie"},{"last":"Lu","first":"Li"},{"last":"Liu","first":"Ming"}],"keywords":["iterated game","social welfare control","vehicular crowdsensing","zero-determinant strategy"],"abstract":"Mobile crowdsensing is a popular platform that takes advantage of the onboard sensors and resources on mobile nodes. The crowdsensing platform chooses to assign several sensing tasks each day, whose utility is based on the quality of harvested sensing data, the payment of transmitting data, and the recruitment of mobile nodes. An Internet service provider (ISP) selects a portion of access points (APs) to power on for uploading data, whose utility depends on three parts: the traffic income of transmitting sensing data, the energy cost of operating APs, and the energy cost of data transmissions by APs. The interaction between the crowdsensing platform and ISP is formulated as an iterated game, with social welfare defined as the sum of their expected utilities. In this paper, our objective is to unilaterally control social welfare without considering the opponent's strategy, with the aim of achieving stable and maximized social welfare. To achieve this goal, we leverage the concept of a zero-determinant strategy in the game theory. We introduce a zero-determinant strategy for the vehicular crowdsensing platform (ZD-VCS) and analyze it in discrete and continuous models in the vehicular crowdsensing scenario. Furthermore, we analyze an extortion strategy between the platform and ISP. Experimental results demonstrate that the ZD-VCS strategy enables unilateral control of social welfare, leading to a high and stable value.","volume":40,"issue":2,"firstpage":531,"lastpage":551,"year":2025,"type":"Regular Paper","research_area":["Game Theory & Mechanism Design"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3041-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3041-0?year=2025&issue=2","affiliations":["University of Electronic Science & Technology of China","Chengdu University of Information Technology","Pennsylvania Commonwealth System of Higher Education (PCSHE)","Temple University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2981-3","title":"HeartIt: Low-Power Smoking Detection with a Smartwatch on Either Wrist","authors":[{"last":"Ma","first":"Jiao"},{"last":"Xing","first":"Tian-Zhang"},{"last":"Xi","first":"Wei"},{"last":"Zhao","first":"Kun"},{"last":"Tan","first":"Jun"},{"last":"Chen","first":"Xiao-Jiang"}],"keywords":["mobile computing","smartwatch","smoking detection","heart rate sensor"],"abstract":"To assist with smoking cessation, wearable devices are used to detect the puff (hand-to-mouth gesture) recognition within the smoking activity in a ubiquitous manner. There is a strong assumption that smoking and wearing a smartwatch are usually with the same hand. It will certainly fail to detect smoking gesture with the opposite hand. In this work, we find an interesting phenomenon: smoking can cause a unique pattern of heart rate (HR) which is quite different from other daily activities' effects. Based on this psychophysiological response, we propose HeartIt, a just-in-time smoking detection solution through measuring the HR by a smartwatch. HeartIt works well for the smoker wearing a smartwatch on either wrist. It can accurately distinguish smoking from other similar hand-to-mouth gestures (e.g., eating, drinking). Moreover, we design an adaptive tracker to trigger the HR sensor once the gesture of lighting a cigarette is detected by low-cost accelerometers. It is robust for different people in various postures and scenarios. Our real-world experiments show that the precision and recall rate of HeartIt reaches 96.7% and 99.8%, respectively.","volume":40,"issue":2,"firstpage":552,"lastpage":571,"year":2025,"type":"Regular Paper","research_area":["Human-Computer Interaction"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2981-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2981-3?year=2025&issue=2","affiliations":["Northwest University Xi'an","Xi'an Jiaotong University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3276-4","title":"GGF: Global Geometric Feature for Rotation-Invariant Point Cloud Understanding","authors":[{"last":"Xiao","first":"Yun-Zhe"},{"last":"Li","first":"Fu"},{"last":"Wang","first":"Hao-Tian"},{"last":"Yang","first":"Shao-Wu"}],"keywords":["point cloud","rotation invariance","point cloud understanding"],"abstract":"Most 3D vision tasks related to point cloud understanding require rotation-invariant solutions. However, existing deep learning techniques for point clouds do not always ensure rotation invariance, and achieving rotation invariance necessitates data augmentation or professional networks, which is not feasible for generic point cloud understanding tasks. To address this issue, we propose a plug-and-play feature called Global Geometric Feature (GGF), as an effective and efficient solution achieving rotation invariance for generic point cloud understanding networks. GGF extracts a distributed global description by capturing geometric relationships between points and projecting the point cloud into a rotation-invariant feature space. We find that GGF can be directly integrated into a variety of point cloud understanding tasks without network modification. Our experimental evaluation shows that GGF can improve the performance of generic point cloud networks for rotation-invariant understanding without data augmentation and is comparable to dedicated rotation-invariant methods.","volume":40,"issue":2,"firstpage":572,"lastpage":587,"year":2025,"type":"Regular Paper","research_area":["Point Cloud & 3D Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3276-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3276-4?year=2025&issue=2","affiliations":["National University of Defense Technology - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3021-z","title":"Multi-Source Data with Laplacian Eigenmaps and Denoising Autoencoder for Predicting Microbe-Disease Associations via Convolutional Neural Network","authors":[{"last":"Lei","first":"Xiu-Juan"},{"last":"Chen","first":"Ya-Li"},{"last":"Pan","first":"Yi"}],"keywords":["multi-source data","Laplacian eigenmap","denoising autoencoder","convolutional neural network","microbe-disease association"],"abstract":"Identifying microbes associated with diseases is important for understanding the pathogenesis of diseases as well as for the diagnosis and treatment of diseases. In this article, we propose a method based on a multi-source association network to predict microbe-disease associations, named MMHN-MDA. First, a heterogeneous network of multi-molecule associations is constructed based on associations between microbes, diseases, drugs, and metabolites. Second, the graph embedding algorithm Laplacian eigenmaps is applied to the association network to learn the behavior features of microbe nodes and disease nodes. At the same time, the denoising autoencoder (DAE) is used to learn the attribute features of microbe nodes and disease nodes. Finally, attribute features and behavior features are combined to get the final embedding features of microbes and diseases, which are fed into the convolutional neural network (CNN) to predict the microbe-disease associations. Experimental results show that the proposed method is more effective than existing methods. In addition, case studies on bipolar disorder and schizophrenia demonstrate good predictive performance of the MMHN-MDA model, and further, the results suggest that gut microbes may influence host gene expression or compounds in the nervous system, such as neurotransmitters, or metabolites that alter the blood-brain barrier.","volume":40,"issue":2,"firstpage":588,"lastpage":604,"year":2025,"type":"Regular Paper","research_area":["Convolutional & Spiking Networks","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3021-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3021-z?year=2025&issue=2","affiliations":["Shaanxi Normal University","Chinese Academy of Sciences","Shenzhen Institute of Advanced Technology, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-5036-x","title":"Caging AI","authors":[{"last":"Li","first":"Ming"}],"keywords":["Kolmogorov complexity","large language model (LLM)","relativization","consciousness","artificial general intelligence (AGI)"],"abstract":"As we celebrate the success of AI, it is necessary to investigate the boundaries of AI, a la Karl Popper, so that our society does not fall for misleading commercial claims, and prevent dangers of misusing AI. We chat with our readers casually on several frontier questions from if AI will replace human beings, to AI consciousness, self and nonself awareness, and to our jobs and education. While some things in this essay are speculative, some other things are mathematically proved. We argue why AI and AI generated content should be segregated, and why AGI (artificial general intelligence) cannot make innovations about things independent to human knowledge without external experiments.","volume":40,"issue":1,"firstpage":1,"lastpage":5,"year":2025,"type":"Perspective","research_area":["LLM Agents & Embodied Intelligence"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-5036-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-5036-x?year=2025&issue=1","affiliations":["University of Waterloo"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-4178-1","title":"AI Computing Systems for Large Language Models Training","authors":[{"last":"Zhang","first":"Zhen-Xing"},{"last":"Wen","first":"Yuan-Bo"},{"last":"Lyu","first":"Han-Qi"},{"last":"Liu","first":"Chang"},{"last":"Zhang","first":"Rui"},{"last":"Li","first":"Xia-Qing"},{"last":"Wang","first":"Chao"},{"last":"Du","first":"Zi-Dong"},{"last":"Guo","first":"Qi"},{"last":"Li","first":"Ling"},{"last":"Zhou","first":"Xue-Hai"},{"last":"Chen","first":"Yun-Ji"}],"keywords":["artificial intelligence (AI) chip","large language model (LLM)","AI computing system","accelerator"],"abstract":"In this paper, we present a comprehensive overview of artificial intelligence (AI) computing systems for large language models (LLMs) training. The rapid advancement of LLMs in recent years, coupled with the widespread adoption of algorithms and applications such as BERT, ChatGPT, and DeepSeek, has sparked significant interest in this field. We classify LLMs into encoder-only, encoder-decoder, and decoder-only models, and briefly analyze their training and inference processes to emphasize their substantial need for computational resources. These operations depend heavily on AI-specific accelerators like GPUs (graphics processing units), TPUs (tensor processing units), and MLUs (machine learning units). However, as the gap widens between the increasing complexity of LLMs and the current capabilities of accelerators, it becomes essential to adopt heterogeneous computing systems optimized for distributed environments to manage the growing computational and memory requirements of LLMs. We delve into the execution and scheduling of LLM algorithms, underlining the critical role of distributed computing strategies, memory management enhancements, and boosting computational efficiency. This paper clarifies the complex relationship between algorithm design, hardware infrastructure, and software optimization, and provides an in-depth understanding of both the software and hardware infrastructure supporting LLMs training, offering insights into the challenges and potential avenues for future development and deployment.","volume":40,"issue":1,"firstpage":6,"lastpage":41,"year":2025,"type":"Survey","research_area":["Deep Learning & Neural Networks","GPU & Accelerator Architecture","LLM Systems & Infrastructure"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4178-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4178-1?year=2025&issue=1","affiliations":["Chinese Academy of Sciences","University of Science & Technology of China, CAS","Institute of Computing Technology, CAS","Institute of Software, CAS"],"type_origin":"Review"},{"doi":"10.1007/s11390-024-4314-y","title":"Mix-Lingual Relation Extraction: Dataset and a Training Approach","authors":[{"last":"Kong","first":"Ling-Xing"},{"last":"Chu","first":"You-Gang"},{"last":"Ma","first":"Zheng"},{"last":"Zhang","first":"Jian-Bing"},{"last":"Chen","first":"Jia-Jun"}],"keywords":["natural language processing (NLP)","code-switching","large language model (LLM)","relation extraction","human-annotated dataset"],"abstract":"Relation extraction is a pivotal task within the field of natural language processing, boasting numerous real-world applications. Existing research predominantly centers on monolingual relation extraction or cross-lingual enhancement for relation extraction. However, there exists a notable gap in understanding relation extraction within mix-lingual (or code-switching) scenarios. In these scenarios, individuals blend content from different languages within sentences, generating mix-lingual content. The effectiveness of existing relation extraction models in such scenarios remains largely unexplored due to the absence of dedicated datasets. To address this gap, we introduce the Mix-Lingual Relation Extraction (MixRE) task and construct a human-annotated dataset MixRED to support this task. Additionally, we propose a hierarchical training approach for the mix-lingual scenario named Mix-Lingual Training (MixTrain), designed to enhance the performance of large language models (LLMs) when capturing relational dependencies from mix-lingual content spanning different semantic levels. Our experiments involve evaluating state-of-the-art supervised models and LLMs on the constructed dataset, with results indicating that MixTrain notably improves model performance. Moreover, we investigate the effectiveness of using mix-lingual content as a tool to transfer learned relational dependencies across different languages. Additionally, we delve into factors influencing model performance for both supervised models and LLMs in the novel MixRE task.","volume":40,"issue":1,"firstpage":42,"lastpage":59,"year":2025,"type":"Regular Paper","research_area":["Information Extraction"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4314-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4314-y?year=2025&issue=1","affiliations":["Nanjing University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2870-9","title":"EKBSA: A Chinese Sentiment Analysis Model by Enhancing K-BERT","authors":[{"last":"Bai","first":"Huan"},{"last":"Wang","first":"Da-Ling"},{"last":"Feng","first":"Shi"},{"last":"Zhang","first":"Yi-Fei"}],"keywords":["Chinese sentiment analysis","local attention","sentiment knowledge graph","pre-trained language model","context attention"],"abstract":"Pre-trained language models (PLMs), such as BERT, have achieved good results on many natural language processing (NLP) tasks. Recently, some studies have attempted to integrate factual knowledge into PLMs to adapt to various downstream tasks. For sentiment analysis tasks, sentiment knowledge, such as sentiment words, plays a significant role in determining the sentiment tendencies of texts. For Chinese sentiment analysis, historical stories and fables imbue words with richer connotations and more complex sentiments than those typically found in English, which makes sentiment knowledge injection necessary. But clearly, this knowledge has not been fully considered. In this paper, we propose EKBSA, a Chinese sentiment analysis model, which is based on the K-BERT model and utilizes a sentiment knowledge graph to achieve better results on sentiment analysis tasks. To construct a high-quality sentiment knowledge graph, we collect a large number of sentiment words by combining several existing sentiment lexica. Moreover, in order to understand texts better, we enhance local attention through syntactic analysis and direct to EKBSA focus more on syntactically relevant words. EKBSA is compatible with BERT and existing structural knowledge. Experimental results show that EKBSA achieves better performance on Chinese sentiment analysis tasks. Built upon EKBSA, we further change the general attention to the context attention and propose Context EKBSA, so that the model can adapt to sentiment analysis tasks in Chinese conversations and achieve good performance.","volume":40,"issue":1,"firstpage":60,"lastpage":72,"year":2025,"type":"Regular Paper","research_area":["Sentiment Analysis & Opinion Mining"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2870-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2870-9?year=2025&issue=1","affiliations":["Northeastern University"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-024-2896-z","title":"Learnability in Online Kernel Selection with Memory Constraint via Data-Dependent Regret Analysis","authors":[{"last":"Li","first":"Jun-Fan"},{"last":"Liao","first":"Shi-Zhong"}],"keywords":["model selection","online kernel learning","memory constraint","learnability"],"abstract":"Online kernel selection is a fundamental problem of online kernel methods. In this paper, we study online kernel selection with memory constraint in which the memory of kernel selection and online prediction procedures is limited to a fixed budget. An essential question is what is the intrinsic relationship among online learnability, memory constraint, and data complexity. To answer the question, it is necessary to show the trade-offs between regret and memory budget. Previous work gives a worst-case lower bound depending on the data size, and shows learning is impossible within a small memory budget. In contrast, we present distinct results by offering data-dependent upper bounds that rely on two data complexities: kernel alignment and the cumulative losses of competitive hypothesis. We propose an algorithmic framework giving data-dependent upper bounds for two types of loss functions. For the hinge loss function, our algorithm achieves an expected upper bound depending on kernel alignment. For the smooth loss functions, our algorithm achieves a high-probability upper bound depending on the cumulative losses of competitive hypothesis. We also prove a matching lower bound for smooth loss functions. Our results show that if the two data complexities are sub-linear, then learning is possible within a small memory budget. Our algorithmic framework depends on a new buffer maintaining framework and a reduction from online kernel selection to prediction with expert advice. Finally, we empirically verify the prediction performance of our algorithms on benchmark datasets.","volume":40,"issue":1,"firstpage":73,"lastpage":84,"year":2025,"type":"Regular Paper","research_area":["Optimization & Heuristic Methods"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2896-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2896-z?year=2025&issue=1","affiliations":["Tianjin University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3667-6","title":"3D Point Cloud Matching Based Selfie Generation for Chang'e-5","authors":[{"last":"Chen","first":"Xiao-Rui"},{"last":"Yang","first":"Meng-Fei"},{"last":"Zhang","first":"Gao"},{"last":"Zhang","first":"Wu"},{"last":"Peng","first":"Jing"},{"last":"Gu","first":"Zheng"},{"last":"Deng","first":"Xiang-Jin"},{"last":"Yang","first":"Liu-Zhi"},{"last":"Yang","first":"Fei"},{"last":"Yang","first":"Yun"},{"last":"Sun","first":"Shou-Qian"},{"last":"Tong","first":"Ruo-Feng"},{"last":"Tang","first":"Min"}],"keywords":["image stitching","3D point cloud matching","Chang'e-5","GPU computing","selfie generation"],"abstract":"Generating selfie images on the surface of a celestial body poses several challenges, including the position of the robotic arm, camera field of view, and limited shooting time. To address these challenges, the PCMIS (3D Point Cloud Matching Based Image Stitching) algorithm is designed, along with a corresponding shooting plan. This algorithm establishes a correspondence between depth and color information, enabling the generation of stitching views under any given view parameter. Furthermore, the algorithm is accelerated using GPU processing, resulting in a significant reduction in stitching time. The algorithm is successfully applied to generate selfie images for the Chang'e-5 mission.","volume":40,"issue":1,"firstpage":85,"lastpage":98,"year":2025,"type":"Regular Paper","research_area":["GPU & Accelerator Architecture","Point Cloud & 3D Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3667-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3667-6?year=2025&issue=1","affiliations":["Zhejiang University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2900-7","title":"A Reinforcement Learning Based Approach to Partition Testing","authors":[{"last":"Sun","first":"Chang-Ai"},{"last":"Xiao","first":"Ming-Jun"},{"last":"Dai","first":"He-Peng"},{"last":"Liu","first":"Huai"}],"keywords":["partition testing","reinforcement learning","temporal-difference learning","intelligent software engineering"],"abstract":"Partition testing is one of the most fundamental and popularly used software testing techniques. It first divides the input domain of the program under test into a set of disjoint partitions, and then creates test cases based on these partitions. Motivated by the theory of software cybernetics, some strategies have been proposed to dynamically select partitions based on the feedback information gained during testing. The basic intuition of these strategies is to assign higher probabilities to those partitions with higher fault-detection potentials, which are judged and updated mainly according to the previous test results. Such a feedback-driven mechanism can be considered as a learning process-it makes decisions based on the observations acquired in the test execution. Accordingly, advanced learning techniques could be leveraged to empower the smart partition selection, with the purpose of further improving the effectiveness and efficiency of partition testing. In this paper, we particularly leverage reinforcement learning to enhance the state-of-the-art adaptive partition testing techniques. Two algorithms, namely RLAPT_Q and RLAPT_S, have been developed to implement the proposed approach. Empirical studies have been conducted to evaluate the performance of the proposed approach based on seven object programs with 26 faults. The experimental results show that our approach outperforms the existing partition testing techniques in terms of the fault-detection capability as well as the overall testing time. Our study demonstrates the applicability and effectiveness of reinforcement learning in advancing the performance of software testing.","volume":40,"issue":1,"firstpage":99,"lastpage":118,"year":2025,"type":"Regular Paper","research_area":["Code Intelligence & Maintenance","Reinforcement Learning","Software Testing & Analysis"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2900-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2900-7?year=2025&issue=1","affiliations":["University of Science & Technology Beijing","Swinburne University of Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2943-9","title":"Detecting and Untangling Composite Commits via Attributed Graph Modeling","authors":[{"last":"Xu","first":"Sheng-Bin"},{"last":"Chen","first":"Si-Yu"},{"last":"Yao","first":"Yuan"},{"last":"Xu","first":"Feng"}],"keywords":["composite commit","commit untangling","code dependency graph","attributed graph"],"abstract":"During software development, developers tend to tangle multiple concerns into a single commit, resulting in many composite commits. This paper studies the problem of detecting and untangling composite commits, so as to improve the maintainability and understandability of software. Our approach is built upon the observation that both the textual content of code statements and the dependencies between code statements are helpful in comprehending the code commit. Based on this observation, we first construct an attributed graph for each commit, where code statements and various code dependencies are modeled as nodes and edges, respectively, and the textual bodies of code statements are maintained as node attributes. Based on the attributed graph, we propose graph-based learning algorithms that first detect whether the given commit is a composite commit, and then untangle the composite commit into atomic ones. We evaluate our approach on nine C# projects, and the results demonstrate the effectiveness and efficiency of our approach.","volume":40,"issue":1,"firstpage":119,"lastpage":137,"year":2025,"type":"Regular Paper","research_area":["Code Intelligence & Maintenance","Graph Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2943-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2943-9?year=2025&issue=1","affiliations":["Nanjing University"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-023-2878-6","title":"SAGA: Summarization-Guided Assert Statement Generation","authors":[{"last":"Zhang","first":"Yu-Wei"},{"last":"Jin","first":"Zhi"},{"last":"Wang","first":"Ze-Jun"},{"last":"Xing","first":"Ying"},{"last":"Li","first":"Ge"}],"keywords":["assert generation","deep learning","method summarization","pre-trained language model","unit testing"],"abstract":"Generating meaningful assert statements is one of the key challenges in automated test case generation, which requires understanding the intended functionality of the tested code. Recently, deep learning based models have shown promise in improving the performance of assert statement generation. However, the existing models only rely on the test prefixes along with their corresponding focal methods, yet ignore the developer-written summarization. Based on our observations, the summarization contents usually express the intended program behavior or contain parameters that will appear directly in the assert statement. Such information will help existing models address their current inability to accurately predict assert statements. This paper presents a summarization-guided approach for automatically generating assert statements. To derive generic representations for natural language (i.e., summarization) and programming language (i.e., test prefixes and focal methods), we leverage a pre-trained language model as the reference architecture and fine-tune it on the task of assert statement generation. To the best of our knowledge, the proposed approach makes the first attempt to leverage the summarization of focal methods as the guidance for making the generated assert statements more accurate. We demonstrate the effectiveness of our approach on two real-world datasets compared with state-of-the-art models.","volume":40,"issue":1,"firstpage":138,"lastpage":157,"year":2025,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2878-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2878-6?year=2025&issue=1","affiliations":["Peking University","Beijing University of Posts & Telecommunications"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2967-1","title":"Coverage-Based Fault Localization in Haskell","authors":[{"last":"Li","first":"Feng"},{"last":"Wang","first":"Guo-Qing"},{"last":"Wang","first":"Meng"},{"last":"Hao","first":"Dan"}],"keywords":["debugging","fault localization","Haskell","programming paradigms"],"abstract":"Fault localization is to identify faulty program elements. Among a large number of fault localization approaches in the literature, coverage-based fault localization, especially spectrum-based fault localization (SBFL), has been intensively studied due to its effectiveness and lightweightness. Despite the rich literature, almost all existing fault localization approaches and studies have been conducted on imperative programming languages such as Java and C, leaving a gap in other programming paradigms. In this paper, we aim to study fault localization approaches for the functional programming paradigm, using the Haskell language as a representative. To the best of our knowledge, we build up the first dataset on real Haskell projects, including both real and seeded faults. The dataset enables the research of fault localization for functional languages. With it, we explore fault localization techniques for Haskell. In particular, as is typical for SBFL approaches, we study methods for coverage collection and formulae for suspiciousness score computation, and carefully adapt these two components to Haskell considering the language features and characteristics, resulting in a series of adaption approaches. Moreover, we design a learning-based approach and a transfer learning based approach to take advantage of data from imperative languages. Both approaches are evaluated on our dataset to demonstrate the promises of the direction.","volume":40,"issue":1,"firstpage":158,"lastpage":177,"year":2025,"type":"Regular Paper","research_area":["Software Testing & Analysis"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2967-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2967-1?year=2025&issue=1","affiliations":["Peking University","University of Bristol"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2831-8","title":"CHANN: A Hierarchical Neural Network for Clone Consistency Prediction","authors":[{"last":"Zhang","first":"Fan-Long"},{"last":"Chen","first":"Yu-Chen"},{"last":"Khoo","first":"Siau-Cheng"},{"last":"Jiang","first":"Wen-Chao"}],"keywords":["code clone","clone consistent change","clone consistency prediction","software maintenance","deep learning"],"abstract":"Modifying a code segment may give rise to a consistency issue when the code segment belongs to a clone group comprising closely similar code segments. Recent studies have demonstrated that such consistent changes can incur extra maintenance costs when clones are checked for consistency and introduce defects if developers forget to change clones consistently when needed. To address this problem, researchers have proposed an approach to predict clone consistency in advance with handcrafted attributes, notably using machine learning methods. Although these attributes can help predict clone consistency to some extent, the capability of such an approach is generally weak and unsatisfactory in practice. Such limitations in capability are especially severe at a project's infancy stage when there is not sufficient within-project data to model clone consistency behavior, and cross-project data have not been helpful in supporting prediction. In this paper, we propose the Clone Hierarchical Attention Neural Network (CHANN) to represent code clones and their evolution by adopting a hierarchical perspective of code, context, and code evolution, and thus enhancing the effectiveness of clone consistency prediction. To assess the effectiveness of CHANN, we conduct experiments on the dataset collected from eight open-source projects. The experimental results show that CHANN is highly effective in predicting clone consistency, and the precision, recall, and F-measure attained in prediction are around 82%. These findings support our hypothesis that the hierarchical neural network can help developers predict clone consistency effectively in the case of cross-project incubation when insufficient data are available at the early stage of software development.","volume":40,"issue":1,"firstpage":178,"lastpage":195,"year":2025,"type":"Regular Paper","research_area":["Code Intelligence & Maintenance","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2831-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2831-8?year=2025&issue=1","affiliations":["Guangdong University of Technology","National University of Singapore"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3342-y","title":"Orchestrating In-Network Aggregation for Distributed Machine Learning via In-Band Network Telemetry","authors":[{"last":"Ji","first":"Ming-Tao"},{"last":"Jin","first":"Yi-Bo"},{"last":"Qian","first":"Zhu-Zhong"},{"last":"Cao","first":"Tuo"},{"last":"Ye","first":"Bao-Liu"}],"keywords":["in-network aggregation","distributed learning acceleration","in-band network telemetry","optimization","datacenter network"],"abstract":"Distributed machine learning systems train models via iterative updates between parallel workers and the parameter server. To expedite the transmissions, in-network aggregation of updates along with the packet forwarding at those programmable switches decreases the network traffic over these bottleneck links. However, existing in-network aggregation schemas do not adequately prepare the most suitable switches for various worker distributions and fail to capture the dynamic network status. Based on the status derived from in-band network telemetry, we aim to select the best switches upon the optimization we formulate with the objective of minimum transmission latency. Although the problem is actually a non-linear integer program, by adopting delicate transformations, a substitute with totally unimodular constraints and separable convex objective is then solved to obtain the integral optimum. We implement our in-network aggregation protocol and reconstruct in-band network telemetry protocol upon real devices, i.e., Barefoot Wedge100BF and Dell servers. Then, we evaluate the performance of our proposed AGG algorithm and the results indicate that the completion of related coflows decreases 40% on average compared with other strategies, improving at least 30% performance, compared with the state-of-the-art.","volume":40,"issue":1,"firstpage":196,"lastpage":214,"year":2025,"type":"Regular Paper","research_area":["Data Center Systems & Networks","Optimization & Heuristic Methods"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3342-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3342-y?year=2025&issue=1","affiliations":["Nanjing University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2933-y","title":"Identity-Based Encryption with Equality Test Supporting Accountable Authorization in Cloud Computing","authors":[{"last":"Zhao","first":"Zhen"},{"last":"Wang","first":"Bao-Cang"},{"last":"Gao","first":"Wen"}],"keywords":["identity-based encryption with equality test","accountable authorization","cloud computing","Gentry's IBE","zero-knowledge proof"],"abstract":"Identity-based encryption with equality test (IBEET) is proposed to check whether the underlying messages of ciphertexts, even those encrypted with different public keys, are the same or not without decryption. Since people prefer to encrypt before outsourcing their data for privacy protection nowadays, the research of IBEET on cloud computing applications naturally attracts attention. However, we claim that the existing IBEET schemes suffer from the illegal trapdoor sharing problem caused by the inherited key escrow problem of the Identity-Based Encryption (IBE) mechanism. In traditional IBEET, the private key generator (PKG) with the master secret key generates trapdoors for all authorized cloud servers. Considering the reality in practice, the PKG is usually not fully trusted. In this case, the Private-Key Generator (PKG) may generate, share, or even sell any trapdoor without any risk of being caught, or not being held accountable, which may lead to serious consequences such as the illegal sharing of a gene bank's trapdoors. In this paper, to relieve the illegal trapdoor sharing problem in IBEET, we present a new notion, called IBEET Supporting Accountable Authorization (IBEET-AA). In IBEET-AA, if there is a disputed trapdoor, the generator will be distinguished among the PKG and suspected testers by an additional tracing algorithm. For the additional tracing function, except for the traditional indistinguishability (IND) and one-way (OW) security models in IBEET, we define three more security models to protect the tracing security against dishonest authorizers, PKG, and testers, respectively. Based on Gentry's IBE scheme, we instantiate IBEET-AA and give a specific construction along with a formalized security proof with random oracles.","volume":40,"issue":1,"firstpage":215,"lastpage":228,"year":2025,"type":"Regular Paper","research_area":["Cloud, Edge & Utility Computing","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2933-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2933-y?year=2025&issue=1","affiliations":["Xidian University","Xi'an University of Posts & Telecommunications"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2722-z","title":"Multi-Person Respiration Monitoring Leveraging Commodity Wi-Fi Devices","authors":[{"last":"Yi","first":"En-Ze"},{"last":"Niu","first":"Kai"},{"last":"Zhang","first":"Fu-Sang"},{"last":"Gao","first":"Rui-Yang"},{"last":"Luo","first":"Jun"},{"last":"Zhang","first":"Da-Qing"}],"keywords":["respiration monitoring","multi-person sensing","Wi-Fi sensing"],"abstract":"Monitoring respiration is an important component of personal health care. Though recent developments in Wi-Fi sensing offer a potential tool to achieve contact-free respiration monitoring, existing proposals for Wi-Fi-based multi-person respiration sensing mainly extract individual's respiration rate in the frequency domain using the fast Fourier transform (FFT) or multiple signal classification (MUSIC) method, leading to the following limitations: 1) largely ineffective in recovering breaths of multiple persons from received mixed signals and in differentiating individual breaths, 2) unable to acquire the time-varying respiration pattern when the subject has respiratory abnormity, such as apnea and changing respiration rates, and 3) difficult to identify the real number of subjects when multiple subjects share the same or similar respiration rates. To address these issues, we propose Wi-Fi-enabled MUlti-person SEnsing (WiMUSE) as a signal processing pipeline to perform respiration monitoring for multiple persons simultaneously. Essentially, as a pioneering time domain approach, WiMUSE models the mixed signals of multi-person respiration as a linear superposition of multiple waveforms, so as to form a blind source separation (BSS) problem. The effective separation of the signal sources (respiratory waveforms) further enables us to quantify the differences in the respiratory waveform patterns of multiple subjects, and thus to identify the number of subjects along with their respective respiration waveforms. We implement WiMUSE on commodity Wi-Fi devices and conduct extensive experiments to demonstrate that, compared with the approaches based on the FFT or MUSIC method, 90% error of respiration rate can be reduced by more than 60%.","volume":40,"issue":1,"firstpage":229,"lastpage":251,"year":2025,"type":"Regular Paper","research_area":["Bioinformatics & Life Sciences","IoT & Wireless Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2722-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2722-z?year=2025&issue=1","affiliations":["Peking University","Chinese Academy of Sciences","Institute of Software, CAS","Nanyang Technological University"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-3086-0","title":"Semi-Discrete Optimal Transport for Long-Tailed Classification","authors":[{"last":"Jin","first":"Lian-Bao"},{"last":"Lei","first":"Na"},{"last":"Luo","first":"Zhong-Xuan"},{"last":"Wu","first":"Jin"},{"last":"Ai","first":"Chao"},{"last":"Gu","first":"Xianfeng"}],"keywords":["semi-discrete optimal transport","long-tailed classification","decision boundary","supervised contrastive loss"],"abstract":"The long-tailed data distribution poses an enormous challenge for training neural networks in classification. A classification network can be decoupled into a feature extractor and a classifier. This paper takes a semi-discrete optimal transport (OT) perspective to analyze the long-tailed classification problem, where the feature space is viewed as a continuous source domain, and the classifier weights are viewed as a discrete target domain. The classifier is indeed to find a cell decomposition of the feature space with each cell corresponding to one class. An imbalanced training set causes the more frequent classes to have larger volume cells, which means that the classifier's decision boundary is biased towards less frequent classes, resulting in reduced classification performance in the inference phase. Therefore, we propose a novel OT-dynamic softmax loss, which dynamically adjusts the decision boundary in the training phase to avoid overfitting in the tail classes. In addition, our method incorporates the supervised contrastive loss so that the feature space can satisfy the uniform distribution condition. Extensive and comprehensive experiments demonstrate that our method achieves state-of-the-art performance on multiple long-tailed recognition benchmarks, including CIFAR-LT, ImageNet-LT, iNaturalist 2018, and Places-LT.","volume":40,"issue":1,"firstpage":252,"lastpage":266,"year":2025,"type":"Regular Paper","research_area":["Optimization & Heuristic Methods"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3086-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3086-0?year=2025&issue=1","affiliations":["Dalian University of Technology","Huawei Technologies","State University of New York (SUNY) System","Stony Brook University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3726-z","title":"Key-Policy Attribute-Based Encryption Based on SM9","authors":[{"last":"Liu","first":"Xiao-Hong"},{"last":"Huang","first":"Xin-Yi"},{"last":"Wu","first":"Wei"},{"last":"Ning","first":"Jian-Ting"}],"keywords":["key-policy attribute-based encryption","large universe","SM9","selective-set model"],"abstract":"Attribute-based encryption (ABE) is a type of encryption derived from identity-based encryption, implementing access control over encrypted data based on attributes rather than on specific identities. SM9 is the Chinese national standard for identity-based cryptography. This paper presents two novel key-policy attribute-based encryption (KP-ABE) designs based on SM9. The first scheme operates in a small attribute universe, while the second scheme caters to a large universe where the size of public parameters is only proportional to the maximum number of attributes used for encryption. Both schemes have a similar private-key/ciphertext structure to the original SM9 identity-based encryption algorithm, enabling effective integration into information systems built on SM9. Further, both schemes are selectively secure under the (f, g)-GDDHE assumption. Extensive experiments show that both schemes are comparable to other classical KP-ABE schemes, in terms of the communication and computational costs. We believe the proposed schemes will expedite the implementation of SM9 in distributed computing systems such as cloud computing and blockchain.","volume":40,"issue":1,"firstpage":267,"lastpage":282,"year":2025,"type":"Regular Paper","research_area":["Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3726-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3726-z?year=2025&issue=1","affiliations":["Fujian Normal University","Yuncheng University","Hong Kong University of Science & Technology (Guangzhou)"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2583-5","title":"Inductive Lottery Ticket Learning for Graph Neural Networks","authors":[{"last":"Sui","first":"Yong-Duo"},{"last":"Wang","first":"Xiang"},{"last":"Chen","first":"Tianlong"},{"last":"Wang","first":"Meng"},{"last":"He","first":"Xiang-Nan"},{"last":"Chua","first":"Tat-Seng"}],"keywords":["lottery ticket hypothesis","graph neural networks","neural network pruning"],"abstract":"Graph neural networks (GNNs) have gained increasing popularity, while usually suffering from unaffordable computations for real-world large-scale applications. Hence, pruning GNNs is of great need but largely unexplored. The recent work Unified GNN Sparsification (UGS) studies lottery ticket learning for GNNs, aiming to find a subset of model parameters and graph structures that can best maintain the GNN performance. However, it is tailed for the transductive setting, failing to generalize to unseen graphs, which are common in inductive tasks like graph classification. In this work, we propose a simple and effective learning paradigm, Inductive Co-Pruning of GNNs (ICPG), to endow graph lottery tickets with inductive pruning capacity. To prune the input graphs, we design a predictive model to generate importance scores for each edge based on the input. To prune the model parameters, it views the weight's magnitude as their importance scores. Then we design an iterative co-pruning strategy to trim the graph edges and GNN weights based on their importance scores. Although it might be strikingly simple, ICPG surpasses the existing pruning method and can be universally applicable in both inductive and transductive learning settings. On 10 graph-classification and two node-classification benchmarks, ICPG achieves the same performance level with 14.26%-43.12% sparsity for graphs and 48.80%-91.41% sparsity for the GNN model.","volume":39,"issue":6,"firstpage":1223,"lastpage":1237,"year":2024,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2583-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2583-5?year=2024&issue=6","affiliations":["Chinese Academy of Sciences","University of Science & Technology of China, CAS","University of Texas System","University of Texas Austin"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2386-8","title":"Fine-Tuning Channel-Pruned Deep Model via Knowledge Distillation","authors":[{"last":"Zhang","first":"Chong"},{"last":"Wang","first":"Hong-Zhi"},{"last":"Liu","first":"Hong-Wei"},{"last":"Chen","first":"Yi-Lin"}],"keywords":["model compression","deep learning","knowledge distillation","fine-tuning"],"abstract":"Deep convolutional neural networks with high performance are hard to be deployed in many real world applications, since the computing resources of edge devices such as smart phones or embedded GPU are limited. To alleviate this hardware limitation, the compression of deep neural networks from the model side becomes important. As one of the most popular methods in the spotlight, channel pruning of the deep convolutional model can effectively remove redundant convolutional channels from the CNN (convolutional neural network) without affecting the network's performance remarkably. Existing methods focus on pruning design, evaluating the importance of different convolutional filters in the CNN model. A fast and effective fine-tuning method to restore accuracy is urgently needed. In this paper, we propose a fine-tuning method KDFT (Knowledge Distillation Based Fine-Tuning), which improves the accuracy of fine-tuned models with almost negligible training overhead by introducing knowledge distillation. Extensive experimental results on benchmark datasets with representative CNN models show that up to 4.86% accuracy improvement and 79% time saving can be obtained.","volume":39,"issue":6,"firstpage":1238,"lastpage":1247,"year":2024,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Fine-Tuning & Model Adaptation","Knowledge Distillation"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2386-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2386-8?year=2024&issue=6","affiliations":["Harbin Institute of Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2655-1","title":"Document-Level Event Factuality Identification via Reinforced Semantic Learning Network","authors":[{"last":"Qian","first":"Zhong"},{"last":"Li","first":"Pei-Feng"},{"last":"Zhu","first":"Qiao-Ming"},{"last":"Zhou","first":"Guo-Dong"}],"keywords":["document-level event factuality identification","hierarchical reinforcement learning","attention network","multi-granularity encoding"],"abstract":"This paper focuses on document-level event factuality identification (DEFI), which predicts the factual nature of an event from the view of a document. As the document-level sub-task of event factuality identification (EFI), DEFI is a challenging and fundamental task in natural language processing (NLP). Currently, most existing studies focus on sentence-level event factuality identification (SEFI). However, DEFI is still in the early stage and related studies are quite limited. Previous work is heavily dependent on various NLP tools and annotated information, e.g., dependency trees, event triggers, speculative and negative cues, and does not consider filtering irrelevant and noisy texts that can lead to wrong results. To address these issues, this paper proposes a reinforced multi-granularity hierarchical network model: Reinforced Semantic Learning Network (RSLN), which means it can learn semantics from sentences and tokens at various levels of granularity and hierarchy. Since integrated with hierarchical reinforcement learning (HRL), the RSLN model is able to select relevant and meaningful sentences and tokens. Then, RSLN encodes the event and document according to these selected texts. To evaluate our model, based on the DLEF (Document-Level Event Factuality) corpus, we annotate the ExDLEF corpus as the benchmark dataset. Experimental results show that the RSLN model outperforms several state-of-the-arts.","volume":39,"issue":6,"firstpage":1248,"lastpage":1268,"year":2024,"type":"Regular Paper","research_area":["Reinforcement Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2655-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2655-1?year=2024&issue=6","affiliations":["Soochow University - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2638-7","title":"Adversarial Graph Convolutional Network for Skeleton-Based Early Action Prediction","authors":[{"last":"Li","first":"Xian-Shan"},{"last":"Zhang","first":"Neng"},{"last":"Cai","first":"Bin-Quan"},{"last":"Kang","first":"Jing-Wen"},{"last":"Zhao","first":"Feng-Da"}],"keywords":["graph convolutional network","adversarial learning","skeleton-based action prediction"],"abstract":"This paper proposes a novel method for early action prediction based on 3D skeleton data. Our method combines the advantages of graph convolutional networks (GCNs) and adversarial learning to avoid the problems of insufficient spatio-temporal feature extraction and difficulty in predicting actions in the early execution stage of actions. In our method, GCNs, which have outstanding performance in the field of action recognition, are used to extract the spatio-temporal features of the skeleton. The model learns how to optimize the feature distribution of partial videos from the features of full videos through adversarial learning. Experiments on two challenging action prediction datasets show that our method performs well on skeleton-based early action prediction. State-of-the-art performance is reported in some observation ratios.","volume":39,"issue":6,"firstpage":1269,"lastpage":1280,"year":2024,"type":"Regular Paper","research_area":["Computer Vision","Graph Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2638-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2638-7?year=2024&issue=6","affiliations":["Yanshan University","Xinjiang University of Science and Technology"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-024-3142-4","title":"Unsupervised Reconstruction for Gradient-Domain Rendering with Illumination Separation","authors":[{"last":"Ma","first":"Ming-Cong"},{"last":"Wang","first":"Lu"},{"last":"Xu","first":"Yan-Ning"},{"last":"Meng","first":"Xiang-Xu"}],"keywords":["gradient-domain rendering","unsupervised network","deep learning"],"abstract":"Gradient-domain rendering methods can render higher-quality images at the same time cost compared with traditional ray tracing rendering methods, and, combined with the neural network, achieve better rendering quality than conventional screened Poisson reconstruction. However, it is still challenging for these methods to keep detailed information, especially in areas with complex indirect illumination and shadows. We propose an unsupervised reconstruction method that separates the direct rendering from the indirect, and feeds them into our unsupervised network with some corresponding auxiliary channels as two separated tasks. In addition, we introduce attention modules into our network which can further improve details. We finally combine the results of the direct and indirect illumination tasks to form the rendering results. Experiments show that our method significantly improves image quality details, especially in scenes with complex conditions.","volume":39,"issue":6,"firstpage":1281,"lastpage":1291,"year":2024,"type":"Regular Paper","research_area":["Computer Graphics & Visualization","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3142-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3142-4?year=2024&issue=6","affiliations":["Shandong University"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2703-2","title":"Qualitative and Quantitative Model Checking Against Recurrent Neural Networks","authors":[{"last":"Liang","first":"Zhen"},{"last":"Liu","first":"Wan-Wei"},{"last":"Song","first":"Fu"},{"last":"Xue","first":"Bai"},{"last":"Yang","first":"Wen-Jing"},{"last":"Wang","first":"Ji"},{"last":"Pang","first":"Zheng-Bin"}],"keywords":["recurrent neural network","model checking","temporal logic","qualitative/quantitative verification"],"abstract":"Recurrent neural networks (RNNs) have been heavily used in applications relying on sequence data such as time series and natural languages. As a matter of fact, their behaviors lack rigorous quality assurance due to the black-box nature of deep learning. It is an urgent and challenging task to formally reason about the behaviors of RNNs. To this end, we first present an extension of linear-time temporal logic to reason about properties with respect to RNNs, such as local robustness, reachability, and some temporal properties. Based on the proposed logic, we formalize the verification obligation as a Hoare-like triple, from both qualitative and quantitative perspectives. The former concerns whether all the outputs resulting from the inputs fulfilling the pre-condition satisfy the post-condition, whereas the latter is to compute the probability that the post-condition is satisfied on the premise that the inputs fulfill the pre-condition. To tackle these problems, we develop a systematic verification framework, mainly based on polyhedron propagation, dimension-preserving abstraction, and the Monte Carlo sampling. We also implement our algorithm with a prototype tool and conduct experiments to demonstrate its feasibility and efficiency.","volume":39,"issue":6,"firstpage":1292,"lastpage":1311,"year":2024,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Formal Methods & Verification"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2703-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2703-2?year=2024&issue=6","affiliations":["National University of Defense Technology - China","ShanghaiTech University","Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2726-3","title":"A Pattern Matching Based Framework for Quantum Circuit Rewriting","authors":[{"last":"Jiang","first":"Hui"},{"last":"Li","first":"Dian-Kang"},{"last":"Deng","first":"Yu-Xin"},{"last":"Xu","first":"Ming"}],"keywords":["pattern matching","quantum circuit rewriting","subsequence"],"abstract":"The realization of quantum algorithms relies on specific quantum compilations according to the underlying quantum processors. However, there are various ways to physically implement qubits and manipulate those qubits in different physical devices. These differences lead to different communication methods and connection topologies, with each vendor implementing its own set of primitive gates. Therefore, quantum circuits have to be rewritten or transformed in order to be transplanted from one platform to another. We propose a pattern matching based framework for rewriting quantum circuits, called QRewriting. It takes advantage of a new representation of quantum circuits using symbolic sequences. Unlike the traditional approach using directed acyclic graphs, the new representation allows us to easily identify the patterns that appear non-consecutively but are reducible. Then, we convert the problem of pattern matching into that of finding distinct subsequences and propose a polynomial-time dynamic programming based pattern matching and replacement algorithm. We develop a rule library for basic optimizations and rewrite the arithmetic and Toffoli circuits from a commonly used gate set to the gate set supported by the Surface-17 quantum processor. Compared with a state-of-the-art quantum circuit optimization framework PaF optimized on the BIGD benchmarks, QRewriting further reduces the depth and the gate count by an average of 26.5% and 17.4%, respectively.","volume":39,"issue":6,"firstpage":1312,"lastpage":1327,"year":2024,"type":"Regular Paper","research_area":["Quantum Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2726-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2726-3?year=2024&issue=6","affiliations":["East China Normal University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2850-0","title":"Heuristic Search with Cut Point Based Strategy for Critical Node Problem","authors":[{"last":"Chen","first":"Zhi-Han"},{"last":"Cai","first":"Shao-Wei"},{"last":"Gao","first":"Jian"},{"last":"Ge","first":"Shi-Ke"},{"last":"Liu","first":"Chan-Juan"},{"last":"Lin","first":"Jin-Kun"}],"keywords":["local search","cut point","heuristic search","critical node problem"],"abstract":"The critical node problem (CNP) aims to deal with critical node identification in a graph, which has extensive applications in many fields. Solving CNP is a challenging task due to its computational complexity, and it attracts much attention from both academia and industry. In this paper, we propose a population-based heuristic search algorithm called CPHS (Cut Point Based Heuristic Search) to solve CNP, which integrates two main ideas. The first one is a cut point based greedy strategy in the local search, and the second one involves the functions used to update the solution pool of the algorithm. Besides, a mutation strategy is applied to solutions with probability based on the overall average similarity to maintain the diversity of the solution pool. Experiments are performed on a synthetic benchmark, a real-world benchmark, and a large-scale network benchmark to evaluate our algorithm. Compared with state-of-the-art algorithms, our algorithm has better performance in terms of both solution quality and run time on all the three benchmarks.","volume":39,"issue":6,"firstpage":1328,"lastpage":1340,"year":2024,"type":"Regular Paper","research_area":["Graph Theory & Algorithms","Optimization & Heuristic Methods"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2850-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2850-0?year=2024&issue=6","affiliations":["Chinese Academy of Sciences","University of Chinese Academy of Sciences, CAS","Nanjing Institute of Geology & Paleontology, CAS","Institute of Software, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2561-y","title":"P3DC: Reducing DRAM Cache Hit Latency by Hybrid Mappings","authors":[{"last":"Chi","first":"Ye"},{"last":"Guo","first":"Ren-Tong"},{"last":"Liao","first":"Xiao-Fei"},{"last":"Liu","first":"Hai-Kun"},{"last":"Yue","first":"Jianhui"}],"keywords":["die-stacked dynamic random access memory (DRAM)","cache","set-associative","direct-mapped","hit latency"],"abstract":"Die-stacked dynamic random access memory (DRAM) caches are increasingly advocated to bridge the performance gap between the on-chip cache and the main memory. To fully realize their potential, it is essential to improve DRAM cache hit rate and lower its cache hit latency. In order to take advantage of the high hit-rate of set-association and the low hit latency of direct-mapping at the same time, we propose a partial direct-mapped die-stacked DRAM cache called P3DC. This design is motivated by a key observation, i.e., applying a unified mapping policy to different types of blocks cannot achieve a high cache hit rate and low hit latency simultaneously. To address this problem, P3DC classifies data blocks into leading blocks and following blocks, and places them at static positions and dynamic positions, respectively, in a unified set-associative structure. We also propose a replacement policy to balance the miss penalty and the temporal locality of different blocks. In addition, P3DC provides a policy to mitigate cache thrashing due to block type variations. Experimental results demonstrate that P3DC can reduce the cache hit latency by 20.5% while achieving a similar cache hit rate compared with typical set-associative caches. P3DC improves the instructions per cycle (IPC) by up to 66% (12% on average) compared with the state-of-the-art direct-mapped cache-BEAR, and by up to 19% (6% on average) compared with the tag-data decoupled set-associative cache-DEC-A8.","volume":39,"issue":6,"firstpage":1341,"lastpage":1360,"year":2024,"type":"Regular Paper","research_area":["Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2561-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2561-y?year=2024&issue=6","affiliations":["Huazhong University of Science & Technology","Shenzhen Technology University","Michigan Technological University"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2646-7","title":"An Enhanced Physical-Locality Deduplication System for Space Efficiency","authors":[{"last":"Li","first":"Peng-Fei"},{"last":"Hua","first":"Yu"},{"last":"Cao","first":"Qin"}],"keywords":["deduplication system","data reduction","space efficiency","physical-locality"],"abstract":"An abundance of data have been generated from various embedded devices, applications, and systems, and require cost-efficient storage services. Data deduplication removes duplicate chunks and becomes an important technique for storage systems to improve space efficiency. However, stored unique chunks are heavily fragmented, decreasing restore performance and incurs high overheads for garbage collection. Existing schemes fail to achieve an efficient trade-off among deduplication, restore and garbage collection performance, due to failing to explore and exploit the physical locality of different chunks. In this paper, we trace the storage patterns of the fragmented chunks in backup systems, and propose a high-performance deduplication system, called HiDeStore. The main insight is to enhance the physical-locality for the new backup versions during the deduplication phase, which identifies and stores hot chunks in the active containers. The chunks not appearing in new backups become cold and are gathered together in the archival containers. Moreover, we remove the expired data with an isolated container deletion scheme, avoiding the high overheads for expired data detection. Compared with state-of-the-art schemes, HiDeStore improves the deduplication and restore performance by up to 1.4x and 1.6x, respectively, without decreasing the deduplication ratios and incurring high garbage collection overheads.","volume":39,"issue":6,"firstpage":1361,"lastpage":1379,"year":2024,"type":"Regular Paper","research_area":["Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2646-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2646-7?year=2024&issue=6","affiliations":["Huazhong University of Science & Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2635-5","title":"Personalized Privacy-Preserving Routing Mechanism Design in Payment Channel Network","authors":[{"last":"Zhao","first":"Peng-Cheng"},{"last":"Xu","first":"Li-Jie"},{"last":"Xu","first":"Jia"}],"keywords":["blockchain","payment channel network","routing mechanism","differential privacy","personalized privacy-preserving"],"abstract":"Payment Channel Network (PCN) provides the off-chain settlement of transactions. It is one of the most promising solutions to solve the scalability issue of the blockchain. Many routing techniques in PCN have been proposed. However, both incentive attack and privacy protection have not been considered in existing studies. In this paper, we present an auction-based system model for PCN routing using the Laplace differential privacy mechanism. We formulate the cost optimization problem to minimize the path cost under the constraints of the Hashed Time-Lock Contract (HTLC) tolerance and the channel capacity. We propose an approximation algorithm to find the top K\\documentclass[12pt]{minimal} \\usepackage{amsmath} \\usepackage{wasysym} \\usepackage{amsfonts} \\usepackage{amssymb} \\usepackage{amsbsy} \\usepackage{mathrsfs} \\usepackage{upgreek} \\setlength{\\oddsidemargin}{-69pt} \\begin{document}$$\\cal{K}$$\\end{document} shortest paths constrained by the HTLC tolerance and the channel capacity, i.e., top K\\documentclass[12pt]{minimal} \\usepackage{amsmath} \\usepackage{wasysym} \\usepackage{amsfonts} \\usepackage{amssymb} \\usepackage{amsbsy} \\usepackage{mathrsfs} \\usepackage{upgreek} \\setlength{\\oddsidemargin}{-69pt} \\begin{document}$$\\cal{K}$$\\end{document}-restricted shortest paths. Besides, we design the probability comparison function to find the path with the largest probability of having the lowest path cost among the top K\\documentclass[12pt]{minimal} \\usepackage{amsmath} \\usepackage{wasysym} \\usepackage{amsfonts} \\usepackage{amssymb} \\usepackage{amsbsy} \\usepackage{mathrsfs} \\usepackage{upgreek} \\setlength{\\oddsidemargin}{-69pt} \\begin{document}$$\\cal{K}$$\\end{document}-restricted shortest paths as the final path. Moreover, we apply the binary search to calculate the transaction fee of each user. Through both theoretical analysis and extensive simulations, we demonstrate that the proposed routing mechanism can guarantee the truthfulness and individual rationality with the probabilities of 1/2 and 1/4, respectively. It can also ensure the differential privacy of the users. The experiments on the real-world datasets demonstrate that the privacy leakage of the proposed mechanism is 73.21% lower than that of the unified privacy protection mechanism with only 13.2% more path cost compared with the algorithm without privacy protection on average.","volume":39,"issue":6,"firstpage":1380,"lastpage":1400,"year":2024,"type":"Regular Paper","research_area":["Blockchain & Distributed Ledger","Network Protocols & Measurement","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2635-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2635-5?year=2024&issue=6","affiliations":["Nanjing University of Posts & Telecommunications"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3020-0","title":"UAV Localization with Unreliable Observations in Hostile Underground Environments","authors":[{"last":"Chen","first":"Peng-Peng"},{"last":"Zhang","first":"Kui-Yuan"},{"last":"Gao","first":"Shou-Wan"},{"last":"Ren","first":"Si-Yi"}],"keywords":["unmanned aerial vehicle (UAV) localization","Kalman filter","ultra-wideband (UWB) observation","hostile underground environment"],"abstract":"The accurate and robust unmanned aerial vehicle (UAV) localization is significant due to the requirements of safety-critical monitoring and emergency wireless communication in hostile underground environments. Existing range-based localization approaches fundamentally rely on the assumption that the environment is relatively ideal, which enables a precise range for localization. However, radio propagation in the underground environments may be dramatically influenced by various equipments, obstacles, and ambient noises. In this case, inaccurate range measurements and intermittent ranging failures inevitably occur, which leads to severe localization performance degradation. To address the challenges, a novel UAV localization scheme is proposed in this paper, which can effectively handle unreliable observations in hostile underground environments. We first propose an adaptive extended Kalman filter (EKF) based on the fusion of ultra-wideband (UWB) and inertial measurement unit (IMU) to detect and adjust the inaccurate range measurements. Aiming to deal with intermittent ranging failures, we further design the constraint condition by limiting the system state. Specifically, the auto-regressive model is proposed to implement the localization in the ranging blind areas by reconstructing the lost measurements. Finally, extensive simulations have been conducted to verify the effectiveness. We carry out field experiments in an underground garage and a coal mine based on P440 UWB sensors. Results show that the localization accuracy is improved by 16.9% compared with the recent methods in the hostile underground environments.","volume":39,"issue":6,"firstpage":1401,"lastpage":1418,"year":2024,"type":"Regular Paper","research_area":["Robotics & Control"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3020-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3020-0?year=2024&issue=6","affiliations":["China University of Mining & Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2608-0","title":"Spatio-Temporal Location Recommendation for Urban Facility Placement via Graph Convolutional and Recurrent Networks","authors":[{"last":"Wang","first":"Pu"},{"last":"Lu","first":"Jian-Jiang"},{"last":"Chen","first":"Wei"},{"last":"Zhao","first":"Peng-Peng"},{"last":"Zhao","first":"Lei"}],"keywords":["location recommendation","popularity prediction","spatio-temporal correlation","deep learning"],"abstract":"The ability to recommend candidate locations for service facility placement is crucial for the success of urban planning. Whether a location is suitable for establishing new facilities is largely determined by its potential popularity. However, it is a non-trivial task to predict popularity of candidate locations due to three significant challenges: 1) the spatio-temporal behavior correlations of urban dwellers, 2) the spatial correlations between candidate locations and existing facilities, and 3) the temporal auto-correlations of locations themselves. To this end, we propose a novel semi-supervised learning model, Spatio-Temporal Graph Convolutional and Recurrent Networks (STGCRN), aiming for popularity prediction and location recommendation. Specifically, we first partition the urban space into spatial neighborhood regions centered by locations, extract the corresponding features, and develop the location correlation graph. Next, a contextual graph convolution module based on the attention mechanism is introduced to incorporate local and global spatial correlations among locations. A recurrent neural network is proposed to capture temporal dependencies between locations. Furthermore, we adopt a location popularity approximation block to estimate the missing popularity from both the spatial and temporal domains. Finally, the overall implicit characteristics are concatenated and then fed into the recurrent neural network to obtain the ultimate popularity. The extensive experiments on two real-world datasets demonstrate the superiority of the proposed model compared with state-of-the-art baselines.","volume":39,"issue":6,"firstpage":1419,"lastpage":1440,"year":2024,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Recommendation Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2608-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2608-0?year=2024&issue=6","affiliations":["Soochow University"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-023-2418-4","title":"Indoor Uncertain Semantic Trajectory Similarity Join","authors":[{"last":"Yin","first":"Hong-Bo"},{"last":"Yang","first":"Dong-Hua"},{"last":"Zhang","first":"Kai-Qi"},{"last":"Gao","first":"Hong"},{"last":"Li","first":"Jian-Zhong"}],"keywords":["filtering-and-verification framework","indoor uncertain semantic trajectory","inverted index","trajectory similarity join"],"abstract":"With the widespread deployment of indoor positioning systems, an unprecedented scale of indoor trajectories is being produced. By considering the inherent uncertainties and the text information contained in such an indoor trajectory, a new definition named Indoor Uncertain Semantic Trajectory is defined in this paper. In this paper, we focus on a new primitive, yet quite essential query named Indoor Uncertain Semantic Trajectory Similarity Join (IUST-Join for short), which is to match all similar pairs of indoor uncertain semantic trajectories from two sets. IUST-Join targets a number of essential indoor applications. With these applications in mind, we provide a purposeful definition of an indoor uncertain semantic trajectory similarity metric named IUS. To process IUST-Join more efficiently, both an inverted index on indoor uncertain semantic trajectories named 3IST and the first acceleration strategy are proposed to form a filtering-and-verification framework, where most invalid pairs of indoor uncertain semantic trajectories are pruned at quite low computation cost. And based on this filtering-and-verification framework, we present a highly-efficient algorithm named Indoor Uncertain Semantic Trajectory Similarity Join Processing (USP for short). In addition, lots of novel and effective acceleration strategies are proposed and embedded in the USP algorithm. Thanks to these techniques, both the time complexity and the time overhead of the USP algorithm are further reduced. The results of extensive experiments demonstrate the superior performance of the proposed work.","volume":39,"issue":6,"firstpage":1441,"lastpage":1465,"year":2024,"type":"Regular Paper","research_area":["Databases & Query Processing","Trajectory & Spatial Data"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2418-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2418-4?year=2024&issue=6","affiliations":["Harbin Institute of Technology","Chinese Academy of Sciences"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2874-5","title":"Generation of Escher-Like Rosette Drawings","authors":[{"last":"Ouyang","first":"Pei-Chang"},{"last":"Chung","first":"Kwok-Wai"},{"last":"Fathauer","first":"Robert W."},{"last":"Nicolas","first":"Alain"},{"last":"Pang","first":"Jian-Hua"},{"last":"Cao","first":"Shi-Yun"},{"last":"Gdawiec","first":"Krzysztof"}],"keywords":["color symmetry","Escher art","rosette tiling","spiral symmetry"],"abstract":"Smaller and Smaller is a woodcut by the Dutch artist M.C. Escher in which the lizards designed in a rosette tiling approach the centre by geometric series. This paper proposes an easy method to generate drawings similar to Smaller and Smaller. To this end, the geometrical structure of rosette tilings is first considered from the viewpoint of the symmetry group in detail. This gives a simple way to construct rosette tilings. Then, a one-to-one mapping between kite-shaped and square regions is presented to embed a pre-designed template into kite-shaped tiles of rosette tilings. Next, the algorithms for rendering the rosette tilings are discussed. Finally, some detailed implements of producing rosette drawings are specified. The presented examples show that by using the existing rich wallpaper templates, the method proposed in the paper can generate a variety of Escher-like rosette drawings.","volume":39,"issue":6,"firstpage":1466,"lastpage":1479,"year":2024,"type":"Regular Paper","research_area":["Computer Graphics & Visualization"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2874-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2874-5?year=2024&issue=6","affiliations":["Guangxi University of Science & Technology","City University of Hong Kong","University of Silesia in Katowice"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-0005-y","title":"openGauss: An Open-Source Database for the Era of Artificial Intelligence","authors":[{"last":"Li","first":"Jian-Zhong"}],"keywords":[],"abstract":"","volume":39,"issue":5,"firstpage":1005,"lastpage":1006,"year":2024,"type":"Perspective","research_area":["Databases & Query Processing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-0005-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-0005-y?year=2024&issue=5","affiliations":["Chinese Academy of Sciences","Shenzhen Institute of Advanced Technology, CAS","Harbin Institute of Technology"],"type_origin":"Article","cover_doi":"10.1007/s11390-024-4302-2","topic_source":"cover_inherited"},{"doi":"10.1007/s11390-024-4302-2","title":"openGauss: An Enterprise-Grade Open-Source Database System","authors":[{"last":"Li","first":"Guo-Liang"},{"last":"Wang","first":"Jiang"},{"last":"Chen","first":"Guo"}],"keywords":["database system","open-source","high performance","storage engine"],"abstract":"We have built openGauss, an enterprise-grade open-source database system. openGauss has fulfilled its design goal of high performance, high availability, high security, and high intelligence. For high performance, it leverages NUMA (non-uniform memory access)-aware data access among multiple cores to enable efficient concurrent transaction processing, and symmetric multi-processing to make use of parallel processing resources adaptively. Moreover, memory-optimized tables (MOTs) are designed to put everything in memory. For high availability, a three-tier pooling architecture that shares storage among the master and standby instances is proposed to achieve availability at 99.99%, containing both a distributed memory service (DMS) and a distributed storage service (DSS). For high security, it is a fully encrypted database with safe storage features, efficient complex querying, and tamper-proof. For high intelligence, an AI-based optimizer in the kernel and a self-driving platform named DBMind are demonstrated to achieve better performance and greater user-friendliness. openGauss has served over 150 enterprises and institutions since its release in 2020. We share the lessons we learned from its development and operation, and our customers.","volume":39,"issue":5,"firstpage":1007,"lastpage":1028,"year":2024,"type":"Regular Paper","research_area":["Databases & Query Processing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4302-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4302-2?year=2024&issue=5","affiliations":["Tsinghua University","Huawei Technologies"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3702-7","title":"Balancing Accuracy and Training Time in Federated Learning for Violence Detection in Surveillance Videos: A Study of Neural Network Architectures","authors":[{"last":"Pajon","first":"Quentin"},{"last":"Serre","first":"Swan"},{"last":"Wissocq","first":"Hugo"},{"last":"Rabaud","first":"Leo"},{"last":"Haidar","first":"Siba"},{"last":"Yaacoub","first":"Antoun"}],"keywords":["artificial intelligence","federated learning","neural network","violence detection","video analysis"],"abstract":"This paper presents an original investigation into the domain of violence detection in videos, introducing an innovative approach tailored to the unique challenges of a federated learning environment. The study encompasses a comprehensive exploration of machine learning techniques, leveraging spatio-temporal features extracted from benchmark video datasets. In a notable departure from conventional methodologies, we introduce a novel architecture, the Diff Gated network, designed to streamline preprocessing and training while simultaneously enhancing accuracy. Our exploration of advanced machine learning techniques, such as super-convergence and transfer learning, expands the horizons of federated learning, offering a broader range of practical applications. Moreover, our research introduces a method for seamlessly adapting centralized datasets to the federated learning context, bridging the gap between traditional machine learning and federated learning approaches. The outcome of this study is a remarkable advancement in the field of violence detection, with our federated learning model consistently outperforming state-of-the-art models, underscoring the transformative potential of our contributions. This work represents a significant step forward in the application of machine learning techniques to critical societal challenges.","volume":39,"issue":5,"firstpage":1029,"lastpage":1039,"year":2024,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Federated Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3702-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3702-7?year=2024&issue=5","affiliations":["Ecole Super Informat Elect Automat ESIEA"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3639-x","title":"FedBone: Towards Large-Scale Federated Multi-Task Learning","authors":[{"last":"Chen","first":"Yi-Qiang"},{"last":"Zhang","first":"Teng"},{"last":"Jiang","first":"Xin-Long"},{"last":"Chen","first":"Qian"},{"last":"Gao","first":"Chen-Long"},{"last":"Huang","first":"Wu-Liang"}],"keywords":["federated learning","multi-task learning","split learning","heterogeneous task"],"abstract":"Federated multi-task learning (FMTL) has emerged as a promising framework for learning multiple tasks simultaneously with client-aware personalized models. While the majority of studies have focused on dealing with the non-independent and identically distributed (Non-IID) characteristics of client datasets, the issue of task heterogeneity has largely been overlooked. Dealing with task heterogeneity often requires complex models, making it impractical for federated learning in resource-constrained environments. In addition, the varying nature of these heterogeneous tasks introduces inductive biases, leading to interference during aggregation and potentially resulting in biased global models. To address these issues, we propose a hierarchical FMTL framework, referred to as FedBone, to facilitate the construction of large-scale models with improved generalization. FedBone leverages server-client split learning and gradient projection to split the entire model into two components: 1) a large-scale general model (referred to as the general model) on the cloud server, and 2) multiple task-specific models (referred to as client models) on edge clients, accommodating devices with limited compute power. To enhance the robustness of the large-scale general model, we incorporate the conflicting gradient projection technique into FedBone to rectify the skewed gradient direction caused by aggregating gradients from heterogeneous tasks. The proposed FedBone framework is evaluated on three benchmark datasets and one real ophthalmic dataset. The comprehensive experiments demonstrate that FedBone efficiently adapts to the heterogeneous local tasks of each client and outperforms existing federated learning algorithms in various dense prediction and classification tasks while utilizing off-the-shelf computational resources on the client side.","volume":39,"issue":5,"firstpage":1040,"lastpage":1057,"year":2024,"type":"Regular Paper","research_area":["Federated Learning","Multi-Task & Transfer Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3639-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3639-x?year=2024&issue=5","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2863-8","title":"Meta-Learning Based Few-Shot Link Prediction for Emerging Knowledge Graph","authors":[{"last":"Zhang","first":"Yu-Feng"},{"last":"Chen","first":"Wei"},{"last":"Zhao","first":"Peng-Peng"},{"last":"Xu","first":"Jia-Jie"},{"last":"Fang","first":"Jun-Hua"},{"last":"Zhao","first":"Lei"}],"keywords":["knowledge graph","graph representation learning","few-shot learning","inductive link prediction"],"abstract":"Inductive knowledge graph embedding (KGE) aims to embed unseen entities in emerging knowledge graphs (KGs). The major recent studies of inductive KGE embed unseen entities by aggregating information from their neighboring entities and relations with graph neural networks (GNNs). However, these methods rely on the existing neighbors of unseen entities and suffer from two common problems: data sparsity and feature smoothing. Firstly, the data sparsity problem means unseen entities usually emerge with few triplets containing insufficient information. Secondly, the effectiveness of the features extracted from original KGs will degrade when repeatedly propagating these features to represent unseen entities in emerging KGs, which is termed feature smoothing problem. To tackle the two problems, we propose a novel model entitled Meta-Learning Based Memory Graph Convolutional Network (MMGCN) consisting of three different components: 1) the two-layer information transforming module (TITM) developed to effectively transform information from original KGs to emerging KGs; 2) the hyper-relation feature initializing module (HFIM) proposed to extract type-level features shared between KGs and obtain a coarse-grained representation for each entity with these features; and 3) the meta-learning training module (MTM) designed to simulate the few-shot emerging KGs and train the model in a meta-learning framework. The extensive experiments conducted on the few-shot link prediction task for emerging KGs demonstrate the superiority of our proposed model MMGCN compared with state-of-the-art methods.","volume":39,"issue":5,"firstpage":1058,"lastpage":1077,"year":2024,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Graph Neural Networks","Knowledge Graphs & Heterogeneous Information Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2863-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2863-8?year=2024&issue=5","affiliations":["Soochow University - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3515-8","title":"Combining Innovative CVTNet and Regularization Loss for Robust Adversarial Defense","authors":[{"last":"Wang","first":"Wei-Dong"},{"last":"Li","first":"Zhi"},{"last":"Zhang","first":"Li"}],"keywords":["deep learning","adversarial defense","vision transformer","image reconstruction"],"abstract":"Deep neural networks (DNNs) are vulnerable to elaborately crafted and imperceptible adversarial perturbations. With the continuous development of adversarial attack methods, existing defense algorithms can no longer defend against them proficiently. Meanwhile, numerous studies have shown that vision transformer (ViT) has stronger robustness and generalization performance than the convolutional neural network (CNN) in various domains. Moreover, because the standard denoiser is subject to the error amplification effect, the prediction network cannot correctly classify all reconstruction examples. Firstly, this paper proposes a defense network (CVTNet) that combines CNNs and ViTs that is appended in front of the prediction network. CVTNet can effectively eliminate adversarial perturbations and maintain high robustness. Furthermore, this paper proposes a regularization loss (LCPL\\documentclass[12pt]{minimal} \\usepackage{amsmath} \\usepackage{wasysym} \\usepackage{amsfonts} \\usepackage{amssymb} \\usepackage{amsbsy} \\usepackage{mathrsfs} \\usepackage{upgreek} \\setlength{\\oddsidemargin}{-69pt} \\begin{document}$$\\mathcal{L}_{\\text{CPL}}$$\\end{document}), which optimizes the CVTNet by computing different losses for the correct prediction set (CPS) and the wrong prediction set (WPS) of the reconstruction examples, respectively. The evaluation results on several standard benchmark datasets show that CVTNet performs better robustness than other advanced methods. Compared with state-of-the-art algorithms, the proposed CVTNet defense improves the average accuracy of pixel-constrained attack examples generated on the CIFAR-10 dataset by 24.25% and spatially-constrained attack examples by 14.06%. Moreover, CVTNet shows excellent generalizability in cross-model protection.","volume":39,"issue":5,"firstpage":1078,"lastpage":1093,"year":2024,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3515-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3515-8?year=2024&issue=5","affiliations":["Guizhou University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2264-z","title":"Sequential Cooperative Distillation for Imbalanced Multi-Task Learning","authors":[{"last":"Feng","first":"Quan"},{"last":"Yao","first":"Jia-Yu"},{"last":"Xie","first":"Ming-Kun"},{"last":"Huang","first":"Sheng-Jun"},{"last":"Chen","first":"Song-Can"}],"keywords":["multi-task learning (MIT)","imbalanced learning","similarity estimation","knowledge distillation","distillation queue"],"abstract":"Multi-task learning (MTL) can boost the performance of individual tasks by mutual learning among multiple related tasks. However, when these tasks assume diverse complexities, their corresponding losses involved in the MTL objective inevitably compete with each other and ultimately make the learning biased towards simple tasks rather than complex ones. To address this imbalanced learning problem, we propose a novel MTL method that can equip multiple existing deep MTL model architectures with a sequential cooperative distillation (SCD) module. Specifically, we first introduce an efficient mechanism to measure the similarity between tasks, and group similar tasks into the same block to allow their cooperative learning from each other. Based on this, the grouped task blocks are sorted in a queue to determine the learning sequence of the tasks according to their complexities estimated with the defined performance indicator. Finally, a distillation between the individual task-specific models and the MTL model is performed block by block from complex to simple manner, achieving a balance between competition and cooperation among learning multiple tasks. Extensive experiments demonstrate that our method is significantly more competitive compared with state-of-the-art methods, ranking No.1 with average performances across multiple datasets by improving 12.95% and 3.72% compared with OMTL and MTLKD, respectively.","volume":39,"issue":5,"firstpage":1094,"lastpage":1106,"year":2024,"type":"Regular Paper","research_area":["Knowledge Distillation","Multi-Task & Transfer Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2264-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2264-z?year=2024&issue=5","affiliations":["Nanjing University of Aeronautics & Astronautics"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2828-y","title":"Spatio-Temporal Learning for Route-Based Travel Time Estimation","authors":[{"last":"Fang","first":"Zi-Quan"},{"last":"Sun","first":"Qi-Chen"},{"last":"Chen","first":"Lu"},{"last":"Hu","first":"Dan-Lei"},{"last":"Gao","first":"Yun-Jun"}],"keywords":["heterogeneous traffic modeling","spatio-temporal learning","travel time estimation","traffic speed prediction"],"abstract":"Travel time estimation (TTE) is a fundamental task to build intelligent transportation systems. However, most existing TTE solutions design models upon simple homogeneous graphs and ignore the heterogeneity of traffic networks, where, e.g., main roads typically contribute differently from side roads. In terms of spatial dimension, few studies consider the dynamic spatial correlations across road segments, e.g., the traffic speed/volume on road segment A may correlate with the traffic speed/volume on road segment B, where A and B could be adjacent or non-adjacent, and such correlations may vary across time. In terms of temporal dimension, even fewer studies consider the dynamic temporal dependences, where, e.g., the historical states of road A may directly correlate with the recent state of A, and may also indirectly correlate with the recent state of road B. To track all aforementioned issues of existing TTE approaches, we provide HDTTE, a solution that employs heterogeneous and dynamic spatio-temporal predictive learning. Specifically, we first design a general multi-relational graph constructor that extracts hidden heterogeneous information of road segments, where we model road segments as nodes and model correlations as edges in the multi-relational graph. Next, we propose a dynamic graph attention convolution module that aggregates dynamic spatial dependence of neighbor roads to focal roads. We also present a novel correlation-augmented temporal convolution module to capture the influence of states at past time steps on current traffic states. Finally, in view of the periodic dependence of traffic, we develop a multi-scale adaptive fusion layer to enable HDTTE to exploit periodic patterns from recent, daily, and weekly traffic states. An experimental study using real-life highway and urban datasets demonstrates the validity of the approach and its advantage over others.","volume":39,"issue":5,"firstpage":1107,"lastpage":1122,"year":2024,"type":"Regular Paper","research_area":["Trajectory & Spatial Data"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2828-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2828-y?year=2024&issue=5","affiliations":["Zhejiang University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-4069-5","title":"Enhancing Recommendation with Denoising Auxiliary Task","authors":[{"last":"Liu","first":"Peng-Sheng"},{"last":"Zheng","first":"Li-Nan"},{"last":"Chen","first":"Jia-Le"},{"last":"Zhang","first":"Guang-Fa"},{"last":"Xu","first":"Yang"},{"last":"Fang","first":"Jin-Yun"}],"keywords":["auxiliary task learning","recommender system","sequence denoising"],"abstract":"The historical interaction sequences of users play a crucial role in training recommender systems that can accurately predict user preferences. However, due to the arbitrariness of user behaviors, the presence of noise in these sequences poses a challenge to predicting their next actions in recommender systems. To address this issue, our motivation is based on the observation that training noisy sequences and clean sequences (sequences without noise) with equal weights can impact the performance of the model. We propose the novel self-supervised Auxiliary Task Joint Training (ATJT) method aimed at more accurately reweighting noisy sequences in recommender systems. Specifically, we strategically select subsets from users' original sequences and perform random replacements to generate artificially replaced noisy sequences. Subsequently, we perform joint training on these artificially replaced noisy sequences and the original sequences. Through effective reweighting, we incorporate the training results of the noise recognition model into the recommender model. We evaluate our method on three datasets using a consistent base model. Experimental results demonstrate the effectiveness of introducing the self-supervised auxiliary task to enhance the base model's performance.","volume":39,"issue":5,"firstpage":1123,"lastpage":1137,"year":2024,"type":"Regular Paper","research_area":["Recommendation Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4069-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4069-5?year=2024&issue=5","affiliations":["Guizhou University","Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3522-9","title":"Intent-Aware Graph-Level Embedding Learning Based Recommendation","authors":[{"last":"Hao","first":"Peng-Yi"},{"last":"Liu","first":"Si-Hao"},{"last":"Bai","first":"Cong"}],"keywords":["recommendation system","graph embedding learning","graph neural network","intent-aware"],"abstract":"Recommendation has been widely used in business scenarios to provide users with personalized and accurate item lists by efficiently analyzing complex user-item interactions. However, existing recommendation methods have significant shortcomings in capturing the dynamic preference changes of users and discovering their true potential intents. To address these problems, a novel framework named Intent-Aware Graph-Level Embedding Learning (IaGEL) is proposed for recommendation. In this framework, the potential user interest is explored by capturing the co-occurrence of items in different periods, and then user interest is further improved based on an adaptive aggregation algorithm, forming generic intents and specific intents. In addition, for better representing the intents, graph-level embedding learning is designed based on the mutual information comparison among positive intents and negative intents. Finally, an intent-based recommendation strategy is designed to further mine the dynamic changes in user preferences. Experiments on three public and industrial datasets demonstrate the effectiveness of the proposed IaGEL in the task of recommendation.","volume":39,"issue":5,"firstpage":1138,"lastpage":1152,"year":2024,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Graph Neural Networks","Recommendation Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3522-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3522-9?year=2024&issue=5","affiliations":["Zhejiang University of Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2403-y","title":"Combining KNN with AutoEncoder for Outlier Detection","authors":[{"last":"Liu","first":"Shu-Zheng"},{"last":"Ma","first":"Shuai"},{"last":"Chen","first":"Han-Qing"},{"last":"Cui","first":"Li-Zhen"},{"last":"Ding","first":"Jie"}],"keywords":["outlier detection","AutoEncoder","K-nearest neighbor (KNN)","unsupervised learning"],"abstract":"K-nearest neighbor (KNN) is one of the most fundamental methods for unsupervised outlier detection because of its various advantages, e.g., ease of use and relatively high accuracy. Currently, most data analytic tasks need to deal with high-dimensional data, and the KNN-based methods often fail due to the curse of dimensionality. AutoEncoder-based methods have recently been introduced to use reconstruction errors for outlier detection on high-dimensional data, but the direct use of AutoEncoder typically does not preserve the data proximity relationships well for outlier detection. In this study, we propose to combine KNN with AutoEncoder for outlier detection. First, we propose the Nearest Neighbor AutoEncoder (NNAE) by persevering the original data proximity in a much lower dimension that is more suitable for performing KNN. Second, we propose the K-nearest reconstruction neighbors (KNRNs) by incorporating the reconstruction errors of NNAE with the K-distances of KNN to detect outliers. Third, we develop a method to automatically choose better parameters for optimizing the structure of NNAE. Finally, using five real-world datasets, we experimentally show that our proposed approach NNAE+KNRN is much better than existing methods, i.e., KNN, Isolation Forest, a traditional AutoEncoder using reconstruction errors (AutoEncoder-RE), and Robust AutoEncoder.","volume":39,"issue":5,"firstpage":1153,"lastpage":1166,"year":2024,"type":"Regular Paper","research_area":["Data Mining & Analytics","Contrastive & Self-Supervised Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2403-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2403-y?year=2024&issue=5","affiliations":["Beihang University","Shandong University","Jiangsu University of Science & Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3521-x","title":"Point-Voxel Based Geometry-Adaptive Network for 3D Point Cloud Analysis","authors":[{"last":"Zhao","first":"Tian-Meng"},{"last":"Zeng","first":"Hui"},{"last":"Zhang","first":"Bao-Qing"},{"last":"Liu","first":"Hong-Min"},{"last":"Fan","first":"Bin"}],"keywords":["point cloud","geometric feature","multi-representation","part segmentation","shape classification"],"abstract":"Point cloud analysis is challenging because of the unordered and irregular data structure of point clouds. To describe geometric information in point clouds, existing methods mainly use convolution, graph, and attention operations to construct sophisticated local aggregation operators. These operators work well in extracting local information but bring unfavorable inference latency due to high computation complexity. To solve the above problem, this paper presents a novel point-voxel based geometry-adaptive network (PVGANet), which combines multiple representations of point and voxel to describe the point cloud from different granularities and can obtain features of different scales effectively. To extract fine-grained geometric features, we design the position-adaptive pooling operator, which uses point pairs' relative position and feature similarity to weight and aggregate the point features at local areas of point clouds. To extract coarse-grained local features, we design a depth-wise convolution operator, which conducts the depth-wise convolution on voxel grids. With an easy addition, fine-grained geometric and coarse-grained local features can be fused, and we can use the geometry-adaptive fused features to complete the efficient shape analysis of point clouds, such as shape classification and part segmentation. Extensive experiments on ModelNet40, ScanObjectNN, and ShapeNet Part benchmarks demonstrate that our PVGANet achieves competitive performance compared with the related methods.","volume":39,"issue":5,"firstpage":1167,"lastpage":1179,"year":2024,"type":"Regular Paper","research_area":["Point Cloud & 3D Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3521-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3521-x?year=2024&issue=5","affiliations":["University of Science & Technology Beijing","University Of Science & Technology Beijing"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-2194-6","title":"ScenePalette: Contextually Exploring Object Collections Through Multiplex Relations in 3D Scenes","authors":[{"last":"Zhang","first":"Shao-Kui"},{"last":"Xie","first":"Wei-Yu"},{"last":"Wang","first":"Chen"},{"last":"Zhang","first":"Song-Hai"}],"keywords":["computer graphics","3D scene context","3D repository exploration","multiplex network embedding"],"abstract":"This paper presents ScenePalette, a modeling tool that allows users to draw 3D scenes interactively by placing objects on a canvas based on their contextual relationship. ScenePalette is inspired by an important intuition which was often ignored in previous work: a real-world 3D scene consists of the contextually reasonable organization of objects, e.g. people typically place one double bed with several subordinate objects into a bedroom instead of different shapes of beds. ScenePalette, abstracts 3D repositories as multiplex networks and accordingly encodes implicit relations between or among objects. Specifically, basic statistics such as co-occurrence, in combination with advanced relations, are used to tackle object relationships of different levels. Extensive experiments demonstrate that the latent space of ScenePalette has rich contexts that are essential for contextual representation and exploration.","volume":39,"issue":5,"firstpage":1180,"lastpage":1192,"year":2024,"type":"Regular Paper","research_area":["Computer Graphics & Visualization"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-2194-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-2194-6?year=2024&issue=5","affiliations":["Tsinghua University"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-2188-4","title":"New Proper Reparameterization of Plane Rational Bézier Curves","authors":[{"last":"Wang","first":"Zhen-Fei"},{"last":"Chen","first":"Xiao-Diao"},{"last":"Yong","first":"Jun-Hai"}],"keywords":["rational Bézier curve","coincidence condition","control polygon","degeneration","proper reparameterization"],"abstract":"Coincidence detection of two curves or two surfaces has wide application in computer-aided design (CAD) and computer-aided geometric design (CAGD). Proper reparameterization is the most complicated part in the detection. This paper presents and proves the efficient and necessary coincidence condition for two rational B & eacute;zier curves in a new way. It also proposes an effective and efficient proper reparameterization method, Algorithm 1, for detecting a rational B & eacute;zier curve which can be degenerated into a new one of a lower degree. A numerical proper reparameterization method, Algorithm 2, and examples are also presented. Algorithm 1 is up to ten times faster than other prevailing methods, and Algorithm 2 is twice as fast and half as close as other prevailing methods. New CAD systems using Algorithm 1 and Algorithm 2 will hold accuracy and little computation time.","volume":39,"issue":5,"firstpage":1193,"lastpage":1206,"year":2024,"type":"Regular Paper","research_area":["Computer Graphics & Visualization"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-2188-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-2188-4?year=2024&issue=5","affiliations":["Hangzhou Dianzi University","Tsinghua University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2732-5","title":"The t/s-Diagnosability and Diagnostic Strategy of Balanced Hypercube Under Two Classic Diagnostic Models","authors":[{"last":"Liu","first":"Xiao-Qing"},{"last":"Zhou","first":"Shu-Ming"},{"last":"Cheng","first":"Eddie"},{"last":"Zhang","first":"Hong"}],"keywords":["fault diagnosis","t/s-diagnosability","t/s-diagnosis algorithm","balanced hypercube"],"abstract":"Fault diagnosis plays a crucial role in the fault tolerability assessment of an interconnection network, which is of great value in the design and maintenance of large-scale multiprocessor systems. A t/s-diagnostic strategy, as the generalization of the t/t-diagnostic strategy, refers to the self-diagnosis of a multiprocessor system in which all faulty vertices can be identified in a set of size at most s in the presence of at most t faulty vertices. In this work, we show that the balanced hypercube BHn (n >= 4) is ((2n + 1) (sic)g/2(sic) - (sic)g/2(sic)2)/((2n + 1) (sic)g/2(sic) - (sic)g/2(sic)2 + (g - 2))-diagnosable under both the Preparata, Metze, and Chien (PMC) and MM* models for 4 <= (sic)g/2(sic) <= n. Moreover, we propose two effective t/s-diagnosis algorithms under the PMC and MM* models with time complexity O(NlogN) and O(N(logN)2) (N = 22n is the order of BHn), respectively. Finally, comparison results indicate that t/s-diagnosability strengthens the self-diagnosable capability of the system compared with traditional diagnosabilities.","volume":39,"issue":5,"firstpage":1207,"lastpage":1222,"year":2024,"type":"Regular Paper","research_area":["Fault Diagnosis & Reliability"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2732-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2732-5?year=2024&issue=5","affiliations":["Fujian Normal University","Oakland University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-4165-6","title":"OAAFormer: Robust and Efficient Point Cloud Registration Through Overlapping-Aware Attention in Transformer","authors":[{"last":"Gao","first":"Jun-Jie"},{"last":"Dong","first":"Qiu-Jie"},{"last":"Wang","first":"Rui-An"},{"last":"Chen","first":"Shuang-Min"},{"last":"Xin","first":"Shi-Qing"},{"last":"Tu","first":"Chang-He"},{"last":"Wang","first":"Wenping"}],"keywords":["point cloud registration","coarse-to-fine","overlapping region","feature matching","Transformer"],"abstract":"In the domain of point cloud registration, the coarse-to-fine feature matching paradigm has received significant attention due to its impressive performance. This paradigm involves a two-step process: first, the extraction of multilevel features, and subsequently, the propagation of correspondences from coarse to fine levels. However, this approach faces two notable limitations. Firstly, the use of the Dual Softmax operation may promote one-to-one correspondences between superpoints, inadvertently excluding valuable correspondences. Secondly, it is crucial to closely examine the overlapping areas between point clouds, as only correspondences within these regions decisively determine the actual transformation. Considering these issues, we propose OAAFormer to enhance correspondence quality. On the one hand, we introduce a soft matching mechanism to facilitate the propagation of potentially valuable correspondences from coarse to fine levels. On the other hand, we integrate an overlapping region detection module to minimize mismatches to the greatest extent possible. Furthermore, we introduce a region-wise attention module with linear complexity during the fine-level matching phase, designed to enhance the discriminative capabilities of the extracted features. Tests on the challenging 3DLoMatch benchmark demonstrate that our approach leads to a substantial increase of about 7% in the inlier ratio, as well as an enhancement of 2%-4% in registration recall. Finally, to accelerate the prediction process, we replace the Conventional Random Sample Consensus (RANSAC) algorithm with the selection of a limited yet representative set of high-confidence correspondences, resulting in a 100 times speedup while still maintaining comparable registration performance.","volume":39,"issue":4,"firstpage":755,"lastpage":770,"year":2024,"type":"Regular Paper","research_area":["Point Cloud & 3D Vision","Transformers & Attention"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4165-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4165-6?year=2024&issue=4","affiliations":["Shandong University","Qingdao University of Science & Technology","Texas A&M University System","Texas A&M University College Station"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-4123-3","title":"A Tiny Example Based Procedural Model for Real-Time Glinty Appearance Rendering","authors":[{"last":"Xing","first":"You-Xin"},{"last":"Tan","first":"Hao-Wen"},{"last":"Xu","first":"Yan-Ning"},{"last":"Wang","first":"Lu"}],"keywords":["real-time rendering","reflectance modeling","glinty material","photorealistic rendering","microstructure"],"abstract":"The glinty details from complex microstructures significantly enhance rendering realism. However, the previous methods use high-resolution normal maps to define each micro-geometry, which requires huge memory overhead. This paper observes that many self-similarity materials have independent structural characteristics, which we define as tiny example microstructures. We propose a procedural model to represent microstructures implicitly by performing spatial transformations and spatial distribution on tiny examples. Furthermore, we precompute normal distribution functions (NDFs) by 4D Gaussians for tiny examples and store them in multi-scale NDF maps. Combined with a tiny example based NDF evaluation method, complex glinty surfaces can be rendered simply by texture sampling. The experimental results show that our tiny example based the microstructure rendering method is GPU-friendly, successfully reproducing high-frequency reflection features of different microstructures in real time with low memory and computational overhead.","volume":39,"issue":4,"firstpage":771,"lastpage":784,"year":2024,"type":"Regular Paper","research_area":["Computer Graphics & Visualization"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4123-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4123-3?year=2024&issue=4","affiliations":["Shandong University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-4157-6","title":"SG-NeRF: Sparse-Input Generalized Neural Radiance Fields for Novel View Synthesis","authors":[{"last":"Xu","first":"Kuo"},{"last":"Li","first":"Jie"},{"last":"Li","first":"Zhen-Qiang"},{"last":"Cao","first":"Yang-Jie"}],"keywords":["Neural Radiance Fields (NeRF)","multi-view stereo (MVS)","new view synthesis (NVS)"],"abstract":"Traditional neural radiance fields for rendering novel views require intensive input images and pre-scene optimization, which limits their practical applications. We propose a generalization method to infer scenes from input images and perform high-quality rendering without pre-scene optimization named SG-NeRF (Sparse-Input Generalized Neural Radiance Fields). Firstly, we construct an improved multi-view stereo structure based on the convolutional attention and multi-level fusion mechanism to obtain the geometric features and appearance features of the scene from the sparse input images, and then these features are aggregated by multi-head attention as the input of the neural radiance fields. This strategy of utilizing neural radiance fields to decode scene features instead of mapping positions and orientations enables our method to perform cross-scene training as well as inference, thus enabling neural radiance fields to generalize for novel view synthesis on unseen scenes. We tested the generalization ability on DTU dataset, and our PSNR (peak signal-to-noise ratio) improved by 3.14 compared with the baseline method under the same input conditions. In addition, if the scene has dense input views available, the average PSNR can be improved by 1.04 through further refinement training in a short time, and a higher quality rendering effect can be obtained.","volume":39,"issue":4,"firstpage":785,"lastpage":797,"year":2024,"type":"Regular Paper","research_area":["Computer Vision","Computer Graphics & Visualization"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4157-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4157-6?year=2024&issue=4","affiliations":["Zhengzhou University","Shanghai Jiao Tong University"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-024-4158-5","title":"Knowledge Distillation via Hierarchical Matching for Small Object Detection","authors":[{"last":"Ma","first":"Yong-Chi"},{"last":"Ma","first":"Xiao"},{"last":"Hao","first":"Tian-Ran"},{"last":"Cui","first":"Li-Sha"},{"last":"Jin","first":"Shao-Hui"},{"last":"Lyu","first":"Pei"}],"keywords":["knowledge distillation","object detection","small object detection","machine learning"],"abstract":"Knowledge distillation is often used for model compression and has achieved a great breakthrough in image classification, but there still remains scope for improvement in object detection, especially for knowledge extraction of small objects. The main problem is the features of small objects are often polluted by background noise and not prominent due to down-sampling of convolutional neural network (CNN), resulting in the insufficient refinement of small object features during distillation. In this paper, we propose Hierarchical Matching Knowledge Distillation Network (HMKD) that operates on the pyramid level P2 to pyramid level P4 of the feature pyramid network (FPN), aiming to intervene on small object features before affecting. We employ an encoder-decoder network to encapsulate low-resolution, highly semantic information, akin to eliciting insights from profound strata within a teacher network, and then match the encapsulated information with high-resolution feature values of small objects from shallow layers as the key. During this period, we use an attention mechanism to measure the relevance of the inquiry to the feature values. Also in the process of decoding, knowledge is distilled to the student. In addition, we introduce a supplementary distillation module to mitigate the effects of background noise. Experiments show that our method achieves excellent improvements for both one-stage and two-stage object detectors. Specifically, applying the proposed method on Faster R-CNN achieves 41.7% mAP on COCO2017 (ResNet50 as the backbone), which is 3.8% higher than that of the baseline.","volume":39,"issue":4,"firstpage":798,"lastpage":810,"year":2024,"type":"Regular Paper","research_area":["Computer Vision","Deep Learning & Neural Networks","Knowledge Distillation"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4158-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4158-5?year=2024&issue=4","affiliations":["Zhengzhou University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-4125-1","title":"Multi-Task Visual Semantic Embedding Network for Image-Text Retrieval","authors":[{"last":"Qin","first":"Xue-Yang"},{"last":"Li","first":"Li-Shuang"},{"last":"Tang","first":"Jing-Yao"},{"last":"Hao","first":"Fei"},{"last":"Ge","first":"Mei-Ling"},{"last":"Pang","first":"Guang-Yao"}],"keywords":["image-text retrieval","cross-modal retrieval","multi-task learning","graph convolutional network"],"abstract":"Image-text retrieval aims to capture the semantic correspondence between images and texts, which serves as a foundation and crucial component in multi-modal recommendations, search systems, and online shopping. Existing mainstream methods primarily focus on modeling the association of image-text pairs while neglecting the advantageous impact of multi-task learning on image-text retrieval. To this end, a multi-task visual semantic embedding network (MVSEN) is proposed for image-text retrieval. Specifically, we design two auxiliary tasks, including text-text matching and multi-label classification, for semantic constraints to improve the generalization and robustness of visual semantic embedding from a training perspective. Besides, we present an intra- and inter-modality interaction scheme to learn discriminative visual and textual feature representations by facilitating information flow within and between modalities. Subsequently, we utilize multi-layer graph convolutional networks in a cascading manner to infer the correlation of image-text pairs. Experimental results show that MVSEN outperforms state-of-the-art methods on two publicly available datasets, Flickr30K and MSCO-CO, with rSum improvements of 8.2% and 3.0%, respectively.","volume":39,"issue":4,"firstpage":811,"lastpage":826,"year":2024,"type":"Regular Paper","research_area":["Computer Vision","Multi-Task & Transfer Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4125-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4125-1?year=2024&issue=4","affiliations":["Dalian University of Technology","Shaanxi Normal University","Weifang University","Wuzhou University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-4164-7","title":"Face Anti-Spoofing with Unknown Attacks: A Comprehensive Feature Extraction and Representation Perspective","authors":[{"last":"Li","first":"Li-Min"},{"last":"Wang","first":"Bin-Wu"},{"last":"Wang","first":"Xu"},{"last":"Wang","first":"Peng-Kun"},{"last":"Zhang","first":"Yu-Dong"},{"last":"Wang","first":"Yang"}],"keywords":["face anti-spoofing","spoof detection","zero-shot learning","convolutional neural network","deep learning"],"abstract":"Face anti-spoofing aims at detecting whether the input is a real photo of a user (living) or a fake (spoofing) image. As new types of attacks keep emerging, the detection of unknown attacks, known as Zero-Shot Face Anti-Spoofing (ZSFA), has become increasingly important in both academia and industry. Existing ZSFA methods mainly focus on extracting discriminative features between spoofing and living faces. However, the nature of the spoofing faces is to trick anti-spoofing systems by mimicking the livings, therefore the deceptive features between the known attacks and the livings, which have been ignored by existing ZSFA methods, are essential to comprehensively represent the livings. Therefore, existing ZSFA models are incapable of learning the complete representations of living faces and thus fall short of effectively detecting newly emerged attacks. To tackle this problem, we propose an innovative method that effectively captures both the deceptive and discriminative features distinguishing between genuine and spoofing faces. Our method consists of two main components: a two-against-all training strategy and a semantic autoencoder. The two-against-all training strategy is employed to separate deceptive and discriminative features. To address the subsequent invalidation issue of categorical functions and the dominance disequilibrium issue among different dimensions of features after importing deceptive features, we introduce a modified semantic autoencoder. This autoencoder is designed to map all extracted features to a semantic space, thereby achieving a balance in the dominance of each feature dimension. We combine our method with the feature extraction model ResNet50, and experimental results show that the trained ResNet50 model simultaneously achieves a feasible detection of unknown attacks and comparably accurate detection of known spoofing. Experimental results confirm the superiority and effectiveness of our proposed method in identifying the living with the interference of both known and unknown spoofing types.","volume":39,"issue":4,"firstpage":827,"lastpage":840,"year":2024,"type":"Regular Paper","research_area":["Computer Vision","Convolutional & Spiking Networks","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4164-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4164-7?year=2024&issue=4","affiliations":["Chinese Academy of Sciences","University of Science & Technology of China, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-4585-3","title":"Overcoming Spatial Constraints in VR: A Survey of Redirected Walking Techniques","authors":[{"last":"Liu","first":"Jia-Hong"},{"last":"Ren","first":"Yang-Fu"},{"last":"Gan","first":"Qi Wen"},{"last":"Huang","first":"Kui"},{"last":"Chen","first":"Fiona Xiao Yu"},{"last":"Luo","first":"Er-Xia"},{"last":"Tang","first":"Khang Yeu"},{"last":"Fu","first":"Yue-Yao"},{"last":"Fan","first":"Cheng-Wei"},{"last":"Xu","first":"Sen-Zhe"},{"last":"Zhang","first":"Song-Hai"}],"keywords":["virtual reality (VR)","redirected walking (RDW)","redirection gain","perception"],"abstract":"As the virtual reality (VR) technology strives to provide immersive and natural user experiences, the challenge of aligning vast virtual environments with limited physical spaces remains significant. This survey comprehensively explores the advancements in redirected walking (RDW) techniques aimed at overcoming spatial constraints in VR. RDW addresses this by subtly manipulating users' physical movements to allow for seamless navigation within constrained areas. The survey delves into gain perception mechanisms, detailing how slight discrepancies between virtual and real-world movements can be utilized without user awareness, thus extending the effective navigable space. Various RDW control algorithms for gain-based RDW are analyzed, highlighting their implementation and effectiveness in maintaining immersion and minimizing perceptual disturbances. Furthermore, novel methods extending beyond traditional gain-based techniques are discussed, showcasing innovative approaches that further refine VR interactions. The practical implications of RDW in enhancing safety and reducing physical collisions in VR environments are underscored, alongside its potential to improve user experience by aligning virtual exploration more closely with natural human behavior patterns. Through a thorough review of existing literature and recent advancements, this survey provides a systematic understanding for researchers, developers, and industry professionals. It underscores the importance of RDW in the future of VR, emphasizing RDW's role in making VR more accessible and practical across various applications, from education and training to therapy and entertainment. The paper concludes with a forward-looking perspective on the continued evolution and potential of RDW in revolutionizing virtual reality experiences.","volume":39,"issue":4,"firstpage":841,"lastpage":870,"year":2024,"type":"Survey","research_area":["Computer Graphics & Visualization"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4585-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4585-3?year=2024&issue=4","affiliations":["Tsinghua University","Qinghai University","Beijing Information Science & Technology University","University of Science & Technology Beijing"],"type_origin":"Review"},{"doi":"10.1007/s11390-023-2939-x","title":"Skyway: Accelerate Graph Applications with a Dual-Path Architecture and Fine-Grained Data Management","authors":[{"last":"Zou","first":"Mo"},{"last":"Zhang","first":"Ming-Zhe"},{"last":"Wang","first":"Ru-Jia"},{"last":"Sun","first":"Xian-He"},{"last":"Ye","first":"Xiao-Chun"},{"last":"Fan","first":"Dong-Rui"},{"last":"Tang","first":"Zhi-Min"}],"keywords":["graph application","computer architecture","memory hierarchy"],"abstract":"Graph processing is a vital component of many AI and big data applications. However, due to its poor locality and complex data access patterns, graph processing is also a known performance killer of AI and big data applications. In this work, we propose to enhance graph processing applications by leveraging fine-grained memory access patterns with a dual-path architecture on top of existing software-based graph optimizations. We first identify that memory accesses to the offset, edge, and state array have distinct locality and impact on performance. We then introduce the Skyway architecture, which consists of two primary components: 1) a dedicated direct data path between the core and memory to transfer state array elements efficiently, and 2) a data-type aware fine-grained memory-side row buffer hardware for both the newly designed direct data path and the regular memory hierarchy data path. The proposed Skyway architecture is able to improve the overall performance by reducing the memory access interference and improving data access efficiency with a minimal overhead. We evaluate Skyway on a set of diverse algorithms using large real-world graphs. On a simulated four-core system, Skyway improves the performance by 23% on average over the best-performing graph-specialized hardware optimizations.","volume":39,"issue":4,"firstpage":871,"lastpage":894,"year":2024,"type":"Regular Paper","research_area":["Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2939-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2939-x?year=2024&issue=4","affiliations":["Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2934-x","title":"Audio Enhancement for Computer Audition-An Iterative Training Paradigm Using Sample Importance","authors":[{"last":"Milling","first":"Manuel"},{"last":"Liu","first":"Shuo"},{"last":"Triantafyllopoulos","first":"Andreas"},{"last":"Aslan","first":"Ilhan"},{"last":"Schuller","first":"Bjoern W."}],"keywords":["audio enhancement","computer audition","joint optimisation","multi-task learning","voice suppression"],"abstract":"Neural network models for audio tasks, such as automatic speech recognition (ASR) and acoustic scene classification (ASC), are susceptible to noise contamination for real-life applications. To improve audio quality, an enhancement module, which can be developed independently, is explicitly used at the front-end of the target audio applications. In this paper, we present an end-to-end learning solution to jointly optimise the models for audio enhancement (AE) and the subsequent applications. To guide the optimisation of the AE module towards a target application, and especially to overcome difficult samples, we make use of the sample-wise performance measure as an indication of sample importance. In experiments, we consider four representative applications to evaluate our training paradigm, i.e., ASR, speech command recognition (SCR), speech emotion recognition (SER), and ASC. These applications are associated with speech and nonspeech tasks concerning semantic and non-semantic features, transient and global information, and the experimental results indicate that our proposed approach can considerably boost the noise robustness of the models, especially at low signal-to-noise ratios, for a wide range of computer audition tasks in everyday-life noisy environments.","volume":39,"issue":4,"firstpage":895,"lastpage":911,"year":2024,"type":"Regular Paper","research_area":["Multi-Task & Transfer Learning","Speech & Audio"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2934-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2934-x?year=2024&issue=4","affiliations":["University of Augsburg","Technical University of Munich","Huawei Technologies","Imperial College London"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2113-0","title":"Learning a Mixture of Conditional Gating Blocks for Visual Question Answering","authors":[{"last":"Sun","first":"Qiang"},{"last":"Fu","first":"Yan-Wei"},{"last":"Xue","first":"Xiang-Yang"}],"keywords":["visual question answering","Transformer","dynamic network"],"abstract":"As a Turing test in multimedia, visual question answering (VQA) aims to answer the textual question with a given image. Recently, the dynamic property of neural networks has been explored as one of the most promising ways of improving the adaptability, interpretability, and capacity of the neural network models. Unfortunately, despite the prevalence of dynamic convolutional neural networks, it is relatively less touched and very nontrivial to exploit dynamics in the transformers of the VQA tasks through all the stages in an end-to-end manner. Typically, due to the large computation cost of transformers, researchers are inclined to only apply transformers on the extracted high-level visual features for downstream vision and language tasks. To this end, we introduce a question-guided dynamic layer to the transformer as it can effectively increase the model capacity and require fewer transformer layers for the VQA task. In particular, we name the dynamics in the Transformer as Conditional Multi-Head Self-Attention block (cMHSA). Furthermore, our questionguided cMHSA is compatible with conditional ResNeXt block (cResNeXt). Thus a novel model mixture of conditional gating blocks (McG) is proposed for VQA, which keeps the best of the Transformer, convolutional neural network (CNN), and dynamic networks. The pure conditional gating CNN model and the conditional gating Transformer model can be viewed as special examples of McG. We quantitatively and qualitatively evaluate McG on the CLEVR and VQA-Abstract datasets. Extensive experiments show that McG has achieved the state-of-the-art performance on these benchmark datasets.","volume":39,"issue":4,"firstpage":912,"lastpage":928,"year":2024,"type":"Regular Paper","research_area":["Computer Vision","Transformers & Attention"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2113-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2113-0?year=2024&issue=4","affiliations":["Shanghai University of International Business & Economics","Fudan University"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2070-z","title":"Towards Effective Author Name Disambiguation by Hybrid Attention","authors":[{"last":"Zhou","first":"Qian"},{"last":"Chen","first":"Wei"},{"last":"Zhao","first":"Peng-Peng"},{"last":"Liu","first":"An"},{"last":"Xu","first":"Jia-Jie"},{"last":"Qu","first":"Jian-Feng"},{"last":"Zhao","first":"Lei"}],"keywords":["author name disambiguation","multiple-feature information","hybrid attention","pruning strategy","structural information loss of vector space"],"abstract":"Author name disambiguation (AND) is a central task in academic search, which has received more attention recently accompanied by the increase of authors and academic publications. To tackle the AND problem, existing studies have proposed various approaches based on different types of information, such as raw document features (e.g., co-authors, titles, and keywords), the fusion feature (e.g., a hybrid publication embedding based on multiple raw document features), the local structural information (e.g., a publication's neighborhood information on a graph), and the global structural information (e.g., interactive information between a node and others on a graph). However, there has been no work taking all the above-mentioned information into account and taking full advantage of the contributions of each raw document feature for the AND problem so far. To fill the gap, we propose a novel framework named EAND (Towards Effective Author Name Disambiguation by Hybrid Attention). Specifically, we design a novel feature extraction model, which consists of three hybrid attention mechanism layers, to extract key information from the global structural information and the local structural information that are generated from six similarity graphs constructed based on different similarity coefficients, raw document features, and the fusion feature. Each hybrid attention mechanism layer contains three key modules: a local structural perception, a global structural perception, and a feature extractor. Additionally, the mean absolute error function in the joint loss function is used to introduce the structural information loss of the vector space. Experimental results on two real-world datasets demonstrate that EAND achieves superior performance, outperforming state-of-the-art methods by at least +2.74% in terms of the micro-F1 score and +3.31% in terms of the macro-F1 score.","volume":39,"issue":4,"firstpage":929,"lastpage":950,"year":2024,"type":"Regular Paper","research_area":["Information Extraction"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2070-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2070-z?year=2024&issue=4","affiliations":["Soochow University - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2408-1","title":"Alarm Log Data Augmentation Algorithm Based on a GAN Model and Apriori","authors":[{"last":"Yang","first":"Yang"},{"last":"Li","first":"Yu-Ting"},{"last":"Huo","first":"Yong-Hua"},{"last":"Gao","first":"Zhi-Peng"},{"last":"Rui","first":"Lan-Lan"}],"keywords":["data augmentation","alarm log data","Apriori","generative adversarial network (GAN)"],"abstract":"The complexity of alarm detection and diagnosis tasks often results in a lack of alarm log data. Due to the strong rule associations inherent in alarm log data, existing data augmentation algorithms cannot obtain good results for alarm log data. To address this problem, this paper introduces a new algorithm for augmenting alarm log data, termed APRGAN, which combines a generative adversarial network (GAN) with the Apriori algorithm. APRGAN generates alarm log data under the guidance of rules mined by the rule miner. Moreover, we propose a new dynamic updating mechanism to alleviate the mode collapse problem of the GAN. In addition to updating the real reference dataset used to train the discriminator in the GAN, we dynamically update the parameters and the rule set of the Apriori algorithm according to the data generated in each epoch. Through extensive experimentation on two public datasets, it is demonstrated that APRGAN surpasses other data augmentation algorithms in the domain with respect to alarm log data augmentation, as evidenced by its superior performance on metrics such as BLEU, ROUGE, and METEOR.","volume":39,"issue":4,"firstpage":951,"lastpage":966,"year":2024,"type":"Regular Paper","research_area":["Generative Models"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2408-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2408-1?year=2024&issue=4","affiliations":["Beijing University of Posts & Telecommunications","China Electronics Technology Group"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-2149-y","title":"CAGCN: Centrality-Aware Graph Convolution Network for Anomaly Detection in Industrial Control Systems","authors":[{"last":"Yang","first":"Jun"},{"last":"Sheng","first":"Yi-Qiang"},{"last":"Wang","first":"Jin-Lin"},{"last":"Ni","first":"Hong"}],"keywords":["graph convolution network (GCN)","data mining","network centrality","anomaly detection","industrial control system"],"abstract":"In industrial control systems, the utilization of deep learning based methods achieves improvements for anomaly detection. However, most current methods ignore the association of inner components in industrial control systems. In industrial control systems, an anomaly component may affect the neighboring components; therefore, the connective relationship can help us to detect anomalies effectively. In this paper, we propose a centrality-aware graph convolution network (CAGCN) for anomaly detection in industrial control systems. Unlike the traditional graph convolution network (GCN) model, we utilize the concept of centrality to enhance the ability of graph convolution networks to deal with the inner relationship in industrial control systems. Our experiments show that compared with GCN, our CAGCN has a better ability to utilize this relationship between components in industrial control systems. The performances of the model are evaluated on the Secure Water Treatment (SWaT) dataset and the Water Distribution (WADI) dataset, the two most common industrial control systems datasets in the field of industrial anomaly detection. The experimental results show that our CAGCN achieves better results on precision, recall, and F1 score than the state-of-the-art methods.","volume":39,"issue":4,"firstpage":967,"lastpage":983,"year":2024,"type":"Regular Paper","research_area":["Data Mining & Analytics","Graph Neural Networks","Robotics & Control"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-2149-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-2149-y?year=2024&issue=4","affiliations":["Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Institute of Acoustics, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-4058-8","title":"A Communication Theory Perspective on Prompting Engineering Methods for Large Language Models","authors":[{"last":"Song","first":"Yuan-Feng"},{"last":"He","first":"Yuan-Qin"},{"last":"Zhao","first":"Xue-Fang"},{"last":"Gu","first":"Han-Lin"},{"last":"Jiang","first":"Di"},{"last":"Yang","first":"Hai-Jun"},{"last":"Fan","first":"Li-Xin"}],"keywords":["prompting method","large language model","communication theory"],"abstract":"The springing up of large language models (LLMs) has shifted the community from single-task-orientated natural language processing (NLP) research to a holistic end-to-end multi-task learning paradigm. Along this line of research endeavors in the area, LLM-based prompting methods have attracted much attention, partially due to the technological advantages brought by prompt engineering (PE) as well as the underlying NLP principles disclosed by various prompting methods. Traditional supervised learning usually requires training a model based on labeled data and then making predictions. In contrast, PE methods directly use the powerful capabilities of existing LLMs (e.g., GPT-3 and GPT-4) via composing appropriate prompts, especially under few-shot or zero-shot scenarios. Facing the abundance of studies related to the prompting and the ever-evolving nature of this field, this article aims to 1) illustrate a novel perspective to review existing PE methods within the well-established communication theory framework, 2) facilitate a better/deeper understanding of developing trends of existing PE methods used in three typical tasks, and 3) shed light on promising research directions for future PE methods.","volume":39,"issue":4,"firstpage":984,"lastpage":1004,"year":2024,"type":"Survey","research_area":["LLM Data & Prompting"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4058-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4058-8?year=2024&issue=4","affiliations":["WeBank Co., Ltd."],"type_origin":"Article"},{"doi":"10.1007/s11390-024-4143-z","title":"Video Colorization: A Survey","authors":[{"last":"Peng","first":"Zhong-Zheng"},{"last":"Yang","first":"Yi-Xin"},{"last":"Tang","first":"Jin-Hui"},{"last":"Pan","first":"Jin-Shan"}],"keywords":["video colorization","deep convolutional neural network","spatial-temporal consistency"],"abstract":"Video colorization aims to add color to grayscale or monochrome videos. Although existing methods have achieved substantial and noteworthy results in the field of image colorization, video colorization presents more formidable obstacles due to the additional necessity for temporal consistency. Moreover, there is rarely a systematic review of video colorization methods. In this paper, we aim to review existing state-of-the-art video colorization methods. In addition, maintaining spatial-temporal consistency is pivotal to the process of video colorization. To gain deeper insight into the evolution of existing methods in terms of spatial-temporal consistency, we further review video colorization methods from a novel perspective. Video colorization methods can be categorized into four main categories: optical-flow based methods, scribble-based methods, exemplar-based methods, and fully automatic methods. However, optical-flow based methods rely heavily on accurate optical-flow estimation, scribble-based methods require extensive user interaction and modifications, exemplar-based methods face challenges in obtaining suitable reference images, and fully automatic methods often struggle to meet specific colorization requirements. We also discuss the existing challenges and highlight several future research opportunities worth exploring.","volume":39,"issue":3,"firstpage":487,"lastpage":508,"year":2024,"type":"Survey","research_area":["Convolutional & Spiking Networks","Deep Learning & Neural Networks","Computer Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4143-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4143-z?year=2024&issue=3","affiliations":["Nanjing University of Science & Technology"],"type_origin":"Review"},{"doi":"10.1007/s11390-024-3814-0","title":"A Survey of Multimodal Controllable Diffusion Models","authors":[{"last":"Jiang","first":"Rui"},{"last":"Zheng","first":"Guang-Cong"},{"last":"Li","first":"Teng"},{"last":"Yang","first":"Tian-Rui"},{"last":"Wang","first":"Jing-Dong"},{"last":"Li","first":"Xi"}],"keywords":["diffusion model","controllable generation","application","personalization"],"abstract":"Diffusion models have recently emerged as powerful generative models, producing high-fidelity samples across domains. Despite this, they have two key challenges, including improving the time-consuming iterative generation process and controlling and steering the generation process. Existing surveys provide broad overviews of diffusion model advancements. However, they lack comprehensive coverage specifically centered on techniques for controllable generation. This survey seeks to address this gap by providing a comprehensive and coherent review on controllable generation in diffusion models. We provide a detailed taxonomy defining controlled generation for diffusion models. Controllable generation is categorized based on the formulation, methodologies, and evaluation metrics. By enumerating the range of methods researchers have developed for enhanced control, we aim to establish controllable diffusion generation as a distinct subfield warranting dedicated focus. With this survey, we contextualize recent results, provide the dedicated treatment of controllable diffusion model generation, and outline limitations and future directions. To demonstrate applicability, we highlight controllable diffusion techniques for major computer vision tasks application. By consolidating methods and applications for controllable diffusion models, we hope to catalyze further innovations in reliable and scalable controllable generation.","volume":39,"issue":3,"firstpage":509,"lastpage":541,"year":2024,"type":"Survey","research_area":["Generative Models"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3814-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3814-0?year=2024&issue=3","affiliations":["Zhejiang University","Nanjing University","Baidu"],"type_origin":"Review"},{"doi":"10.1007/s11390-024-3767-3","title":"A Survey of LLM Datasets: From Autoregressive Model to AI Chatbot","authors":[{"last":"Du","first":"Fei"},{"last":"Ma","first":"Xin-Jian"},{"last":"Yang","first":"Jing-Ru"},{"last":"Liu","first":"Yi"},{"last":"Luo","first":"Chao-Ran"},{"last":"Wang","first":"Xue-Bin"},{"last":"Jiang","first":"Hai-Ou"},{"last":"Jing","first":"Xiang"}],"keywords":["large language model (LLM)","autoregressive model","AI chatbot","natural language processing (NLP) corpora","OpenAI"],"abstract":"Since OpenAI opened access to ChatGPT, large language models (LLMs) become an increasingly popular topic attracting researchers' attention from abundant domains. However, public researchers meet some problems when developing LLMs given that most of the LLMs are produced by industries and the training details are typically unrevealed. Since datasets are an important setup of LLMs, this paper does a holistic survey on the training datasets used in both the pre-train and fine-tune processes. The paper first summarizes 16 pre-train datasets and 16 fine-tune datasets used in the state-of-the-art LLMs. Secondly, based on the properties of the pre-train and fine-tune processes, it comments on pre-train datasets from quality, quantity, and relation with models, and comments on fine-tune datasets from quality, quantity, and concerns. This study then critically figures out the problems and research trends that exist in current LLM datasets. The study helps public researchers train and investigate LLMs by visual cases and provides useful comments to the research community regarding data development. To the best of our knowledge, this paper is the first to summarize and discuss datasets used in both autoregressive and chat LLMs. The survey offers insights and suggestions to researchers and LLM developers as they build their models, and contributes to the LLM study by pointing out the existing problems of LLM studies from the perspective of data.","volume":39,"issue":3,"firstpage":542,"lastpage":566,"year":2024,"type":"Survey","research_area":["LLM Data & Prompting"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3767-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3767-3?year=2024&issue=3","affiliations":["Columbia University","Peking University"],"type_origin":"Review"},{"doi":"10.1007/s11390-024-3872-3","title":"Advances of Pipeline Model Parallelism for Deep Learning Training: An Overview","authors":[{"last":"Guan","first":"Lei"},{"last":"Li","first":"Dong-Sheng"},{"last":"Liang","first":"Ji-Ye"},{"last":"Wang","first":"Wen-Jian"},{"last":"Ge","first":"Ke-Shi"},{"last":"Lu","first":"Xi-Cheng"}],"keywords":["deep learning","pipeline schedule","load balance","multi-GPU system","pipeline model parallelism (PMP)"],"abstract":"Deep learning has become the cornerstone of artificial intelligence, playing an increasingly important role in human production and lifestyle. However, as the complexity of problem-solving increases, deep learning models become increasingly intricate, resulting in a proliferation of large language models with an astonishing number of parameters. Pipeline model parallelism (PMP) has emerged as one of the mainstream approaches to addressing the significant challenge of training big models. This paper presents a comprehensive review of PMP. It covers the basic concepts and main challenges of PMP. It also comprehensively compares synchronous and asynchronous pipeline schedules for PMP approaches, and discusses the main techniques to achieve load balance for both intra-node and inter-node training. Furthermore, the main techniques to optimize computation, storage, and communication are presented, with potential research directions being discussed.","volume":39,"issue":3,"firstpage":567,"lastpage":584,"year":2024,"type":"Survey","research_area":["Deep Learning & Neural Networks","GPU & Accelerator Architecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3872-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3872-3?year=2024&issue=3","affiliations":["National University of Defense Technology - China","Shanxi University"],"type_origin":"Review"},{"doi":"10.1007/s11390-024-2883-4","title":"Knowledge-Enhanced Conversational Agents","authors":[{"last":"Caffaro","first":"Fabio"},{"last":"Rizzo","first":"Giuseppe"}],"keywords":["conversational agent","dialogue system","knowledge enhancing","artificial agent","intelligent conversation"],"abstract":"Humanity has fantasized about artificial intelligence tools able to discuss with human beings fluently for decades. Numerous efforts have been proposed ranging from ELIZA to the modern vocal assistants. Despite the large interest in this research and innovation field, there is a lack of common understanding on the concept of conversational agents and general over expectations that hide the current limitations of existing solutions. This work proposes a literature review on the subject with a focus on the most promising type of conversational agents that are powered on top of knowledge bases and that can offer the ground knowledge to hold conversation autonomously on different topics. We describe a conceptual architecture to define the knowledge-enhanced conversational agents and investigate different domains of applications. We conclude this work by listing some promising research pathways for future work.","volume":39,"issue":3,"firstpage":585,"lastpage":609,"year":2024,"type":"Survey","research_area":["Text Generation & Dialogue"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2883-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2883-4?year=2024&issue=3","affiliations":["LINKS Fdn"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-2700-0","title":"A Survey and Experimental Review on Data Distribution Strategies for Parallel Spatial Clustering Algorithms","authors":[{"last":"Challa","first":"Jagat Sesh"},{"last":"Goyal","first":"Navneet"},{"last":"Sharma","first":"Amogh"},{"last":"Sreekumar","first":"Nikhil"},{"last":"Balasubramaniam","first":"Sundar"},{"last":"Goyal","first":"Poonam"}],"keywords":["parallel data mining","data distribution","parallel clustering","spatial locality preservation"],"abstract":"The advent of Big Data has led to the rapid growth in the usage of parallel clustering algorithms that work over distributed computing frameworks such as MPI, MapReduce, and Spark. An important step for any parallel clustering algorithm is the distribution of data amongst the cluster nodes. This step governs the methodology and performance of the entire algorithm. Researchers typically use random, or a spatial/geometric distribution strategy like kd-tree based partitioning and grid-based partitioning, as per the requirements of the algorithm. However, these strategies are generic and are not tailor-made for any specific parallel clustering algorithm. In this paper, we give a very comprehensive literature survey of MPI-based parallel clustering algorithms with special reference to the specific data distribution strategies they employ. We also propose three new data distribution strategies namely Parameterized Dimensional Split for parallel density-based clustering algorithms like DBSCAN and OPTICS, Cell-Based Dimensional Split for dGridSLINK, which is a grid-based hierarchical clustering algorithm that exhibits efficiency for disjoint spatial distribution, and Projection-Based Split, which is a generic distribution strategy. All of these preserve spatial locality, achieve disjoint partitioning, and ensure good data load balancing. The experimental analysis shows the benefits of using the proposed data distribution strategies for algorithms they are designed for, based on which we give appropriate recommendations for their usage.","volume":39,"issue":3,"firstpage":610,"lastpage":636,"year":2024,"type":"Survey","research_area":["Data Mining & Analytics","Databases & Query Processing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-2700-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-2700-0?year=2024&issue=3","affiliations":["Birla Institute of Technology & Science Pilani (BITS Pilani)","Uber Technologies, Inc.","University of Minnesota System","University of Minnesota Twin Cities"],"type_origin":"Review"},{"doi":"10.1007/s11390-024-3914-x","title":"Age-of-Information-Aware Federated Learning","authors":[{"last":"Xu","first":"Yin"},{"last":"Xiao","first":"Ming-Jun"},{"last":"Wu","first":"Chen"},{"last":"Wu","first":"Jie"},{"last":"Zhou","first":"Jin-Rui"},{"last":"Sun","first":"He"}],"keywords":["federated learning","Age of Information","restless multi-armed bandit","Whittle's index"],"abstract":"Federated learning (FL) is an emerging privacy-preserving distributed computing paradigm, enabling numerous clients to collaboratively train machine learning models without the necessity of transmitting clients' private datasets to the central server. Unlike most existing research where the local datasets of clients are assumed to be unchanged over time throughout the whole FL process, our study addresses such scenarios in this paper where clients' datasets need to be updated periodically, and the server can incentivize clients to employ as fresh as possible datasets for local model training. Our primary objective is to design a client selection strategy to minimize the loss of the global model for FL loss within a constrained budget. To this end, we introduce the concept of Age of Information (AoI) to quantitatively assess the freshness of local datasets and conduct a theoretical analysis of the convergence bound in our AoI-aware FL system. Based on the convergence bound, we further formulate our problem as a restless multi-armed bandit (RMAB) problem. Next, we relax the RMAB problem and apply the Lagrangian Dual approach to decouple it into multiple subproblems. Finally, we propose a Whittle's Index Based Client Selection (WICS) algorithm to determine the set of selected clients. In addition, comprehensive simulations substantiate that the proposed algorithm can effectively reduce training loss and enhance the learning accuracy compared with some state-of-the-art methods.","volume":39,"issue":3,"firstpage":637,"lastpage":653,"year":2024,"type":"Regular Paper","research_area":["Federated Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3914-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3914-x?year=2024&issue=3","affiliations":["Chinese Academy of Sciences","University of Science & Technology of China, CAS","Pennsylvania Commonwealth System of Higher Education (PCSHE)","Temple University"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1987-y","title":"Multimodal Dependence Attention and Large-Scale Data Based Offline Handwritten Formula Recognition","authors":[{"last":"Liu","first":"Han-Chao"},{"last":"Dong","first":"Lan-Fang"},{"last":"Zhang","first":"Xin-Ming"}],"keywords":["handwritten formula recognition","multimodal dependence attention","semantic dependence","visual dependence","Handwritten Formula Image Dataset"],"abstract":"Offline handwritten formula recognition is a challenging task due to the variety of handwritten symbols and two-dimensional formula structures. Recently, the deep neural network recognizers based on the encoder-decoder framework have achieved great improvements on this task. However, the unsatisfactory recognition performance for formulas with long LATEX strings is one shortcoming of the existing work. Moreover, lacking sufficient training data also limits the capability of these recognizers. In this paper, we design a multimodal dependence attention (MDA) module to help the model learn visual and semantic dependencies among symbols in the same formula to improve the recognition performance of the formulas with long LATEX strings. To alleviate overfitting and further improve the recognition performance, we also propose a new dataset, Handwritten Formula Image Dataset (HFID), which contains 25 620 handwritten formula images collected from real life. We conduct extensive experiments to demonstrate the effectiveness of our proposed MDA module and HFID dataset and achieve state-of-the-art performances, 63.79% and 65.24% expression accuracy on CROHME 2014 and CROHME 2016, respectively.","volume":39,"issue":3,"firstpage":654,"lastpage":670,"year":2024,"type":"Regular Paper","research_area":["Computer Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1987-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1987-y?year=2024&issue=3","affiliations":["Chinese Academy of Sciences","University of Science & Technology of China, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2519-0","title":"When Crowdsourcing Meets Data Markets: A Fair Data Value Metric for Data Trading","authors":[{"last":"Liu","first":"Yang-Su"},{"last":"Zheng","first":"Zhen-Zhe"},{"last":"Wu","first":"Fan"},{"last":"Chen","first":"Gui-Hai"}],"keywords":["data trading","crowdsourcing","mechanism design","Shapley value"],"abstract":"Large-quantity and high-quality data is critical to the success of machine learning in diverse applications. Faced with the dilemma of data silos where data is difficult to circulate, emerging data markets attempt to break the dilemma by facilitating data exchange on the Internet. Crowdsourcing, on the other hand, is one of the important methods to efficiently collect large amounts of data with high-value in data markets. In this paper, we investigate the joint problem of efficient data acquisition and fair budget distribution across the crowdsourcing and data markets. We propose a new metric of data value as the uncertainty reduction of a Bayesian machine learning model by integrating the data into model training. Guided by this data value metric, we design a mechanism called Shapley Value Mechanism with Individual Rationality (SV-IR), in which we design a greedy algorithm with a constant approximation ratio to greedily select the most cost-efficient data brokers, and a fair compensation determination rule based on the Shapley value, respecting the individual rationality constraints. We further propose a fair reward distribution method for the data holders with various effort levels under the charge of a data broker. We demonstrate the fairness of the compensation determination rule and reward distribution rule by evaluating our mechanisms on two real-world datasets. The evaluation results also show that the selection algorithm in SV-IR could approach the optimal solution, and outperforms state-of-the-art methods.","volume":39,"issue":3,"firstpage":671,"lastpage":690,"year":2024,"type":"Regular Paper","research_area":["Education & Social Computing","Game Theory & Mechanism Design"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2519-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2519-0?year=2024&issue=3","affiliations":["Shanghai Jiao Tong University"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-3788-3","title":"DCFNet: Discriminant Correlation Filters Network for Visual Tracking","authors":[{"last":"Hu","first":"Wei-Ming"},{"last":"Wang","first":"Qiang"},{"last":"Gao","first":"Jin"},{"last":"Li","first":"Bing"},{"last":"Maybank","first":"Stephen"}],"keywords":["correlation filter","convolutional neural network (CNN)","visual tracking"],"abstract":"CNN (convolutional neural network) based real time trackers usually do not carry out online network update in order to maintain rapid tracking speed. This inevitably influences the adaptability to changes in object appearance. Correlation filter based trackers can update the model parameters online in real time. In this paper, we present an end-to-end lightweight network architecture, namely Discriminant Correlation Filter Network (DCFNet). A differentiable DCF (discriminant correlation filter) layer is incorporated into a Siamese network architecture in order to learn the convolutional features and the correlation filter simultaneously. The correlation filter can be efficiently updated online. In previous work, we introduced a joint scale-position space to the DCFNet, forming a scale DCFNet which carries out the predictions of object scale and position simultaneously. We combine the scale DCFNet with the convolutional-deconvolutional network, learning both the high-level embedding space representations and the low-level fine-grained representations for images. The adaptability of the fine-grained correlation analysis and the generalization capability of the semantic embedding are complementary for visual tracking. The back-propagation is derived in the Fourier frequency domain throughout the entire work, preserving the efficiency of the DCF. Extensive evaluations on the OTB (Object Tracking Benchmark) and VOT (Visual Object Tracking Challenge) datasets demonstrate that the proposed trackers have fast speeds, while maintaining tracking accuracy.","volume":39,"issue":3,"firstpage":691,"lastpage":714,"year":2024,"type":"Regular Paper","research_area":["Convolutional & Spiking Networks","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3788-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3788-3?year=2024&issue=3","affiliations":["Chinese Academy of Sciences","Institute of Automation, CAS","University of London","Birkbeck University London"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-1935-5","title":"An Empirical Study on Automated Test Generation Tools for Java: Effectiveness and Challenges","authors":[{"last":"Liu","first":"Xiang-Jun"},{"last":"Yu","first":"Ping"},{"last":"Ma","first":"Xiao-Xing"}],"keywords":["automated test generation","search-based software testing","random testing","symbolic execution"],"abstract":"Automated test generation tools enable test automation and further alleviate the low efficiency caused by writing hand-crafted test cases. However, existing automated tools are not mature enough to be widely used by software testing groups. This paper conducts an empirical study on the state-of-the-art automated tools for Java, i.e., EvoSuite, Randoop, JDoop, JTeXpert, T3, and Tardis. We design a test workflow to facilitate the process, which can automatically run tools for test generation, collect data, and evaluate various metrics. Furthermore, we conduct empirical analysis on these six tools and their related techniques from different aspects, i.e., code coverage, mutation score, test suite size, readability, and real fault detection ability. We discuss about the benefits and drawbacks of hybrid techniques based on experimental results. Besides, we introduce our experience in setting up and executing these tools, and summarize their usability and user-friendliness. Finally, we give some insights into automated tools in terms of test suite readability improvement, meaningful assertion generation, test suite reduction for random testing tools, and symbolic execution integration.","volume":39,"issue":3,"firstpage":715,"lastpage":736,"year":2024,"type":"Regular Paper","research_area":["Software Testing & Analysis"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1935-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1935-5?year=2024&issue=3","affiliations":["Nanjing University"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2007-6","title":"Neighborhood Combination Search for Single-Machine Scheduling with Sequence-Dependent Setup Time","authors":[{"last":"Liu","first":"Xiao-Lu"},{"last":"Xu","first":"Hong-Yun"},{"last":"Chen","first":"Jia-Ming"},{"last":"Su","first":"Zhou-Xing"},{"last":"Lyu","first":"Zhi-Peng"},{"last":"Ding","first":"Jun-Wen"}],"keywords":["single-machine scheduling","sequence-dependent setup time","neighborhood combination search","token-ring search","hybrid evolutionary algorithm"],"abstract":"In a local search algorithm, one of its most important features is the definition of its neighborhood which is crucial to the algorithm's performance. In this paper, we present an analysis of neighborhood combination search for solving the single-machine scheduling problem with sequence-dependent setup time with the objective of minimizing total weighted tardiness (SMSWT). First, We propose a new neighborhood structure named Block Swap (B1) which can be considered as an extension of the previously widely used Block Move (B2) neighborhood, and a fast incremental evaluation technique to enhance its evaluation efficiency. Second, based on the Block Swap and Block Move neighborhoods, we present two kinds of neighborhood structures: neighborhood union (denoted by B1 boolean OR B2) and token-ring search (denoted by B1 -> B2), both of which are combinations of B1 and B2. Third, we incorporate the neighborhood union and token-ring search into two representative metaheuristic algorithms: the Iterated Local Search Algorithm (ILSnew) and the Hybrid Evolutionary Algorithm (HEAnew) to investigate the performance of the neighborhood union and token-ring search. Extensive experiments show the competitiveness of the token-ring search combination mechanism of the two neighborhoods. Tested on the 120 public benchmark instances, our HEAnew has a highly competitive performance in solution quality and computational time compared with both the exact algorithms and recent metaheuristics. We have also tested the HEAnew algorithm with the selected neighborhood combination search to deal with the 64 public benchmark instances of the single-machine scheduling problem with sequence-dependent setup time. HEAnew is able to match the optimal or the best known results for all the 64 instances. In particular, the computational time for reaching the best well-known results for five challenging instances is reduced by at least 61.25%.","volume":39,"issue":3,"firstpage":737,"lastpage":752,"year":2024,"type":"Regular Paper","research_area":["Scheduling & Resource Allocation"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2007-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2007-6?year=2024&issue=3","affiliations":["National University of Defense Technology - China","Jianghan University","Huazhong University of Science & Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-0003-0","title":"Graph Accelerators-A Case for Sparse Data Processing","authors":[{"last":"Chen","first":"Wen-Guang"}],"keywords":[],"abstract":"","volume":39,"issue":2,"firstpage":243,"lastpage":244,"year":2024,"type":"Perspective","research_area":["GPU & Accelerator Architecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-0003-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-0003-0?year=2024&issue=2","affiliations":["Tsinghua University"],"type_origin":"Editorial Material","cover_doi":"10.1007/s11390-024-4150-0","topic_source":"cover_inherited"},{"doi":"10.1007/s11390-024-4150-0","title":"Towards High-Performance Graph Processing: From a Hardware/Software Co-Design Perspective","authors":[{"last":"Liao","first":"Xiao-Fei"},{"last":"Zhao","first":"Wen-Ju"},{"last":"Jin","first":"Hai"},{"last":"Yao","first":"Peng-Cheng"},{"last":"Huang","first":"Yu"},{"last":"Wang","first":"Qing-Gang"},{"last":"Zhao","first":"Jin"},{"last":"Zheng","first":"Long"},{"last":"Zhang","first":"Yu"},{"last":"Shao","first":"Zhi-Yuan"}],"keywords":["graph processing","hardware accelerator","software system","high performance","ecosystem"],"abstract":"Graph processing has been widely used in many scenarios, from scientific computing to artificial intelligence. Graph processing exhibits irregular computational parallelism and random memory accesses, unlike traditional workloads. Therefore, running graph processing workloads on conventional architectures (e.g., CPUs and GPUs) often shows a significantly low compute-memory ratio with few performance benefits, which can be, in many cases, even slower than a specialized single-thread graph algorithm. While domain-specific hardware designs are essential for graph processing, it is still challenging to transform the hardware capability to performance boost without coupled software codesigns. This article presents a graph processing ecosystem from hardware to software. We start by introducing a series of hardware accelerators as the foundation of this ecosystem. Subsequently, the codesigned parallel graph systems and their distributed techniques are presented to support graph applications. Finally, we introduce our efforts on novel graph applications and hardware architectures. Extensive results show that various graph applications can be efficiently accelerated in this graph processing ecosystem.","volume":39,"issue":2,"firstpage":245,"lastpage":266,"year":2024,"type":"Regular Paper","research_area":["GPU & Accelerator Architecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4150-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4150-0?year=2024&issue=2","affiliations":["Huazhong University of Science & Technology","Zhejiang Laboratory"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-0002-1","title":"The Preface","authors":[{"last":"Wu","first":"En-Hua"},{"last":"Sheng","first":"Bin"}],"keywords":[],"abstract":"","volume":39,"issue":2,"firstpage":267,"lastpage":268,"year":2024,"type":"Regular Paper","research_area":[],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-0002-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-0002-1?year=2024&issue=2","affiliations":["Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Institute of Software, CAS","Shanghai Jiao Tong University"],"type_origin":"Editorial Material"},{"doi":"10.1007/s11390-024-3408-x","title":"Computational Approaches for Traditional Chinese Painting: From the Six Principles of Painting Perspective","authors":[{"last":"Zhang","first":"Wei"},{"last":"Zhang","first":"Jian-Wei"},{"last":"Wong","first":"Kam-Kwai"},{"last":"Wang","first":"Yi-Fang"},{"last":"Feng","first":"Ying-Chao-Jie"},{"last":"Wang","first":"Lu-Wei"},{"last":"Chen","first":"Wei"}],"keywords":["traditional Chinese painting (TCP)","digital humanities","cultural heritage","computer vision","deep learning"],"abstract":"Traditional Chinese painting (TCP) is an invaluable cultural heritage resource and a unique visual art style. In recent years, there has been a growing emphasis on the digitalization of TCP for cultural preservation and revitalization. The resulting digital copies have enabled the advancement of computational methods for a structured and systematic understanding of TCP. To explore this topic, we conduct an in-depth analysis of 94 pieces of literature. We examine the current use of computer technologies on TCP from three perspectives, based on numerous conversations with specialists. First, in light of the Six Principles of Painting theory, we categorize the articles according to their research focus on artistic elements. Second, we create a four-stage framework to illustrate the purposes of TCP applications. Third, we summarize the popular computational techniques applied to TCP. This work also provides insights into potential applications and prospects, with professional opinion.","volume":39,"issue":2,"firstpage":269,"lastpage":285,"year":2024,"type":"Survey","research_area":["Computer Vision","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3408-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3408-x?year=2024&issue=2","affiliations":["Zhejiang University","Hong Kong University of Science & Technology","Northwestern University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3679-2","title":"A Transformer-Assisted Cascade Learning Network for Choroidal Vessel Segmentation","authors":[{"last":"Wen","first":"Yang"},{"last":"Wu","first":"Yi-Lin"},{"last":"Bi","first":"Lei"},{"last":"Shi","first":"Wu-Zhen"},{"last":"Liu","first":"Xiao-Xiao"},{"last":"Xu","first":"Yu-Peng"},{"last":"Xu","first":"Xun"},{"last":"Cao","first":"Wen-Ming"},{"last":"Feng","first":"David Dagan"}],"keywords":["choroidal vessel segmentation","optical coherence tomography (OCT)","Transformer-assisted cascade learning","retinal fluid segmentation","multi-scale feature extraction"],"abstract":"As a highly vascular eye part, the choroid is crucial in various eye disease diagnoses. However, limited research has focused on the inner structure of the choroid due to the challenges in obtaining sufficient accurate label data, particularly for the choroidal vessels. Meanwhile, the existing direct choroidal vessel segmentation methods for the intelligent diagnosis of vascular assisted ophthalmic diseases are still unsatisfactory due to noise data, while the synergistic segmentation methods compromise vessel segmentation performance for the choroid layer segmentation tasks. Common cascaded structures grapple with error propagation during training. To address these challenges, we propose a cascade learning segmentation method for the inner vessel structures of the choroid in this paper. Specifically, we propose Transformer-Assisted Cascade Learning Network (TACLNet) for choroidal vessel segmentation, which comprises a two-stage training strategy: pre-training for choroid layer segmentation and joint training for choroid layer and choroidal vessel segmentation. We also enhance the skip connection structures by introducing a multi-scale subtraction connection module designated as MSC, capturing differential and detailed information simultaneously. Additionally, we implement an auxiliary Transformer branch named ATB to integrate global features into the segmentation process. Experimental results exhibit that our method achieves the state-of-the-art performance for choroidal vessel segmentation. Besides, we further validate the significant superiority of the proposed method for retinal fluid segmentation in optical coherence tomography (OCT) scans on a publicly available dataset. All these fully prove that our TACLNet contributes to the advancement of choroidal vessel segmentation and is of great significance for ophthalmic research and clinical application.","volume":39,"issue":2,"firstpage":286,"lastpage":304,"year":2024,"type":"Regular Paper","research_area":["Transformers & Attention"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3679-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3679-2?year=2024&issue=2","affiliations":["Shenzhen University","Shanghai Jiao Tong University","University of Sydney"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-3596-9","title":"SinGRAV: Learning a Generative Radiance Volume from a Single Natural Scene","authors":[{"last":"Wang","first":"Yu-Jie"},{"last":"Chen","first":"Xue-Lin"},{"last":"Chen","first":"Bao-Quan"}],"keywords":["generative model","neural radiance field","3D scene generation"],"abstract":"We present SinGRAV, an attempt to learn a generative radiance volume from multi-view observations of a single natural scene, in stark contrast to existing category-level 3D generative models that learn from images of many object-centric scenes. Inspired by SinGAN, we also learn the internal distribution of the input scene, which necessitates our key designs w.r.t. the scene representation and network architecture. Unlike popular multi-layer perceptrons (MLP)-based architectures, we particularly employ convolutional generators and discriminators, which inherently possess spatial locality bias, to operate over voxelized volumes for learning the internal distribution over a plethora of overlapping regions. On the other hand, localizing the adversarial generators and discriminators over confined areas with limited receptive fields easily leads to highly implausible geometric structures in the spatial. Our remedy is to use spatial inductive bias and joint discrimination on geometric clues in the form of 2D depth maps. This strategy is effective in improving spatial arrangement while incurring negligible additional computational cost. Experimental results demonstrate the ability of SinGRAV in generating plausible and diverse variations from a single scene, the merits of SinGRAV over state-of-the-art generative neural scene models, and the versatility of SinGRAV by its use in a variety of applications. Code and data will be released to facilitate further research.","volume":39,"issue":2,"firstpage":305,"lastpage":319,"year":2024,"type":"Regular Paper","research_area":["Generative Models"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3596-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3596-9?year=2024&issue=2","affiliations":["Shandong University","Chinese Academy of Sciences","Institute of Automation, CAS","Peking University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3414-z","title":"WavEnhancer: Unifying Wavelet and Transformer for Image Enhancement","authors":[{"last":"Li","first":"Zi-Nuo"},{"last":"Chen","first":"Xu-Hang"},{"last":"Guo","first":"Shu-Na"},{"last":"Wang","first":"Shu-Qiang"},{"last":"Pun","first":"Chi-Man"}],"keywords":["transformer","wavelet transform","image enhancement"],"abstract":"Image enhancement is a widely used technique in digital image processing that aims to improve image aesthetics and visual quality. However, traditional methods of enhancement based on pixel-level or global-level modifications have limited effectiveness. Recently, as learning-based techniques gain popularity, various studies are now focusing on utilizing networks for image enhancement. However, these techniques often fail to optimize image frequency domains. This study addresses this gap by introducing a transformer-based model for improving images in the wavelet domain. The proposed model refines various frequency bands of an image and prioritizes local details and high-level features. Consequently, the proposed technique produces superior enhancement results. The proposed model's performance was assessed through comprehensive benchmark evaluations, and the results suggest it outperforms the state-of-the-art techniques.","volume":39,"issue":2,"firstpage":336,"lastpage":345,"year":2024,"type":"Regular Paper","research_area":["Computer Vision","Transformers & Attention"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3414-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3414-z?year=2024&issue=2","affiliations":["University of Macau","Chinese Academy of Sciences","Shenzhen Institute of Advanced Technology, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3538-1","title":"Enhancing Storage Efficiency and Performance: A Survey of Data Partitioning Techniques","authors":[{"last":"Liu","first":"Peng-Ju"},{"last":"Li","first":"Cui-Ping"},{"last":"Chen","first":"Hong"}],"keywords":["data partitioning","survey","partitioning feature","partition generation","partition update"],"abstract":"Data partitioning techniques are pivotal for optimal data placement across storage devices, thereby enhancing resource utilization and overall system throughput. However, the design of effective partition schemes faces multiple challenges, including considerations of the cluster environment, storage device characteristics, optimization objectives, and the balance between partition quality and computational efficiency. Furthermore, dynamic environments necessitate robust partition detection mechanisms. This paper presents a comprehensive survey structured around partition deployment environments, outlining the distinguishing features and applicability of various partitioning strategies while delving into how these challenges are addressed. We discuss partitioning features pertaining to database schema, table data, workload, and runtime metrics. We then delve into the partition generation process, segmenting it into initialization and optimization stages. A comparative analysis of partition generation and update algorithms is provided, emphasizing their suitability for different scenarios and optimization objectives. Additionally, we illustrate the applications of partitioning in prevalent database products and suggest potential future research directions and solutions. This survey aims to foster the implementation, deployment, and updating of high-quality partitions for specific system scenarios.","volume":39,"issue":2,"firstpage":346,"lastpage":368,"year":2024,"type":"Survey","research_area":["Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3538-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3538-1?year=2024&issue=2","affiliations":["Renmin University of China"],"type_origin":"Review"},{"doi":"10.1007/s11390-022-1751-3","title":"SHA: QoS-Aware Software and Hardware Auto-Tuning for Database Systems","authors":[{"last":"Li","first":"Jin"},{"last":"Chen","first":"Quan"},{"last":"Tang","first":"Xiao-Xin"},{"last":"Guo","first":"Min-Yi"}],"keywords":["auto-tuning","database configuration","joint tuning","utilization","quality-of-service (QoS)"],"abstract":"While databases are widely-used in commercial user-facing services that have stringent quality-of-service (QoS) requirement, it is crucial to ensure their good performance and minimize the hardware usage at the same time. Our investigation shows that the optimal DBMS (database management system) software configuration varies for different user request patterns (i.e., workloads) and hardware configurations. It is challenging to identify the optimal software and hardware configurations for a database workload, because DBMSs have hundreds of tunable knobs, the effect of tuning a knob depends on other knobs, and the dependency relationship changes under different hardware configurations. In this paper, we propose SHA, a software and hardware auto-tuning system for DBMSs. SHA is comprised of a scaling-based performance predictor, a reinforcement learning (RL) based software tuner, and a QoS-aware resource reallocator. The performance predictor predicts its optimal performance with different hardware configurations and identifies the minimum amount of resources for satisfying its performance requirement. The software tuner fine-tunes the DBMS software knobs to optimize the performance of the workload. The resource reallocator assigns the saved resources to other applications to improve resource utilization without incurring QoS violation of the database workload. Experimental results show that SHA improves the performance of database workloads by 9.9% on average compared with a state-of-the-art solution when the hardware configuration is fixed, and improves 43.2% of resource utilization while ensuring the QoS.","volume":39,"issue":2,"firstpage":369,"lastpage":383,"year":2024,"type":"Regular Paper","research_area":["Databases & Query Processing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1751-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1751-3?year=2024&issue=2","affiliations":["Shanghai Jiao Tong University","Shanghai University of Finance & Economics"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-1840-y","title":"SAIH: A Scalable Evaluation Methodology for Understanding AI Performance Trend on HPC Systems","authors":[{"last":"Du","first":"Jiang-Su"},{"last":"Li","first":"Dong-Sheng"},{"last":"Wen","first":"Ying-Peng"},{"last":"Jiang","first":"Jia-Zhi"},{"last":"Huang","first":"Dan"},{"last":"Liao","first":"Xiang-Ke"},{"last":"Lu","first":"Yu-Tong"}],"keywords":["high-performance computing (HPC)","deep learning","parallel computing","AI framework"],"abstract":"Novel artificial intelligence (AI) technology has expedited various scientific research, e.g., cosmology, physics, and bioinformatics, inevitably becoming a significant category of workload on high-performance computing (HPC) systems. Existing AI benchmarks tend to customize well-recognized AI applications, so as to evaluate the AI performance of HPC systems under the predefined problem size, in terms of datasets and AI models. However, driven by novel AI technology, most of AI applications are evolving fast on models and datasets to achieve higher accuracy and be applicable to more scenarios. Due to the lack of scalability on the problem size, static AI benchmarks might be under competent to help understand the performance trend of evolving AI applications on HPC systems, in particular, the scientific AI applications on large-scale systems. In this paper, we propose a scalable evaluation methodology (SAIH) for analyzing the AI performance trend of HPC systems with scaling the problem sizes of customized AI applications. To enable scalability, SAIH builds a set of novel mechanisms for augmenting problem sizes. As the data and model constantly scale, we can investigate the trend and range of AI performance on HPC systems, and further diagnose system bottlenecks. To verify our methodology, we augment a cosmological AI application to evaluate a real HPC system equipped with GPUs as a case study of SAIH. With data and model augment, SAIH can progressively evaluate the AI performance trend of HPC systems, e.g., increasing from 5.2% to 59.6% of the peak theoretical hardware performance. The evaluation results are analyzed and summarized into insight findings on performance issues. For instance, we find that the AI application constantly consumes the I/O bandwidth of the shared parallel file system during its iteratively training model. If I/O contention exists, the shared parallel file system might become a bottleneck.","volume":39,"issue":2,"firstpage":384,"lastpage":400,"year":2024,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","High-Performance & Parallel Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1840-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1840-y?year=2024&issue=2","affiliations":["Sun Yat Sen University"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1632-9","title":"AutoQNN: An End-to-End Framework for Automatically Quantizing Neural Networks","authors":[{"last":"Gong","first":"Cheng"},{"last":"Lu","first":"Ye"},{"last":"Dai","first":"Su-Rong"},{"last":"Deng","first":"Qian"},{"last":"Du","first":"Cheng-Kun"},{"last":"Li","first":"Tao"}],"keywords":["automatic quantization","mixed precision","quantizing scheme search","quantizing precision learning","quantized architecture generation"],"abstract":"Exploring the expected quantizing scheme with suitable mixed-precision policy is the key to compress deep neural networks (DNNs) in high efficiency and accuracy. This exploration implies heavy workloads for domain experts, and an automatic compression method is needed. However, the huge search space of the automatic method introduces plenty of computing budgets that make the automatic process challenging to be applied in real scenarios. In this paper, we propose an end-to-end framework named AutoQNN, for automatically quantizing different layers utilizing different schemes and bitwidths without any human labor. AutoQNN can seek desirable quantizing schemes and mixed-precision policies for mainstream DNN models efficiently by involving three techniques: quantizing scheme search (QSS), quantizing precision learning (QPL), and quantized architecture generation (QAG). QSS introduces five quantizing schemes and defines three new schemes as a candidate set for scheme search, and then uses the Differentiable Neural Architecture Search (DNAS) algorithm to seek the layer- or model-desired scheme from the set. QPL is the first method to learn mixed-precision policies by reparameterizing the bitwidths of quantizing schemes, to the best of our knowledge. QPL optimizes both classification loss and precision loss of DNNs efficiently and obtains the relatively optimal mixed-precision model within limited model size and memory footprint. QAG is designed to convert arbitrary architectures into corresponding quantized ones without manual intervention, to facilitate end-to-end neural network quantization. We have implemented AutoQNN and integrated it into Keras. Extensive experiments demonstrate that AutoQNN can consistently outperform state-of-the-art quantization. For 2-bit weight and activation of AlexNet and ResNet18, AutoQNN can achieve the accuracy results of 59.75% and 68.86%, respectively, and obtain accuracy improvements by up to 1.65% and 1.74%, respectively, compared with state-of-the-art methods. Especially, compared with the full-precision AlexNet and ResNet18, the 2-bit models only slightly incur accuracy degradation by 0.26% and 0.76%, respectively, which can fulfill practical application demands.","volume":39,"issue":2,"firstpage":401,"lastpage":420,"year":2024,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1632-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1632-9?year=2024&issue=2","affiliations":["Nankai University","Chinese Academy of Sciences","Institute of Computing Technology, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2121-5","title":"Qubit Mapping Based on Tabu Search","authors":[{"last":"Jiang","first":"Hui"},{"last":"Deng","first":"Yu-Xin"},{"last":"Xu","first":"Ming"}],"keywords":["quantum computing","qubit mapping","initial mapping","tabu search","logical circuit"],"abstract":"The goal of qubit mapping is to map a logical circuit to a physical device by introducing additional gates as few as possible in an acceptable amount of time. We present an effective approach called Tabu Search Based Adjustment (TSA) algorithm to construct the mappings. It consists of two key steps: one is making use of a combined subgraph isomorphism and completion to initialize some candidate mappings, and the other is dynamically modifying the mappings by TSA. Our experiments show that, compared with state-of-the-art methods, TSA can generate mappings with a smaller number of additional gates and have better scalability for large-scale circuits.","volume":39,"issue":2,"firstpage":421,"lastpage":433,"year":2024,"type":"Regular Paper","research_area":["Quantum Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2121-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2121-5?year=2024&issue=2","affiliations":["East China Normal University"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1670-3","title":"Understanding and Detecting Inefficient Image Displaying Issues in Android Apps","authors":[{"last":"Li","first":"Wen-Jie"},{"last":"Ma","first":"Jun"},{"last":"Jiang","first":"Yan-Yan"},{"last":"Xu","first":"Chang"},{"last":"Ma","first":"Xiao-Xing"}],"keywords":["Android application (app)","inefficient image displaying (IID)","performance","empirical study","static analysis"],"abstract":"Mobile applications (apps for short) often need to display images. However, inefficient image displaying (IID) issues are pervasive in mobile apps, and can severely impact app performance and user experience. This paper first establishes a descriptive framework for the image displaying procedures of IID issues. Based on the descriptive framework, we conduct an empirical study of 216 real-world IID issues collected from 243 popular open-source Android apps to validate the presence and severity of IID issues, and then shed light on these issues' characteristics to support research on effective issue detection. With the findings of this study, we propose a static IID issue detection tool TAPIR and evaluate it with 243 real-world Android apps. Encouragingly, 49 and 64 previously-unknown IID issues in two different versions of 16 apps reported by TAPIR are manually confirmed as true positives, respectively, and 16 previously-unknown IID issues reported by TAPIR have been confirmed by developers and 13 have been fixed. Then, we further evaluate the performance impact of these detected IID issues and the performance improvement if they are fixed. The results demonstrate that the IID issues detected by TAPIR indeed cause significant performance degradation, which further show the effectiveness and efficiency of TAPIR.","volume":39,"issue":2,"firstpage":434,"lastpage":459,"year":2024,"type":"Regular Paper","research_area":["Software Testing & Analysis"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1670-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1670-3?year=2024&issue=2","affiliations":["Nanjing University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-1743-6","title":"CAT: A Simple yet Effective Cross-Attention Transformer for One-Shot Object Detection","authors":[{"last":"Lin","first":"Wei-Dong"},{"last":"Deng","first":"Yu-Yan"},{"last":"Gao","first":"Yang"},{"last":"Wang","first":"Ning"},{"last":"Liu","first":"Ling-Qiao"},{"last":"Zhang","first":"Lei"},{"last":"Wang","first":"Peng"}],"keywords":["one-shot object detection","Transformer","attention mechanism"],"abstract":"Given a query patch from a novel class, one-shot object detection aims to detect all instances of this class in a target image through the semantic similarity comparison. However, due to the extremely limited guidance in the novel class as well as the unseen appearance difference between the query and target instances, it is difficult to appropriately exploit their semantic similarity and generalize well. To mitigate this problem, we present a universal Cross-Attention Transformer (CAT) module for accurate and efficient semantic similarity comparison in one-shot object detection. The proposed CAT utilizes the transformer mechanism to comprehensively capture bi-directional correspondence between any paired pixels from the query and the target image, which empowers us to sufficiently exploit their semantic characteristics for accurate similarity comparison. In addition, the proposed CAT enables feature dimensionality compression for inference speedup without performance loss. Extensive experiments on three object detection datasets MS-COCO, PASCAL VOC and FSOD under the one-shot setting demonstrate the effectiveness and efficiency of our model, e.g., it surpasses CoAE, a major baseline in this task, by 1.0% in average precision (AP) on MS-COCO and runs nearly 2.5 times faster.","volume":39,"issue":2,"firstpage":460,"lastpage":471,"year":2024,"type":"Regular Paper","research_area":["Computer Vision","Transformers & Attention"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-1743-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-1743-6?year=2024&issue=2","affiliations":["Northwestern Polytechnical University","Adelaide University","University of Adelaide"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-1611-9","title":"Random Subspace Sampling for Classification with Missing Data","authors":[{"last":"Cao","first":"Yun-Hao"},{"last":"Wu","first":"Jian-Xin"}],"keywords":["missing data","random subspace","neural network","ensemble learning"],"abstract":"Many real-world datasets suffer from the unavoidable issue of missing values, and therefore classification with missing data has to be carefully handled since inadequate treatment of missing values will cause large errors. In this paper, we propose a random subspace sampling method, RSS, by sampling missing items from the corresponding feature histogram distributions in random subspaces, which is effective and efficient at different levels of missing data. Unlike most established approaches, RSS does not train on fixed imputed datasets. Instead, we design a dynamic training strategy where the filled values change dynamically by resampling during training. Moreover, thanks to the sampling strategy, we design an ensemble testing strategy where we combine the results of multiple runs of a single model, which is more efficient and resource-saving than previous ensemble methods. Finally, we combine these two strategies with the random subspace method, which makes our estimations more robust and accurate. The effectiveness of the proposed RSS method is well validated by experimental studies.","volume":39,"issue":2,"firstpage":472,"lastpage":486,"year":2024,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1611-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1611-9?year=2024&issue=2","affiliations":["Nanjing University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-0001-2","title":"Technical Perspective: Research on General-Purpose Brain-Inspired Computing Systems","authors":[{"last":"Rhodes","first":"Oliver"}],"keywords":[],"abstract":"","volume":39,"issue":1,"firstpage":1,"lastpage":3,"year":2024,"type":"Perspective","research_area":["Processor & Microarchitecture","Convolutional & Spiking Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-0001-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-0001-2?year=2024&issue=1","affiliations":["University of Manchester"],"type_origin":"Editorial Material","cover_doi":"10.1007/s11390-023-4002-3","topic_source":"cover_inherited"},{"doi":"10.1007/s11390-023-4002-3","title":"Research on General-Purpose Brain-Inspired Computing Systems","authors":[{"last":"Qu","first":"Peng"},{"last":"Ji","first":"Xing-Long"},{"last":"Chen","first":"Jia-Jie"},{"last":"Pang","first":"Meng"},{"last":"Li","first":"Yu-Chen"},{"last":"Liu","first":"Xiao-Yi"},{"last":"Zhang","first":"You-Hui"}],"keywords":["brain-inspired computing","neuromorphic chip","compiler","spiking neural network"],"abstract":"Brain-inspired computing is a new technology that draws on the principles of brain science and is oriented to the efficient development of artificial general intelligence (AGI), and a brain-inspired computing system is a hierarchical system composed of neuromorphic chips, basic software and hardware, and algorithms/applications that embody this technology. While the system is developing rapidly, it faces various challenges and opportunities brought by interdisciplinary research, including the issue of software and hardware fragmentation. This paper analyzes the status quo of brain-inspired computing systems. Enlightened by some design principle and methodology of general-purpose computers, it is proposed to construct “general-purpose” brain-inspired computing systems. A general-purpose brain-inspired computing system refers to a brain-inspired computing hierarchy constructed based on the design philosophy of decoupling software and hardware, which can flexibly support various brain-inspired computing applications and neuromorphic chips with different architectures. Further, this paper introduces our recent work in these aspects, including the ANN (artificial neural network)/SNN (spiking neural network) development tools, the hardware agnostic compilation infrastructure, and the chip micro-architecture with high flexibility of programming and high performance; these studies show that the “general-purpose” system can remarkably improve the efficiency of application development and enhance the productivity of basic software, thereby being conductive to accelerating the advancement of various brain-inspired algorithms and applications. We believe that this is the key to the collaborative research and development, and the evolution of applications, basic software and chips in this field, and conducive to building a favorable software/hardware ecosystem of brain-inspired computing.","volume":39,"issue":1,"firstpage":4,"lastpage":21,"year":2024,"type":"Survey","research_area":["Processor & Microarchitecture","Convolutional & Spiking Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-4002-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-4002-3?year=2024&issue=1","affiliations":["Tsinghua University"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-024-4035-2","title":"VPI: Vehicle Programming Interface for Vehicle Computing","authors":[{"last":"Wu","first":"Bao-Fu"},{"last":"Zhong","first":"Ren"},{"last":"Wang","first":"Yuxin"},{"last":"Wan","first":"Jian"},{"last":"Zhang","first":"Ji-Lin"},{"last":"Shi","first":"Weisong"}],"keywords":["software-defined vehicle (SDV)","vehicle computing (VC)","vehicle programming interface (VPI)","autonomous system"],"abstract":"The emergence of software-defined vehicles (SDVs), combined with autonomous driving technologies, has enabled a new era of vehicle computing (VC), where vehicles serve as a mobile computing platform. However, the interdisciplinary complexities of automotive systems and diverse technological requirements make developing applications for autonomous vehicles challenging. To simplify the development of applications running on SDVs, we propose a comprehensive suite of vehicle programming interfaces (VPIs). In this study, we rigorously explore the nuanced requirements for application development within the realm of VC, centering our analysis on the architectural intricacies of the Open Vehicular Data Analytics Platform (OpenVDAP). We then detail our creation of a comprehensive suite of standardized VPIs, spanning five critical categories: Hardware, Data, Computation, Service, and Management, to address these evolving programming requirements. To validate the design of VPIs, we conduct experiments using the indoor autonomous vehicle, Zebra, and develop the OpenVDAP prototype system. By comparing it with the industry-influential AUTOSAR interface, our VPIs demonstrate significant enhancements in programming efficiency, marking an important advancement in the field of SDV application development. We also show a case study and evaluate its performance. Our work highlights that VPIs significantly enhance the efficiency of developing applications on VC. They meet both current and future technological demands and propel the software-defined automotive industry toward a more interconnected and intelligent future.","volume":39,"issue":1,"firstpage":22,"lastpage":44,"year":2024,"type":"Regular Paper","research_area":["Robotics & Control"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-4035-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-4035-2?year=2024&issue=1","affiliations":["Hangzhou Dianzi University","Wayne State University","University of Delaware"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-3011-6","title":"10-Million Atoms Simulation of First-Principle Package LS3DF","authors":[{"last":"Yan","first":"Yu-Jin"},{"last":"Li","first":"Hai-Bo"},{"last":"Zhao","first":"Tong"},{"last":"Wang","first":"Lin-Wang"},{"last":"Shi","first":"Lin"},{"last":"Liu","first":"Tao"},{"last":"Tan","first":"Guang-Ming"},{"last":"Jia","first":"Wei-Le"},{"last":"Sun","first":"Ning-Hui"}],"keywords":["single instruction multiple thread accelerator","electronic structure","high-performance computing","linearly scaling three-dimensional fragment (LS3DF)"],"abstract":"The growing demand for semiconductor devices simulation poses a big challenge for large-scale electronic structure calculations. Among various methods, the linearly scaling three-dimensional fragment (LS3DF) method exhibits excellent scalability in large-scale simulations. Based on algorithmic and system-level optimizations, we propose a highly scalable and highly efficient implementation of LS3DF on a domestic heterogeneous supercomputer equipped with accelerators. In terms of algorithmic optimizations, the original all-band conjugate gradient algorithm is refined to achieve faster convergence, and mixed precision computing is adopted to increase overall efficiency. In terms of system-level optimizations, the original two-layer parallel structure is replaced by a coarse-grained parallel method. Optimization strategies such as multi-stream, kernel fusion, and redundant computation removal are proposed to increase further utilization of the computational power provided by the heterogeneous machines. As a result, our optimized LS3DF can scale to a 10-million silicon atoms system, attaining a peak performance of 34.8 PFLOPS (21.2% of the peak). All the improvements can be adapted to the next-generation supercomputers for larger simulations.","volume":39,"issue":1,"firstpage":45,"lastpage":62,"year":2024,"type":"Regular Paper","research_area":["GPU & Accelerator Architecture","High-Performance & Parallel Computing","Point Cloud & 3D Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3011-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3011-6?year=2024&issue=1","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS","Huawei Technologies"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2565-7","title":"Approximate Similarity-Aware Compression for Non-Volatile Main Memory","authors":[{"last":"Chen","first":"Zhang-Yu"},{"last":"Hua","first":"Yu"},{"last":"Zuo","first":"Peng-Fei"},{"last":"Sun","first":"Yuan-Yuan"},{"last":"Guo","first":"Yun-Cheng"}],"keywords":["approximate computing","data compression","memory architecture","non-volatile memory"],"abstract":"Image bitmaps, i.e., data containing pixels and visual perception, have been widely used in emerging applications for pixel operations while consuming lots of memory space and energy. Compared with legacy DRAM (dynamic random access memory), non-volatile memories (NVMs) are suitable for bitmap storage due to the salient features of high density and intrinsic durability. However, writing NVMs suffers from higher energy consumption and latency compared with read accesses. Existing precise or approximate compression schemes in NVM controllers show limited performance for bitmaps due to the irregular data patterns and variance in bitmaps. We observe the pixel-level similarity when writing bitmaps due to the analogous contents in adjacent pixels. By exploiting the pixel-level similarity, we propose SimCom, an approximate similarity-aware compression scheme in the NVM module controller, to efficiently compress data for each write access on-the-fly. The idea behind SimCom is to compress continuous similar words into the pairs of base words with runs. The storage costs for small runs are further mitigated by reusing the least significant bits of base words. SimCom adaptively selects an appropriate compression mode for various bitmap formats, thus achieving an efficient trade-off between quality and memory performance. We implement SimCom on GEM5/zsim with NVMain and evaluate the performance with real-world image/video workloads. Our results demonstrate the efficacy and efficiency of our SimCom with an efficient quality-performance trade-off.","volume":39,"issue":1,"firstpage":63,"lastpage":81,"year":2024,"type":"Regular Paper","research_area":["Approximate Computing & Circuits"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2565-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2565-7?year=2024&issue=1","affiliations":["Huazhong University of Science & Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-1601-y","title":"DIR: Dynamic Request Interleaving for Improving the Read Performance of Aged Solid-State Drives","authors":[{"last":"Nie","first":"Shi-Qiang"},{"last":"Zhang","first":"Chi"},{"last":"Wu","first":"Wei-Guo"}],"keywords":["triple-layer cell solid-state drive (TLC SSD)","performance","interleaving data","unbalanced bit error rate"],"abstract":"Triple-level cell (TLC) NAND flash is increasingly adopted to build solid-state drives (SSDs) for modern computer systems. While TLC NAND flash effectively improves storage density, it faces severe reliability issues; in particular, the pages exhibit different raw bit error rates (RBERs). Integrating strong low-density parity-check (LDPC) code helps to improve reliability but suffers from prolonged and proportional read latency due to multiple read retries for worse pages. The straightforward idea is that dispersing page-size data across several pages in different types can achieve a lower average RBER and reduce the read latency. However, directly implementing this simple idea into flash translation layer (FTL) induces the read amplification issue as one logic page residing in more than one physical page brings several read operations. In this paper, we propose the Dynamic Request Interleaving (DIR) technology for improving the performance of TLC NAND flash-based SSDs, in particular, the aged ones with large RBERs. DIR exploits the observation that the latency of an I/O request is determined, without considering the queuing time, by the access of the slowest device page, i.e., the page that has the highest RBER. By grouping consecutive logical pages that have high locality and interleaving their encoded data in different types of device pages that have different RBERs, DIR effectively reduces the number of read retries for LDPC with limited read amplification. To meet the requirement of allocating hybrid page types for interleaved data, we also design a page-interleaving friendly page allocation scheme, which splits all the planes into multi-plane regions for storing the interleaved data and single-plane regions for storing the normal data. The pages in the multi-plane region can be read/written in parallel by the proposed multi-plane command and avoid the read amplification issue. Based on the DIR scheme and the proposed page allocation scheme, we build DIR-enable FTL, which integrates the proposed schemes into the FTL with some modifications. Our experimental results show that adopting DIR in aged SSDs exploits nearly 33% locality from I/O requests and, on average, reduces 43% read latency over conventional aged SSDs.","volume":39,"issue":1,"firstpage":82,"lastpage":98,"year":2024,"type":"Regular Paper","research_area":["Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1601-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1601-y?year=2024&issue=1","affiliations":["Xi'an Jiaotong University"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-3964-5","title":"CFP: A Coherence-Free Processor Design","authors":[{"last":"Yang","first":"Franklin"}],"keywords":["multiprocessor","multitasking","cache","coherence","snoopy"],"abstract":"This paper presents the design of a Coherence-Free Processor (CFP) that enables a scalable multiprocessor by eliminating cache coherence operations in both hardware and software. The CFP uses a coherence-free cache (CFC) that can improve the cost-effectiveness and performance-effectiveness of the existing multiprocessors for commonly used workloads. The CFC is feasible because not all program data that reside in a multiprocessor cache need to be accessed by other processors, and private caches at level 1 (L1) and level 2 (L2) facilitate this method of sharing. Reentrant programs are specifically designed to protect their data from modification by other tasks. Program data that are modified but not shared with other tasks do not require a coherence protocol. Adding processors reduces the multitasking queue, reducing elapsed time. Simultaneous execution replaces concurrent execution.","volume":39,"issue":1,"firstpage":99,"lastpage":102,"year":2024,"type":"Regular Paper","research_area":["Processor & Microarchitecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3964-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3964-5?year=2024&issue=1","affiliations":["IBM Systems","Smith Barney, New York","Mortgage Backed Securities"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-1535-4","title":"An Online Algorithm Based on Replication for Using Spot Instances in IaaS Clouds","authors":[{"last":"Xu","first":"Zhi-Wei"},{"last":"Pan","first":"Li"},{"last":"Liu","first":"Shi-Jun"}],"keywords":["Infrastructure-as-a-Service (IaaS) cloud","cost management","competitive analysis","online algorithm","spot instance"],"abstract":"Infrastructure-as-a-Service (IaaS) cloud platforms offer resources with diverse buying options. Users can run an instance on the on-demand market which is stable but expensive or on the spot market with a significant discount. However, users have to carefully weigh the low cost of spot instances against their poor availability. Spot instances will be revoked when the revocation event occurs. Thus, an important problem that an IaaS user faces now is how to use spot instances in a cost-effective and low-risk way. Based on the replication-based fault tolerance mechanism, we propose an online termination algorithm that optimizes the cost of using spot instances while ensuring operational stability. We prove that in most cases, the cost of our proposed online algorithm will not exceed twice the minimum cost of the optimal offline algorithm that knows the exact future a priori. Through a large number of experiments, we verify that our algorithm in most cases has a competitive ratio of no more than 2, and in other cases it can also reach the guaranteed competitive ratio.","volume":39,"issue":1,"firstpage":103,"lastpage":115,"year":2024,"type":"Regular Paper","research_area":["Scheduling & Resource Allocation"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1535-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1535-4?year=2024&issue=1","affiliations":["Shandong University"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1629-9","title":"Online Nonstop Task Management for Storm-Based Distributed Stream Processing Engines","authors":[{"last":"Zhang","first":"Zhou"},{"last":"Jin","first":"Pei-Quan"},{"last":"Xie","first":"Xi-Ke"},{"last":"Wang","first":"Xiao-Liang"},{"last":"Liu","first":"Rui-Cheng"},{"last":"Wan","first":"Shou-Hong"}],"keywords":["distributed stream processing engine (DSPE)","Apache Storm","online task migration","online task deployment"],"abstract":"Most distributed stream processing engines (DSPEs) do not support online task management and cannot adapt to time-varying data flows. Recently, some studies have proposed online task deployment algorithms to solve this problem. However, these approaches do not guarantee the Quality of Service (QoS) when the task deployment changes at runtime, because the task migrations caused by the change of task deployments will impose an exorbitant cost. We study one of the most popular DSPEs, Apache Storm, and find out that when a task needs to be migrated, Storm has to stop the resource (implemented as a process of Worker in Storm) where the task is deployed. This will lead to the stop and restart of all tasks in the resource, resulting in the poor performance of task migrations. Aiming to solve this problem, in this paper, we propose N-Storm (Nonstop Storm), which is a task-resource decoupling DSPE. N-Storm allows tasks allocated to resources to be changed at runtime, which is implemented by a thread-level scheme for task migrations. Particularly, we add a local shared key/value store on each node to make resources aware of the changes in the allocation plan. Thus, each resource can manage its tasks at runtime. Based on N-Storm, we further propose Online Task Deployment (OTD). Differing from traditional task deployment algorithms that deploy all tasks at once without considering the cost of task migrations caused by a task re-deployment, OTD can gradually adjust the current task deployment to an optimized one based on the communication cost and the runtime states of resources. We demonstrate that OTD can adapt to different kinds of applications including computation- and communication-intensive applications. The experimental results on a real DSPE cluster show that N-Storm can avoid the system stop and save up to 87% of the performance degradation time, compared with Apache Storm and other state-of-the-art approaches. In addition, OTD can increase the average CPU usage by 51% for computation-intensive applications and reduce network communication costs by 88% for communication-intensive applications.","volume":39,"issue":1,"firstpage":116,"lastpage":138,"year":2024,"type":"Regular Paper","research_area":["High-Performance & Parallel Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1629-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1629-9?year=2024&issue=1","affiliations":["Chinese Academy of Sciences","University of Science & Technology of China, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2972-9","title":"Federated Dynamic Client Selection for Fairness Guarantee in Heterogeneous Edge Computing","authors":[{"last":"Mao","first":"Ying-Chi"},{"last":"Shen","first":"Li-Juan"},{"last":"Wu","first":"Jun"},{"last":"Ping","first":"Ping"},{"last":"Wu","first":"Jie"}],"keywords":["federated learning fairness","computational efficiency","data distribution","client selection","client grouping"],"abstract":"Federated learning has emerged as a distributed learning paradigm by training at each client and aggregating at a parameter server. System heterogeneity hinders stragglers from responding to the server in time with huge communication costs. Although client grouping in federated learning can solve the straggler problem, the stochastic selection strategy in client grouping neglects the impact of data distribution within each group. Besides, current client grouping approaches make clients suffer unfair participation, leading to biased performances for different clients. In order to guarantee the fairness of client participation and mitigate biased local performances, we propose a federated dynamic client selection method based on data representativity (FedSDR). FedSDR clusters clients into groups correlated with their own local computational efficiency. To estimate the significance of client datasets, we design a novel data representativity evaluation scheme based on local data distribution. Furthermore, the two most representative clients in each group are selected to optimize the global model. Finally, the DYNAMIC-SELECT algorithm updates local computational efficiency and data representativity states to regroup clients after periodic average aggregation. Evaluations on real datasets show that FedSDR improves client participation by 27.4%, 37.9%, and 23.3% compared with FedAvg, TiFL, and FedSS, respectively, taking fairness into account in federated learning. In addition, FedSDR surpasses FedAvg, FedGS, and FedMS by 21.32%, 20.4%, and 6.90%, respectively, in local test accuracy variance, balancing the performance bias of the global model across clients.","volume":39,"issue":1,"firstpage":139,"lastpage":158,"year":2024,"type":"Regular Paper","research_area":["Federated Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2972-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2972-9?year=2024&issue=1","affiliations":["Hohai University","Pennsylvania Commonwealth System of Higher Education (PCSHE)","Temple University"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-3204-z","title":"4D-MAP: Multipath Adaptive Packet Scheduling for Live Streaming over QUIC","authors":[{"last":"Song","first":"Cong-Xi"},{"last":"Han","first":"Biao"},{"last":"Su","first":"Jin-Shu"}],"keywords":["multipath transmission","live streaming","Quick UDP Internet Connections (QUIC)","quality of experience (QoE)","packet scheduling"],"abstract":"In recent years, live streaming has become a popular application, which uses TCP as its primary transport protocol. Quick UDP Internet Connections (QUIC) protocol opens up new opportunities for live streaming. However, how to leverage QUIC to transmit live videos has not been studied yet. This paper first investigates the achievable quality of experience (QoE) of streaming live videos over TCP, QUIC, and their multipath extensions Multipath TCP (MPTCP) and Multipath QUIC (MPQUIC). We observe that MPQUIC achieves the best performance with bandwidth aggregation and transmission reliability. However, network fluctuations may cause heterogeneous paths, high path loss, and bandwidth degradation, resulting in significant QoE deterioration. Motivated by the above observations, we investigate the multipath packet scheduling problem in live streaming and design 4D-MAP, a multipath adaptive packet scheduling scheme over QUIC. Specifically, a linear upper confidence bound (LinUCB)-based online learning algorithm, along with four novel scheduling mechanisms, i.e., Dispatch, Duplicate, Discard, and Decompensate, is proposed to conquer the above problems. 4D-MAP has been evaluated in both controlled emulation and real-world networks to make comparison with the state-of-the-art multipath transmission schemes. Experimental results reveal that 4D-MAP outperforms others in terms of improving the QoE of live streaming.","volume":39,"issue":1,"firstpage":159,"lastpage":176,"year":2024,"type":"Regular Paper","research_area":["Scheduling & Resource Allocation"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3204-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3204-z?year=2024&issue=1","affiliations":["National University of Defense Technology - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2256-4","title":"Identity-Preserving Adversarial Training for Robust Network Embedding","authors":[{"last":"Cen","first":"Ke-Ting"},{"last":"Shen","first":"Hua-Wei"},{"last":"Cao","first":"Qi"},{"last":"Xu","first":"Bing-Bing"},{"last":"Cheng","first":"Xue-Qi"}],"keywords":["network embedding","identity-preserving","adversarial training","adversarial the example"],"abstract":"Network embedding, as an approach to learning low-dimensional representations of nodes, has been proved extremely useful in many applications, e.g., node classification and link prediction. Unfortunately, existing network embedding models are vulnerable to random or adversarial perturbations, which may degrade the performance of network embedding when being applied to downstream tasks. To achieve robust network embedding, researchers introduce adversarial training to regularize the embedding learning process by training on a mixture of adversarial examples and original examples. However, existing methods generate adversarial examples heuristically, failing to guarantee the imperceptibility of generated adversarial examples, and thus limit the power of adversarial training. In this paper, we propose a novel method Identity-Preserving Adversarial Training (IPAT) for network embedding, which generates imperceptible adversarial examples with explicit identity-preserving regularization. We formalize such identity-preserving regularization as a multi-class classification problem where each node represents a class, and we encourage each adversarial example to be discriminated as the class of its original node. Extensive experimental results on real-world datasets demonstrate that our proposed IPAT method significantly improves the robustness of network embedding models and the generalization of the learned node representations on various downstream tasks.","volume":39,"issue":1,"firstpage":177,"lastpage":191,"year":2024,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2256-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2256-4?year=2024&issue=1","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS","Beijing Academy of Artificial Intelligence"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1277-0","title":"SMEC: Scene Mining for E-Commerce","authors":[{"last":"Wang","first":"Gang"},{"last":"Li","first":"Xiang"},{"last":"Guo","first":"Zi-Yi"},{"last":"Yin","first":"Da-Wei"},{"last":"Ma","first":"Shuai"}],"keywords":["graph clustering","E-commerce","heterogeneous information network (HIN)","scene mining"],"abstract":"Scene-based recommendation has proven its usefulness in E-commerce, by recommending commodities based on a given scene. However, scenes are typically unknown in advance, which necessitates scene discovery for E-commerce. In this article, we study scene discovery for E-commerce systems. We first formalize a scene as a set of commodity categories that occur simultaneously and frequently in real-world situations, and model an E-commerce platform as a heterogeneous information network (HIN), whose nodes and links represent different types of objects and different types of relationships between objects, respectively. We then formulate the scene mining problem for E-commerce as an unsupervised learning problem that finds the overlapping clusters of commodity categories in the HIN. To solve the problem, we propose a non-negative matrix factorization based method SMEC (Scene Mining for E-Commerce), and theoretically prove its convergence. Using six real-world E-commerce datasets, we finally conduct an extensive experimental study to evaluate SMEC against 13 other methods, and show that SMEC consistently outperforms its competitors with regard to various evaluation measures.","volume":39,"issue":1,"firstpage":192,"lastpage":210,"year":2024,"type":"Regular Paper","research_area":["Data Mining & Analytics"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1277-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1277-0?year=2024&issue=1","affiliations":["Beihang University","East China Normal University","Baidu"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-1569-7","title":"Minimal Context-Switching Data Race Detection with Dataflow Tracking","authors":[{"last":"Zheng","first":"Long"},{"last":"Li","first":"Yang"},{"last":"Xin","first":"Jie"},{"last":"Liu","first":"Hai-Feng"},{"last":"Zheng","first":"Ran"},{"last":"Liao","first":"Xiao-Fei"},{"last":"Jin","first":"Hai"}],"keywords":["data race","satisfiability modulo theory","multi-threaded program","dynamic detection"],"abstract":"Data race is one of the most important concurrent anomalies in multi-threaded programs. Emerging constraint- based techniques are leveraged into race detection, which is able to find all the races that can be found by any other sound race detector. However, this constraint-based approach has serious limitations on helping programmers analyze and understand data races. First, it may report a large number of false positives due to the unrecognized dataflow propagation of the program. Second, it recommends a wide range of thread context switches to schedule the reported race (including the false one) whenever this race is exposed during the constraint-solving process. This ad hoc recommendation imposes too many context switches, which complicates the data race analysis. To address these two limitations in the state-of-the-art constraint-based race detection, this paper proposes DFTracker, an improved constraint-based race detector to recommend each data race with minimal thread context switches. Specifically, we reduce the false positives by analyzing and tracking the dataflow in the program. By this means, DFTracker thus reduces the unnecessary analysis of false race schedules. We further propose a novel algorithm to recommend an effective race schedule with minimal thread context switches for each data race. Our experimental results on the real applications demonstrate that 1) without removing any true data race, DFTracker effectively prunes false positives by 68% in comparison with the state-of-the-art constraint-based race detector; 2) DFTracker recommends as low as 2.6-8.3 (4.7 on average) thread context switches per data race in the real world, which is 81.6% fewer context switches per data race than the state-of-the-art constraint based race detector. Therefore, DFTracker can be used as an effective tool to understand the data race for programmers.","volume":39,"issue":1,"firstpage":211,"lastpage":226,"year":2024,"type":"Regular Paper","research_area":["Software Testing & Analysis"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1569-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1569-7?year=2024&issue=1","affiliations":["Huazhong University of Science & Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-1541-6","title":"Label-Aware Chinese Event Detection with Heterogeneous Graph Attention Network","authors":[{"last":"Cui","first":"Shi-Yao"},{"last":"Yu","first":"Bo-Wen"},{"last":"Cong","first":"Xin"},{"last":"Liu","first":"Ting-Wen"},{"last":"Tan","first":"Qing-Feng"},{"last":"Shi","first":"Jin-Qiao"}],"keywords":["Chinese event detection","heterogeneous graph attention network (HGAT)","label embedding"],"abstract":"Event detection (ED) seeks to recognize event triggers and classify them into the predefined event types. Chinese ED is formulated as a character-level task owing to the uncertain word boundaries. Prior methods try to incorporate word-level information into characters to enhance their semantics. However, they experience two problems. First, they fail to incorporate word-level information into each character the word encompasses, causing the insufficient word-character interaction problem. Second, they struggle to distinguish events of similar types with limited annotated instances, which is called the event confusing problem. This paper proposes a novel model named Label-Aware Heterogeneous Graph Attention Network (L-HGAT) to address these two problems. Specifically, we first build a heterogeneous graph of two node types and three edge types to maximally preserve word-character interactions, and then deploy a heterogeneous graph attention network to enhance the semantic propagation between characters and words. Furthermore, we design a pushing-away game to enlarge the predicting gap between the ground-truth event type and its confusing counterpart for each character. Experimental results show that our L-HGAT model consistently achieves superior performance over prior competitive methods.","volume":39,"issue":1,"firstpage":227,"lastpage":242,"year":2024,"type":"Regular Paper","research_area":["Information Extraction"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1541-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1541-6?year=2024&issue=1","affiliations":["Chinese Academy of Sciences","Institute of Information Engineering, CAS","University of Chinese Academy of Sciences, CAS","Guangzhou University"],"type_origin":"Article"},{"doi":"10.1007/s11390-024-3419-7","title":"A Transfer Function Design for Medical Volume Data Using a Knowledge Database Based on Deep Image and Primitive Intensity Profile Features Retrieval","authors":[{"last":"Jung","first":"Younhyun"},{"last":"Kong","first":"Jim"},{"last":"Sheng","first":"Bin"},{"last":"Kim","first":"Jinman"}],"keywords":["data retrieval","direct volume rendering","ray analysis","transfer function"],"abstract":"Direct volume rendering (DVR) is a technique that emphasizes structures of interest (SOIs) within a volume visually, while simultaneously depicting adjacent regional information, e.g., the spatial location of a structure concerning its neighbors. In DVR, transfer function (TF) plays a key role by enabling accurate identification of SOIs interactively as well as ensuring appropriate visibility of them. TF generation typically involves non-intuitive trial-and-error optimization of rendering parameters, which is time-consuming and inefficient. Attempts at mitigating this manual process have led to approaches that make use of a knowledge database consisting of pre-designed TFs by domain experts. In these approaches, a user navigates the knowledge database to find the most suitable pre-designed TF for their input volume to visualize the SOIs. Although these approaches potentially reduce the workload to generate the TFs, they, however, require manual TF navigation of the knowledge database, as well as the likely fine tuning of the selected TF to suit the input. In this work, we propose a TF design approach, CBR-TF, where we introduce a new content-based retrieval (CBR) method to automatically navigate the knowledge database. Instead of pre-designed TFs, our knowledge database contains volumes with SOI labels. Given an input volume, our CBR-TF approach retrieves relevant volumes (with SOI labels) from the knowledge database; the retrieved labels are then used to generate and optimize TFs of the input. This approach largely reduces manual TF navigation and fine tuning. For our CBR-TF approach, we introduce a novel volumetric image feature which includes both a local primitive intensity profile along the SOIs and regional spatial semantics available from the co-planar images to the profile. For the regional spatial semantics, we adopt a convolutional neural network to obtain high-level image feature representations. For the intensity profile, we extend the dynamic time warping technique to address subtle alignment differences between similar profiles (SOIs). Finally, we propose a two-stage CBR scheme to enable the use of these two different feature representations in a complementary manner, thereby improving SOI retrieval performance. We demonstrate the capabilities of our CBR-TF approach with comparison with a conventional approach in visualization, where an intensity profile matching algorithm is used, and also with potential use-cases in medical volume visualization.","volume":null,"issue":null,"firstpage":null,"lastpage":null,"year":2024,"type":"Regular Paper","research_area":["Computer Graphics & Visualization"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-024-3419-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-024-3419-7?year=2024","affiliations":["Gachon University","University of Sydney","Shanghai Jiao Tong University"],"type_origin":"Article; Early Access"},{"doi":"10.1007/s11390-022-1332-5","title":"A Probabilistic Framework for Temporal Cognitive Diagnosis in Online Learning Systems","authors":[{"last":"Liu","first":"Jia-Yu"},{"last":"Wang","first":"Fei"},{"last":"Ma","first":"Hai-Ping"},{"last":"Huang","first":"Zhen-Ya"},{"last":"Liu","first":"Qi"},{"last":"Chen","first":"En-Hong"},{"last":"Su","first":"Yu"}],"keywords":["cognitive diagnosis","probabilistic graphical model","item response theory (IRT)","stochastic process","expectation maximization (EM) algorithm"],"abstract":"Cognitive diagnosis is an important issue of intelligent education systems, which aims to estimate students' proficiency on specific knowledge concepts. Most existing studies rely on the assumption of static student states and ignore the dynamics of proficiency in the learning process, which makes them unsuitable for online learning scenarios. In this paper, we propose a unified temporal item response theory (UTIRT) framework, incorporating temporality and randomness of proficiency evolving to get both accurate and interpretable diagnosis results. Specifically, we hypothesize that students' proficiency varies as a Wiener process and describe a probabilistic graphical model in UTIRT to consider temporality and randomness factors. Furthermore, based on the relationship between student states and exercising answers, we hypothesize that the answering result at time k contributes most to inferring a student's proficiency at time k, which also reflects the temporality aspect and enables us to get analytical maximization (M-step) in the expectation maximization (EM) algorithm when estimating model parameters. Our UTIRT is a framework containing unified training and inferencing methods, and is general to cover several typical traditional models such as Item Response Theory (IRT), multidimensional IRT (MIRT), and temporal IRT (TIRT). Extensive experimental results on real-world datasets show the effectiveness of UTIRT and prove its superiority in leveraging temporality theoretically and practically over TIRT.","volume":38,"issue":6,"firstpage":1203,"lastpage":1222,"year":2023,"type":"Regular Paper","research_area":["Education & Social Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1332-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1332-5?year=2023&issue=6","affiliations":["Chinese Academy of Sciences","University of Science & Technology of China, CAS","Anhui University","Hefei Normal University"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-1302-6","title":"Visual Topic Semantic Enhanced Machine Translation for Multi-Modal Data Efficiency","authors":[{"last":"Wang","first":"Chao"},{"last":"Cai","first":"Si-Jia"},{"last":"Shi","first":"Bei-Xiang"},{"last":"Chong","first":"Zhi-Hong"}],"keywords":["multi-modal machine translation","visual topic semantics","data efficiency"],"abstract":"The scarcity of bilingual parallel corpus imposes limitations on exploiting the state-of-the-art supervised translation technology. One of the research directions is employing relations among multi-modal data to enhance performance. However, the reliance on manually annotated multi-modal datasets results in a high cost of data labeling. In this paper, the topic semantics of images is proposed to alleviate the above problem. First, topic-related images can be automatically collected from the Internet by search engines. Second, topic semantics is sufficient to encode the relations between multi-modal data such as texts and images. Specifically, we propose a visual topic semantic enhanced translation (VTSE) model that utilizes topic-related images to construct a cross-lingual and cross-modal semantic space, allowing the VTSE model to simultaneously integrate the syntactic structure and semantic features. In the above process, topic similar texts and images are wrapped into groups so that the model can extract more robust topic semantics from a set of similar images and then further optimize the feature integration. The results show that our model outperforms competitive baselines by a large margin on the Multi30k and the Ambiguous COCO datasets. Our model can use external images to bring gains to translation, improving data efficiency.","volume":38,"issue":6,"firstpage":1223,"lastpage":1236,"year":2023,"type":"Regular Paper","research_area":["Text Generation & Dialogue"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1302-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1302-6?year=2023&issue=6","affiliations":["Southeast University"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-022-1479-0","title":"Unsupervised Domain Adaptation on Sentence Matching Through Self-Supervision","authors":[{"last":"Bai","first":"Gui-Rong"},{"last":"Liu","first":"Qing-Bin"},{"last":"He","first":"Shi-Zhu"},{"last":"Liu","first":"Kang"},{"last":"Zhao","first":"Jun"}],"keywords":["unsupervised domain adaptation","sentence matching","self-supervision"],"abstract":"Although neural approaches have yielded state-of-the-art results in the sentence matching task, their performance inevitably drops dramatically when applied to unseen domains. To tackle this cross-domain challenge, we address unsupervised domain adaptation on sentence matching, in which the goal is to have good performance on a target domain with only unlabeled target domain data as well as labeled source domain data. Specifically, we propose to perform self-supervised tasks to achieve it. Different from previous unsupervised domain adaptation methods, self-supervision can not only flexibly suit the characteristics of sentence matching with a special design, but also be much easier to optimize. When training, each self-supervised task is performed on both domains simultaneously in an easy-to-hard curriculum, which gradually brings the two domains closer together along the direction relevant to the task. As a result, the classifier trained on the source domain is able to generalize to the unlabeled target domain. In total, we present three types of self-supervised tasks and the results demonstrate their superiority. In addition, we further study the performance of different usages of self-supervised tasks, which would inspire how to effectively utilize self-supervision for cross-domain scenarios.","volume":38,"issue":6,"firstpage":1237,"lastpage":1249,"year":2023,"type":"Regular Paper","research_area":["Multi-Task & Transfer Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1479-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1479-0?year=2023&issue=6","affiliations":["Chinese Academy of Sciences","Institute of Automation, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-1337-8","title":"A Novel Three-Staged Generative Model for Skeletonizing Chinese Characters with Versatile Styles","authors":[{"last":"Tian","first":"Ye-Chuan"},{"last":"Xu","first":"Song-Hua"},{"last":"Sylla","first":"Cheickna"}],"keywords":["skeletonization of characters","three-staged skeletonization","X-net"],"abstract":"Skeletons of characters provide vital information to support a variety of tasks, e.g., optical character recognition, image restoration, stroke segmentation and extraction, and style learning and transfer. However, automatically skeletonizing Chinese characters poses a steep computational challenge due to the large volume of Chinese characters and their versatile styles, for which traditional image analysis approaches are error-prone and fragile. Current deep learning based approach requires a heavy amount of manual labeling efforts, which imposes serious limitations on the precision, robustness, scalability and generalizability of an algorithm to solve a specific problem. To tackle the above challenge, this paper introduces a novel three-staged deep generative model developed as an image-to-image translation approach, which significantly reduces the model's demand for labeled training samples. The new model is built upon an improved G-net, an enhanced X-net, and a newly proposed F-net. As compellingly demonstrated by comprehensive experimental results, the new model is able to iteratively extract skeletons of Chinese characters in versatile styles with a high quality, which noticeably outperforms two state-of-the-art peer deep learning methods and a classical thinning algorithm in terms of F-measure, Hausdorff distance, and average Hausdorff distance.","volume":38,"issue":6,"firstpage":1250,"lastpage":1271,"year":2023,"type":"Regular Paper","research_area":["Computer Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1337-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1337-8?year=2023&issue=6","affiliations":["Xi'an Jiaotong University","New Jersey Institute of Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-1295-1","title":"Composing Like an Ancient Chinese Poet: Learn to Generate Rhythmic Chinese Poetry","authors":[{"last":"He","first":"Ming"},{"last":"Chen","first":"Yan"},{"last":"Zhao","first":"Hong-Ke"},{"last":"Liu","first":"Qi"},{"last":"Wu","first":"Le"},{"last":"Cui","first":"Yu"},{"last":"Zeng","first":"Gui-Hua"},{"last":"Liu","first":"Gui-Quan"}],"keywords":["aesthetics","poetry generation","polishing","semantics","two-stage method"],"abstract":"Automatic generation of Chinese classical poetry is still a challenging problem in artificial intelligence. Recently, Encoder-Decoder models have provided a few viable methods for poetry generation. However, by reviewing the prior methods, two major issues still need to be settled: 1) most of them are one-stage generation methods without further polishing; 2) they rarely take into consideration the restrictions of poetry, such as tone and rhyme. Intuitively, some ancient Chinese poets tended first to write a coarse poem underlying aesthetics and then deliberated its semantics; while others first create a semantic poem and then refine its aesthetics. On this basis, in order to better imitate the human creation procedure of poems, we propose a two-stage method (i.e., restricted polishing generation method) of which each stage focuses on the different aspects of poems (i.e., semantics and aesthetics), which can produce a higher quality of generated poems. In this way, the two-stage method develops into two symmetrical generation methods, the aesthetics-to-semantics method and the semantics-to-aesthetics method. In particular, we design a sampling method and a gate to formulate the tone and rhyme restrictions, which can further improve the rhythm of the generated poems. Experimental results demonstrate the superiority of our proposed two-stage method in both automatic evaluation metrics and human evaluation metrics compared with baselines, especially in yielding consistent improvements in tone and rhyme.","volume":38,"issue":6,"firstpage":1272,"lastpage":1287,"year":2023,"type":"Regular Paper","research_area":["Text Generation & Dialogue"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1295-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1295-1?year=2023&issue=6","affiliations":["Shanghai Jiao Tong University","Baidu","Tianjin University","Chinese Academy of Sciences"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1326-8","title":"M-LSM: An Improved Multi-Liquid State Machine for Event-Based Vision Recognition","authors":[{"last":"Wang","first":"Lei"},{"last":"Guo","first":"Sha-Sha"},{"last":"Qu","first":"Lian-Hua"},{"last":"Tian","first":"Shuo"},{"last":"Xu","first":"Wei-Xia"}],"keywords":["liquid state machine","bio-inspired learning","classification","event-based vision"],"abstract":"Event-based computation has recently gained increasing research interest for applications of vision recognition due to its intrinsic advantages on efficiency and speed. However, the existing event-based models for vision recognition are faced with several issues, such as large network complexity and expensive training cost. In this paper, we propose an improved multi-liquid state machine (M-LSM) method for high-performance vision recognition. Specifically, we introduce two methods, namely multi-state fusion and multi-liquid search, to optimize the liquid state machine (LSM). Multistate fusion by sampling the liquid state at multiple timesteps could reserve richer spatiotemporal information. We adapt network architecture search (NAS) to find the potential optimal architecture of the multi-liquid state machine. We also train the M-LSM through an unsupervised learning rule spike-timing dependent plasticity (STDP). Our M-LSM is evaluated on two event-based datasets and demonstrates state-of-the-art recognition performance with superior advantages on network complexity and training cost.","volume":38,"issue":6,"firstpage":1288,"lastpage":1299,"year":2023,"type":"Regular Paper","research_area":["Computer Vision","Convolutional & Spiking Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1326-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1326-8?year=2023&issue=6","affiliations":["National University of Defense Technology - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1523-5","title":"Hardware Acceleration for SLAM in Mobile Systems","authors":[{"last":"Fan","first":"Zhe"},{"last":"Hao","first":"Yi-Fan"},{"last":"Zhi","first":"Tian"},{"last":"Guo","first":"Qi"},{"last":"Du","first":"Zi-Dong"}],"keywords":["hardware accelerator","instruction set","mobile system","simultaneous localization and mapping (SLAM) algorithm"],"abstract":"The emerging mobile robot industry has spurred a flurry of interest in solving the simultaneous localization and mapping (SLAM) problem. However, existing SLAM platforms have difficulty in meeting the real-time and low-power requirements imposed by mobile systems. Though specialized hardware is promising with regard to achieving high performance and lowering the power, designing an efficient accelerator for SLAM is severely hindered by a wide variety of SLAM algorithms. Based on our detailed analysis of representative SLAM algorithms, we observe that SLAM algorithms advance two challenges for designing efficient hardware accelerators: the large number of computational primitives and irregular control flows. To address these two challenges, we propose a hardware accelerator that features composable computation units classified as the matrix, vector, scalar, and control units. In addition, we design a hierarchical instruction set for coping with a broad range of SLAM algorithms with irregular control flows. Experimental results show that, compared against an Intel x86 processor, on average, our accelerator with the area of 7.41 mm2 achieves 10.52x and 112.62x better performance and energy savings, respectively, across different datasets. Compared against a more energy-efficient ARM Cortex processor, our accelerator still achieves 33.03x and 62.64x better performance and energy savings, respectively.","volume":38,"issue":6,"firstpage":1300,"lastpage":1322,"year":2023,"type":"Regular Paper","research_area":["GPU & Accelerator Architecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1523-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1523-5?year=2023&issue=6","affiliations":["Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1251-x","title":"wrBench: Comparing Cache Architectures and Coherency Protocols on ARMv8 Many-Core Systems","authors":[{"last":"Gao","first":"Wan-Rong"},{"last":"Fang","first":"Jian-Bin"},{"last":"Huang","first":"Chun"},{"last":"Xu","first":"Chuan-Fu"},{"last":"Wang","first":"Zheng"}],"keywords":["ARMv8 many-core","cache architecture","microbenchmark","core-to-core communication"],"abstract":"Cache performance is a critical design constraint for modern many-core systems. Since the cache often works in a black-box manner, it is difficult for the software to reason about the cache behavior to match the running software to the underlying hardware. To better support code optimization, we need to understand and characterize the cache behavior. While cache performance characterization is heavily studied on traditional x86 architectures, there is little work for understanding the cache implementations on emerging ARMv8-based many-cores. This paper presents a comprehensive study to evaluate the cache architecture design on three representative ARMv8 multi-cores, Phytium 2000+, ThunderX2, and Kunpeng 920 (KP920). To this end, we develop wrBench, a micro-benchmark suite to measure the realized latency and bandwidth of caches at different memory hierarchies when performing core-to-core communication. Our evaluation provides inter-core latency and bandwidth in different cache levels and coherency states for the three ARMv8 many-cores. The quantitative performance data is shown in tables. We mine the characteristics of caches and coherency protocols by analyzing the data for the three processors, Phytium 2000+, ThunderX2, and KP920. Our paper also provides discussions and guidelines for optimizing memory access on ARMv8 many-cores.","volume":38,"issue":6,"firstpage":1323,"lastpage":1338,"year":2023,"type":"Regular Paper","research_area":["Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1251-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1251-x?year=2023&issue=6","affiliations":["National University of Defense Technology - China","University of Leeds"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1919-x","title":"Automatic Target Description File Generation","authors":[{"last":"Geng","first":"Hong-Na"},{"last":"Lyu","first":"Fang"},{"last":"Zhong","first":"Ming"},{"last":"Cui","first":"Hui-Min"},{"last":"Xue","first":"Jingling"},{"last":"Feng","first":"Xiao-Bing"}],"keywords":["retargetability","compiler","target description","target backend","automatic generator"],"abstract":"Agile hardware design is gaining increasing momentum and bringing new chips in larger quantities to the market faster. However, it also takes new challenges for compiler developers to retarget existing compilers to these new chips in shorter time than ever before. Currently, retargeting a compiler backend, e.g., an LLVM backend to a new target, requires compiler developers to write manually a set of target description files (totalling 10 300+ lines of code (LOC) for RISC-V in LLVM), which is error-prone and time-consuming. In this paper, we introduce a new approach, Automatic Target Description File Generation (ATG), which accelerates the generation of a compiler backend for a new target by generating its target description files automatically. Given a new target, ATG proceeds in two stages. First, ATG synthesizes a small list of target-specific properties and a list of code-layout templates from the target description files of a set of existing targets with similar instruction set architectures (ISAs). Second, ATG requests compiler developers to fill in the information for each instruction in the new target in tabular form according to the list of target-specific properties synthesized and then generates its target description files automatically according to the list of code-layout templates synthesized. The first stage can often be reused by different new targets sharing similar ISAs. We evaluate ATG using nine RISC-V instruction sets drawn from a total of 1 029 instructions in LLVM 12.0. ATG enables compiler developers to generate compiler backends for these ISAs that emit the same assembly code as the existing compiler backends for RISC-V but with significantly less development effort (by specifying each instruction in terms of up to 61 target-specific properties only).","volume":38,"issue":6,"firstpage":1339,"lastpage":1355,"year":2023,"type":"Regular Paper","research_area":["Programming Languages & Compilers"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1919-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1919-x?year=2023&issue=6","affiliations":["Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1887-1","title":"Motion-Inspired Real-Time Garment Synthesis with Temporal-Consistency","authors":[{"last":"Wei","first":"Yu-Kun"},{"last":"Shi","first":"Min"},{"last":"Feng","first":"Wen-Ke"},{"last":"Zhu","first":"Deng-Ming"},{"last":"Mao","first":"Tian-Lu"}],"keywords":["clothing animation","computer graphics","transformer","temporal consistency"],"abstract":"Synthesizing garment dynamics according to body motions is a vital technique in computer graphics. Physics-based simulation depends on an accurate model of the law of kinetics of cloth, which is time-consuming, hard to implement, and complex to control. Existing data-driven approaches either lack temporal consistency, or fail to handle garments that are different from body topology. In this paper, we present a motion-inspired real-time garment synthesis workflow that enables high-level control of garment shape. Given a sequence of body motions, our workflow is able to generate corresponding garment dynamics with both spatial and temporal coherence. To that end, we develop a transformerbased garment synthesis network to learn the mapping from body motions to garment dynamics. Frame-level attention is employed to capture the dependency of garments and body motions. Moreover, a post-processing procedure is further taken to perform penetration removal and auto-texturing. Then, textured clothing animation that is collision-free and temporally-consistent is generated. We quantitatively and qualitatively evaluated our proposed workflow from different aspects. Extensive experiments demonstrate that our network is able to deliver clothing dynamics which retain the wrinkles from the physics-based simulation, while running 1 000 times faster. Besides, our workflow achieved superior synthesis performance compared with alternative approaches. To stimulate further research in this direction, our code will be publicly available soon.","volume":38,"issue":6,"firstpage":1356,"lastpage":1368,"year":2023,"type":"Regular Paper","research_area":["Computer Graphics & Visualization"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1887-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1887-1?year=2023&issue=6","affiliations":["North China Electric Power University","Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Institute of Computing Technology, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1270-7","title":"Community-Preserving Social Graph Release with Node Differential Privacy","authors":[{"last":"Zhang","first":"Sen"},{"last":"Ni","first":"Wei-Wei"},{"last":"Fu","first":"Nan"}],"keywords":["differential privacy","social graph","community structure","private eigenvector"],"abstract":"The goal of privacy-preserving social graph release is to protect individual privacy while preserving data utility. Community structure, which is an important global pattern of nodes, is a crucial data utility as it is fundamental to many graph analysis tasks. Yet, most existing methods with differential privacy (DP) commonly fall into edge-DP to sacrifice security in exchange for utility. Moreover, they reconstruct graphs from the local feature-extraction of nodes, resulting in poor community preservation. Motivated by this, we develop PrivCom, a strict node-DP graph release algorithm to maximize the utility on the community structure while maintaining a higher level of privacy. In this algorithm, to reduce the huge sensitivity, we devise a Katz index based private graph feature extraction method, which can capture global graph structure features while greatly reducing the global sensitivity via a sensitivity regulation strategy. Yet, under the condition that the sensitivity is fixed, the feature captured by the Katz index, which is presented in matrix form, requires privacy budget splits. As a result, plenty of noise is injected, mitigating global structural utility. To bridge this gap, we design a private eigenvector estimation method, which yields noisy eigenvectors from extracted low-dimensional vectors. Then, a dynamic privacy budget allocation method with provable utility guarantees is developed to preserve the inherent relationship between eigenvalues and eigenvectors, so that the utility of the generated noise Katz matrix is well maintained. Finally, we reconstruct the synthetic graph via calculating its Laplacian with the noisy Katz matrix. Experimental results confirm our theoretical findings and the efficacy of PrivCom.","volume":38,"issue":6,"firstpage":1369,"lastpage":1386,"year":2023,"type":"Regular Paper","research_area":["Graph Theory & Algorithms","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1270-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1270-7?year=2023&issue=6","affiliations":["Southeast University - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1320-9","title":"Shapelet Based Two-Step Time Series Positive and Unlabeled Learning","authors":[{"last":"Zhang","first":"Han-Bo"},{"last":"Wang","first":"Peng"},{"last":"Zhang","first":"Ming-Ming"},{"last":"Wang","first":"Wei"}],"keywords":["positive unlabeled learning","time series","shapelet"],"abstract":"In the last decade, there has been significant progress in time series classification. However, in real-world industrial settings, it is expensive and difficult to obtain high-quality labeled data. Therefore, the positive and unlabeled learning (PU-learning) problem has become more and more popular recently. The current PU-learning approaches of the time series data suffer from low accuracy due to the lack of negative labeled time series. In this paper, we propose a novel shapelet based two-step (2STEP) PU-learning approach. In the first step, we generate shapelet features based on the positive time series, which are used to select a set of negative examples. In the second step, based on both positive and negative time series, we select the final features and build the classification model. The experimental results show that our 2STEP approach can improve the average F1 score on 15 datasets by 9.1% compared with the baselines, and achieves the highest F1 score on 10 out of 15 time series datasets.","volume":38,"issue":6,"firstpage":1387,"lastpage":1402,"year":2023,"type":"Regular Paper","research_area":["Data Mining & Analytics"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1320-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1320-9?year=2023&issue=6","affiliations":["Fudan University"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-1346-7","title":"Hadamard Encoding Based Frequent Itemset Mining under Local Differential Privacy","authors":[{"last":"Zhao","first":"Dan"},{"last":"Zhao","first":"Su-Yun"},{"last":"Chen","first":"Hong"},{"last":"Liu","first":"Rui-Xuan"},{"last":"Li","first":"Cui-Ping"},{"last":"Zhang","first":"Xiao-Ying"}],"keywords":["local differential privacy","frequent itemset mining","frequency oracle"],"abstract":"Local differential privacy (LDP) approaches to collecting sensitive information for frequent itemset mining (FIM) can reliably guarantee privacy. Most current approaches to FIM under LDP add padding and sampling steps to obtain frequent itemsets and their frequencies because each user transaction represents a set of items. The current state-of-the-art approach, namely set-value itemset mining (SVSM), must balance variance and bias to achieve accurate results. Thus, an unbiased FIM approach with lower variance is highly promising. To narrow this gap, we propose an Item-Level LDP frequency oracle approach, named the Integrated-with-Hadamard-Transform-Based Frequency Oracle (IHFO). For the first time, Hadamard encoding is introduced to a set of values to encode all items into a fixed vector, and perturbation can be subsequently applied to the vector. An FIM approach, called optimized united itemset mining (O-UISM), is proposed to combine the padding-and-sampling-based frequency oracle (PSFO) and the IHFO into a framework for acquiring accurate frequent itemsets with their frequencies. Finally, we theoretically and experimentally demonstrate that O-UISM significantly outperforms the extant approaches in finding frequent itemsets and estimating their frequencies under the same privacy guarantee.","volume":38,"issue":6,"firstpage":1403,"lastpage":1422,"year":2023,"type":"Regular Paper","research_area":["Data Mining & Analytics","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1346-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1346-7?year=2023&issue=6","affiliations":["Renmin University of China"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1361-0","title":"Characterization of Exact One-Query Quantum Algorithms for Partial Boolean Functions","authors":[{"last":"Ye","first":"Ze-Kun"},{"last":"Li","first":"Lv-Zhou"}],"keywords":["quantum computing","quantum query complexity","quantum algorithm"],"abstract":"The query model (or black-box model) has attracted much attention from the communities of both classical and quantum computing. Usually, quantum advantages are revealed by presenting a quantum algorithm that has a better query complexity than its classical counterpart. In the history of quantum algorithms, the Deutsch algorithm and the Deutsch-Jozsa algorithm play a fundamental role and both are exact one-query quantum algorithms. This leads us to consider the problem: what functions can be computed by exact one-query quantum algorithms? This problem has been addressed in the literature for total Boolean functions and symmetric partial Boolean functions, but is still open for general partial Boolean functions. Thus, in this paper, we continue to characterize the computational power of exact one-query quantum algorithms for general partial Boolean functions. First, we present several necessary and sufficient conditions for a partial Boolean function to be computed by exact one-query quantum algorithms. Second, inspired by these conditions, we discover some new representative functions that can be computed by exact one-query quantum algorithms but have an essential difference from the already known ones. Specially, it is worth pointing out that before our work, the known functions that can be computed by exact one-query quantum algorithms are all symmetric functions and the quantum algorithm used is essentially the Deutsch-Jozsa algorithm, whereas the functions discovered in this paper are generally asymmetric and new algorithms to compute these functions are required. Thus, this expands the class of functions that can be computed by exact one-query quantum algorithms.","volume":38,"issue":6,"firstpage":1423,"lastpage":1430,"year":2023,"type":"Regular Paper","research_area":["Quantum Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1361-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1361-0?year=2023&issue=6","affiliations":["Sun Yat Sen University"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-1420-1","title":"2k-Vertex Kernels for Cluster Deletion and Strong Triadic Closure","authors":[{"last":"Gao","first":"Wen-Yu"},{"last":"Gao","first":"Hang"}],"keywords":["cluster deletion","strong triadic closure","kernelization","parameterized complexity","social network"],"abstract":"Cluster deletion and strong triadic closure are two important NP-complete problems that have received significant attention due to their applications in various areas, including social networks and data analysis. Although cluster deletion and strong triadic closure are closely linked by induced paths on three vertices, there are subtle differences between them. In some cases, the solutions of strong triadic closure and cluster deletion are quite different. In this paper, we study the parameterized algorithms for these two problems. More specifically, we focus on the kernels of these two problems. Instead of separating the critical clique and its neighbors for analysis, we consider them as a whole, which allows us to more effectively bound the number of related vertices. In addition, in analyzing the kernel of strong triadic closure, we introduce the concept of edge-disjoint induced path on three vertices, which enables us to obtain the lower bound of weak edge number in a more concise way. Our analysis demonstrates that cluster deletion and strong triadic closure both admit 2k-vertex kernels. These results represent improvements over previously best-known kernels for both problems. Furthermore, our analysis provides additional insights into the relationship between cluster deletion and strong triadic closure.","volume":38,"issue":6,"firstpage":1431,"lastpage":1439,"year":2023,"type":"Regular Paper","research_area":["Graph Theory & Algorithms"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1420-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1420-1?year=2023&issue=6","affiliations":["Guangdong University of Finance & Economics","Rutgers University System","Rutgers University New Brunswick"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-0006-2","title":"Disaggregated Datacenters for Future Cloud Computing","authors":[{"last":"Xu","first":"Zhi-Wei"}],"keywords":[],"abstract":"","volume":38,"issue":5,"firstpage":947,"lastpage":948,"year":2023,"type":"Perspective","research_area":["Cloud, Edge & Utility Computing","Data Center Systems & Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-0006-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-0006-2?year=2023&issue=5","affiliations":["Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Institute of Computing Technology, CAS","Great Bay University"],"type_origin":"Editorial Material","cover_doi":"10.1007/s11390-023-3272-0","topic_source":"cover_inherited"},{"doi":"10.1007/s11390-023-3272-0","title":"Reinvent Cloud Software Stacks for Resource Disaggregation","authors":[{"last":"Wang","first":"Chen-Xi"},{"last":"Shan","first":"Yi-Zhou"},{"last":"Zuo","first":"Peng-Fei"},{"last":"Cui","first":"Hui-Min"}],"keywords":["cloud computing","resource disaggregation","datacenter","program semantics"],"abstract":"Due to the unprecedented development of low-latency interconnect technology, building large-scale disaggregated architecture is drawing more and more attention from both industry and academia. Resource disaggregation is a new way to organize the hardware resources of datacenters, and has the potential to overcome the limitations, e.g., low resource utilization and low reliability, of conventional datacenters. However, the emerging disaggregated architecture brings severe performance and latency problems to the existing cloud systems. In this paper, we take memory disaggregation as an example to demonstrate the unique challenges that the disaggregated datacenter poses to the existing cloud software stacks, e.g., programming interface, language runtime, and operating system, and further discuss the possible ways to reinvent the cloud systems.","volume":38,"issue":5,"firstpage":949,"lastpage":969,"year":2023,"type":"Survey","research_area":["Cloud, Edge & Utility Computing","Data Center Systems & Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3272-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3272-0?year=2023&issue=5","affiliations":["Chinese Academy of Sciences","University of the Chinese Academy of Sciences","Huawei Cloud"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-023-3009-0","title":"FedIERF: Federated Incremental Extremely Random Forest for Wearable Health Monitoring","authors":[{"last":"Hu","first":"Chun-Yu"},{"last":"Hu","first":"Li-Sha"},{"last":"Yuan","first":"Lin"},{"last":"Lu","first":"Dian-Jie"},{"last":"Lyu","first":"Lei"},{"last":"Chen","first":"Yi-Qiang"}],"keywords":["federated learning","incremental learning","random forest","wearable health monitoring"],"abstract":"Wearable health monitoring is a crucial technical tool that offers early warning for chronic diseases due to its superior portability and low power consumption. However, most wearable health data is distributed across different organizations, such as hospitals, research institutes, and companies, and can only be accessed by the owners of the data in compliance with data privacy regulations. The first challenge addressed in this paper is communicating in a privacy-preserving manner among different organizations. The second technical challenge is handling the dynamic expansion of the federation without model retraining. To address the first challenge, we propose a horizontal federated learning method called Federated Extremely Random Forest (FedERF). Its contribution-based splitting score computing mechanism significantly mitigates the impact of privacy protection constraints on model performance. Based on FedERF, we present a federated incremental learning method called Federated Incremental Extremely Random Forest (FedIERF) to address the second technical challenge. FedIERF introduces a hardness-driven weighting mechanism and an importance-based updating scheme to update the existing federated model incrementally. The experiments show that FedERF achieves comparable performance with non-federated methods, and FedIERF effectively addresses the dynamic expansion of the federation. This opens up opportunities for cooperation between different organizations in wearable health monitoring.","volume":38,"issue":5,"firstpage":970,"lastpage":984,"year":2023,"type":"Regular Paper","research_area":["Federated Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3009-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3009-0?year=2023&issue=5","affiliations":["Qilu University of Technology","Hebei University of Economics & Business","Shandong Normal University","Chinese Academy of Sciences"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1167-0","title":"Top-down Text-Level Discourse Rhetorical Structure Parsing with Bidirectional Representation Learning","authors":[{"last":"Zhang","first":"Long-Yin"},{"last":"Tan","first":"Xin"},{"last":"Kong","first":"Fang"},{"last":"Li","first":"Pei-Feng"},{"last":"Zhou","first":"Guo-Dong"}],"keywords":["discourse rhetorical structure","discourse parsing","representation learning"],"abstract":"Early studies on discourse rhetorical structure parsing mainly adopt bottom-up approaches, limiting the parsing process to local information. Although current top-down parsers can better capture global information and have achieved particular success, the importance of local and global information at various levels of discourse parsing is different. This paper argues that combining local and global information for discourse parsing is more sensible. To prove this, we introduce a top-down discourse parser with bidirectional representation learning capabilities. Existing corpora on Rhetorical Structure Theory (RST) are known to be much limited in size, which makes discourse parsing very challenging. To alleviate this problem, we leverage some boundary features and a data augmentation strategy to tap the potential of our parser. We use two methods for evaluation, and the experiments on the RST-DT corpus show that our parser can primarily improve the performance due to the effective combination of local and global information. The boundary features and the data augmentation strategy also play a role. Based on gold standard elementary discourse units (EDUs), our parser significantly advances the baseline systems in nuclearity detection, with the results on the other three indicators (span, relation, and full) being competitive. Based on automatically segmented EDUs, our parser still outperforms previous state-of-the-art work.","volume":38,"issue":5,"firstpage":985,"lastpage":1001,"year":2023,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1167-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1167-0?year=2023&issue=5","affiliations":["Soochow University - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1103-8","title":"FDNet: A Deep Learning Approach with Two Parallel Cross Encoding Pathways for Precipitation Nowcasting","authors":[{"last":"Yan","first":"Bi-Ying"},{"last":"Yang","first":"Chao"},{"last":"Chen","first":"Feng"},{"last":"Takeda","first":"Kohei"},{"last":"Wang","first":"Changjun"}],"keywords":["spatio-temporal predictive learning","precipitation nowcasting","neural network"],"abstract":"With the goal of predicting the future rainfall intensity in a local region over a relatively short period time, precipitation nowcasting has been a long-time scientific challenge with great social and economic impact. The radar echo extrapolation approaches for precipitation nowcasting take radar echo images as input, aiming to generate future radar echo images by learning from the historical images. To effectively handle complex and high non-stationary evolution of radar echoes, we propose to decompose the movement into optical flow field motion and morphologic deformation. Following this idea, we introduce Flow-Deformation Network (FDNet), a neural network that models flow and deformation in two parallel cross pathways. The flow encoder captures the optical flow field motion between consecutive images and the deformation encoder distinguishes the change of shape from the translational motion of radar echoes. We evaluate the proposed network architecture on two real-world radar echo datasets. Our model achieves state-of-the-art prediction results compared with recent approaches. To the best of our knowledge, this is the first network architecture with flow and deformation separation to model the evolution of radar echoes for precipitation nowcasting. We believe that the general idea of this work could not only inspire much more effective approaches but also be applied to other similar spatio-temporal prediction tasks.","volume":38,"issue":5,"firstpage":1002,"lastpage":1020,"year":2023,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1103-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1103-8?year=2023&issue=5","affiliations":["Chinese Academy of Sciences","University of Chinese Academy of Sciences, CAS","Nanjing Institute of Geology & Paleontology, CAS","Institute of Software, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1153-y","title":"Chinese Named Entity Recognition Augmented with Lexicon Memory","authors":[{"last":"Zhou","first":"Yi"},{"last":"Zheng","first":"Xiao-Qing"},{"last":"Huang","first":"Xuan-Jing"}],"keywords":["named entity recognition (NER)","lexicon-based memory","content-addressable retrieval","position-dependent feature","neural network"],"abstract":"Inspired by the concept of content-addressable retrieval from cognitive science, we propose a novel fragment-based Chinese named entity recognition (NER) model augmented with a lexicon-based memory in which both character-level and word-level features are combined to generate better feature representations for possible entity names. Observing that the boundary information of entity names is particularly useful to locate and classify them into pre-defined categories, position-dependent features, such as prefix and suffix, are introduced and taken into account for NER tasks in the form of distributed representations. The lexicon-based memory is built to help generate such position-dependent features and deal with the problem of out-of-vocabulary words. Experimental results show that the proposed model, called LEMON, achieved state-of-the-art performance with an increase in the F 1-score up to 3.2% over the state-of-the-art models on four different widely-used NER datasets.","volume":38,"issue":5,"firstpage":1021,"lastpage":1035,"year":2023,"type":"Regular Paper","research_area":["Information Extraction","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1153-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1153-y?year=2023&issue=5","affiliations":["Fudan University","Shanghai Key Laboratory of Intelligent Information Processing"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-021-1691-3","title":"Cognition: Accurate and Consistent Linear Log Parsing Using Template Correction","authors":[{"last":"Tian","first":"Ran"},{"last":"Diao","first":"Zu-Long"},{"last":"Jiang","first":"Hai-Yang"},{"last":"Xie","first":"Gao-Gang"}],"keywords":["log analysis","log parsing","template correction"],"abstract":"Logs contain runtime information for both systems and users. As many of them use natural language, a typical log-based analysis needs to parse logs into the structured format first. Existing parsing approaches often take two steps. The first step is to find similar words (tokens) or sentences. Second, parsers extract log templates by replacing different tokens with variable placeholders. However, we observe that most parsers concentrate on precisely grouping similar tokens or logs. But they do not have a well-designed template extraction process, which leads to inconsistent accuracy on particular datasets. The root cause is the ambiguous definition of variable placeholders and similar templates. The consequences include abuse of variable placeholders, incorrectly divided templates, and an excessive number of templates over time. In this paper, we propose our online log parsing approach Cognition. It redefines variable placeholders via a strict lower bound to avoid ambiguity first. Then, it applies our template correction technique to merge and absorb similar templates. It eliminates the interference of commonly used parameters and thus isolates template quantity. Evaluation through 16 public datasets shows that Cognition has better accuracy and consistency than the state-of-the-art approaches. It also saves up to 52.1% of time cost on average than the others.","volume":38,"issue":5,"firstpage":1036,"lastpage":1050,"year":2023,"type":"Regular Paper","research_area":["Code Intelligence & Maintenance"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1691-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1691-3?year=2023&issue=5","affiliations":["Chinese Academy of Sciences","University of Chinese Academy of Sciences, CAS","Nanjing Institute of Geology & Paleontology, CAS","Institute of Computing Technology, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2957-8","title":"Dalea: A Persistent Multi-Level Extendible Hashing with Improved Tail Performance","authors":[{"last":"Xiong","first":"Zi-Wei"},{"last":"Jiang","first":"De-Jun"},{"last":"Xiong","first":"Jin"},{"last":"Ren","first":"Ren"}],"keywords":["persistent memory","persistent hashing","indexing structure"],"abstract":"Persistent memory (PM) promises byte-addressability, large capacity, and durability. Main memory systems, such as key-value stores and in-memory databases, benefit from such features of PM. Due to the great popularity of hashing index in main memory systems, a number of research efforts are made to provide high average performance persistent hashing. However, suboptimal tail performance in terms of tail throughput and tail latency is still observed for existing persistent hashing. In this paper, we analyze major sources of suboptimal tail performance from key design issues of persistent hashing. We identify the global hash structure and concurrency control as remaining explorable design spaces for improving tail performance. We propose Directory-sharing Multi-level Extendible Hashing (Dalea) for PM. Dalea designs ancestor link-based extendible hashing as well as fine-grained transient lock to address the two main sources (rehashing and locking) affecting tail performance. The evaluation results show that, compared with state-of-the-art persistent hashing Dash, Dalea achieves increased tail throughput by 4.1x and reduced tail latency by 5.4x. Moreover, in order to provide design guidelines for improving tail performance, we adopt Dalea as a testbed to identify different impacts of four factors on tail performance, including fine-grained rehashing, transient locking, memory pre-allocation, and fingerprinting.","volume":38,"issue":5,"firstpage":1051,"lastpage":1073,"year":2023,"type":"Regular Paper","research_area":["Databases & Query Processing","Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2957-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2957-8?year=2023&issue=5","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS","Huawei Technologies"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1457-6","title":"VTensor: Using Virtual Tensors to Build a Layout-Oblivious AI Programming Framework","authors":[{"last":"Yu","first":"Feng"},{"last":"Zhao","first":"Jia-Cheng"},{"last":"Cui","first":"Hui-Min"},{"last":"Feng","first":"Xiao-Bing"},{"last":"Xue","first":"Jingling"}],"keywords":["artificial intelligence (AI) programming","layout-oblivious","tensor processing"],"abstract":"Tensors are a popular programming interface for developing artificial intelligence (AI) algorithms. Layout refers to the order of placing tensor data in the memory and will affect performance by affecting data locality; therefore the deep neural network library has a convention on the layout. Since AI applications can use arbitrary layouts, and existing AI systems do not provide programming abstractions to shield the layout conventions of libraries, operator developers need to write a lot of layout-related code, which reduces the efficiency of integrating new libraries or developing new operators. Furthermore, the developer assigns the layout conversion operation to the internal operator to deal with the uncertainty of the input layout, thus losing the opportunity for layout optimization. Based on the idea of polymorphism, we propose a layout-agnostic virtual tensor programming interface, namely the VTensor framework, which enables developers to write new operators without caring about the underlying physical layout of tensors. In addition, the VTensor framework performs global layout inference at runtime to transparently resolve the required layout of virtual tensors, and runtime layout-oriented optimizations to globally minimize the number of layout transformation operations. Experimental results demonstrate that with VTensor, developers can avoid writing layout-dependent code. Compared with TensorFlow, for the 16 operations used in 12 popular networks, VTensor can reduce the lines of code (LOC) of writing a new operation by 47.82% on average, and improve the overall performance by 18.65% on average.","volume":38,"issue":5,"firstpage":1074,"lastpage":1097,"year":2023,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1457-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1457-6?year=2023&issue=5","affiliations":["Chinese Academy of Sciences","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS","University of New South Wales Sydney"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1232-8","title":"Path-Based Multicast Routing for Network-on-Chip of the Neuromorphic Processor","authors":[{"last":"Kang","first":"Zi-Yang"},{"last":"Li","first":"Shi-Ming"},{"last":"Wang","first":"Shi-Ying"},{"last":"Qu","first":"Lian-Hua"},{"last":"Gong","first":"Rui"},{"last":"Shi","first":"Wei"},{"last":"Xu","first":"Wei-Xia"},{"last":"Wang","first":"Lei"}],"keywords":["neuromorphic processor","spiking neural network (SNN)","Network-on-Chip (NoC)","path-based multicast"],"abstract":"Network-on-Chip (NoC) is widely adopted in neuromorphic processors to support communication between neurons in spiking neural networks (SNNs). However, SNNs generate enormous spiking packets due to the one-to-many traffic pattern. The spiking packets may cause communication pressure on NoC. We propose a path-based multicast routing method to alleviate the pressure. Firstly, all destination nodes of each source node on NoC are divided into several clusters. Secondly, multicast paths in the clusters are created based on the Hamiltonian path algorithm. The proposed routing can reduce the length of path and balance the communication load of each router. Lastly, we design a lightweight microarchitecture of NoC, which involves a customized multicast packet and a routing function. We use six datasets to verify the proposed multicast routing. Compared with unicast routing, the running time of path-based multicast routing achieves 5.1x speedup, and the number of hops and the maximum transmission latency of path-based multicast routing are reduced by 68.9% and 77.4%, respectively. The maximum length of path is reduced by 68.3% and 67.2% compared with the dual-path (DP) and multi-path (MP) multicast routing, respectively. Therefore, the proposed multicast routing has improved performance in terms of average latency and throughput compared with the DP or MP multicast routing.","volume":38,"issue":5,"firstpage":1098,"lastpage":1112,"year":2023,"type":"Regular Paper","research_area":["Convolutional & Spiking Networks","Deep Learning & Neural Networks","Processor & Microarchitecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1232-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1232-8?year=2023&issue=5","affiliations":["National University of Defense Technology - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2839-0","title":"CA-DTS: A Distributed and Collaborative Task Scheduling Algorithm for Edge Computing Enabled Intelligent Road Network","authors":[{"last":"Hu","first":"Shi-Hong"},{"last":"Luo","first":"Qu-Yuan"},{"last":"Li","first":"Guang-Hui"},{"last":"Shi","first":"Weisong"},{"last":"Ye","first":"Bao-Liu"}],"keywords":["edge computing","deep reinforcement learning","task scheduling","vehicular edge computing"],"abstract":"Edge computing enabled Intelligent Road Network (EC-IRN) provides powerful and convenient computing services for vehicles and roadside sensing devices. The continuous emergence of transportation applications has caused a huge burden on roadside units (RSUs) equipped with edge servers in the Intelligent Road Network (IRN). Collaborative task scheduling among RSUs is an effective way to solve this problem. However, it is challenging to achieve collaborative scheduling among different RSUs in a completely decentralized environment. In this paper, we first model the interactions involved in task scheduling among distributed RSUs as a Markov game. Given that multi-agent deep reinforcement learning (MADRL) is a promising approach for the Markov game in decision optimization, we propose a collaborative task scheduling algorithm based on MADRL for EC-IRN, named CA-DTS, aiming to minimize the long-term average delay of tasks. To reduce the training costs caused by trial-and-error, CA-DTS specially designs a reward function and utilizes the distributed deployment and collective training architecture of counterfactual multi-agent policy gradient (COMA). To improve the stability of performance in large-scale environments, CA-DTS takes advantage of the action semantics network (ASN) to facilitate cooperation among multiple RSUs. The evaluation results of both the testbed and simulation demonstrate the effectiveness of our proposed algorithm. Compared with the baselines, CA-DTS can achieve convergence about 35% faster, and obtain average task delay that is lower by approximately 9.4%, 9.8%, and 6.7%, in different scenarios with varying numbers of RSUs, service types, and task arrival rates, respectively.","volume":38,"issue":5,"firstpage":1113,"lastpage":1131,"year":2023,"type":"Regular Paper","research_area":["Cloud, Edge & Utility Computing","Reinforcement Learning","Scheduling & Resource Allocation"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2839-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2839-0?year=2023&issue=5","affiliations":["Southwest Jiaotong University","Jiangnan University","University of Delaware","Nanjing University"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1229-3","title":"Side-Channel Analysis for the Re-Keying Protocol of Bluetooth Low Energy","authors":[{"last":"Cao","first":"Pei"},{"last":"Zhang","first":"Chi"},{"last":"Lu","first":"Xiang-Jun"},{"last":"Lu","first":"Hai-Ning"},{"last":"Gu","first":"Da-Wu"}],"keywords":["Bluetooth low energy (BLE/BTLE)","long term key","re-keying protocol","side-channel analysis"],"abstract":"In the era of the Internet of Things, Bluetooth low energy (BLE/BTLE) plays an important role as a well-known wireless communication technology. While the security and privacy of BLE have been analyzed and fixed several times, the threat of side-channel attacks to BLE devices is still not well understood. In this work, we highlight a side-channel threat to the re-keying protocol of BLE. This protocol uses a fixed long term key for generating session keys, and the leakage of the long term key could render the encryption of all the following (and previous) connections useless. Our attack exploits the side-channel leakage of the re-keying protocol when it is implemented on embedded devices. In particular, we present successful correlation electromagnetic analysis and deep learning based profiled analysis that recover long term keys of BLE devices. We evaluate our attack on an ARM Cortex-M4 processor (Nordic Semiconductor nRF52840) running Nimble, a popular open-source BLE stack. Our results demonstrate that the long term key can be recovered within only a small amount of electromagnetic traces. Further, we summarize the features and limitations of our attack, and suggest a range of countermeasures to prevent it.","volume":38,"issue":5,"firstpage":1132,"lastpage":1148,"year":2023,"type":"Regular Paper","research_area":["Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1229-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1229-3?year=2023&issue=5","affiliations":["Shanghai Jiao Tong University"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1458-5","title":"Accurate Robotic Grasp Detection with Angular Label Smoothing","authors":[{"last":"Shi","first":"Min"},{"last":"Lu","first":"Hao"},{"last":"Li","first":"Zhao-Xin"},{"last":"Zhu","first":"Deng-Ming"},{"last":"Wang","first":"Zhao-Qi"}],"keywords":["robotic grasp detection","attention mechanism","angular label smoothing","anchor box","deep learning"],"abstract":"Grasp detection is a visual recognition task where the robot makes use of its sensors to detect graspable objects in its environment. Despite the steady progress in robotic grasping, it is still difficult to achieve both real-time and high accuracy grasping detection. In this paper, we propose a real-time robotic grasp detection method, which can accurately predict potential grasp for parallel-plate robotic grippers using RGB images. Our work employs an end-to-end convolutional neural network which consists of a feature descriptor and a grasp detector. And for the first time, we add an attention mechanism to the grasp detection task, which enables the network to focus on grasp regions rather than background. Specifically, we present an angular label smoothing strategy in our grasp detection method to enhance the fault tolerance of the network. We quantitatively and qualitatively evaluate our grasp detection method from different aspects on the public Cornell dataset and Jacquard dataset. Extensive experiments demonstrate that our grasp detection method achieves superior performance to the state-of-the-art methods. In particular, our grasp detection method ranked first on both the Cornell dataset and the Jacquard dataset, giving rise to the accuracy of 98.9% and 95.6%, respectively at real-time calculation speed.","volume":38,"issue":5,"firstpage":1149,"lastpage":1161,"year":2023,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Robotics & Control"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1458-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1458-5?year=2023&issue=5","affiliations":["North China Electric Power University","Chinese Academy of Sciences","Institute of Computing Technology, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1218-6","title":"Model Checking for Probabilistic Multiagent Systems","authors":[{"last":"Fu","first":"Chen"},{"last":"Turrini","first":"Andrea"},{"last":"Huang","first":"Xiaowei"},{"last":"Song","first":"Lei"},{"last":"Feng","first":"Yuan"},{"last":"Zhang","first":"Li-Jun"}],"keywords":["probabilistic multiagent system","model checking","uniform scheduler","probabilistic epistemic temporal logic"],"abstract":"In multiagent systems, agents usually do not have complete information of the whole system, which makes the analysis of such systems hard. The incompleteness of information is normally modelled by means of accessibility relations, and the schedulers consistent with such relations are called uniform. In this paper, we consider probabilistic multiagent systems with accessibility relations and focus on the model checking problem with respect to the probabilistic epistemic temporal logic, which can specify both temporal and epistemic properties. However, the problem is undecidable in general. We show that it becomes decidable when restricted to memoryless uniform schedulers. Then, we present two algorithms for this case: one reduces the model checking problem into a mixed integer non-linear programming (MINLP) problem, which can then be solved by Satisfiability Modulo Theories (SMT) solvers, and the other is an approximate algorithm based on the upper confidence bounds applied to trees (UCT) algorithm, which can return a result whenever queried. These algorithms have been implemented in an existing model checker and then validated on experiments. The experimental results show the efficiency and extendability of these algorithms, and the algorithm based on UCT outperforms the one based on MINLP in most cases.","volume":38,"issue":5,"firstpage":1162,"lastpage":1186,"year":2023,"type":"Regular Paper","research_area":["Formal Methods & Verification","Uncertainty & Probabilistic Modeling"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1218-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1218-6?year=2023&issue=5","affiliations":["Chinese Academy of Sciences","Institute of Software, CAS","University of Chinese Academy of Sciences, CAS","University of Liverpool"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1803-8","title":"Parallel Bounded Search for the Maximum Clique Problem","authors":[{"last":"Jiang","first":"Hua"},{"last":"Bai","first":"Ke"},{"last":"Liu","first":"Hai-Jiao"},{"last":"Li","first":"Chu-Min"},{"last":"Manya","first":"Felip"},{"last":"Fu","first":"Zhang-Hua"}],"keywords":["Branch-and-Bound (BnB)","maximum clique problem (MCP)","parallel search"],"abstract":"Given an undirected graph, the Maximum Clique Problem (MCP) is to find a largest complete subgraph of the graph. MCP is NP-hard and has found many practical applications. In this paper, we propose a parallel Branch-and- Bound (BnB) algorithm to tackle this NP-hard problem, which carries out multiple bounded searches in parallel. Each search has its upper bound and shares a lower bound with the rest of the searches. The potential benefit of the proposed approach is that an active search terminates as soon as the best lower bound found so far reaches or exceeds its upper bound. We describe the implementation of our highly scalable and efficient parallel MCP algorithm, called PBS, which is based on a state-of-the-art sequential MCP algorithm. The proposed algorithm PBS is evaluated on hard DIMACS and BHOSLIB instances. The results show that PBS achieves a near-linear speedup on most DIMACS instances and a super-linear speedup on most BHOSLIB instances. Finally, we give a detailed analysis that explains the good speedups achieved for the tested instances.","volume":38,"issue":5,"firstpage":1187,"lastpage":1202,"year":2023,"type":"Regular Paper","research_area":["Graph Theory & Algorithms"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1803-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1803-8?year=2023&issue=5","affiliations":["Yunnan University","Universite de Picardie Jules Verne (UPJV)","Consejo Superior de Investigaciones Cientificas (CSIC)","CSIC - Instituto de Investigacion en Inteligencia Artificial (IIIA)"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-0005-3","title":"What's Missing in Agile Hardware Design? Verification!","authors":[{"last":"Falsafi","first":"Babak"}],"keywords":[],"abstract":"","volume":38,"issue":4,"firstpage":735,"lastpage":736,"year":2023,"type":"Perspective","research_area":["Processor & Microarchitecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-0005-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-0005-3?year=2023&issue=4","affiliations":["Swiss Federal Institutes of Technology Domain","Ecole Polytechnique Federale de Lausanne"],"type_origin":"Editorial Material","cover_doi":"10.1007/s11390-023-3285-8","topic_source":"cover_inherited"},{"doi":"10.1007/s11390-023-3285-8","title":"Functional Verification for Agile Processor Development: A Case for Workflow Integration","authors":[{"last":"Xu","first":"Yi-Nan"},{"last":"Yu","first":"Zi-Hao"},{"last":"Wang","first":"Kai-Fan"},{"last":"Wang","first":"Hua-Qiang"},{"last":"Lin","first":"Jia-Wei"},{"last":"Jin","first":"Yue"},{"last":"Zhang","first":"Lin-Juan"},{"last":"Zhang","first":"Zi-Fei"},{"last":"Tang","first":"Dan"},{"last":"Wang","first":"Sa"},{"last":"Shi","first":"Kan"},{"last":"Sun","first":"Ning-Hui"},{"last":"Bao","first":"Yun-Gang"}],"keywords":["functional verification","agile development","open-source hardware","workflow integration"],"abstract":"Agile hardware development methodology has been widely adopted over the past decade. Despite the research progress, the industry still doubts its applicability, especially for the functional verification of complicated processor chips. Functional verification commonly employs a simulation-based method of co-simulating the design under test with a reference model and checking the consistency of their outcomes given the same input stimuli. We observe limited collaboration and information exchange through the design and verification processes, dramatically leading to inefficiencies when applying the conventional functional verification workflow to agile development. In this paper, we propose workflow integration with collaborative task delegation and dynamic information exchange as the design principles to effectively address the challenges on functional verification under the agile development model. Based on workflow integration, we enhance the functional verification workflows with a series of novel methodologies and toolchains. The diff-rule based agile verification methodology (DRAV) reduces the overhead of building reference models with runtime execution information from designs under test. We present the RISC-V implementation for DRAV, DiffTest, which adopts information probes to extract internal design behaviors for co-simulation and debugging. It further integrates two plugins, namely XFUZZ for effective test generation guided by design coverage metrics and LightSSS for efficient fault analysis triggered by co-simulation mismatches. We present the integrated workflows for agile hardware development and demonstrate their effectiveness in designing and verifying RISC-V processors with 33 functional bugs found in NutShell. We also illustrate the efficiency of the proposed toolchains with a case study on a functional bug in the L2 cache of XiangShan.","volume":38,"issue":4,"firstpage":737,"lastpage":753,"year":2023,"type":"Regular Paper","research_area":["Processor & Microarchitecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3285-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3285-8?year=2023&issue=4","affiliations":["Chinese Academy of Sciences","University of Chinese Academy of Sciences","Beijing Institute of Open Source Chip"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-023-3074-4","title":"Joint Participant Selection and Learning Optimization for Federated Learning of Multiple Models in Edge Cloud","authors":[{"last":"Wei","first":"Xinliang"},{"last":"Liu","first":"Jiyao"},{"last":"Wang","first":"Yu"}],"keywords":["edge computing","federated learning (FL)","participant selection","learning optimization"],"abstract":"To overcome the limitations of long latency and privacy concerns from cloud computing, edge computing along with distributed machine learning such as federated learning (FL), has gained much attention and popularity in academia and industry. Most existing work on FL over the edge mainly focuses on optimizing the training of one shared global model in edge systems. However, with the increasing applications of FL in edge systems, there could be multiple FL models from different applications concurrently being trained in the shared edge cloud. Such concurrent training of these FL models can lead to edge resource competition (for both computing and network resources), and further affect the FL training performance of each other. Therefore, in this paper, considering a multi-model FL scenario, we formulate a joint participant selection and learning optimization problem in a shared edge cloud. This joint optimization aims to determine FL participants and the learning schedule for each FL model such that the total training cost of all FL models in the edge cloud is minimized. We propose a multi-stage optimization framework by decoupling the original problem into two or three subproblems that can be solved respectively and iteratively. Extensive evaluation has been conducted with realworld FL datasets and models. The results have shown that our proposed algorithms can reduce the total cost efficiently compared with prior algorithms.","volume":38,"issue":4,"firstpage":754,"lastpage":772,"year":2023,"type":"Regular Paper","research_area":["Cloud, Edge & Utility Computing","Federated Learning","Optimization & Heuristic Methods"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3074-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3074-4?year=2023&issue=4","affiliations":["Pennsylvania Commonwealth System of Higher Education (PCSHE)","Temple University"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1214-x","title":"Prepartition: Load Balancing Approach for Virtual Machine Reservations in a Cloud Data Center","authors":[{"last":"Tian","first":"Wen-Hong"},{"last":"Xu","first":"Min-Xian"},{"last":"Zhou","first":"Guang-Yao"},{"last":"Wu","first":"Kui"},{"last":"Xu","first":"Cheng-Zhong"},{"last":"Buyya","first":"Rajkumar"}],"keywords":["cloud computing","physical machine (PM)","virtual machine (VM)","reservation","load balancing","Prepartition"],"abstract":"Load balancing is vital for the efficient and long-term operation of cloud data centers. With virtualization, post (reactive) migration of virtual machines (VMs) after allocation is the traditional way for load balancing and consolidation. However, it is not easy for reactive migration to obtain predefined load balance objectives and it may interrupt services and bring instability. Therefore, we provide a new approach, called Prepartition, for load balancing. It partitions a VM request into a few sub-requests sequentially with start time, end time and capacity demands, and treats each sub-request as a regular VM request. In this way, it can proactively set a bound for each VM request on each physical machine and makes the scheduler get ready before VM migration to obtain the predefined load balancing goal, which supports the resource allocation in a fine-grained manner. Simulations with real-world trace and synthetic data show that our proposed approach with offline version (PrepartitionOff) scheduling has 10%-20% better performance than the existing load balancing baselines under several metrics, including average utilization, imbalance degree, makespan and Capacity_makespan. We also extend Prepartition to online load balancing. Evaluation results show that our proposed approach also outperforms state-of-the-art online algorithms.","volume":38,"issue":4,"firstpage":773,"lastpage":792,"year":2023,"type":"Regular Paper","research_area":["Cloud, Edge & Utility Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1214-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1214-x?year=2023&issue=4","affiliations":["University of Electronic Science & Technology of China","Chinese Academy of Sciences","Shenzhen Institute of Advanced Technology, CAS","University of Victoria"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1189-z","title":"Improving Performance of Virtual Machine Covert Timing Channel Through Optimized Run-Length Encoding","authors":[{"last":"Wang","first":"Chong"},{"last":"Chen","first":"Rong-Liang"},{"last":"Gu","first":"Liang"}],"keywords":["covert storage channel","information security","covert channel threat evaluation","anti-detection criterion","covert channel restriction"],"abstract":"With its wider acceptability, cloud can host a diverse set of data and applications ranging from entertainment to personal to industry. The foundation of cloud computing is based on virtual machines where boundaries among the application data are very thin, and the potential of data leakage exists all the time. For instance, a virtual machine covert timing channel is an aggressive mechanism to leak confidential information through shared components or networks by violating isolation and security policies in practice. The performance of a covert timing channel (covert channel) is crucial to adversaries and attempts have been made to improve the performance of covert timing channels by advancing the encoding mechanism and covert information carriers. Though promising, the redundancy of the covert message is mainly overlooked. This paper applies three encoding schemes namely run-length, Huffman, and arithmetic encoding schemes for data compression of a virtual machine covert timing channel by exploiting redundancy. Accordingly, the paper studies the performance of such channels according to their capacity. Unfortunately, we show that these encoding schemes still contain redundancy in a covert channel scenario, and thereby a new encoding scheme namely optimized Runlength encoding (OptRLE) is presented that greatly enhances the performance of a covert timing channel. Several optimizations schemes adopted by OptRLE are also discussed, and a mathematical model of the behavior of an OptRLE-based covert timing channel is proposed. The theoretical capacity of a channel can be obtained using the proposed model. Our analysis reveals that OptRLE further improves the performance of a covert timing channel, in addition to the effects of the optimizations. Experimental result shows how OptRLE affects the size of covert data and the capacity of covert timing channels, and why the performance of the covert timing channel is improved.","volume":38,"issue":4,"firstpage":793,"lastpage":806,"year":2023,"type":"Regular Paper","research_area":["Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1189-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1189-z?year=2023&issue=4","affiliations":["Chinese Academy of Sciences","Shenzhen Institute of Advanced Technology, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-1266-6","title":"Evaluating RISC-V Vector Instruction Set Architecture Extension with Computer Vision Workloads","authors":[{"last":"Li","first":"Ruo-Shi"},{"last":"Peng","first":"Ping"},{"last":"Shao","first":"Zhi-Yuan"},{"last":"Jin","first":"Hai"},{"last":"Zheng","first":"Ran"}],"keywords":["RISC-V vector extension","single instruction multiple data (SIMD)","computer vision","OpenCV"],"abstract":"Computer vision (CV) algorithms have been extensively used for a myriad of applications nowadays. As the multimedia data are generally well-formatted and regular, it is beneficial to leverage the massive parallel processing power of the underlying platform to improve the performances of CV algorithms. Single Instruction Multiple Data (SIMD) instructions, capable of conducting the same operation on multiple data items in a single instruction, are extensively employed to improve the efficiency of CV algorithms. In this paper, we evaluate the power and effectiveness of RISC-V vector extension (RV-V) on typical CV algorithms, such as Gray Scale, Mean Filter, and Edge Detection. By our examinations, we show that compared with the baseline OpenCV implementation using scalar instructions, the equivalent implementations using the RV-V (version 0.8) can reduce the instruction count of the same CV algorithm up to 24x, when processing the same input images. Whereas, the actual performances improvement measured by the cycle counts is highly related with the specific implementation of the underlying RV-V co-processor. In our evaluation, by using the vector co-processor (with eight execution lanes) of Xuantie C906, vector-version CV algorithms averagely exhibit up to 2.98x performances speedups compared with their scalar counterparts.","volume":38,"issue":4,"firstpage":807,"lastpage":820,"year":2023,"type":"Regular Paper","research_area":["Computer Vision","Processor & Microarchitecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1266-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1266-6?year=2023&issue=4","affiliations":["Huazhong University of Science & Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1099-0","title":"Probabilistic Fault Diagnosis of Clustered Faults for Multiprocessor Systems","authors":[{"last":"Sun","first":"Xue-Li"},{"last":"Fan","first":"Jian-Xi"},{"last":"Cheng","first":"Bao-Lei"},{"last":"Wang","first":"Yan"},{"last":"Zhang","first":"Li"}],"keywords":["regular graph","clustered fault","probabilistic diagnosis algorithm","Preparata Metze Chien model (PMC model)"],"abstract":"With the development of high-performance computing and the expansion of large-scale multiprocessor systems, it is significant to study the reliability of systems. Probabilistic fault diagnosis is of practical value to the reliability analysis of multiprocessor systems. In this paper, we design a linear time diagnosis algorithm with the multiprocessor system whose threshold is set to 3, where the probability that any node is correctly diagnosed in the discrete state can be calculated. Furthermore, we give the probabilities that all nodes of a d-regular and d-connected graph can be correctly diagnosed in the continuous state under the Weibull fault distribution and the Chi-square fault distribution. We prove that they approach to 1, which implies that our diagnosis algorithm can correctly diagnose almost all nodes of the graph.","volume":38,"issue":4,"firstpage":821,"lastpage":833,"year":2023,"type":"Regular Paper","research_area":["Fault Diagnosis & Reliability"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1099-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1099-0?year=2023&issue=4","affiliations":["Soochow University - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1064-y","title":"Unsupervised Dialogue State Tracking for End-to-End Task-Oriented Dialogue with a Multi-Span Prediction Network","authors":[{"last":"Liu","first":"Qing-Bin"},{"last":"He","first":"Shi-Zhu"},{"last":"Liu","first":"Cao"},{"last":"Liu","first":"Kang"},{"last":"Zhao","first":"Jun"}],"keywords":["end-to-end task-oriented dialogue","dialogue state tracking (DST)","unsupervised learning","reinforcement learning"],"abstract":"This paper focuses on end-to-end task-oriented dialogue systems, which jointly handle dialogue state tracking (DST) and response generation. Traditional methods usually adopt a supervised paradigm to learn DST from a manually labeled corpus. However, the annotation of the corpus is costly, time-consuming, and cannot cover a wide range of domains in the real world. To solve this problem, we propose a multi-span prediction network (MSPN) that performs unsupervised DST for end-to-end task-oriented dialogue. Specifically, MSPN contains a novel split-merge copy mechanism that captures long-term dependencies in dialogues to automatically extract multiple text spans as keywords. Based on these keywords, MSPN uses a semantic distance based clustering approach to obtain the values of each slot. In addition, we propose an ontology-based reinforcement learning approach, which employs the values of each slot to train MSPN to generate relevant values. Experimental results on single-domain and multi-domain task-oriented dialogue datasets show that MSPN achieves state-of-the-art performance with significant improvements. Besides, we construct a new Chinese dialogue dataset MeDial in the low-resource medical domain, which further demonstrates the adaptability of MSPN.","volume":38,"issue":4,"firstpage":834,"lastpage":852,"year":2023,"type":"Regular Paper","research_area":["Contrastive & Self-Supervised Learning","Reinforcement Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1064-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1064-y?year=2023&issue=4","affiliations":["Chinese Academy of Sciences","Institute of Automation, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1119-0","title":"Improving BERT Fine-Tuning via Self-Ensemble and Self-Distillation","authors":[{"last":"Xu","first":"Yi-Ge"},{"last":"Qiu","first":"Xi-Peng"},{"last":"Zhou","first":"Li-Gao"},{"last":"Huang","first":"Xuan-Jing"}],"keywords":["BERT","deep learning","fine-tuning","natural language processing (NLP)","pre-training model"],"abstract":"Fine-tuning pre-trained language models like BERT have become an effective way in natural language processing (NLP) and yield state-of-the-art results on many downstream tasks. Recent studies on adapting BERT to new tasks mainly focus on modifying the model structure, re-designing the pre-training tasks, and leveraging external data and knowledge. The fine-tuning strategy itself has yet to be fully explored. In this paper, we improve the fine-tuning of BERT with two effective mechanisms: self-ensemble and self-distillation. The self-ensemble mechanism utilizes the checkpoints from an experience pool to integrate the teacher model. In order to transfer knowledge from the teacher model to the student model efficiently, we further use knowledge distillation, which is called self-distillation because the distillation comes from the model itself through the time dimension. Experiments on the GLUE benchmark and the Text Classification benchmark show that our proposed approach can significantly improve the adaption of BERT without any external data or knowledge. We conduct exhaustive experiments to investigate the efficiency of the self-ensemble and self-distillation mechanisms, and our proposed approach achieves a new state-of-the-art result on the SNLI dataset.","volume":38,"issue":4,"firstpage":853,"lastpage":866,"year":2023,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Fine-Tuning & Model Adaptation"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1119-0","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1119-0?year=2023&issue=4","affiliations":["Fudan University","Huawei Technologies"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-3140-y","title":"PESTA: An Elastic Motion Capture Data Retrieval Method","authors":[{"last":"Jiang","first":"Zi-Fei"},{"last":"Li","first":"Wei"},{"last":"Huang","first":"Yan"},{"last":"Yin","first":"Yi-Long"},{"last":"Kuo","first":"C. -C. Jay"},{"last":"Peng","first":"Jing-Liang"}],"keywords":["motion capture (MoCap)","content-based retrieval","adversarial autoencoder","temporal alignment"],"abstract":"Prevalent use of motion capture (MoCap) produces large volumes of data and MoCap data retrieval becomes crucial for efficient data reuse. MoCap clips may not be neatly segmented and labeled, increasing the difficulty of retrieval. In order to effectively retrieve such data, we propose an elastic content-based retrieval scheme via unsupervised posture encoding and strided temporal alignment (PESTA) in this work. It retrieves similarities at the sub-sequence level, achieves robustness against singular frames and enables control of tradeoff between precision and efficiency. It firstly learns a dictionary of encoded postures utilizing unsupervised adversarial autoencoder techniques and, based on which, compactly symbolizes any MoCap sequence. Secondly, it conducts strided temporal alignment to align a query sequence to repository sequences to retrieve the best-matching sub-sequences from the repository. Further, it extends to find matches for multiple sub-queries in a long query at sharply promoted efficiency and minutely sacrificed precision. Outstanding performance of the proposed scheme is well demonstrated by experiments on two public MoCap datasets and one MoCap dataset captured by ourselves.","volume":38,"issue":4,"firstpage":867,"lastpage":884,"year":2023,"type":"Regular Paper","research_area":["Computer Vision","Databases & Query Processing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3140-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3140-y?year=2023&issue=4","affiliations":["Shandong University","University of Southern California","University of Jinan"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1115-z","title":"Real-Time Underwater Image Enhancement Using Adaptive Full-Scale Retinex","authors":[{"last":"Xu","first":"Xing-Gui"},{"last":"Fan","first":"Xiang-Suo"},{"last":"Liu","first":"Yong-Li"}],"keywords":["underwater","image enhancement","Retinex","imaging through turbulent media"],"abstract":"Current Retinex-based image enhancement methods with fixed scale filters cannot adapt to situations involving various depths of field and illuminations. In this paper, a simple but effective method based on adaptive full-scale Retinex (AFSR) is proposed to clarify underwater images or videos. First, we design an adaptive full-scale filter that is guided by the optical transmission rate to estimate illumination components. Then, to reduce the computational complexity, we develop a quantitative mapping method instead of non-linear log functions for directly calculating the reflection component. The proposed method is capable of real-time processing of underwater videos using temporal coherence and Fourier transformations. Compared with eight state-of-the-art clarification methods, our method yields comparable or better results for image contrast enhancement, color-cast correction and clarity.","volume":38,"issue":4,"firstpage":885,"lastpage":898,"year":2023,"type":"Regular Paper","research_area":["Computer Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1115-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1115-z?year=2023&issue=4","affiliations":["Yunnan University of Finance & Economics","Guangxi University of Science & Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1161-y","title":"DyPipe: A Holistic Approach to Accelerating Dynamic Neural Networks with Dynamic Pipelining","authors":[{"last":"Zhuang","first":"Yi-Min"},{"last":"Hu","first":"Xing"},{"last":"Chen","first":"Xiao-Bing"},{"last":"Zhi","first":"Tian"}],"keywords":["dynamic neural network (NN)","deep neural network (DNN) accelerator","dynamic pipelining"],"abstract":"Dynamic neural network (NN) techniques are increasingly important because they facilitate deep learning techniques with more complex network architectures. However, existing studies, which predominantly optimize the static computational graphs by static scheduling methods, usually focus on optimizing static neural networks in deep neural network (DNN) accelerators. We analyze the execution process of dynamic neural networks and observe that dynamic features introduce challenges for efficient scheduling and pipelining in existing DNN accelerators. We propose DyPipe, a holistic approach to optimizing dynamic neural network inferences in enhanced DNN accelerators. DyPipe achieves significant performance improvements for dynamic neural networks while it introduces negligible overhead for static neural networks. Our evaluation demonstrates that DyPipe achieves 1.7x speedup on dynamic neural networks and maintains more than 96% performance for static neural networks.","volume":38,"issue":4,"firstpage":899,"lastpage":910,"year":2023,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","GPU & Accelerator Architecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1161-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1161-y?year=2023&issue=4","affiliations":["Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1152-7","title":"Multimodal Interactive Network for Sequential Recommendation","authors":[{"last":"Han","first":"Teng-Yue"},{"last":"Wang","first":"Peng-Fei"},{"last":"Niu","first":"Shao-Zhang"}],"keywords":["multi-modality","interactive network","sequential recommendation"],"abstract":"Building an effective sequential recommendation system is still a challenging task due to limited interactions among users and items. Recent work has shown the effectiveness of incorporating textual or visual information into sequential recommendation to alleviate the data sparse problem. The data sparse problem now is attracting a lot of attention in both industry and academic community. However, considering interactions among modalities on a sequential scenario is an interesting yet challenging task because of multimodal heterogeneity. In this paper, we introduce a novel recommendation approach of considering both textual and visual information, namely Multimodal Interactive Network (MIN). The advantage of MIN lies in designing a learning framework to leverage the interactions among modalities from both the item level and the sequence level for building an efficient system. Firstly, an item-wise interactive layer based on the encoder-decoder mechanism is utilized to model the item-level interactions among modalities to select the informative information. Secondly, a sequence interactive layer based on the attention strategy is designed to capture the sequence-level preference of each modality. MIN seamlessly incorporates interactions among modalities from both the item level and the sequence level for sequential recommendation. It is the first time that interactions in each modality have been explicitly discussed and utilized in sequential recommenders. Experimental results on four real-world datasets show that our approach can significantly outperform all the baselines in sequential recommendation task.","volume":38,"issue":4,"firstpage":911,"lastpage":926,"year":2023,"type":"Regular Paper","research_area":["Recommendation Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1152-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1152-7?year=2023&issue=4","affiliations":["Beijing University of Posts & Telecommunications"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1048-y","title":"Context-Aware Semantic Type Identification for Relational Attributes","authors":[{"last":"Ding","first":"Yue"},{"last":"Guo","first":"Yu-He"},{"last":"Lu","first":"Wei"},{"last":"Li","first":"Hai-Xiang"},{"last":"Zhang","first":"Mei-Hui"},{"last":"Li","first":"Hui"},{"last":"Pan","first":"An-Qun"},{"last":"Du","first":"Xiao-Yong"}],"keywords":["attribute semantic type (AST) identification","context-aware","semantic embedding","knowledge base embedding"],"abstract":"Identifying semantic types for attributes in relations, known as attribute semantic type (AST) identification, plays an important role in many data analysis tasks, such as data cleaning, schema matching, and keyword search in databases. However, due to a lack of unified naming standards across prevalent information systems (a.k.a. information islands), AST identification still remains as an open problem. To tackle this problem, we propose a context-aware method to figure out the ASTs for relations in this paper. We transform the AST identification into a multi-class classification problem and propose a schema context aware (SCA) model to learn the representation from a collection of relations associated with attribute values and schema context. Based on the learned representation, we predict the AST for a given attribute from an underlying relation, wherein the predicted AST is mapped to one of the labeled ASTs. To improve the performance for AST identification, especially for the case that the predicted semantic types of attributes are not included in the labeled ASTs, we then introduce knowledge base embeddings (a.k.a. KBVec) to enhance the above representation and construct a schema context aware model with knowledge base enhanced (SCA-KB) to get a stable and robust model. Extensive experiments based on real datasets demonstrate that our context-aware method outperforms the state-of-the-art approaches by a large margin, up to 6.14% and 25.17% in terms of macro average F1 score, and up to 0.28% and 9.56% in terms of weighted F1 score over high-quality and low-quality datasets respectively.","volume":38,"issue":4,"firstpage":927,"lastpage":946,"year":2023,"type":"Regular Paper","research_area":["Databases & Query Processing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1048-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1048-y?year=2023&issue=4","affiliations":["Renmin University of China","Beijing Institute of Technology","Guizhou University"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-0003-5","title":"Preface","authors":[{"last":"Hu","first":"Shi-Min"},{"last":"Bermano","first":"Amit"},{"last":"Hu","first":"Rui-Zhen"}],"keywords":[],"abstract":"","volume":38,"issue":3,"firstpage":471,"lastpage":472,"year":2023,"type":"Regular Paper","research_area":[],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-0003-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-0003-5?year=2023&issue=3","affiliations":["Tsinghua University","Tel Aviv University","Shenzhen University"],"type_origin":"Editorial Material"},{"doi":"10.1007/s11390-023-3210-1","title":"A Survey on 360° Images and Videos in Mixed Reality: Algorithms and Applications","authors":[{"last":"Zhang","first":"Fanglue"},{"last":"Zhao","first":"Junhong"},{"last":"Zhang","first":"Yun"},{"last":"Zollmann","first":"Stefanie"}],"keywords":["360(degrees) image","mixed reality","360(degrees) image processing","virtual reality scene reconstruction","virtual reality content manipulation"],"abstract":"Mixed reality technologies provide real-time and immersive experiences, which bring tremendous opportunities in entertainment, education, and enriched experiences that are not directly accessible owing to safety or cost. The research in this field has been in the spotlight in the last few years as the metaverse went viral. The recently emerging omnidirectional video streams, i.e., 360(degrees) videos, provide an affordable way to capture and present dynamic real-world scenes. In the last decade, fueled by the rapid development of artificial intelligence and computational photography technologies, the research interests in mixed reality systems using 360(degrees )videos with richer and more realistic experiences are dramatically increased to unlock the true potential of the metaverse. In this survey, we cover recent research aimed at addressing the above issues in the 360(degrees ) image and video processing technologies and applications for mixed reality. The survey summarizes the contributions of the recent research and describes potential future research directions about 360(degrees) media in the field of mixed reality.","volume":38,"issue":3,"firstpage":473,"lastpage":491,"year":2023,"type":"Survey","research_area":["Computer Graphics & Visualization","Computer Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3210-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3210-1?year=2023&issue=3","affiliations":["Victoria University Wellington","Communication University of Zhejiang","University of Otago"],"type_origin":"Review"},{"doi":"10.1007/s11390-023-3127-8","title":"PuzzleNet: Boundary-Aware Feature Matching for Non-Overlapping 3D Point Clouds Assembly","authors":[{"last":"Liu","first":"Hao-Yu"},{"last":"Guo","first":"Jian-Wei"},{"last":"Jiang","first":"Hai-Yong"},{"last":"Liu","first":"Yan-Chao"},{"last":"Zhang","first":"Xiao-Peng"},{"last":"Yan","first":"Dong-Ming"}],"keywords":["shape assembly","3D registration","geometric learning","boundary feature","point cloud"],"abstract":"We address the 3D shape assembly of multiple geometric pieces without overlaps, a scenario often encountered in 3D shape design, field archeology, and robotics. Existing methods depend on strong assumptions on the number of shape pieces and coherent geometry or semantics of shape pieces. Despite raising attention to 3D registration with complex or low overlapping patterns, few methods consider shape assembly with rare overlaps. To address this problem, we present a novel framework inspired by solving puzzles, named PuzzleNet, which conducts multi-task learning by leveraging both 3D alignment and boundary information. Specifically, we design an end-to-end neural network based on a point cloud transformer with two-way branches for estimating rigid transformation and predicting boundaries simultaneously. The framework is then naturally extended to reassemble multiple pieces into a full shape by using an iterative greedy approach based on the distance between each pair of candidate-matched pieces. To train and evaluate PuzzleNet, we construct two datasets, named DublinPuzzle and ModelPuzzle, based on a real-world urban scan dataset (DublinCity) and a synthetic CAD dataset (ModelNet40) respectively. Experiments demonstrate our effectiveness in solving 3D shape assembly for multiple pieces with arbitrary geometry and inconsistent semantics. Our method surpasses state-of-the-art algorithms by more than 10 times in rotation metrics and four times in translation metrics.","volume":38,"issue":3,"firstpage":492,"lastpage":509,"year":2023,"type":"Regular Paper","research_area":["Point Cloud & 3D Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3127-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3127-8?year=2023&issue=3","affiliations":["Chinese Academy of Sciences","Institute of Automation, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-3088-y","title":"Self-Supervised Monocular Depth Estimation by Digging into Uncertainty Quantification","authors":[{"last":"Li","first":"Yuan-Zhen"},{"last":"Zheng","first":"Sheng-Jie"},{"last":"Tan","first":"Zi-Xin"},{"last":"Cao","first":"Tuo"},{"last":"Luo","first":"Fei"},{"last":"Xiao","first":"Chun-Xia"}],"keywords":["self-supervised","monocular depth estimation","uncertainty quantification","variance"],"abstract":"Based on well-designed network architectures and objective functions, self-supervised monocular depth estimation has made great progress. However, lacking a specific mechanism to make the network learn more about the regions containing moving objects or occlusion scenarios, existing depth estimation methods likely produce poor results for them. Therefore, we propose an uncertainty quantification method to improve the performance of existing depth estimation networks without changing their architectures. Our uncertainty quantification method consists of uncertainty measurement, the learning guidance by uncertainty, and the ultimate adaptive determination. Firstly, with Snapshot and Siam learning strategies, we measure the uncertainty degree by calculating the variance of pre-converged epochs or twins during training. Secondly, we use the uncertainty to guide the network to strengthen learning about those regions with more uncertainty. Finally, we use the uncertainty to adaptively produce the final depth estimation results with a balance of accuracy and robustness. To demonstrate the effectiveness of our uncertainty quantification method, we apply it to two state-of-the-art models, Monodepth2 and Hints. Experimental results show that our method has improved the depth estimation performance in seven evaluation metrics compared with two baseline models and exceeded the existing uncertainty method.","volume":38,"issue":3,"firstpage":510,"lastpage":525,"year":2023,"type":"Regular Paper","research_area":["Contrastive & Self-Supervised Learning","Point Cloud & 3D Vision","Uncertainty & Probabilistic Modeling"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3088-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3088-y?year=2023&issue=3","affiliations":["Wuhan University"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-3117-x","title":"RC-Net: Row and Column Network with Text Feature for Parsing Floor Plan Images","authors":[{"last":"Wang","first":"Teng"},{"last":"Meng","first":"Wei-Liang"},{"last":"Lu","first":"Zheng-Da"},{"last":"Guo","first":"Jian-Wei"},{"last":"Xiao","first":"Jun"},{"last":"Zhang","first":"Xiao-Peng"}],"keywords":["floor plan understanding","text feature","Row and Column (RC) constraint module","Row and Column network (RC-Net)"],"abstract":"The popularity of online home design and floor plan customization has been steadily increasing. However, the manual conversion of floor plan images from books or paper materials into electronic resources can be a challenging task due to the vast amount of historical data available. By leveraging neural networks to identify and parse floor plans, the process of converting these images into electronic materials can be significantly streamlined. In this paper, we present a novel learning framework for automatically parsing floor plan images. Our key insight is that the room type text is very common and crucial in floor plan images as it identifies the important semantic information of the corresponding room. However, this clue is rarely considered in previous learning-based methods. In contrast, we propose the Row and Column network (RC-Net) for recognizing floor plan elements by integrating the text feature. Specifically, we add the text feature branch in the network to extract text features corresponding to the room type for the guidance of room type predictions. More importantly, we formulate the Row and Column constraint module (RC constraint module) to share and constrain features across the entire row and column of the feature maps to ensure that only one type is predicted in each room as much as possible, making the segmentation boundaries between different rooms more regular and cleaner. Extensive experiments on three benchmark datasets validate that our framework substantially outperforms other state-of-the-art approaches in terms of the metrics of FWIoU, mACC and mIoU.","volume":38,"issue":3,"firstpage":526,"lastpage":539,"year":2023,"type":"Regular Paper","research_area":["Computer Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3117-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3117-x?year=2023&issue=3","affiliations":["Chinese Academy of Sciences","Institute of Automation, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-3064-6","title":"Emotion-Aware Music Driven Movie Montage","authors":[{"last":"Liu","first":"Wu-Qin"},{"last":"Lin","first":"Min-Xuan"},{"last":"Huang","first":"Hai-Bin"},{"last":"Ma","first":"Chong-Yang"},{"last":"Song","first":"Yu"},{"last":"Dong","first":"Wei-Ming"},{"last":"Xu","first":"Chang-Sheng"}],"keywords":["movie montage","emotion analysis","audio-visual modality","contrastive learning"],"abstract":"In this paper, we present Emotion-Aware Music Driven Movie Montage, a novel paradigm for the challenging task of generating movie montages. Specifically, given a movie and a piece of music as the guidance, our method aims to generate a montage out of the movie that is emotionally consistent with the music. Unlike previous work such as video summarization, this task requires not only video content understanding, but also emotion analysis of both the input movie and music. To this end, we propose a two-stage framework, including a learning-based module for the prediction of emotion similarity and an optimization-based module for the selection and composition of candidate movie shots. The core of our method is to align and estimate emotional similarity between music clips and movie shots in a multi-modal latent space via contrastive learning. Subsequently, the montage generation is modeled as a joint optimization of emotion similarity and additional constraints such as scene-level story completeness and shot-level rhythm synchronization. We conduct both qualitative and quantitative evaluations to demonstrate that our method can generate emotionally consistent montages and outperforms alternative baselines.","volume":38,"issue":3,"firstpage":540,"lastpage":553,"year":2023,"type":"Regular Paper","research_area":["Contrastive & Self-Supervised Learning","Speech & Audio"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3064-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3064-6?year=2023&issue=3","affiliations":["Chinese Academy of Sciences","University of Chinese Academy of Sciences, CAS","Institute of Automation, CAS","University of Science & Technology Beijing"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-3101-5","title":"Learning Local Contrast for Crisp Edge Detection","authors":[{"last":"Fang","first":"Xiao-Nan"},{"last":"Zhang","first":"Song-Hai"}],"keywords":["edge detection","image processing","neural network","local contrast"],"abstract":"In recent years, the accuracy of edge detection on several benchmarks has been significantly improved by deep learning based methods. However, the prediction of deep neural networks is usually blurry and needs further post-processing including non-maximum suppression and morphological thinning. In this paper, we demonstrate that the blurry effect arises from the binary cross-entropy loss, and crisp edges could be obtained directly from deep convolutional neural networks. We propose to learn edge maps as the representation of local contrast with a novel local contrast loss. The local contrast is optimized in a stochastic way to focus on specific edge directions. Experiments show that the edge detection network trained with local contrast loss achieves a high accuracy comparable to previous methods and dramatically improves the crispness. We also present several applications of the crisp edges, including image completion, image retrieval, sketch generation, and video stylization.","volume":38,"issue":3,"firstpage":554,"lastpage":566,"year":2023,"type":"Regular Paper","research_area":["Computer Vision","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3101-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3101-5?year=2023&issue=3","affiliations":["Tsinghua University"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-023-3066-4","title":"PCRTAM-Net: A Novel Pre-Activated Convolution Residual and Triple Attention Mechanism Network for Retinal Vessel Segmentation","authors":[{"last":"Wang","first":"Hua-Deng"},{"last":"Li","first":"Zi-Zheng"},{"last":"Okuwobi","first":"Idowu Paul"},{"last":"Li","first":"Bing-Bing"},{"last":"Pan","first":"Xi-Peng"},{"last":"Liu","first":"Zhen-Bing"},{"last":"Lan","first":"Ru-Shi"},{"last":"Luo","first":"Xiao-Nan"}],"keywords":["retinal image segmentation","triple attention mechanism","atrous convolution","residual network"],"abstract":"Retinal images play an essential role in the early diagnosis of ophthalmic diseases. Automatic segmentation of retinal vessels in color fundus images is challenging due to the morphological differences between the retinal vessels and the low-contrast background. At the same time, automated models struggle to capture representative and discriminative retinal vascular features. To fully utilize the structural information of the retinal blood vessels, we propose a novel deep learning network called Pre-Activated Convolution Residual and Triple Attention Mechanism Network (PCRTAM-Net). PCRTAM-Net uses the pre-activated dropout convolution residual method to improve the feature learning ability of the network. In addition, the residual atrous convolution spatial pyramid is integrated into both ends of the network encoder to extract multiscale information and improve blood vessel information flow. A triple attention mechanism is proposed to extract the structural information between vessel contexts and to learn long-range feature dependencies. We evaluate the proposed PCRTAM-Net on four publicly available datasets, DRIVE, CHASE_DB1, STARE, and HRF. Our model achieves state-of-the-art performance of 97.10%, 97.70%, 97.68%, and 97.14% for ACC and 83.05%, 82.26%, 84.64%, and 81.16% for F1, respectively.","volume":38,"issue":3,"firstpage":567,"lastpage":581,"year":2023,"type":"Regular Paper","research_area":["Transformers & Attention"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3066-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3066-4?year=2023&issue=3","affiliations":["Guilin University of Electronic Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-1438-4","title":"Multi-Feature Fusion Based Structural Deep Neural Network for Predicting Answer Time on Stack Overflow","authors":[{"last":"Guo","first":"Shi-Kai"},{"last":"Wang","first":"Si-Wen"},{"last":"Li","first":"Hui"},{"last":"Fan","first":"Yu-Long"},{"last":"Liu","first":"Ya-Qing"},{"last":"Zhang","first":"Bin"}],"keywords":["answer time","structural deep neural network","Stack Overflow","feature acquisition","feature fusion"],"abstract":"Stack Overflow provides a platform for developers to seek suitable solutions by asking questions and receiving answers on various topics. However, many questions are usually not answered quickly enough. Since the questioners are eager to know the specific time interval at which a question can be answered, it becomes an important task for Stack Overflow to feedback the answer time to the question. To address this issue, we propose a model for predicting the answer time of questions, named Predicting Answer Time (i.e., PAT model), which consists of two parts: a feature acquisition and fusion model, and a deep neural network model. The framework uses a variety of features mined from questions in Stack Overflow, including the question description, question title, question tags, the creation time of the question, and other temporal features. These features are fused and fed into the deep neural network to predict the answer time of the question. As a case study, post data from Stack Overflow are used to assess the model. We use traditional regression algorithms as the baselines, such as Linear Regression, K-Nearest Neighbors Regression, Support Vector Regression, Multilayer Perceptron Regression, and Random Forest Regression. Experimental results show that the PAT model can predict the answer time of questions more accurately than traditional regression algorithms, and shorten the error of the predicted answer time by nearly 10 hours.","volume":38,"issue":3,"firstpage":582,"lastpage":599,"year":2023,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1438-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1438-4?year=2023&issue=3","affiliations":["Dalian Maritime University","Shandong Technology & Business University"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1143-8","title":"Augmenting Trigger Semantics to Improve Event Coreference Resolution","authors":[{"last":"Huan","first":"Min"},{"last":"Xu","first":"Sheng"},{"last":"Li","first":"Pei-Feng"}],"keywords":["event coreference resolution","trigger semantics augmentation","information interaction"],"abstract":"Due to the small size of the annotated corpora and the sparsity of the event trigger words, the event coreference resolver cannot capture enough event semantics, especially the trigger semantics, to identify coreferential event mentions. To address the above issues, this paper proposes a trigger semantics augmentation mechanism to boost event coreference resolution. First, this mechanism performs a trigger-oriented masking strategy to pre-train a BERT (Bidirectional Encoder Representations from Transformers)-based encoder (Trigger-BERT), which is fine-tuned on a large-scale unlabeled dataset Gigaword. Second, it combines the event semantic relations from the Trigger-BERT encoder with the event interactions from the soft-attention mechanism to resolve event coreference. Experimental results on both the KBP2016 and KBP2017 datasets show that our proposed model outperforms several state-of-the-art baselines.","volume":38,"issue":3,"firstpage":600,"lastpage":611,"year":2023,"type":"Regular Paper","research_area":["Information Extraction"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1143-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1143-8?year=2023&issue=3","affiliations":["Soochow University - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1000-1","title":"Graph Enhanced Transformer for Aspect Category Detection","authors":[{"last":"Chen","first":"Chen"},{"last":"Wang","first":"Hou-Feng"},{"last":"Zhu","first":"Qing-Qing"},{"last":"Liu","first":"Jun-Fei"}],"keywords":["aspect based sentiment analysis","aspect category detection","hierarchical multi-label classification","transformer network"],"abstract":"Aspect category detection is one challenging subtask of aspect based sentiment analysis, which categorizes a review sentence into a set of predefined aspect categories. Most existing methods regard the aspect category detection as a flat classification problem. However, aspect categories are inter-related, and they are usually organized with a hierarchical tree structure. To leverage the structure information, this paper proposes a hierarchical multi-label classification model to detect aspect categories and uses a graph enhanced transformer network to integrate label dependency information into prediction features. Experiments have been conducted on four widely-used benchmark datasets, showing that the proposed model outperforms all strong baselines.","volume":38,"issue":3,"firstpage":612,"lastpage":625,"year":2023,"type":"Regular Paper","research_area":["Sentiment Analysis & Opinion Mining","Transformers & Attention"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1000-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1000-1?year=2023&issue=3","affiliations":["Peking University"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-023-1902-1","title":"Bi-GAE: A Bidirectional Generative Auto-Encoder","authors":[{"last":"Hua","first":"Qin"},{"last":"Hu","first":"Han-Wen"},{"last":"Qian","first":"Shi-You"},{"last":"Yang","first":"Ding-Yu"},{"last":"Cao","first":"Jian"}],"keywords":["auto-encoder","adversarial network","image reconstruction and generation","feature representation"],"abstract":"Improving the generative and representational capabilities of auto-encoders is a hot research topic. However, it is a challenge to jointly and simultaneously optimize the bidirectional mapping between the encoder and the decoder/generator while ensuing convergence. Most existing auto-encoders cannot automatically trade off bidirectional mapping. In this work, we propose Bi-GAE, an unsupervised bidirectional generative auto-encoder based on bidirectional generative adversarial network (BiGAN). First, we introduce two terms that enhance information expansion in decoding to follow human visual models and to improve semantic-relevant feature representation capability in encoding. Furthermore, we embed a generative adversarial network (GAN) to improve representation while ensuring convergence. The experimental results show that Bi-GAE achieves competitive results in both generation and representation with stable convergence. Compared with its counterparts, the representational power of Bi-GAE improves the classification accuracy of high-resolution images by about 8.09%. In addition, Bi-GAE increases structural similarity index measure (SSIM) by 0.045, and decreases Frechet inception distance (FID) by 2.48 in the reconstruction of 512 x 512 images.","volume":38,"issue":3,"firstpage":626,"lastpage":643,"year":2023,"type":"Regular Paper","research_area":["Generative Models"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1902-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1902-1?year=2023&issue=3","affiliations":["Shanghai Jiao Tong University","Alibaba Group"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1073-x","title":"Improving Open Set Domain Adaptation Using Image-to-Image Translation and Instance-Weighted Adversarial Learning","authors":[{"last":"Zhang","first":"Hong-Jie"},{"last":"Li","first":"Ang"},{"last":"Guo","first":"Jie"},{"last":"Guo","first":"Yan-Wen"}],"keywords":["adversarial learning","domain adaptation","open set","translation"],"abstract":"We propose to address the open set domain adaptation problem by aligning images at both the pixel space and the feature space. Our approach, called Open Set Translation and Adaptation Network (OSTAN), consists of two main components: translation and adaptation. The translation is a cycle-consistent generative adversarial network, which translates any source image to the style of a target domain to eliminate domain discrepancy in the pixel space. The adaptation is an instance-weighted adversarial network, which projects both (labeled) translated source images and (unlabeled) target images into a domain-invariant feature space to learn a prior probability for each target image. The learned probability is applied as a weight to the unknown classifier to facilitate the identification of the unknown class. The proposed OSTAN model significantly outperforms the state-of-the-art open set domain adaptation methods on multiple public datasets. Our experiments also demonstrate that both the image-to-image translation and the instance-weighting framework can further improve the decision boundaries for both known and unknown classes.","volume":38,"issue":3,"firstpage":644,"lastpage":658,"year":2023,"type":"Regular Paper","research_area":["Multi-Task & Transfer Learning"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1073-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1073-x?year=2023&issue=3","affiliations":["Nanjing University","Alphabet Inc.","DeepMind"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1690-z","title":"Natural Image Matting with Attended Global Context","authors":[{"last":"Zhang","first":"Yi-Yi"},{"last":"Niu","first":"Li"},{"last":"Makihara","first":"Yasushi"},{"last":"Zhang","first":"Jian-Fu"},{"last":"Zhao","first":"Wei-Jie"},{"last":"Yagi","first":"Yasushi"},{"last":"Zhang","first":"Li-Qing"}],"keywords":["image matting","global context","deformable sampling"],"abstract":"Image matting is to estimate the opacity of foreground objects from an image. A few deep learning based methods have been proposed for image matting and perform well in capturing spatially close information. However, these methods fail to capture global contextual information, which has been proved essential in improving matting performance. This is because a matting image may be up to several megapixels, which is too big for a learning-based network to capture global contextual information due to the limit size of a receptive field. Although uniformly downsampling the matting image can alleviate this problem, it may result in the degradation of matting performance. To solve this problem, we introduce a natural image matting with the attended global context method to extract global contextual information from the whole image, and to condense them into a suitable size for learning-based network. Specifically, we first leverage a deformable sampling layer to obtain condensed foreground and background attended images respectively. Then, we utilize a contextual attention layer to extract information related to unknown regions from condensed foreground and background images generated by a deformable sampling layer. Besides, our network predicts a background as well as the alpha matte to obtain more purified foreground, which contributes to better qualitative performance in composition. Comprehensive experiments show that our method achieves competitive performance on both Composition-1k and the alphamatting.com benchmark quantitatively and qualitatively.","volume":38,"issue":3,"firstpage":659,"lastpage":673,"year":2023,"type":"Regular Paper","research_area":["Computer Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1690-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1690-z?year=2023&issue=3","affiliations":["Shanghai Jiao Tong University","University of Osaka"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-0870-1","title":"Semi-Supervised Intracranial Aneurysm Segmentation from CTA Images via Weight-Perceptual Self-Ensembling Model","authors":[{"last":"Li","first":"Cai-Zi"},{"last":"Liu","first":"Rui-Qiang"},{"last":"Zhong","first":"Huan-Xin"},{"last":"Fan","first":"Jun-Ming"},{"last":"Si","first":"Wei-Xin"},{"last":"Zhang","first":"Meng"},{"last":"Heng","first":"Pheng-Ann"}],"keywords":["intracranial aneurysm (IA) segmentation","sample weight perception","self-ensembling model","semi-supervised learning"],"abstract":"Segmentation of intracranial aneurysm (IA) from computed tomography angiography (CTA) images is of significant importance for quantitative assessment of IA and further surgical treatment. Manual segmentation of IA is a labor-intensive, time-consuming job and suffers from inter- and intra-observer variabilities. Training deep neural networks usually requires a large amount of labeled data, while annotating data is very time-consuming for the IA segmentation task. This paper presents a novel weight-perceptual self-ensembling model for semi-supervised IA segmentation, which employs unlabeled data by encouraging the predictions of given perturbed input samples to be consistent. Considering that the quality of consistency targets is not comparable to each other, we introduce a novel sample weight perception module to quantify the quality of different consistency targets. Our proposed module can be used to evaluate the contributions of unlabeled samples during training to force the network to focus on those well-predicted samples. We have conducted both horizontal and vertical comparisons on the clinical intracranial aneurysm CTA image dataset. Experimental results show that our proposed method can improve at least 3% Dice coefficient over the fully-supervised baseline, and at least 1.7% over other state-of-the-art semi-supervised methods.","volume":38,"issue":3,"firstpage":674,"lastpage":685,"year":2023,"type":"Regular Paper","research_area":["Bioinformatics & Life Sciences","Computer Vision"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-0870-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-0870-1?year=2023&issue=3","affiliations":["Chinese Academy of Sciences","Shenzhen Institute of Advanced Technology, CAS","University of Chinese Academy of Sciences, CAS","Shantou University"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1203-5","title":"A Quantitative Evaluation of Vector Transcendental Functions on ARMv8-Based Processors","authors":[{"last":"Shen","first":"Jie"},{"last":"Long","first":"Biao"},{"last":"Huang","first":"Chun"}],"keywords":["transcendental function","vector math library","piecewise quantitative evaluation","microbenchmarking","ARMv8-based processor"],"abstract":"Transcendental functions are important functions in various high performance computing applications. Because these functions are time-consuming and the vector units on modern processors become wider and more scalable, there is an increasing demand for developing and using vector transcendental functions in such performance-hungry applications. However, the performance of vector transcendental functions as well as their accuracy remain largely unexplored. To address this issue, we perform a comprehensive evaluation of two Single Instruction Multiple Data (SIMD) intrinsics based vector math libraries on two ARMv8 compatible processors. We first design dedicated microbenchmarks that help us understand the performance behavior of vector transcendental functions. Then, we propose a piecewise, quantitative evaluation method with a set of meaningful metrics to quantify their performance and accuracy. By analyzing the experimental results, we find that vector transcendental functions achieve good performance speedups thanks to the vectorization and algorithm optimization. Moreover, vector math libraries can replace scalar math libraries in many cases because of improved performance and satisfactory accuracy. Despite this, the implementations of vector math libraries are still immature, which means further optimization is needed, and our evaluation reveals feasible optimization solutions for future vector math libraries.","volume":38,"issue":3,"firstpage":686,"lastpage":701,"year":2023,"type":"Regular Paper","research_area":["Processor & Microarchitecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1203-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1203-5?year=2023&issue=3","affiliations":["National University of Defense Technology - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1981-4","title":"A Semi-Tensor Product Based All Solutions Boolean Satisfiability Solver","authors":[{"last":"Pan","first":"Hong-Yang"},{"last":"Chu","first":"Zhu-Fei"}],"keywords":["all solutions Boolean satisfiability (AllSAT)","semi-tensor product of matrices","conjunctive normal form (CNF) satisfiability","circuit satisfiability"],"abstract":"Boolean satisfiability (SAT) is widely used as a solver engine in electronic design automation (EDA). Typically, SAT is used to determine whether one or more groups of variables can be combined to form a true formula. All solutions SAT (AllSAT) is a variant of the SAT problem. In the fields of formal verification and pattern generation, AllSAT is particularly useful because it efficiently enumerates all possible solutions. In this paper, a semi-tensor product (STP) based AllSAT solver is proposed. The solver can solve instances described in both the conjunctive normal form (CNF) and circuit form. The implementation of our method differs from incremental enumeration because we do not add blocking conditions for existing solutions, but rather compute the matrices to obtain all the solutions in one pass. Additionally, the logical matrices support a variety of logic operations. Results from experiments with MCNC benchmarks using CNF-based and circuit-based forms show that our method can accelerate CPU time by 8.1x (238x maximum) and 19.9x (72x maximum), respectively.","volume":38,"issue":3,"firstpage":702,"lastpage":713,"year":2023,"type":"Regular Paper","research_area":["Formal Methods & Verification"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1981-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1981-4?year=2023&issue=3","affiliations":["Ningbo University"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1007-2","title":"Query Authentication Using Intel SGX for Blockchain Light Clients","authors":[{"last":"Shao","first":"Qi-Feng"},{"last":"Zhang","first":"Zhao"},{"last":"Jin","first":"Che-Qing"},{"last":"Zhou","first":"Ao-Ying"}],"keywords":["blockchain","query authentication","Merkle B-tree (MB-tree)","Intel software guard extensions (SGX)"],"abstract":"Due to limited computing and storage resources, light clients and full nodes coexist in a typical blockchain system. Any query from light clients must be forwarded to full nodes for execution, and light clients verify the integrity of query results returned. Since existing verifiable queries based on an authenticated data structure (ADS) suffer from significant network, storage and computing overheads by virtue of verification objects (VOs), an alternative way turns to the trusted execution environment (TEE), with which light clients do not need to receive or verify any VO. However, state-of-the-art TEEs cannot deal with large-scale applications conveniently due to the limited secure memory space (e.g., the size of the enclave in Intel SGX (software guard extensions), a typical TEE product, is only 128 MB). Hence, we organize data hierarchically in trusted (enclave) and untrusted memory, along with hot data buffered in the enclave to reduce page swapping overhead between two kinds of memory. The cost analysis and empirical study validate the effectiveness of our proposed scheme. The VO size of our scheme is reduced by one to two orders of magnitude compared with that of the traditional scheme.","volume":38,"issue":3,"firstpage":714,"lastpage":734,"year":2023,"type":"Regular Paper","research_area":["Blockchain & Distributed Ledger","Databases & Query Processing","Security, Privacy & Cryptography"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1007-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1007-2?year=2023&issue=3","affiliations":["East China Normal University","Zhongyuan University of Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-2845-7","title":"Facebook and Tencent Data Fit a Cube Law Better than Metcalfe’s Law","authors":[{"last":"Zhang","first":"Xing-Zhou"},{"last":"Xu","first":"Zhi-Wei"}],"keywords":["network effect","Metcalfe’s law","cube law","netoid function"],"abstract":"Metcalfe’s law states that the value of a network grows as the square of the number of its users ( V\\propto n^2 ), which was validated by actual data of Facebook and Tencent in 2013–2015. Since then, the users and the values of Facebook and Tencent have increased significantly. Is Metcalfe’s law still valid? This paper leverages the latest data of Facebook and Tencent to fit the network effect laws and makes the following observations: 1) actual data of network values fit a cube law ( V\\propto n^3 ) better than Metcalfe’s law; 2) actual data of network costs fit a cube law; 3) actual data of network sizes show a growth trend matching the netoid function well. We also discuss the underlying factors affecting such observations and the generality of the network effect laws.","volume":38,"issue":2,"firstpage":219,"lastpage":227,"year":2023,"type":"Regular Paper","research_area":["Data Mining & Analytics","Education & Social Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-2845-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-2845-7?year=2023&issue=2","affiliations":["Chinese Academy of Sciences","University of Chinese Academy of Sciences"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-023-2488-3","title":"On the Security of Smart Home Systems: A Survey","authors":[{"last":"Yuan","first":"Bin"},{"last":"Wan","first":"Jun"},{"last":"Wu","first":"Yu-Han"},{"last":"Zou","first":"De-Qing"},{"last":"Jin","first":"Hai"}],"keywords":["IoT (Internet of Things)","smart home","IoT security","smart home security"],"abstract":"Among the plethora of IoT (Internet of Things) applications, the smart home is one of the fastest-growing. However, the rapid development of the smart home has also made smart home systems a target for attackers. Recently, researchers have made many efforts to investigate and enhance the security of smart home systems. Toward a more secure smart home ecosystem, we present a detailed literature review on the security of smart home systems. Specifically, we categorize smart home systems' security issues into the platform, device, and communication issues. After exploring the research and specific issues in each of these security areas, we summarize the root causes of the security flaws in today's smart home systems, which include the heterogeneity of internal components of the systems, vendors' customization, the lack of clear responsibility boundaries and the absence of standard security standards. Finally, to better understand the security of smart home systems and potentially provide better protection for smart home systems, we propose research directions, including automated vulnerability mining, vigorous security checking, and data-driven security analysis.","volume":38,"issue":2,"firstpage":228,"lastpage":247,"year":2023,"type":"Survey","research_area":["IoT & Wireless Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2488-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2488-3?year=2023&issue=2","affiliations":["Huazhong University of Science & Technology","Shenzhen Huazhong University of Science & Technology Research Institute"],"type_origin":"Review"},{"doi":"10.1007/s11390-023-0002-6","title":"Preface","authors":[{"last":"Qian","first":"Wei-Kang"},{"last":"Chen","first":"Ke"},{"last":"Liu","first":"Wei-Qiang"},{"last":"Li","first":"Hua-Wei"}],"keywords":[],"abstract":"","volume":38,"issue":2,"firstpage":248,"lastpage":250,"year":2023,"type":"Regular Paper","research_area":[],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-0002-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-0002-6?year=2023&issue=2","affiliations":["Shanghai Jiao Tong University","Nanjing University of Aeronautics & Astronautics","Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS"],"type_origin":"Editorial Material"},{"doi":"10.1007/s11390-023-2537-y","title":"A Survey of Approximate Computing: From Arithmetic Units Design to High-Level Applications","authors":[{"last":"Que","first":"Hao-Hua"},{"last":"Jin","first":"Yu"},{"last":"Wang","first":"Tong"},{"last":"Liu","first":"Ming-Kai"},{"last":"Yang","first":"Xing-Hua"},{"last":"Qiao","first":"Fei"}],"keywords":["approximate computing","arithmetic unit","low power","high performance","reduced output quality"],"abstract":"Realizing a high-performance and energy-efficient circuit system is one of the critical tasks for circuit designers. Conventional researchers always concentrated on the tradeoffs between the energy and the performance in circuit and system design based on accurate computing. However, as video/image processing and machine learning algorithms are widespread, the technique of approximate computing in these applications has become a hot topic. The errors caused by approximate computing could be tolerated by these applications with specific processing or algorithms, and large improvements in performance or power savings could be achieved with some acceptable loss in final output quality. This paper presents a survey of approximate computing from arithmetic units design to high-level applications, in which we try to give researchers a comprehensive and insightful understanding of approximate computing. We believe that approximate computing will play an important role in the circuit and system design in the future, especially with the rapid development of artificial intelligence algorithms and their related applications.","volume":38,"issue":2,"firstpage":251,"lastpage":272,"year":2023,"type":"Survey","research_area":["Approximate Computing & Circuits"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2537-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2537-y?year=2023&issue=2","affiliations":["Beijing Forestry University","Tsinghua University"],"type_origin":"Review"},{"doi":"10.1007/s11390-023-2554-x","title":"A Survey of Reliability Issues Related to Approximate Circuits","authors":[{"last":"Wang","first":"Zhen"},{"last":"Xu","first":"Rong-Chen"},{"last":"Chen","first":"Jia-Cheng"},{"last":"Xiao","first":"Jie"}],"keywords":["approximate circuit","error metric","fault tolerance","test","reliability"],"abstract":"As one of the most promising paradigms of integrated circuit design, the approximate circuit has aroused widespread concern in the scientific community. It takes advantage of the inherent error tolerance of some applications and relaxes the accuracy for reductions in area and power consumption. This paper aims to provide a comprehensive survey of reliability issues related to approximate circuits, which covers three concerns: error characteristic analysis, reliability and test, and reliable design involving approximate circuits. The error characteristic analysis is used to compare the outputs of the approximate circuit with those of its precise counterpart, which can help to find the most appropriate approximate design for a specific application in the large design space. With the approximate design getting close to physical realization, manufacturing defects and operational faults are inevitable; therefore, the reliability prediction and vulnerability test become increasingly important. However, the research on approximate circuit reliability and test is insufficient and needs more attention. Furtherly, although there is some existing work combining the approximate design with fault tolerant techniques, the reliability-enhancement approaches for approximate circuits are lacking.","volume":38,"issue":2,"firstpage":273,"lastpage":288,"year":2023,"type":"Survey","research_area":["Approximate Computing & Circuits","Fault Diagnosis & Reliability"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2554-x","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2554-x?year=2023&issue=2","affiliations":["Shanghai University of Electric Power","Zhejiang University of Technology"],"type_origin":"Review"},{"doi":"10.1007/s11390-023-2544-z","title":"An Optimization Technique for PMF Estimation in Approximate Circuits","authors":[{"last":"Dou","first":"Yu-Qin"},{"last":"Wang","first":"Cheng-Hua"}],"keywords":["approximate circuit","error quality estimate","probability mass function (PMF) estimation","architecture level"],"abstract":"As an emerging computing technology, approximate computing enables computing systems to utilize hardware resources efficiently. Recently, approximate arithmetic units have received extensive attention and have been employed as hardware modules to build approximate circuit systems, such as approximate accelerators. In order to make the approximate circuit system meet the application requirements, it is imperative to quickly estimate the error quality caused by the approximate unit, especially in the high-level synthesis of the approximate circuit. However, there are few studies in the literature on how to efficiently evaluate the errors in the approximate circuit system. Hence, this paper focuses on error evaluation techniques for circuit systems consisting of approximate adders and approximate multipliers, which are the key hardware components in fault-tolerant applications. In this paper, the characteristics of probability mass function (PMF) based estimation are analyzed initially, and then an optimization technique for PMF-based estimation is proposed with consideration of these features. Finally, experiments prove that the optimization technology can reduce the time required for PMF-based estimation and improve the estimation quality.","volume":38,"issue":2,"firstpage":289,"lastpage":297,"year":2023,"type":"Regular Paper","research_area":["Approximate Computing & Circuits"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2544-z","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2544-z?year=2023&issue=2","affiliations":["Nanjing University of Aeronautics and Astronautics"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2572-8","title":"LMM: A Fixed-Point Linear Mapping Based Approximate Multiplier for IoT","authors":[{"last":"Wu","first":"Ying"},{"last":"Wen","first":"Chen-Yi"},{"last":"Yin","first":"Xun-Zhao"},{"last":"Zhuo","first":"Cheng"}],"keywords":["approximate computing","fixed-point","linear mapping","multiplier","Internet of Things (IoT)"],"abstract":"The development of IoT (Internet of Things) calls for circuit designs with energy and area efficiency for edge devices. Approximate computing which trades unnecessary computation precision for hardware cost savings is a promising direction for error-tolerant applications. Multipliers, as frequently invoked basic modules which consume non-trivial hardware costs, have been introduced approximation to achieve distinct energy and area savings for data-intensive applications. In this paper, we propose a fixed-point approximate multiplier that employs a linear mapping technique, which enables the configurability of approximation levels and the unbiasedness of computation errors. We then introduce a dynamic truncation method into the proposed multiplier design to cover a wider and more fine-grained configuration range of approximation for more flexible hardware cost savings. In addition, a novel normalization module is proposed for the required shifting operations, which balances the occupied area and the critical path delay compared with normal shifters. The introduced errors of our proposed design are analyzed and expressed by formulas which are validated by experimental results. Experimental evaluations show that compared with accurate multipliers, our proposed approximate multiplier design provides maximum area and power savings up to 49.70% and 66.39% respectively with acceptable computation errors.","volume":38,"issue":2,"firstpage":298,"lastpage":308,"year":2023,"type":"Regular Paper","research_area":["Approximate Computing & Circuits","IoT & Wireless Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2572-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2572-8?year=2023&issue=2","affiliations":["Zhejiang University"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2548-8","title":"Approximate Processing Element Design and Analysis for the Implementation of CNN Accelerators","authors":[{"last":"Li","first":"Tong"},{"last":"Jiang","first":"Hong-Lan"},{"last":"Mo","first":"Hai"},{"last":"Han","first":"Jie"},{"last":"Liu","first":"Lei-Bo"},{"last":"Mao","first":"Zhi-Gang"}],"keywords":["approximate computing","convolutional neural network (CNN)","sum of products (SoP)","data representation","multiplier"],"abstract":"As a primary computation unit, a processing element (PE) is key to the energy efficiency of a convolutional neural network (CNN) accelerator. Taking advantage of the inherent error tolerance of CNNs, approximate computing with high hardware efficiency has been considered for implementing the computation units of CNN accelerators. However, individual approximate designs such as multipliers and adders can only achieve limited accuracy and hardware improvements. In this paper, an approximate PE is dedicatedly devised for CNN accelerators by synergistically considering the data representation, multiplication and accumulation. An approximate data format is defined for the weights using stochastic rounding. This data format enables a simple implementation of multiplication by using small lookup tables, an adder and a shifter. Two approximate accumulators are further proposed for the product accumulation in the PE. Compared with the exact 8-bit fixed-point design, the proposed PE saves more than 29% and 20% in power-delay product for 3 x 3 and 5 x 5 sum of products, respectively. Also, compared with the PEs consisting of state-of-the-art approximate multipliers, the proposed design shows significantly smaller error bias with lower hardware overhead. Moreover, the application of the approximate PEs in CNN accelerators is analyzed by implementing a multi-task CNN for face detection and alignment. We conclude that 1) an approximate PE is more effective for face detection than for alignment, 2) an approximate PE with high statistically-measured accuracy does not necessarily result in good quality in face detection, and 3) properly increasing the number of PEs in a CNN accelerator can improve its power and energy efficiency.","volume":38,"issue":2,"firstpage":309,"lastpage":327,"year":2023,"type":"Regular Paper","research_area":["Approximate Computing & Circuits","Convolutional & Spiking Networks","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2548-8","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2548-8?year=2023&issue=2","affiliations":["Shanghai Jiao Tong University","Tsinghua University","University of Alberta"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2545-y","title":"LayCO: Achieving Least Lossy Accuracy for Most Efficient RRAM-Based Deep Neural Network Accelerator via Layer-Centric Co-Optimization","authors":[{"last":"Zhao","first":"Shao-Feng"},{"last":"Wang","first":"Fang"},{"last":"Liu","first":"Bo"},{"last":"Feng","first":"Dan"},{"last":"Liu","first":"Yang"}],"keywords":["deep learning","accelerator","resistive random access memory (RRAM)","energy efficiency","error tolerance"],"abstract":"Resistive random access memory (RRAM) enables the functionality of operating massively parallel dot products and accumulations. RRAM-based accelerator is such an effective approach to bridging the gap between Internet of Things devices' constrained resources and deep neural networks' tremendous cost. Due to the huge overhead of Analog to Digital (A/D) and digital accumulations, analog RRAM buffer is introduced to extend the processing in analog and in approximation. Although analog RRAM buffer offers potential solutions to A/D conversion issues, the energy consumption is still challenging in resource-constrained environments, especially with enormous intermediate data volume. Besides, critical concerns over endurance must also be resolved before the RRAM buffer could be frequently used in reality for DNN inference tasks. Then we propose LayCO, a layer-centric co-optimizing scheme to address the energy and endurance concerns altogether while strictly providing an inference accuracy guarantee. LayCO relies on two key ideas: 1) co-optimizing with reduced supply voltage and reduced bit-width of accelerator architectures to increase the DNN's error tolerance and achieve the accelerator's energy efficiency, and 2) efficiently mapping and swapping individual DNN data to a corresponding RRAM partition in a way that meets the endurance requirements. The evaluation with representative DNN models demonstrates that LayCO outperforms the baseline RRAM buffer based accelerator by 27x improvement in energy efficiency (over TIMELY-like configuration), 308x in lifetime prolongation and 6x in area reduction (over RAQ) while maintaining the DNN accuracy loss less than 1%.","volume":38,"issue":2,"firstpage":328,"lastpage":347,"year":2023,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","GPU & Accelerator Architecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2545-y","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2545-y?year=2023&issue=2","affiliations":["Huazhong University of Science & Technology","Henan University of Economics & Law","Zhengzhou University"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-1054-3","title":"A Survey of Non-Volatile Main Memory File Systems","authors":[{"last":"Wang","first":"Ying"},{"last":"Jia","first":"Wen-Qing"},{"last":"Jiang","first":"De-Jun"},{"last":"Xiong","first":"Jin"}],"keywords":["non-volatile main memory (NVMM)","file system","performance","scalability","crash consistency","data protection","crossmeida"],"abstract":"Non-volatile memories (NVMs) provide lower latency and higher bandwidth than block devices. Besides, NVMs are byte-addressable and provide persistence that can be used as memory-level storage devices (non-volatile main memory, NVMM). These features change storage hierarchy and allow CPU to access persistent data using load/store instructions. Thus, we can directly build a file system on NVMM. However, traditional file systems are designed based on slow block devices. They use a deep and complex software stack to optimize file system performance. This design results in software overhead being the dominant factor affecting NVMM file systems. Besides, scalability, crash consistency, data protection, and cross-media storage should be reconsidered in NVMM file systems. We survey existing work on optimizing NVMM file systems. First, we analyze the problems when directly using traditional file systems on NVMM, including heavy software overhead, limited scalability, inappropriate consistency guarantee techniques, etc. Second, we summarize the technique of 30 typical NVMM file systems and analyze their advantages and disadvantages. Finally, we provide a few suggestions for designing a high-performance NVMM file system based on real hardware Optane DC persistent memory module. Specifically, we suggest applying various techniques to reduce software overheads, improving the scalability of virtual file system (VFS), adopting highly-concurrent data structures (e.g., lock and index), using memory protection keys (MPK) for data protection, and carefully designing data placement/migration for cross-media file system.","volume":38,"issue":2,"firstpage":348,"lastpage":372,"year":2023,"type":"Survey","research_area":["Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1054-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1054-3?year=2023&issue=2","affiliations":["Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Review"},{"doi":"10.1007/s11390-023-1599-1","title":"Isolate Sets Based Parallel Louvain Method for Community Detection","authors":[{"last":"Qie","first":"Hang"},{"last":"Dou","first":"Yong"},{"last":"Huang","first":"Zhen"},{"last":"Xiong","first":"Yun-Sheng"}],"keywords":["parallel computing","isolate set","graph partition","Louvain method","community detection"],"abstract":"Community detection is a vital task in many fields, such as social networks and financial analysis, to name a few. The Louvain method, the main workhorse of community detection, is a popular heuristic method. To apply it to large-scale graph networks, researchers have proposed several parallel Louvain methods (PLMs), which suffer from two challenges: the latency in the information synchronization, and the community swap. To tackle these two challenges, we propose an isolate sets based parallel Louvain method (IPLM) and a fusion IPLM with the hashtables based Louvain method (FIPLM), which are based on a novel graph partition algorithm. Our graph partition algorithm divides the graph network into subgraphs called isolate sets, in which the vertices are relatively decoupled from others. We first describe the concepts and properties of the isolate set. Second we propose an algorithm to divide the graph network into isolate sets, which enjoys the same computation complexity as the breadth-first search. Third, we propose IPLM, which can efficiently calculate and update vertices information in parallel without latency or community swap. Finally, we achieve further acceleration by FIPLM, which maintains a high quality of community detection with a faster speedup than IPLM. Our two methods are for shared-memory architecture, and we implement our methods on an 8-core PC; the experiments show that IPLM achieves a maximum speedup of 4.62x and outputs higher modularity (maximum 4.76%) than the serial Louvain method on 14 of 18 datasets. Moreover, FIPLM achieves a maximum speedup of 7.26x.","volume":38,"issue":2,"firstpage":373,"lastpage":390,"year":2023,"type":"Regular Paper","research_area":["High-Performance & Parallel Computing","Graph Theory & Algorithms"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-1599-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-1599-1?year=2023&issue=2","affiliations":["National University of Defense Technology - China"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-1573-3","title":"A Prefetch-Adaptive Intelligent Cache Replacement Policy Based on Machine Learning","authors":[{"last":"Yang","first":"Hui-Jing"},{"last":"Fang","first":"Juan"},{"last":"Cai","first":"Min"},{"last":"Cai","first":"Zhi"}],"keywords":["hardware prefetching","machine learning","Prefetch-Adaptive Intelligent Cache Replacement Policy (PAIC)","replacement policy"],"abstract":"Hardware prefetching and replacement policies are two techniques to improve the performance of the memory subsystem. While prefetching hides memory latency and improves performance, interactions take place with the cache replacement policies, thereby introducing performance variability in the application. To improve the accuracy of reuse of cache blocks in the presence of hardware prefetching, we propose Prefetch-Adaptive Intelligent Cache Replacement Policy (PAIC). PAIC is designed with separate predictors for prefetch and demand requests, and uses machine learning to optimize reuse prediction in the presence of prefetching. By distinguishing reuse predictions for prefetch and demand requests, PAIC can better combine the performance benefits from prefetching and replacement policies. We evaluate PAIC on a set of 27 memory-intensive programs from the SPEC 2006 and SPEC 2017. Under single-core configuration, PAIC improves performance over Least Recently Used (LRU) replacement policy by 37.22%, compared with improvements of 32.93% for Signature-based Hit Predictor (SHiP), 34.56% for Hawkeye, and 34.43% for Glider. Under the four-core configuration, PAIC improves performance over LRU by 20.99%, versus 13.23% for SHiP, 17.89% for Hawkeye and 15.50% for Glider.","volume":38,"issue":2,"firstpage":391,"lastpage":404,"year":2023,"type":"Regular Paper","research_area":["Deep Learning & Neural Networks","Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-1573-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-1573-3?year=2023&issue=2","affiliations":["Beijing University of Technology"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-022-2553-3","title":"Parallel Software-Based Self-Testing with Bounded Model Checking for Kilo-Core Networks-on-Chip","authors":[{"last":"Zhang","first":"Ying"},{"last":"Ji","first":"Peng-Fei"},{"last":"Zhu","first":"Pan-Wei"},{"last":"Peng","first":"Zebo"},{"last":"Li","first":"Hua-Wei"},{"last":"Jiang","first":"Jian-Hui"}],"keywords":["software-based self-testing (SBST)","parallel test","kilo-core networks-on-chip (NoCs)","online testing"],"abstract":"Online testing is critical to ensuring reliable operations of the next generation of supercomputers based on a kilo-core network-on-chip (NoC) interconnection fabric. We present a parallel software-based self-testing (SBST) solution that makes use of the bounded model checking (BMC) technique to generate test sequences and parallel packets. In this method, the parallel SBST with BMC derives the leading sequence for each router's internal function and detects all functionally- testable faults related to the function. A Monte-Carlo simulation algorithm is then used to search for the approximately optimum configuration of the parallel packets, which guarantees the test quality and minimizes the test cost. Finally, a multi-threading technology is used to ensure that the Monte-Carlo simulation can reach the approximately optimum configuration in a large random space and reduce the generating time of the parallel test. Experimental results show that the proposed method achieves a high fault coverage with a reduced test overhead. Moreover, by performing online testing in the functional mode with SBST, it effectively avoids the over-testing problem caused by functionally untestable turns in kilo-core NoCs.","volume":38,"issue":2,"firstpage":405,"lastpage":421,"year":2023,"type":"Regular Paper","research_area":["Formal Methods & Verification","High-Performance & Parallel Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-2553-3","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-2553-3?year=2023&issue=2","affiliations":["Tongji University","Linkoping University","Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-021-1249-4","title":"Secure Speculation via Speculative Secret Flow Tracking","authors":[{"last":"Cui","first":"Hong-Wei"},{"last":"Yang","first":"Chun"},{"last":"Cheng","first":"Xu"}],"keywords":["cache side channel attack","hardware","speculative execution attack","security"],"abstract":"Speculative execution attacks can leak arbitrary program data under malicious speculation, presenting a severe security threat. Based on two key observations, this paper presents a software-transparent defense mechanism called speculative secret flow tracking (SSFT), which is capable of defending against all cache-based speculative execution attacks with a low performance overhead. First, we observe that the attacker must use array or pointer variables in the victim code to access arbitrary memory data. Therefore, we propose a strict definition of secret data to reduce the amount of data to be protected. Second, if the load is not data-dependent and control-dependent on secrets, its speculative execution will not leak any secrets. Thus, this paper introduces the concept of speculative secret flow to analyze how secret data are obtained and propagated during speculative execution. By tracking speculative secret flow in hardware, SSFT can identify all unsafe speculative loads (USLs) that are dependent on secrets. Moreover, SSFT exploits three different methods to constrain USLs' speculative execution and prevent them from leaking secrets into the cache and translation lookaside buffer (TLB) states. This paper evaluates the performance of SSFT on the SPEC CPU 2006 workloads, and the results show that SSFT is effective and its performance overhead is very low. To defend against all speculative execution attack variants, SSFT only incurs an average slowdown of 4.5% (Delay USL-L1Miss) or 3.8% (Invisible USLs) compared to a non-secure processor. Our analysis also shows that SSFT maintains a low hardware overhead.","volume":38,"issue":2,"firstpage":422,"lastpage":438,"year":2023,"type":"Regular Paper","research_area":["Security, Privacy & Cryptography","Memory & Storage Systems"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-021-1249-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-021-1249-4?year=2023&issue=2","affiliations":["Peking University"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-0979-2","title":"Single Image Deraining Using Residual Channel Attention Networks","authors":[{"last":"Wang","first":"Di"},{"last":"Pan","first":"Jin-Shan"},{"last":"Tang","first":"Jin-Hui"}],"keywords":["deraining","deep convolutional neural network (DCNN)","channel attention","detail restoration","unsupervised finetuning"],"abstract":"Image deraining is a highly ill-posed problem. Although significant progress has been made due to the use of deep convolutional neural networks, this problem still remains challenging, especially for the details restoration and generalization to real rain images. In this paper, we propose a deep residual channel attention network (DeRCAN) for deraining. The channel attention mechanism is able to capture the inherent properties of the feature space and thus facilitates more accurate estimations of structures and details for image deraining. In addition, we further propose an unsupervised learning approach to better solve real rain images based on the proposed network. Extensive qualitative and quantitative evaluation results on both synthetic and real-world images demonstrate that the proposed DeRCAN performs favorably against state-of-the-art methods.","volume":38,"issue":2,"firstpage":439,"lastpage":454,"year":2023,"type":"Regular Paper","research_area":["Convolutional & Spiking Networks","Deep Learning & Neural Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-0979-2","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-0979-2?year=2023&issue=2","affiliations":["Nanjing University of Science & Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-0824-7","title":"Optimization of Web Service Testing Task Assignment in Crowdtesting Environment","authors":[{"last":"Tang","first":"Wen-Jun"},{"last":"Chen","first":"Rong"},{"last":"Zhang","first":"Jia-Li"},{"last":"Huang","first":"Lin"},{"last":"Zheng","first":"Sheng-Jie"},{"last":"Guo","first":"Shi-Kai"}],"keywords":["crowdtesting","task assignment","web service testing","heuristic algorithm","optimization","quality of web service"],"abstract":"Crowdtesting has emerged as an attractive and economical testing paradigm that features testers from different countries, with various backgrounds and working conditions. Recent developments in crowdsourcing testing suggest that it is feasible to manage test populations and processes, but they are often outside the scope of standard testing theory. This paper explores how to allocate service-testing tasks to proper testers in an ever-changing crowdsourcing environment. We formalize it as an optimization problem with the objective to ensure the testing quality of the crowds, while considering influencing factors such as knowledge capability, the rewards, the network connections, and the geography and the skills required. To solve the proposed problem, we design a task assignment algorithm based on the Differential Evolution (DE) algorithm. Extensive experiments are conducted to evaluate the efficiency and effectiveness of the proposed algorithm in real and synthetic data, and the results show better performance compared with other heuristic-based algorithms.","volume":38,"issue":2,"firstpage":455,"lastpage":470,"year":2023,"type":"Regular Paper","research_area":["Optimization & Heuristic Methods","Scheduling & Resource Allocation"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-0824-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-0824-7?year=2023&issue=2","affiliations":["Dalian Maritime University"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-0001-7","title":"The Vibrant Field of Parallel and Distributed Computing-Scan the Special Issue in Honor of Professor Kai Hwang's 80th Birthday","authors":[{"last":"Li","first":"Guo-Jie"}],"keywords":[],"abstract":"","volume":38,"issue":1,"firstpage":1,"lastpage":2,"year":2023,"type":"Regular Paper","research_area":[],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-0001-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-0001-7?year=2023&issue=1","affiliations":["Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Institute of Computing Technology, CAS"],"type_origin":"Editorial Material"},{"doi":"10.1007/s11390-023-2879-5","title":"HXPY: A High-Performance Data Processing Package for Financial Time-Series Data","authors":[{"last":"Guo","first":"Jiadong"},{"last":"Peng","first":"Jingshu"},{"last":"Yuan","first":"Hang"},{"last":"Ni","first":"Lionel Ming-shuan"}],"keywords":["dataframe","time-series data","SIMD (single instruction multiple data)","CUDA (Compute Unified Device Architecture)"],"abstract":"A tremendous amount of data has been generated by global financial markets everyday, and such time-series data needs to be analyzed in real time to explore its potential value. In recent years, we have witnessed the successful adoption of machine learning models on financial data, where the importance of accuracy and timeliness demands highly effective computing frameworks. However, traditional financial time-series data processing frameworks have shown performance degradation and adaptation issues, such as the outlier handling with stock suspension in Pandas and TA-Lib. In this paper, we propose HXPY, a high-performance data processing package with a C++/Python interface for financial time-series data. HXPY supports miscellaneous acceleration techniques such as the streaming algorithm, the vectorization instruction set, and memory optimization, together with various functions such as time window functions, group operations, down-sampling operations, cross-section operations, row-wise or column-wise operations, shape transformations, and alignment functions. The results of benchmark and incremental analysis demonstrate the superior performance of HXPY compared with its counterparts. From MiBs to GiBs data, HXPY significantly outperforms other in-memory dataframe computing rivals even up to hundreds of times.","volume":38,"issue":1,"firstpage":3,"lastpage":24,"year":2023,"type":"Regular Paper","research_area":["GPU & Accelerator Architecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2879-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2879-5?year=2023&issue=1","affiliations":["Hong Kong University of Science & Technology","International Digital Economy Academy","Hong Kong University of Science & Technology (Guangzhou)"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-3073-5","title":"Ubiquitous WiFi and Acoustic Sensing: Principles, Technologies, and Applications","authors":[{"last":"Huang","first":"Jia-Ling"},{"last":"Wang","first":"Yun-Shu"},{"last":"Zou","first":"Yong-Pan"},{"last":"Wu","first":"Kai-Shun"},{"last":"Ni","first":"Lionel Ming-shuan"}],"keywords":["WiFi sensing","acoustic sensing","human-computer interaction","human activity recognition"],"abstract":"With the increasing pervasiveness of mobile devices such as smartphones, smart TVs, and wearables, smart sensing, transforming the physical world into digital information based on various sensing medias, has drawn researchers' great attention. Among different sensing medias, WiFi and acoustic signals stand out due to their ubiquity and zero hardware cost. Based on different basic principles, researchers have proposed different technologies for sensing applications with WiFi and acoustic signals covering human activity recognition, motion tracking, indoor localization, health monitoring, and the like. To enable readers to get a comprehensive understanding of ubiquitous wireless sensing, we conduct a survey of existing work to introduce their underlying principles, proposed technologies, and practical applications. Besides we also discuss some open issues of this research area. Our survey reals that as a promising research direction, WiFi and acoustic sensing technologies can bring about fancy applications, but still have limitations in hardware restriction, robustness, and applicability.","volume":38,"issue":1,"firstpage":25,"lastpage":63,"year":2023,"type":"Survey","research_area":["Human-Computer Interaction"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-3073-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-3073-5?year=2023&issue=1","affiliations":["Shenzhen University","Hong Kong University of Science & Technology (Guangzhou)","Hong Kong University of Science & Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-2911-1","title":"The Memory-Bounded Speedup Model and Its Impacts in Computing","authors":[{"last":"Sun","first":"Xian-He"},{"last":"Lu","first":"Xiaoyang"}],"keywords":["memory-bounded speedup","scalable computing","memory-wall","performance modeling and optimization","data-centric design"],"abstract":"With the surge of big data applications and the worsening of the memory-wall problem, the memory system, instead of the computing unit, becomes the commonly recognized major concern of computing. However, this memory-centric common understanding has a humble beginning. More than three decades ago, the memory-bounded speedup model is the first model recognizing memory as the bound of computing and provided a general bound of speedup and a computing-memory trade-off formulation. The memory-bounded model was well received even by then. It was immediately introduced in several advanced computer architecture and parallel computing textbooks in the 1990's as a must-know for scalable computing. These include Prof. Kai Hwang's book Scalable Parallel Computing in which he introduced the memory-bounded speedup model as the Sun-Ni's Law, parallel with the Amdahl's Law and the Gustafson's Law. Through the years, the impacts of this model have grown far beyond parallel processing and into the fundamental of computing. In this article, we revisit the memory-bounded speedup model and discuss its progress and impacts in depth to make a unique contribution to this special issue, to stimulate new solutions for big data applications, and to promote data-centric thinking and rethinking.","volume":38,"issue":1,"firstpage":64,"lastpage":79,"year":2023,"type":"Survey","research_area":["High-Performance & Parallel Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-2911-1","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-2911-1?year=2023&issue=1","affiliations":["Illinois Institute of Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-2950-7","title":"Adventures Beyond Amdahl's Law: How Power-Performance Measurement and Modeling at Scale Drive Server and Supercomputer Design","authors":[{"last":"Cameron","first":"Kirk W. W."}],"keywords":["Amdahl's Law","speedup","power-aware computing","power modeling","performance modeling","performance prediction","power measurement"],"abstract":"Amdahl's Law painted a bleak picture for large-scale computing. The implication was that parallelism was limited and therefore so was potential speedup. While Amdahl's contribution was seminal and important, it drove others vested in parallel processing to define more clearly why large-scale systems are critical to our future and how they fundamentally provide opportunities for speedup beyond Amdahl's predictions. In the early 2000s, much like Amdahl, we predicted dire consequences for large-scale systems due to power limits. While our early work was often dismissed, the implications were clear to some: power would ultimately limit performance. In this retrospective, we discuss how power-performance measurement and modeling at scale led to contributions that have driven server and supercomputer design for more than a decade. While the influence of these techniques is now indisputable, we discuss their connections, limits and additional research directions necessary to continue the performance gains our industry is accustomed to.","volume":38,"issue":1,"firstpage":80,"lastpage":86,"year":2023,"type":"Survey","research_area":["High-Performance & Parallel Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-2950-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-2950-7?year=2023&issue=1","affiliations":["Virginia Tech"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2885-7","title":"The Paradigm of Power Bounded High-Performance Computing","authors":[{"last":"Ge","first":"Rong"},{"last":"Feng","first":"Xizhou"},{"last":"Zou","first":"Pengfei"},{"last":"Allen","first":"Tyler"}],"keywords":["power bounded computing","cross-component power coordination","hierarchical power allocation"],"abstract":"Modern computer systems are increasingly bounded by the available or permissible power at multiple layers from individual components to data centers. To cope with this reality, it is necessary to understand how power bounds impact performance, especially for systems built from high-end nodes, each consisting of multiple power hungry components. Because placing an inappropriate power bound on a node or a component can lead to severe performance loss, coordinating power allocation among nodes and components is mandatory to achieve desired performance given a total power budget. In this article, we describe the paradigm of power bounded high-performance computing, which considers coordinated power bound assignment to be a key factor in computer system performance analysis and optimization. We apply this paradigm to the problem of power coordination across multiple layers for both CPU and GPU computing. Using several case studies, we demonstrate how the principles of balanced power coordination can be applied and adapted to the interplay of workloads, hardware technology, and the available total power for performance improvement.","volume":38,"issue":1,"firstpage":87,"lastpage":102,"year":2023,"type":"Perspective","research_area":["High-Performance & Parallel Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2885-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2885-7?year=2023&issue=1","affiliations":["Clemson University","Amazon.com","University of North Carolina","University of North Carolina Charlotte"],"type_origin":"Article"},{"doi":"10.1007/s11390-022-2898-7","title":"Information Superbahn: Towards a Planet-Scale, Low-Entropy and High-Goodput Computing Utility","authors":[{"last":"Xu","first":"Zhi-Wei"},{"last":"Li","first":"Zhen-Ying"},{"last":"Yu","first":"Zi-Shu"},{"last":"Li","first":"Feng-Zhi"}],"keywords":["cloud computing","computing utility","utilization","low-entropy system","high-goodput computing"],"abstract":"In a 1961 lecture to celebrate MIT's centennial, John McCarthy proposed the vision of utility computing, including three key concepts of pay-per-use service, large computer and private computer. Six decades have passed, but Mc- Carthy's computing utility vision has not yet been fully realized, despite advances in grid computing, services computing and cloud computing. This paper presents a perspective of computing utility called Information Superbahn, building on recent advances in cloud computing. This Information Superbahn perspective retains McCarthy's vision as much as possible, while making essential modern requirements more explicit, in the new context of a networked world of billions of users, trillions of devices, and zettabytes of data. Computing utility offers pay-per-use computing services through a 1) planet-scale, 2) low-entropy and 3) high-goodput utility. The three salient characteristics of computing utility are elaborated. Initial evidence is provided to support this viewpoint.","volume":38,"issue":1,"firstpage":103,"lastpage":114,"year":2023,"type":"Perspective","research_area":["Cloud, Edge & Utility Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-022-2898-7","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-022-2898-7?year=2023&issue=1","affiliations":["Chinese Academy of Sciences","Nanjing Institute of Geology & Paleontology, CAS","Institute of Computing Technology, CAS","University of Chinese Academy of Sciences, CAS"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2875-9","title":"GShuttle: Optimizing Memory Access Efficiency for Graph Convolutional Neural Network Accelerators","authors":[{"last":"Li","first":"Jia-Jun"},{"last":"Wang","first":"Ke"},{"last":"Zheng","first":"Hao"},{"last":"Louri","first":"Ahmed"}],"keywords":["graph convolutional neural network","memory access","neural network accelerator"],"abstract":"Graph convolutional neural networks (GCNs) have emerged as an effective approach to extending deep learning for graph data analytics, but they are computationally challenging given the irregular graphs and the large number of nodes in a graph. GCNs involve chain sparse-dense matrix multiplications with six loops, which results in a large design space for GCN accelerators. Prior work on GCN acceleration either employs limited loop optimization techniques, or determines the design variables based on random sampling, which can hardly exploit data reuse efficiently, thus degrading system efficiency. To overcome this limitation, this paper proposes GShuttle, a GCN acceleration scheme that maximizes memory access efficiency to achieve high performance and energy efficiency. GShuttle systematically explores loop optimization techniques for GCN acceleration, and quantitatively analyzes the design objectives (e.g., required DRAM accesses and SRAM accesses) by analytical calculation based on multiple design variables. GShuttle further employs two approaches, pruned search space sweeping and greedy search, to find the optimal design variables under certain design constraints. We demonstrated the efficacy of GShuttle by evaluation on five widely used graph datasets. The experimental simulations show that GShuttle reduces the number of DRAM accesses by a factor of 1.5 and saves energy by a factor of 1.7 compared with the state-of-the-art approaches.","volume":38,"issue":1,"firstpage":115,"lastpage":127,"year":2023,"type":"Regular Paper","research_area":["Convolutional & Spiking Networks","Deep Learning & Neural Networks","GPU & Accelerator Architecture"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2875-9","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2875-9?year=2023&issue=1","affiliations":["Beihang University","University of North Carolina","University of North Carolina Charlotte","State University System of Florida"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2907-5","title":"High Performance MPI over the Slingshot Interconnect","authors":[{"last":"Khorassani","first":"Kawthar Shafie"},{"last":"Chen","first":"Chen-Chun"},{"last":"Ramesh","first":"Bharath"},{"last":"Shafi","first":"Aamir"},{"last":"Subramoni","first":"Hari"},{"last":"Panda","first":"Dhabaleswar K"}],"keywords":["AMD GPU","interconnect technology","MPI (message passing interface)","Slingshot"],"abstract":"The Slingshot interconnect designed by HPE/Cray is becoming more relevant in high-performance computing with its deployment on the upcoming exascale systems. In particular, it is the interconnect empowering the first exascale and highest-ranked supercomputer in the world, Frontier. It offers various features such as adaptive routing, congestion control, and isolated workloads. The deployment of newer interconnects sparks interest related to performance, scalability, and any potential bottlenecks as they are critical elements contributing to the scalability across nodes on these systems. In this paper, we delve into the challenges the Slingshot interconnect poses with current state-of-the-art MPI (message passing interface) libraries. In particular, we look at the scalability performance when using Slingshot across nodes. We present a comprehensive evaluation using various MPI and communication libraries including Cray MPICH, OpenMPI + UCX, RCCL, and MVAPICH2 on CPUs and GPUs on the Spock system, an early access cluster deployed with Slingshot-10, AMD MI100 GPUs and AMD Epyc Rome CPUs to emulate the Frontier system. We also evaluate preliminary CPU-based support of MPI libraries on the Slingshot-11 interconnect.","volume":38,"issue":1,"firstpage":128,"lastpage":145,"year":2023,"type":"Regular Paper","research_area":["High-Performance & Parallel Computing","Data Center Systems & Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2907-5","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2907-5?year=2023&issue=1","affiliations":["The Ohio State University"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-023-2908-4","title":"A Survey on Clock Synchronization in the Industrial Internet","authors":[{"last":"Dang","first":"Fan"},{"last":"Sun","first":"Xi-Kai"},{"last":"Liu","first":"Ke-Bin"},{"last":"Xu","first":"Yi-Fan"},{"last":"Liu","first":"Yun-Hao"}],"keywords":["clock synchronization","industrial communication","Industrial Internet","wireless sensor network"],"abstract":"Clock synchronization is one of the most fundamental and crucial network communication strategies. With the expansion of the Industrial Internet in numerous industrial applications, a new requirement for the precision, security, complexity, and other features of the clock synchronization mechanism has emerged in various industrial situations. This paper presents a study of standardized clock synchronization protocols and techniques for various types of networks, and a discussion of how these protocols and techniques might be classified. Following that is a description of how certain clock synchronization protocols and technologies, such as PROFINET, Time-Sensitive Networking (TSN), and other well-known industrial networking protocols, can be applied in a number of industrial situations. This study also investigates the possible future development of clock synchronization techniques and technologies.","volume":38,"issue":1,"firstpage":146,"lastpage":165,"year":2023,"type":"Survey","research_area":["Network Protocols & Measurement","IoT & Wireless Networks"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2908-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2908-4?year=2023&issue=1","affiliations":["Tsinghua University"],"type_origin":"Article","source":"jcst"},{"doi":"10.1007/s11390-023-2894-6","title":"xCCL: A Survey of Industry-Led Collective Communication Libraries for Deep Learning","authors":[{"last":"Weingram","first":"Adam"},{"last":"Li","first":"Yuke"},{"last":"Qi","first":"Hao"},{"last":"Ng","first":"Darren"},{"last":"Dai","first":"Liuyao"},{"last":"Lu","first":"Xiaoyi"}],"keywords":["collective","deep learning","distributed training","GPUDirect","RDMA (remote direct memory access)"],"abstract":"Machine learning techniques have become ubiquitous both in industry and academic applications. Increasing model sizes and training data volumes necessitate fast and efficient distributed training approaches. Collective communications greatly simplify inter- and intra-node data transfer and are an essential part of the distributed training process as information such as gradients must be shared between processing nodes. In this paper, we survey the current state-of-the-art collective communication libraries (namely xCCL, including NCCL, oneCCL, RCCL, MSCCL, ACCL, and Gloo), with a focus on the industry-led ones for deep learning workloads. We investigate the design features of these xCCLs, discuss their use cases in the industry deep learning workloads, compare their performance with industry-made benchmarks (i.e., NCCL Tests and PARAM), and discuss key take-aways and interesting observations. We believe our survey sheds light on potential research directions of future designs for xCCLs.","volume":38,"issue":1,"firstpage":166,"lastpage":195,"year":2023,"type":"Survey","research_area":["Deep Learning & Neural Networks","High-Performance & Parallel Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2894-6","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2894-6?year=2023&issue=1","affiliations":["University of California System","University of California Merced"],"type_origin":"Review"},{"doi":"10.1007/s11390-023-2835-4","title":"Improving Entity Linking in Chinese Domain by Sense Embedding Based on Graph Clustering","authors":[{"last":"Zhang","first":"Zhao-Bo"},{"last":"Zhong","first":"Zhi-Man"},{"last":"Yuan","first":"Ping-Peng"},{"last":"Jin","first":"Hai"}],"keywords":["natural language processing (NLP)","domain entity linking","computational linguistics","word sense disambiguation","knowledge graph"],"abstract":"Entity linking refers to linking a string in a text to corresponding entities in a knowledge base through candidate entity generation and candidate entity ranking. It is of great significance to some NLP (natural language processing) tasks, such as question answering. Unlike English entity linking, Chinese entity linking requires more consideration due to the lack of spacing and capitalization in text sequences and the ambiguity of characters and words, which is more evident in certain scenarios. In Chinese domains, such as industry, the generated candidate entities are usually composed of long strings and are heavily nested. In addition, the meanings of the words that make up industrial entities are sometimes ambiguous. Their semantic space is a subspace of the general word embedding space, and thus each entity word needs to get its exact meanings. Therefore, we propose two schemes to achieve better Chinese entity linking. First, we implement an n-gram based candidate entity generation method to increase the recall rate and reduce the nesting noise. Then, we enhance the corresponding candidate entity ranking mechanism by introducing sense embedding. Considering the contradiction between the ambiguity of word vectors and the single sense of the industrial domain, we design a sense embedding model based on graph clustering, which adopts an unsupervised approach for word sense induction and learns sense representation in conjunction with context. We test the embedding quality of our approach on classical datasets and demonstrate its disambiguation ability in general scenarios. We confirm that our method can better learn candidate entities' fundamental laws in the industrial domain and achieve better performance on entity linking through experiments.","volume":38,"issue":1,"firstpage":196,"lastpage":210,"year":2023,"type":"Regular Paper","research_area":["Information Extraction"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2835-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2835-4?year=2023&issue=1","affiliations":["Huazhong University of Science & Technology"],"type_origin":"Article"},{"doi":"10.1007/s11390-023-2888-4","title":"Unified Programming Models for Heterogeneous High-Performance Computers","authors":[{"last":"Ma","first":"Zi-Xuan"},{"last":"Jin","first":"Yu-Yang"},{"last":"Tang","first":"Shi-Zhi"},{"last":"Wang","first":"Hao-Jie"},{"last":"Xue","first":"Wei-Cheng"},{"last":"Zhai","first":"Ji-Dong"},{"last":"Zheng","first":"Wei-Min"}],"keywords":["performance portability","programming model","heterogeneous supercomputer"],"abstract":"Unified programming models can effectively improve program portability on various heterogeneous high-performance computers. Existing unified programming models put a lot of effort to code portability but are still far from achieving good performance portability. In this paper, we present a preliminary design of a performance-portable unified programming model including four aspects: programming language, programming abstraction, compilation optimization, and scheduling system. Specifically, domain-specific languages introduce domain knowledge to decouple the optimizations for different applications and architectures. The unified programming abstraction unifies the common features of different architectures to support common optimizations. Multi-level compilation optimization enables comprehensive performance optimization based on multi-level intermediate representations. Resource-aware lightweight runtime scheduling system improves the resource utilization of heterogeneous computers. This is a perspective paper to show our viewpoints on programming models for emerging heterogeneous systems.","volume":38,"issue":1,"firstpage":211,"lastpage":218,"year":2023,"type":"Perspective","research_area":["High-Performance & Parallel Computing"],"url":"https://jcst.ict.ac.cn/article/doi/10.1007/s11390-023-2888-4","pdf":"https://jcst.ict.ac.cn/en/article/pdf/preview/10.1007/s11390-023-2888-4?year=2023&issue=1","affiliations":["Tsinghua University"],"type_origin":"Article"}];
